use std::{fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=assets/icon-shadowed.svg");
    println!("cargo:rerun-if-changed=assets/icon.svg");
    copy_data_themes();
    neoutl_object_shader_build::compile_object_shader("media", "src/renderer/slang/media.slang");
    neoutl_object_shader_build::compile_object_shader(
        "media_video",
        "src/renderer/slang/media_video.slang",
    );
}

fn copy_data_themes() {
    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR未設定");
    let profile_dir = PathBuf::from(&out_dir)
        .ancestors()
        .nth(3)
        .expect("target/{profile}解決失敗")
        .to_path_buf();
    let dest = profile_dir.join("themes");
    let src = PathBuf::from("assets/themes");
    if !src.is_dir() {
        return;
    }
    fs::create_dir_all(&dest).expect("themes配置先作成失敗");
    for entry in fs::read_dir(&src).into_iter().flatten().flatten() {
        let path = entry.path();
        let ext_ok = matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("json" | "toml")
        );
        if ext_ok && let Some(name) = path.file_name() {
            let _ = fs::copy(&path, dest.join(name));
        }
    }
    println!("cargo:rerun-if-changed=assets/themes");
}

use half::f16;

pub const CHANNELS: usize = 4;

pub fn u8_to_rgba16f(data: &[u8]) -> Vec<f16> {
    data.iter()
        .map(|&c| f16::from_f32(c as f32 / 255.0))
        .collect()
}

pub fn rgba16f_to_u8(data: &[f16]) -> Vec<u8> {
    data.iter()
        .map(|&c| (c.to_f32().clamp(0.0, 1.0) * 255.0).round() as u8)
        .collect()
}

pub fn rgb_to_hsv(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let delta = max - min;
    let h = if delta == 0.0 {
        0.0
    } else if max == r {
        60.0 * ((g - b) / delta).rem_euclid(6.0)
    } else if max == g {
        60.0 * ((b - r) / delta + 2.0)
    } else {
        60.0 * ((r - g) / delta + 4.0)
    };
    let s = if max == 0.0 { 0.0 } else { delta / max };
    (h, s, max)
}

pub fn hsv_to_rgb(h: f32, s: f32, v: f32) -> (f32, f32, f32) {
    let c = v * s;
    let x = c * (1.0 - ((h / 60.0).rem_euclid(2.0) - 1.0).abs());
    let m = v - c;
    let (r1, g1, b1) = match (h.rem_euclid(360.0) / 60.0) as u32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    (r1 + m, g1 + m, b1 + m)
}

pub fn hue_distance(a: f32, b: f32) -> f32 {
    let d = (a - b).rem_euclid(360.0);
    d.min(360.0 - d)
}

#[cfg(test)]
mod hsv_tests {
    use super::*;

    #[test]
    fn round_trip_pure_red() {
        let (h, s, v) = rgb_to_hsv(1.0, 0.0, 0.0);
        let (r, g, b) = hsv_to_rgb(h, s, v);
        assert!((r - 1.0).abs() < 1e-5 && g.abs() < 1e-5 && b.abs() < 1e-5);
    }

    #[test]
    fn hue_distance_wraps_at_360() {
        assert!((hue_distance(350.0, 10.0) - 20.0).abs() < 1e-5);
    }

    #[test]
    fn hue_distance_zero_for_equal() {
        assert_eq!(hue_distance(120.0, 120.0), 0.0);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip_preserves_endpoints() {
        let src = [0u8, 128, 255, 255];
        let f = u8_to_rgba16f(&src);
        assert_eq!(f[0].to_f32(), 0.0);
        assert_eq!(f[2].to_f32(), 1.0);
        let back = rgba16f_to_u8(&f);
        assert_eq!(back[0], 0);
        assert_eq!(back[2], 255);
    }
}

[package]
name = "neoutl-schema"
version = "0.1.0"
edition = "2024"

[dependencies]
prost = { workspace = true }
prost-types = { workspace = true }
serde = { workspace = true }

[build-dependencies]
prost-build = { workspace = true }
protoc-bin-vendored = "3"

fn main() {
    let out_dir = std::path::PathBuf::from(std::env::var("OUT_DIR").unwrap());
    let descriptor_path = out_dir.join("neoutl_descriptor.bin");

    let protoc_path = protoc_bin_vendored::protoc_bin_path().unwrap();
    unsafe {
        std::env::set_var("PROTOC", protoc_path);
    }

    let mut config = prost_build::Config::new();
    config.file_descriptor_set_path(&descriptor_path);
    config.type_attribute(".", "#[derive(serde::Serialize, serde::Deserialize)]");
    config
        .compile_protos(
            &[
                "proto/neoutl/v1/common.proto",
                "proto/neoutl/v1/document.proto",
                "proto/neoutl/v1/settings.proto",
                "proto/neoutl/v1/keymap.proto",
                "proto/neoutl/v1/export.proto",
            ],
            &["proto"],
        )
        .unwrap();
}

syntax = "proto3";
package neoutl.v1;

message Transform {
  float x = 1;
  float y = 2;
  float z = 3;
  float scale_x = 4;
  float scale_y = 5;
  float rot_x = 6;
  float rot_y = 7;
  float rot_z = 8;
  float opacity = 9;
  float center_x = 10;
  float center_y = 11;
  float center_z = 12;
}

message AudioParams {
  float volume = 1;
  float pan = 2;
  bool mute = 3;
}

enum ClipMode {
  CLIP_MODE_ALPHA = 0;
  CLIP_MODE_ALPHA_INVERT = 1;
  CLIP_MODE_LUMINANCE = 2;
  CLIP_MODE_LUMINANCE_INVERT = 3;
  CLIP_MODE_CHROMA = 4;
}

message ClipTarget {
  bool enabled = 1;
  uint32 layer_count_down = 2;
  uint32 layer_count_up = 3;
  ClipMode mode = 4;
  float chroma_hue = 5;
  float chroma_tolerance = 6;
  bool blend_edge = 7;
  bool render_self = 8;
}

message CameraParams {
  bool enabled = 1;
  float pos_x = 2;
  float pos_y = 3;
  float pos_z = 4;
  float target_x = 5;
  float target_y = 6;
  float target_z = 7;
  float near = 8;
  float far = 9;
  float tilt_deg = 10;
  float fov_deg = 11;
  int32 target_layer_mode = 12;
  int32 target_layer = 13;
  bool zbuffer_enabled = 14;
  float focus_distance = 15;
  float depth_blur_strength = 16;
}

message GroupControl {
  uint32 layer_count_down = 1;
  uint32 layer_count_up = 2;
  bool generate_framebuffer = 3;
  bool hide_captured = 4;
  optional CameraParams camera = 5;
}

enum TextAlign {
  TEXT_ALIGN_LEFT = 0;
  TEXT_ALIGN_CENTER = 1;
  TEXT_ALIGN_RIGHT = 2;
}

message TextContent {
  string text = 1;
  float font_size = 2;
  repeated float color = 3;
  repeated string font_family_stack = 4;
  bool bold = 5;
  bool italic = 6;
  TextAlign align = 7;
  float line_height = 8;
  float outline_width = 9;
  repeated float outline_color = 10;
}

message ShapeParams {
  uint32 sides = 1;
  repeated float fill_color = 2;
  repeated float stroke_color = 3;
  float stroke_width = 4;
  float extrude_depth = 5;
}

enum MediaKind {
  MEDIA_KIND_UNSPECIFIED = 0;
  MEDIA_KIND_VIDEO = 1;
  MEDIA_KIND_IMAGE = 2;
  MEDIA_KIND_AUDIO = 3;
}

message MediaSource {
  string path = 1;
  MediaKind kind = 2;
  int64 trim_in_frame = 3;
}

enum BlendMode {
  BLEND_MODE_NORMAL = 0;
  BLEND_MODE_ADD = 1;
  BLEND_MODE_MULTIPLY = 2;
  BLEND_MODE_SCREEN = 3;
  BLEND_MODE_OVERLAY = 4;
  BLEND_MODE_DARKEN = 5;
  BLEND_MODE_LIGHTEN = 6;
  BLEND_MODE_DIFFERENCE = 7;
  BLEND_MODE_EXCLUSION = 8;
}

message Keyframe {
  int32 frame = 1;
  float value = 2;
  string engine_id = 3;
  bytes engine_payload = 4;
  uint64 edit_seq = 5;
  reserved 6;
  reserved "apply_mode";
  optional int32 control_frame = 7;
}

message Value {
  oneof kind {
    float number = 1;
    bool boolean = 2;
    string text = 3;
    string file_path = 4;
    uint32 enum_value = 5;
    int32 track_ref = 6;
  }
}

message EffectParam {
  Value static_value = 1;
  repeated Keyframe keyframes = 2;
}

message EffectInstance {
  string effect_id = 1;
  bool enabled = 2;
  map<string, EffectParam> params = 3;
}

message PluginParamInfo {
  uint32 id = 1;
  string name = 2;
  string symbol = 3;
  string unit = 4;
  string comment = 5;
  double min = 6;
  double max = 7;
  double default = 8;
}

message PluginInstanceRef {
  uint64 instance_uid = 1;
  int32 format = 2;
  string path = 3;
  string plugin_id = 4;
  bool bypass = 5;
  map<uint32, double> params = 6;
  repeated PluginParamInfo param_info = 7;
}

message TimeRemapDoc {
  repeated Keyframe keyframes = 1;
  optional int32 freeze_frame = 2;
}

syntax = "proto3";
