pub use neoutl::v1::*;

#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dimensionality {
    TwoD = 0,
    ThreeD = 1,
    Both = 2,
}

#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ParamKind {
    Float = 0,
    Bool = 1,
    Color = 2,
    Enum = 3,
    Text = 4,
    FilePath = 5,
    Track = 6,
    Separator = 7,
    Group = 8,
    Folder = 9,
    /// コールバック実行ボタン。呼び出し先は `ParamSchema::button_callback` を参照する。
    Button = 10,
    /// レイヤー単位で独立した真偽値。値の意味は `ParamKind::Bool` と同一。
    CheckSection = 11,
