            SegmentCurveKind::Bounce { .. } => "Bounce",
            SegmentCurveKind::Elastic { .. } => "Elastic",
        }
    }

    pub fn evaluate(&self, t: f32) -> f32 {
        match self {
            SegmentCurveKind::Linear => t,
            SegmentCurveKind::Bezier {
                handle_left,
