unsafe extern "C" fn evaluate_c(
    keyframes_ptr: *const KeyframeC,
    count: usize,
    frame: i32,
    fallback: f32,
) -> f32 {
    let points = unsafe { decode_keyframes(keyframes_ptr, count) };
