#[cfg(test)]
mod tests {
    fn variance(luminance: f32) -> f32 {
        (luminance - 0.5) * 2.0
    }

    #[test]
    fn variance_black() {
        assert_eq!(variance(0.0), -1.0);
    }

    #[test]
    fn variance_mid() {
        assert_eq!(variance(0.5), 0.0);
    }

    #[test]
    fn variance_white() {
        assert_eq!(variance(1.0), 1.0);
    }
}

