#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    Number(f32),
    Variable(String),
    PropRef(String),
    Func(String),
    Plus,
    Minus,
    Multiply,
    Divide,
    Modulo,
    LParen,
    RParen,
    Comma,
}

#[derive(Clone, Debug)]
pub struct CompiledExpression {
    pub rpn: Vec<Token>,
}

fn tokenize(expr: &str) -> Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = expr.chars().collect();
    let len = chars.len();
    let mut i = 0;

    while i < len {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
            continue;
        }

        if c.is_ascii_digit() || (c == '.' && i + 1 < len && chars[i + 1].is_ascii_digit()) {
            let start = i;
            while i < len && (chars[i].is_ascii_digit() || chars[i] == '.') {
                i += 1;
            }
            let s: String = chars[start..i].iter().collect();
            let num: f32 = s
                .parse()
                .map_err(|e| format!("Invalid number '{}': {}", s, e))?;
            tokens.push(Token::Number(num));
            continue;
        }

        if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < len && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let ident: String = chars[start..i].iter().collect();

            if ident == "prop" {
                while i < len && chars[i].is_whitespace() {
                    i += 1;
                }
                if i < len && chars[i] == '(' {
                    i += 1;
                    while i < len && chars[i].is_whitespace() {
                        i += 1;
                    }
                    if i < len && (chars[i] == '\'' || chars[i] == '"') {
                        let quote = chars[i];
                        i += 1;
                        let p_start = i;
                        while i < len && chars[i] != quote {
                            i += 1;
                        }
                        let prop_name: String = chars[p_start..i].iter().collect();
                        if i < len && chars[i] == quote {
                            i += 1;
                        }
                        while i < len && chars[i].is_whitespace() {
                            i += 1;
                        }
                        if i < len && chars[i] == ')' {
                            i += 1;
                        }
                        tokens.push(Token::PropRef(prop_name));
                        continue;
                    }
                }
            }

            // 関数判定
            let mut peek = i;
            while peek < len && chars[peek].is_whitespace() {
                peek += 1;
            }
            if peek < len && chars[peek] == '(' {
                tokens.push(Token::Func(ident));
            } else {
                tokens.push(Token::Variable(ident));
            }
            continue;
        }

        match c {
            '+' => tokens.push(Token::Plus),
            '-' => tokens.push(Token::Minus),
            '*' => tokens.push(Token::Multiply),
            '/' => tokens.push(Token::Divide),
            '%' => tokens.push(Token::Modulo),
            '(' => tokens.push(Token::LParen),
            ')' => tokens.push(Token::RParen),
            ',' => tokens.push(Token::Comma),
            _ => return Err(format!("Unexpected character: '{}'", c)),
        }
        i += 1;
    }

    Ok(tokens)
}

fn precedence(token: &Token) -> i32 {
    match token {
        Token::Plus | Token::Minus => 1,
        Token::Multiply | Token::Divide | Token::Modulo => 2,
        _ => 0,
    }
}

// Shunting-yard アルゴリズムで中置記法から逆ポーランド記法 (RPN) へ変換
fn to_rpn(tokens: &[Token]) -> Result<Vec<Token>, String> {
    let mut output = Vec::new();
    let mut op_stack = Vec::new();

    let mut prev_is_op = true;

    for token in tokens {
        match token {
            Token::Number(_) | Token::Variable(_) | Token::PropRef(_) => {
                output.push(token.clone());
                prev_is_op = false;
            }
            Token::Func(_) => {
                op_stack.push(token.clone());
                prev_is_op = true;
            }
            Token::Comma => {
                while let Some(top) = op_stack.last() {
                    if *top == Token::LParen {
                        break;
                    }
                    output.push(op_stack.pop().unwrap());
                }
                prev_is_op = true;
            }
            Token::Plus | Token::Minus | Token::Multiply | Token::Divide | Token::Modulo => {
                // 単項マイナスの処理 (0 - x)
                if *token == Token::Minus && prev_is_op {
                    output.push(Token::Number(0.0));
                }

                let p = precedence(token);
                while let Some(top) = op_stack.last() {
                    if *top == Token::LParen {
                        break;
                    }
                    if precedence(top) >= p {
                        output.push(op_stack.pop().unwrap());
                    } else {
                        break;
                    }
                }
                op_stack.push(token.clone());
                prev_is_op = true;
            }
            Token::LParen => {
                op_stack.push(Token::LParen);
                prev_is_op = true;
            }
            Token::RParen => {
                let mut found_lparen = false;
                while let Some(top) = op_stack.pop() {
                    if top == Token::LParen {
                        found_lparen = true;
                        break;
                    }
                    output.push(top);
                }
                if !found_lparen {
                    return Err("Mismatched parentheses".to_string());
                }
                if let Some(Token::Func(_)) = op_stack.last() {
                    output.push(op_stack.pop().unwrap());
                }
                prev_is_op = false;
            }
        }
    }

    while let Some(top) = op_stack.pop() {
        if top == Token::LParen || top == Token::RParen {
            return Err("Mismatched parentheses".to_string());
        }
        output.push(top);
    }

    Ok(output)
}

impl CompiledExpression {
    pub fn parse(expr: &str) -> Result<Self, String> {
        let tokens = tokenize(expr)?;
        let rpn = to_rpn(&tokens)?;
        Ok(Self { rpn })
    }

    pub fn evaluate(
        &self,
        ctx: &ExpressionEvalContext,
        host: Option<&ExpressionHostVTable>,
    ) -> f32 {
        let mut stack: Vec<f32> = Vec::new();

        for token in &self.rpn {
            match token {
                Token::Number(val) => stack.push(*val),
                Token::Variable(var) => match var.as_str() {
                    "time" | "t" => stack.push(ctx.time_seconds as f32),
                    "frame" | "f" => stack.push(ctx.frame as f32),
                    "value" | "val" | "v" => stack.push(ctx.current_value),
                    "fps" => {
                        let fps = if let Some(h) = host {
                            unsafe { (h.get_fps)() }
                        } else {
                            30.0
                        };
                        stack.push(fps);
                    }
                    "pi" | "PI" => stack.push(std::f32::consts::PI),
                    _ => {
                        // ホストコールバック経由でプロパティとして解決試行
                        let val = if let Some(h) = host {
                            let str_ref = StrRef {
                                ptr: var.as_ptr(),
                                len: var.len(),
                            };
                            unsafe { (h.get_property)(ctx.object_id, str_ref, 0.0) }
                        } else {
                            0.0
                        };
                        stack.push(val);
                    }
                },
                Token::PropRef(prop_name) => {
                    let val = if let Some(h) = host {
                        let str_ref = StrRef {
                            ptr: prop_name.as_ptr(),
                            len: prop_name.len(),
                        };
                        unsafe { (h.get_property)(ctx.object_id, str_ref, 0.0) }
                    } else {
                        0.0
                    };
                    stack.push(val);
                }
                Token::Plus => {
                    let b = stack.pop().unwrap_or(0.0);
                    let a = stack.pop().unwrap_or(0.0);
                    stack.push(a + b);
                }
                Token::Minus => {
                    let b = stack.pop().unwrap_or(0.0);
                    let a = stack.pop().unwrap_or(0.0);
                    stack.push(a - b);
                }
                Token::Multiply => {
                    let b = stack.pop().unwrap_or(1.0);
                    let a = stack.pop().unwrap_or(1.0);
                    stack.push(a * b);
                }
                Token::Divide => {
                    let b = stack.pop().unwrap_or(1.0);
                    let a = stack.pop().unwrap_or(0.0);
                    if b.abs() <= 1e-7 {
                        stack.push(0.0);
                    } else {
                        stack.push(a / b);
                    }
                }
                Token::Modulo => {
                    let b = stack.pop().unwrap_or(1.0);
                    let a = stack.pop().unwrap_or(0.0);
                    if b.abs() <= 1e-7 {
                        stack.push(0.0);
                    } else {
                        stack.push(a % b);
                    }
                }
                Token::Func(name) => match name.to_lowercase().as_str() {
                    "sin" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.sin());
                    }
                    "cos" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.cos());
                    }
                    "tan" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.tan());
                    }
                    "abs" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.abs());
                    }
                    "sqrt" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.max(0.0).sqrt());
                    }
                    "floor" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.floor());
                    }
                    "ceil" => {
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.ceil());
                    }
                    "min" => {
                        let b = stack.pop().unwrap_or(0.0);
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.min(b));
                    }
                    "max" => {
                        let b = stack.pop().unwrap_or(0.0);
                        let a = stack.pop().unwrap_or(0.0);
                        stack.push(a.max(b));
                    }
                    "clamp" => {
                        let max_v = stack.pop().unwrap_or(1.0);
                        let min_v = stack.pop().unwrap_or(0.0);
                        let val = stack.pop().unwrap_or(0.0);
                        stack.push(val.clamp(min_v, max_v));
                    }
                    _ => {}
                },
                Token::LParen | Token::RParen | Token::Comma => {}
            }
        }

        stack.pop().unwrap_or(ctx.current_value)
    }
}

