fn format_extension(format: PluginFormat) -> &'static str {
    match format {
        PluginFormat::Vst3 => "vst3",
        PluginFormat::Clap => "clap",
        PluginFormat::Lv2 => "lv2",
        _ => "",
    }
}

fn plugin_name_from_path(path: &Path) -> String {
    path.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown")
        .to_string()
}

fn collect_from_dir(
    format: PluginFormat,
    dir: &Path,
    ext: &str,
    out: &mut Vec<PluginCatalogEntry>,
) {
    let Ok(read) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in read.flatten() {
        let path = entry.path();
        let is_match = path
            .extension()
            .and_then(|e| e.to_str())
            .is_some_and(|e| e.eq_ignore_ascii_case(ext));
        if is_match {
            out.push(PluginCatalogEntry {
                format,
                name: plugin_name_from_path(&path),
                vendor: String::new(),
                plugin_id: path.to_string_lossy().to_string(),
                path,
            });
            continue;
        }
        if path.is_dir() {
            collect_from_dir(format, &path, ext, out);
        }
    }
}

pub fn scan_directories(format: PluginFormat, dirs: &[PathBuf]) -> Vec<PluginCatalogEntry> {
    let ext = format_extension(format);
    if ext.is_empty() {
        return Vec::new();
    }
    let mut out = Vec::new();
    for dir in dirs {
        collect_from_dir(format, dir, ext, &mut out);
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub enum PluginFormat {
    Vst3,
    Clap,
    Lv2,
    Vst2,
    Au,
    Sf2,
    Sfz,
    Jsfx,
    Internal,
}

impl PluginFormat {
    pub fn from_path(path: &std::path::Path) -> Option<Self> {
        let ext = path.extension().and_then(|e| e.to_str())?;
        match ext.to_lowercase().as_str() {
            "vst3" => Some(Self::Vst3),
            "clap" => Some(Self::Clap),
            "lv2" => Some(Self::Lv2),
            "vst" | "dll" | "so" | "dylib" => Some(Self::Vst2),
            "component" => Some(Self::Au),
            "sf2" => Some(Self::Sf2),
            "sfz" => Some(Self::Sfz),
            "jsfx" => Some(Self::Jsfx),
            _ => None,
        }
    }

    pub fn host_format_tag(&self) -> Result<&'static str, HostError> {
        match self {
            Self::Clap => Ok("clap"),
            Self::Vst3 => Ok("vst3"),
            Self::Lv2 => Ok("lv2"),
            _ => Err(HostError::UnsupportedFormat(*self)),
        }
    }
}

