use arc_swap::ArcSwap;
use libloading::{Library, Symbol};
use neoutl_media_api::{AudioBuffer, ENTRY_SYMBOL, EntryFn, MediaKind, MediaVTable};
use std::{
    ffi::OsStr,
    path::{Path, PathBuf},
    sync::{Arc, OnceLock},
};

pub struct MediaPlugin {
    pub id: String,
    pub name: String,
    pub kind: MediaKind,
    pub extensions: Vec<String>,
    pub vtable: MediaVTable,
    _lib: Option<Library>,
}

fn registry_swap() -> &'static ArcSwap<Vec<Arc<MediaPlugin>>> {
    static SWAP: OnceLock<ArcSwap<Vec<Arc<MediaPlugin>>>> = OnceLock::new();
    SWAP.get_or_init(|| ArcSwap::new(Arc::new(Vec::new())))
}

fn from_vtable(vtable: MediaVTable, lib: Option<Library>) -> MediaPlugin {
    let meta = (vtable.meta)();
    let extensions =
        unsafe { std::slice::from_raw_parts(meta.extensions_ptr, meta.extensions_len) }
            .iter()
            .map(|s| s.to_ascii_lowercase())
            .collect();
    MediaPlugin {
        id: meta.id.to_owned(),
        name: meta.name.to_owned(),
        kind: meta.kind,
        extensions,
        vtable,
        _lib: lib,
    }
}

fn native_plugins() -> Vec<MediaPlugin> {
    vec![from_vtable(neo_media_ffmpeg::native_vtable(), None)]
}

pub fn load_all(decoders_dir: &Path) {
    let mut plugins: Vec<MediaPlugin> = native_plugins();

    match std::fs::read_dir(decoders_dir) {
        Ok(entries) => {
            let candidates: Vec<PathBuf> = entries
                .flatten()
                .map(|e| e.path())
                .filter(|p| is_dylib(p))
                .collect();
            for path in candidates {
                match load_one(&path) {
                    Ok(plugin) => plugins.push(plugin),
                    Err(err) => eprintln!(
                        "{}",
                        t!(
                            "[NeoUtl] デコーダ読み込み失敗 %{arg0}: %{arg1}",
                            arg0 = format!("{}", path.display()),
                            arg1 = format!("{}", err)
                        )
                    ),
                }
            }
        }
        Err(err) => eprintln!(
            "{}",
            t!(
                "[NeoUtl] decoders/ 読み込み失敗: %{arg0}",
                arg0 = format!("{}", err)
            )
        ),
    }

    plugins.sort_by(|a, b| a.id.cmp(&b.id));
    for plugin in &plugins {
        eprintln!(
            "{}",
            t!(
                "[NeoUtl] デコーダ登録: %{arg0} (%{arg1})",
                arg0 = plugin.id.to_string(),
                arg1 = plugin.name.to_string()
            )
        );
    }
    registry_swap().store(Arc::new(plugins.into_iter().map(Arc::new).collect()));
}

pub fn registry() -> Arc<Vec<Arc<MediaPlugin>>> {
    registry_swap().load_full()
}

pub fn find_by_extension(ext: &str) -> Option<Arc<MediaPlugin>> {
    registry()
        .iter()
        .find(|p| p.extensions.iter().any(|e| e == ext))
        .cloned()
}

pub fn find_all_by_extension(ext: &str) -> Vec<Arc<MediaPlugin>> {
    registry()
        .iter()
        .filter(|p| p.extensions.iter().any(|e| e == ext))
        .cloned()
        .collect()
}

pub fn decode_audio(path: &Path) -> Result<AudioBuffer, String> {
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .map(str::to_ascii_lowercase)
        .ok_or_else(|| {
            t!("拡張子なし: %{arg0}", arg0 = format!("{}", path.display())).to_string()
        })?;
    let plugin = find_by_extension(&ext).ok_or_else(|| {
        t!(
            "音声デコーダ未登録: %{arg0}",
            arg0 = format!("{}", path.display())
        )
        .to_string()
    })?;
    let decode_fn = plugin.vtable.decode_audio.ok_or_else(|| {
        t!(
            "プラグイン%{arg0}はdecode_audio未実装",
            arg0 = plugin.id.to_string()
        )
        .to_string()
    })?;
    decode_fn(path)
}

pub fn default_decoders_dir() -> PathBuf {
    let Some(exe_dir) = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(Path::to_path_buf))
    else {
        return PathBuf::from("decoders");
    };

    #[cfg(target_os = "macos")]
    {
        let resources_dir = exe_dir.join("../Resources/decoders");
        if resources_dir.is_dir() {
            return resources_dir;
        }
    }

    exe_dir.join("decoders")
}

fn load_one(path: &Path) -> Result<MediaPlugin, Box<dyn std::error::Error>> {
    let lib = unsafe { Library::new(path) }?;
    let entry: Symbol<EntryFn> = unsafe { lib.get(ENTRY_SYMBOL) }?;
    let vtable_ptr = unsafe { entry() };
    let vtable_ref: &MediaVTable = unsafe { &*vtable_ptr };
    let vtable = MediaVTable {
        meta: vtable_ref.meta,
        open_video: vtable_ref.open_video,
        open_image: vtable_ref.open_image,
        decode_audio: vtable_ref.decode_audio,
    };
    Ok(from_vtable(vtable, Some(lib)))
}

fn is_dylib(path: &Path) -> bool {
    matches!(
        path.extension().and_then(OsStr::to_str),
        Some("so" | "dylib" | "dll")
    )
}

use std::sync::OnceLock;
use std::sync::atomic::{AtomicI32, Ordering};
use tokio::runtime::Runtime;

static WORKER_THREADS_SETTING: AtomicI32 = AtomicI32::new(0);
static RUNTIME: OnceLock<Runtime> = OnceLock::new();

fn effective_thread_count() -> usize {
    let configured = WORKER_THREADS_SETTING.load(Ordering::Acquire);
    if configured > 0 {
        configured as usize
    } else {
        std::thread::available_parallelism().map_or(4, |n| n.get())
    }
}

pub fn set_worker_threads(worker_threads: i32) {
    WORKER_THREADS_SETTING.store(worker_threads, Ordering::Release);
}

pub fn handle() -> tokio::runtime::Handle {
    RUNTIME
        .get_or_init(|| {
            let threads = effective_thread_count();
            eprintln!("[media-runtime] デコードスレッドプール起動: worker_threads={threads}");
            tokio::runtime::Builder::new_multi_thread()
                .worker_threads(threads)
                .thread_name("neoutl-decode")
                .build()
                .expect("デコードランタイム構築失敗")
        })
        .handle()
        .clone()
}

use wgpu_text::glyph_brush::ab_glyph::{Font, FontArc, ScaleFont};
use wgpu_text::glyph_brush::{HorizontalAlign, Layout, Section, Text, VerticalAlign};

#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HAlign {
    Left,
    Center,
    Right,
}

pub struct TextLayout {
    pub lines: Vec<String>,
    pub width: u32,
    pub height: u32,
    pub line_height_px: f32,
}

pub fn layout(font: &FontArc, text: &str, font_size: f32, line_height: f32) -> TextLayout {
    let scaled = font.as_scaled(font_size);
    let line_height_px = (scaled.ascent() - scaled.descent()) * line_height.max(0.01);
    let lines: Vec<String> = text.split('\n').map(str::to_owned).collect();
    let width: f32 = lines
        .iter()
        .map(|line| {
            line.chars()
                .map(|c| scaled.h_advance(font.glyph_id(c)))
                .sum::<f32>()
        })
        .fold(0.0_f32, f32::max);
    let height = line_height_px * lines.len().max(1) as f32;
    TextLayout {
        width: width.ceil().max(1.0) as u32,
        height: height.ceil().max(1.0) as u32,
        line_height_px,
        lines,
    }
}

pub fn build_sections<'a>(
    color: [f32; 4],
    font_size: f32,
    align: HAlign,
    text_layout: &'a TextLayout,
    tex_width: u32,
    tex_height: u32,
) -> Vec<Section<'a>> {
    let h_align = match align {
        HAlign::Left => HorizontalAlign::Left,
        HAlign::Center => HorizontalAlign::Center,
        HAlign::Right => HorizontalAlign::Right,
    };
    let x = match h_align {
        HorizontalAlign::Left => 0.0,
        HorizontalAlign::Center => tex_width as f32 / 2.0,
        HorizontalAlign::Right => tex_width as f32,
    };
    text_layout
        .lines
        .iter()
        .enumerate()
        .map(|(row, line)| {
            let y = row as f32 * text_layout.line_height_px;
            Section::default()
                .add_text(Text::new(line).with_color(color).with_scale(font_size))
                .with_screen_position((x, y))
                .with_bounds((tex_width as f32, tex_height as f32))
                .with_layout(
                    Layout::default_single_line()
                        .h_align(h_align)
                        .v_align(VerticalAlign::Top),
                )
        })
        .collect()
}

use neoutl_media_api::AudioBuffer;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, OnceLock, RwLock};

#[derive(Clone, Copy, Debug, Default)]
pub struct Peak {
    pub min: f32,
    pub max: f32,
}

#[derive(Clone, Debug)]
pub struct WaveformAsset {
    pub path: PathBuf,
    pub levels: Vec<Arc<[Peak]>>,
}

static CACHE: OnceLock<RwLock<HashMap<PathBuf, Arc<WaveformAsset>>>> = OnceLock::new();

fn cache() -> &'static RwLock<HashMap<PathBuf, Arc<WaveformAsset>>> {
    CACHE.get_or_init(|| RwLock::new(HashMap::new()))
}

pub fn build(path: &Path, audio: &AudioBuffer) -> Arc<WaveformAsset> {
    let mut levels: Vec<Arc<[Peak]>> = Vec::new();
    let current = make_peaks(audio, 1);
    levels.push(Arc::from(current.into_boxed_slice()));
    while levels.last().is_some_and(|v| v.len() > 512) {
        let previous = levels.last().expect("waveform level");
        let mut next = Vec::with_capacity(previous.len().div_ceil(2));
        for pair in previous.chunks(2) {
            let mut peak = Peak {
                min: 1.0,
                max: -1.0,
            };
            for p in pair {
                peak.min = peak.min.min(p.min);
                peak.max = peak.max.max(p.max);
            }
            next.push(peak);
        }
        levels.push(Arc::from(next.into_boxed_slice()));
    }
    Arc::new(WaveformAsset {
        path: path.to_path_buf(),
        levels,
    })
}

pub fn get(path: &Path) -> Option<Arc<WaveformAsset>> {
    cache().read().ok()?.get(path).cloned()
}

pub fn insert(asset: Arc<WaveformAsset>) {
    if let Ok(mut cache) = cache().write() {
        cache.insert(asset.path.clone(), asset);
    }
}

pub fn level_for_columns(asset: &WaveformAsset, columns: usize) -> Arc<[Peak]> {
    let target = columns.max(1);
    asset
        .levels
        .iter()
        .find(|level| level.len() <= target * 2)
        .cloned()
        .unwrap_or_else(|| {
            asset
                .levels
                .last()
                .cloned()
                .unwrap_or_else(|| Arc::from([]))
        })
}

fn make_peaks(audio: &AudioBuffer, bucket: usize) -> Vec<Peak> {
    let channels = audio.channels.max(1) as usize;
    audio
        .samples
        .chunks(channels * bucket)
        .map(|samples| {
            let mut peak = Peak {
                min: 1.0,
                max: -1.0,
            };
            for sample in samples.chunks(channels) {
                let value = sample.iter().copied().sum::<f32>() / sample.len().max(1) as f32;
                peak.min = peak.min.min(value);
                peak.max = peak.max.max(value);
            }
            peak
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn builds_bounded_levels() {
        let audio = AudioBuffer {
            sample_rate: 48_000,
            channels: 1,
            samples: (0..4096)
                .map(|i| if i % 2 == 0 { -0.5 } else { 0.5 })
                .collect(),
        };
        let asset = build(Path::new("test.wav"), &audio);
        assert!(asset.levels.last().unwrap().len() <= 512);
        assert_eq!(asset.levels[0][0].min, -0.5);
    }
}

use egui_wgpu::wgpu;
use neoutl_media_api::{ColorMeta, VideoSource};
use std::collections::{HashMap, VecDeque};
use std::sync::atomic::AtomicU64;
use std::sync::atomic::{AtomicI64, Ordering};
use std::sync::mpsc::{self, RecvTimeoutError};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

static NEXT_WORKER_TOKEN: AtomicU64 = AtomicU64::new(1);

thread_local! {
    static ACTIVE_WORKER_TOKEN: std::cell::Cell<Option<u64>> = const { std::cell::Cell::new(None) };
}

struct ActiveWorkerTokenGuard;

impl ActiveWorkerTokenGuard {
    fn enter(token: u64) -> Self {
        ACTIVE_WORKER_TOKEN.with(|c| c.set(Some(token)));
        Self
    }
}

impl Drop for ActiveWorkerTokenGuard {
    fn drop(&mut self) {
        ACTIVE_WORKER_TOKEN.with(|c| c.set(None));
    }
}

const PREFETCH_RADIUS: i64 = 8;
pub(crate) const RING_CAPACITY: usize = neoutl_media_api::VIDEO_TEXTURE_POOL_CAPACITY;
const _: () = assert!(RING_CAPACITY as i64 > PREFETCH_RADIUS * 2);
const DECODE_PREFETCH_FAIL_THRESHOLD: i64 = 30;
const DECODE_WATCHDOG_TIMEOUT_MS: u64 = 5_000;

const SAFE_RING_CAPACITY: usize = {
    let radius_window = (PREFETCH_RADIUS as usize) * 2 + 2;
    if RING_CAPACITY < radius_window {
        RING_CAPACITY
    } else {
        radius_window
    }
};

const STOP_SENTINEL: i64 = i64::MIN + 1;
const NONE_SENTINEL: i64 = i64::MIN;
const DECODE_WATCHDOG_TIMEOUT: Duration = Duration::from_millis(DECODE_WATCHDOG_TIMEOUT_MS);

struct TextureStore {
    map: HashMap<i64, (wgpu::Texture, ColorMeta)>,
    order: VecDeque<i64>,
}

impl TextureStore {
    fn new() -> Self {
        Self {
            map: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    fn contains(&self, index: i64) -> bool {
        self.map.contains_key(&index)
    }

    fn touch(&mut self, index: i64) {
        self.order.retain(|&i| i != index);
        self.order.push_back(index);
    }

    fn get(&mut self, index: i64) -> Option<(wgpu::Texture, ColorMeta)> {
        let tex = self.map.get(&index).cloned();
        if tex.is_some() {
            self.touch(index);
        }
        tex
    }

    fn put(&mut self, index: i64, texture: wgpu::Texture, color_meta: ColorMeta) {
        if self.map.contains_key(&index) {
            self.touch(index);
            return;
        }
        self.map.insert(index, (texture, color_meta));
        self.order.push_back(index);
        while self.order.len() > SAFE_RING_CAPACITY {
            if let Some(evicted) = self.order.pop_front() {
                self.map.remove(&evicted);
            }
        }
    }
}

enum DecodeRequest {
    PrefetchOnly(i64),
    Full(i64),
}

enum DecodeResponse {
    PrefetchDone(i64, Result<(), String>),
    FrameDone(i64, Result<(wgpu::Texture, ColorMeta), String>),
}

struct DecodeThreadHandle {
    req_tx: Option<mpsc::Sender<DecodeRequest>>,
    resp_rx: mpsc::Receiver<DecodeResponse>,
    join: Option<thread::JoinHandle<()>>,
    hung: bool,
}

impl DecodeThreadHandle {
    fn spawn(
        mut decoder: Box<dyn VideoSource>,
        device: Arc<wgpu::Device>,
        queue: Arc<wgpu::Queue>,
    ) -> Self {
        let (req_tx, req_rx) = mpsc::channel::<DecodeRequest>();
        let (resp_tx, resp_rx) = mpsc::channel::<DecodeResponse>();

        let join = thread::spawn(move || {
            while let Ok(req) = req_rx.recv() {
                match req {
                    DecodeRequest::PrefetchOnly(index) => {
                        let result = decoder.prefetch(index);
                        if resp_tx
                            .send(DecodeResponse::PrefetchDone(index, result))
                            .is_err()
                        {
                            break;
                        }
                    }
                    DecodeRequest::Full(index) => {
                        let result = decoder
                            .prefetch(index)
                            .and_then(|()| decoder.frame_gpu(index, &device, &queue))
                            .map(|texture| (texture, decoder.last_color_meta()));
                        if resp_tx
                            .send(DecodeResponse::FrameDone(index, result))
                            .is_err()
                        {
                            eprintln!(
                                "[decode-worker] frame={} decode完了もwatchdogは既に諦めていた(遅延完了) thread={:?}",
                                index,
                                thread::current().id()
                            );
                        }
                    }
                }
            }
            eprintln!(
                "[decode-worker] decode thread終了 thread={:?}",
                thread::current().id()
            );
        });

        Self {
            req_tx: Some(req_tx),
            resp_rx,
            join: Some(join),
            hung: false,
        }
    }

    fn prefetch_only(&mut self, frame_index: i64) -> Result<(), String> {
        if self.hung {
            return Err(format!(
                "decoderはhung状態のためprefetch不可 (frame={frame_index})"
            ));
        }
        let Some(req_tx) = self.req_tx.as_ref() else {
            self.hung = true;
            return Err(format!("decode thread終了済み (frame={frame_index})"));
        };
        if req_tx
            .send(DecodeRequest::PrefetchOnly(frame_index))
            .is_err()
        {
            self.hung = true;
            return Err(format!("decode thread消失 (frame={frame_index})"));
        }
        match self.resp_rx.recv_timeout(DECODE_WATCHDOG_TIMEOUT) {
            Ok(DecodeResponse::PrefetchDone(got, result)) if got == frame_index => result,
            Ok(_) => {
                self.hung = true;
                Err(format!("decode thread応答不一致 (frame={frame_index})"))
            }
            Err(RecvTimeoutError::Timeout) => {
                self.hung = true;
                Err(format!(
                    "prefetch watchdog timeout (frame={frame_index}, timeout={DECODE_WATCHDOG_TIMEOUT:?})"
                ))
            }
            Err(RecvTimeoutError::Disconnected) => {
                self.hung = true;
                Err(format!("decode threadとの接続が切断 (frame={frame_index})"))
            }
        }
    }

    fn frame_gpu_watched(
        &mut self,
        frame_index: i64,
    ) -> Result<(wgpu::Texture, ColorMeta), String> {
        if self.hung {
            return Err(format!(
                "decoderは既にwatchdogタイムアウトでhung状態 (frame={frame_index})"
            ));
        }
        let Some(req_tx) = self.req_tx.as_ref() else {
            self.hung = true;
            return Err(format!("decode thread終了済み (frame={frame_index})"));
        };
        if req_tx.send(DecodeRequest::Full(frame_index)).is_err() {
            self.hung = true;
            return Err(format!("decode thread消失 (frame={frame_index})"));
        }
        match self.resp_rx.recv_timeout(DECODE_WATCHDOG_TIMEOUT) {
            Ok(DecodeResponse::FrameDone(got, result)) if got == frame_index => result,
            Ok(_) => {
                self.hung = true;
                Err(format!(
                    "decode thread応答不一致 expected={frame_index} (プロトコル破壊、以後使用不可)"
                ))
            }
            Err(RecvTimeoutError::Timeout) => {
                self.hung = true;
                Err(format!(
                    "decode watchdog timeout (frame={frame_index}, timeout={DECODE_WATCHDOG_TIMEOUT:?})"
                ))
            }
            Err(RecvTimeoutError::Disconnected) => {
                self.hung = true;
                Err(format!(
                    "decode watchdogスレッドとの接続が切断されました (frame={frame_index})"
                ))
            }
        }
    }
}

impl Drop for DecodeThreadHandle {
    fn drop(&mut self) {
        self.req_tx = None;
        if let Some(join) = self.join.take() {
            let _ = join.join();
        }
    }
}

pub struct DecodeWorker {
    generation: u64,
    requested: Arc<AtomicI64>,
    signal: Arc<(Mutex<bool>, Condvar)>,
    store: Arc<Mutex<TextureStore>>,
    last_error: Arc<Mutex<Option<String>>>,

    task: Option<tokio::task::JoinHandle<()>>,
    worker_token: u64,
}

impl DecodeWorker {
    pub fn spawn(
        generation: u64,
        decoder: Box<dyn VideoSource>,
        device: Arc<wgpu::Device>,
        queue: Arc<wgpu::Queue>,
        on_ready: Arc<dyn Fn() + Send + Sync>,
        on_fail: Arc<dyn Fn(String) + Send + Sync>,
    ) -> Self {
        let requested = Arc::new(AtomicI64::new(NONE_SENTINEL));
        let signal = Arc::new((Mutex::new(false), Condvar::new()));
        let store = Arc::new(Mutex::new(TextureStore::new()));
        let last_error = Arc::new(Mutex::new(None));
        let worker_token = NEXT_WORKER_TOKEN.fetch_add(1, Ordering::Relaxed);
        let exact_queue = Arc::new(Mutex::new(VecDeque::new()));

        let requested_t = requested.clone();
        let signal_t = signal.clone();
        let store_t = store.clone();
        let last_error_t = last_error.clone();
        let on_fail_t = on_fail.clone();
        let exact_queue_t = exact_queue.clone();

        let task = super::runtime::handle().spawn_blocking(move || {
            let _token_guard = ActiveWorkerTokenGuard::enter(worker_token);

            let total_frames_t = decoder.total_frames();
            let mut decode_thread = DecodeThreadHandle::spawn(decoder, device, queue);

            let mut served = NONE_SENTINEL;
            let mut direction: i64 = 1;
            let mut consecutive_target_fails: i64 = 0;

            macro_rules! produce {
                ($index:expr, $critical:expr) => {{
                    let index = $index;
                    let critical: bool = $critical;
                    let result = decode_thread.frame_gpu_watched(index);
                    let mut ok = true;
                    match result {
                        Ok((tex, color_meta)) => {
                            store_t.lock().unwrap().put(index, tex, color_meta);
                            *last_error_t.lock().unwrap() = None;
                            if critical {
                                consecutive_target_fails = 0;
                            }
                        }
                        Err(e) => {
                            let msg = format!("decode(frame={index}) failed: {e}");
                            eprintln!("[decode-worker] {msg}");
                            *last_error_t.lock().unwrap() = Some(msg.clone());
                            if decode_thread.hung {
                                on_fail_t(msg);
                                return;
                            }
                            if critical {
                                consecutive_target_fails += 1;
                                if consecutive_target_fails > DECODE_PREFETCH_FAIL_THRESHOLD {
                                    on_fail_t(msg);
                                    return;
                                }
                            }
                            ok = false;
                        }
                    }
                    ok
                }};
            }

            loop {
                let target = {
                    let (lock, cvar) = &*signal_t;
                    let mut pending = lock.lock().unwrap();
                    while !*pending {
                        pending = cvar.wait(pending).unwrap();
                    }
                    *pending = false;
                    requested_t.load(Ordering::Acquire)
                };

                loop {
                    let next_exact = exact_queue_t.lock().unwrap().pop_front();
                    let Some(index) = next_exact else {
                        break;
                    };
                    if store_t.lock().unwrap().contains(index) {
                        on_ready();
                        continue;
                    }
                    if produce!(index, false) {
                        on_ready();
                    }
                }

                if target == STOP_SENTINEL {
                    return;
                }
                if target == served {
                    continue;
                }

                if served != NONE_SENTINEL {
                    direction = if target > served { 1 } else { -1 };
                }

                let already_ready = store_t.lock().unwrap().contains(target);
                if already_ready {
                    served = target;
                    consecutive_target_fails = 0;
                } else if produce!(target, true) {
                    served = target;
                    on_ready();
                }

                let mut farthest_ahead: Option<i64> = None;
                for offset in 1..=PREFETCH_RADIUS {
                    let ahead = target + offset * direction;
                    if ahead < 0 || ahead >= total_frames_t {
                        break;
                    }
                    if !store_t.lock().unwrap().contains(ahead) {
                        farthest_ahead = Some(ahead);
                    }
                }
                if let Some(far) = farthest_ahead
                    && requested_t.load(Ordering::Acquire) == target
                    && let Err(e) = decode_thread.prefetch_only(far)
                {
                    eprintln!(
                        "{}",
                        t!(
                            "[decode-worker] speculative prefetch(frame=%{arg0}) failed: %{arg1}",
                            arg0 = format!("{}", far),
                            arg1 = e.to_string()
                        )
                    );
                    if decode_thread.hung {
                        on_fail_t(e);
                        return;
                    }
                }

                for offset in 1..=PREFETCH_RADIUS {
                    if requested_t.load(Ordering::Acquire) != target {
                        break;
                    }
                    let ahead = target + offset * direction;
                    if ahead < 0 || ahead >= total_frames_t {
                        break;
                    }
                    if store_t.lock().unwrap().contains(ahead) {
                        continue;
                    }
                    if produce!(ahead, false) {
                        on_ready();
                    }
                }
            }
        });

        Self {
            generation,
            requested,
            signal,
            store,
            last_error,
            task: Some(task),
            worker_token,
        }
    }

    pub fn request(&self, frame_index: i64) {
        self.requested.store(frame_index, Ordering::Release);
        let (lock, cvar) = &*self.signal;
        *lock.lock().unwrap() = true;
        cvar.notify_one();
    }

    pub fn poll_texture(&self, frame_index: i64) -> Option<wgpu::Texture> {
        self.store.lock().unwrap().get(frame_index).map(|(t, _)| t)
    }

    pub fn poll_color_meta(&self, frame_index: i64) -> Option<ColorMeta> {
        self.store.lock().unwrap().get(frame_index).map(|(_, m)| m)
    }

    pub fn generation(&self) -> u64 {
        self.generation
    }

    pub fn take_last_error(&self) -> Option<String> {
        self.last_error.lock().unwrap().take()
    }

    pub fn stop_and_join(mut self) {
        self.requested.store(STOP_SENTINEL, Ordering::Release);
        let (lock, cvar) = &*self.signal;
        *lock.lock().unwrap() = true;
        cvar.notify_one();

        if let Some(task) = self.task.take() {
            let is_self = ACTIVE_WORKER_TOKEN.with(|c| c.get()) == Some(self.worker_token);
            if is_self {
                eprintln!(
                    "[decode-worker] stop_and_join自スレッドから呼び出し、同期待機不可のためabortへ縮退"
                );
                task.abort();
                return;
            }
            super::runtime::handle().block_on(async move {
                let _ = task.await;
            });
        }
    }
}

impl Drop for DecodeWorker {
    fn drop(&mut self) {
        self.requested.store(STOP_SENTINEL, Ordering::Release);
        let (lock, cvar) = &*self.signal;
        *lock.lock().unwrap() = true;
        cvar.notify_one();

        if let Some(task) = self.task.take() {
            let is_self = ACTIVE_WORKER_TOKEN.with(|c| c.get()) == Some(self.worker_token);

            if is_self {
                task.abort();
                return;
            }

            super::runtime::handle().spawn(async move {
                let _ = task.await;
            });
        }
    }
}

use std::ffi::CString;
use std::path::Path;
use std::ptr;

use ffmpeg_sys_next as sys;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProbeFailure {
    ContainerOpenFailed,
    NoVideoTrack,
    CodecUnsupported,
    DeviceUnavailable,
    HwFramesCtxUnsupported,
    NeoFrameConversionUnsupported,
}

impl ProbeFailure {
    pub fn message(self) -> &'static str {
        match self {
            Self::ContainerOpenFailed => "ファイルを開けません(コンテナ形式非対応または破損)",
            Self::NoVideoTrack => "映像トラックが見つかりません",
            Self::CodecUnsupported => "非対応のコーデックです",
            Self::DeviceUnavailable => "GPUデコードデバイスが利用できません",
            Self::HwFramesCtxUnsupported => {
                "この映像形式はGPUデコード非対応です(色形式/ビット深度)"
            }
            Self::NeoFrameConversionUnsupported => "GPUフレーム変換が非対応の形式です",
        }
    }
}

#[derive(Debug, Clone)]
pub struct ProbeReport {
    pub width: u32,
    pub height: u32,
    pub codec_name: String,
    pub sw_format_i32: i32,
}

fn pf(fmt: sys::AVPixelFormat) -> i32 {
    fmt as i32
}

fn resolve_hw_sw_format(stream_sw_format: i32) -> Option<i32> {
    let nv12 = pf(sys::AVPixelFormat::AV_PIX_FMT_NV12);
    let yuv420p = pf(sys::AVPixelFormat::AV_PIX_FMT_YUV420P);
    let yuvj420p = pf(sys::AVPixelFormat::AV_PIX_FMT_YUVJ420P);
    let yuv420p10le = pf(sys::AVPixelFormat::AV_PIX_FMT_YUV420P10LE);
    let yuv420p12le = pf(sys::AVPixelFormat::AV_PIX_FMT_YUV420P12LE);
    let p010le = pf(sys::AVPixelFormat::AV_PIX_FMT_P010LE);
    let p012le = pf(sys::AVPixelFormat::AV_PIX_FMT_P012LE);
    let p016le = pf(sys::AVPixelFormat::AV_PIX_FMT_P016LE);
    let rgb0 = pf(sys::AVPixelFormat::AV_PIX_FMT_RGB0);
    let bgr0 = pf(sys::AVPixelFormat::AV_PIX_FMT_BGR0);

    if stream_sw_format == nv12 || stream_sw_format == yuv420p || stream_sw_format == yuvj420p {
        Some(nv12)
    } else if stream_sw_format == yuv420p10le {
        Some(p010le)
    } else if stream_sw_format == yuv420p12le {
        Some(p012le)
    } else if stream_sw_format == p010le
        || stream_sw_format == p012le
        || stream_sw_format == p016le
        || stream_sw_format == rgb0
        || stream_sw_format == bgr0
    {
        Some(stream_sw_format)
    } else {
        None
    }
}

pub fn probe(path: &Path) -> Result<ProbeReport, ProbeFailure> {
    unsafe {
        let mut fmt_ctx: *mut sys::AVFormatContext = ptr::null_mut();
        let c_path = CString::new(path.to_string_lossy().as_bytes())
            .map_err(|_| ProbeFailure::ContainerOpenFailed)?;
        if sys::avformat_open_input(
            &mut fmt_ctx,
            c_path.as_ptr(),
            ptr::null_mut(),
            ptr::null_mut(),
        ) != 0
        {
            return Err(ProbeFailure::ContainerOpenFailed);
        }
        if sys::avformat_find_stream_info(fmt_ctx, ptr::null_mut()) < 0 {
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::ContainerOpenFailed);
        }

        let stream_index = sys::av_find_best_stream(
            fmt_ctx,
            sys::AVMediaType::AVMEDIA_TYPE_VIDEO,
            -1,
            -1,
            ptr::null_mut(),
            0,
        );
        if stream_index < 0 {
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::NoVideoTrack);
        }
        let stream = *(*fmt_ctx).streams.add(stream_index as usize);
        let codecpar = (*stream).codecpar;
        let width = (*codecpar).width.max(0) as u32;
        let height = (*codecpar).height.max(0) as u32;
        let stream_sw_format = std::mem::transmute::<i32, sys::AVPixelFormat>((*codecpar).format);

        let codec = sys::avcodec_find_decoder((*codecpar).codec_id);
        if codec.is_null() {
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::CodecUnsupported);
        }
        let codec_name = std::ffi::CStr::from_ptr((*codec).name)
            .to_string_lossy()
            .into_owned();

        let mut hw_device_ctx: *mut sys::AVBufferRef = ptr::null_mut();
        let ret = sys::av_hwdevice_ctx_create(
            &mut hw_device_ctx,
            sys::AVHWDeviceType::AV_HWDEVICE_TYPE_VAAPI,
            ptr::null(),
            ptr::null_mut(),
            0,
        );
        if ret < 0 || hw_device_ctx.is_null() {
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::DeviceUnavailable);
        }

        let Some(sw_format) = resolve_hw_sw_format(std::mem::transmute::<sys::AVPixelFormat, i32>(
            stream_sw_format,
        )) else {
            sys::av_buffer_unref(&mut hw_device_ctx);
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::HwFramesCtxUnsupported);
        };
        let frames_ref = sys::av_hwframe_ctx_alloc(hw_device_ctx);
        if frames_ref.is_null() {
            sys::av_buffer_unref(&mut hw_device_ctx);
            sys::avformat_close_input(&mut fmt_ctx);
            return Err(ProbeFailure::HwFramesCtxUnsupported);
        }
        let frames_ctx = (*frames_ref).data as *mut sys::AVHWFramesContext;
        (*frames_ctx).format = sys::AVPixelFormat::AV_PIX_FMT_VAAPI;
        (*frames_ctx).sw_format = std::mem::transmute::<i32, sys::AVPixelFormat>(sw_format);
        (*frames_ctx).width = width as i32;
        (*frames_ctx).height = height as i32;
        (*frames_ctx).initial_pool_size = 4;
        let init_ret = sys::av_hwframe_ctx_init(frames_ref);
        let mut frames_ref_mut = frames_ref;
        sys::av_buffer_unref(&mut frames_ref_mut);
        sys::av_buffer_unref(&mut hw_device_ctx);
        sys::avformat_close_input(&mut fmt_ctx);
        if init_ret != 0 {
            return Err(ProbeFailure::HwFramesCtxUnsupported);
        }

        let sw_format_i32 = std::mem::transmute::<sys::AVPixelFormat, i32>(stream_sw_format);

        Ok(ProbeReport {
            width,
            height,
            codec_name,
            sw_format_i32,
        })
    }
}

