#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MatrixCoeffs {
    pub kr: f32,
    pub kb: f32,
}

pub fn matrix_coeffs(mc: MatrixCoefficients) -> MatrixCoeffs {
    match mc {
        MatrixCoefficients::Smpte170m => MatrixCoeffs {
            kr: 0.299,
            kb: 0.114,
        },
        MatrixCoefficients::Bt2020Ncl => MatrixCoeffs {
            kr: 0.2627,
            kb: 0.0593,
        },
        MatrixCoefficients::Bt709 | MatrixCoefficients::Unknown => MatrixCoeffs {
            kr: 0.2126,
            kb: 0.0722,
        },
    }
}

pub fn matrix_index(mc: MatrixCoefficients) -> u32 {
    match mc {
        MatrixCoefficients::Smpte170m => 0,
        MatrixCoefficients::Bt709 | MatrixCoefficients::Unknown => 1,
        MatrixCoefficients::Bt2020Ncl => 2,
    }
}

pub fn range_index(full_range: bool) -> u32 {
    if full_range { 1 } else { 0 }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FilterKind {
    Bilinear,
    Bicubic,
    Lanczos3,
}

pub struct FilterTaps {
    pub offsets: Vec<i32>,
    pub weights: Vec<f32>,
    pub tap_count: usize,
}

fn sinc(x: f32) -> f32 {
    if x.abs() < 1e-6 {
        1.0
    } else {
        (std::f32::consts::PI * x).sin() / (std::f32::consts::PI * x)
    }
}

fn lanczos3(x: f32) -> f32 {
    if x.abs() >= 3.0 {
        0.0
    } else {
        sinc(x) * sinc(x / 3.0)
    }
}

fn bicubic(x: f32) -> f32 {
    let a = -0.5;
    let x = x.abs();
    if x <= 1.0 {
        (a + 2.0) * x.powi(3) - (a + 3.0) * x.powi(2) + 1.0
    } else if x < 2.0 {
        a * x.powi(3) - 5.0 * a * x.powi(2) + 8.0 * a * x - 4.0 * a
    } else {
        0.0
    }
}

fn bilinear(x: f32) -> f32 {
    let x = x.abs();
    if x < 1.0 { 1.0 - x } else { 0.0 }
}

pub fn build_taps(kind: FilterKind, scale_ratio: f32) -> FilterTaps {
    let radius = match kind {
        FilterKind::Bilinear => 1,
        FilterKind::Bicubic => 2,
        FilterKind::Lanczos3 => 3,
    };
    let support = if scale_ratio < 1.0 {
        (radius as f32 / scale_ratio).ceil() as i32
    } else {
        radius
    };
    let mut offsets = Vec::new();
    let mut weights = Vec::new();
    let step = if scale_ratio < 1.0 { scale_ratio } else { 1.0 };
    let mut sum = 0.0f32;
    for i in -support..=support {
        let x = i as f32 * step;
        let w = match kind {
            FilterKind::Bilinear => bilinear(x),
            FilterKind::Bicubic => bicubic(x),
            FilterKind::Lanczos3 => lanczos3(x),
        };
        offsets.push(i);
        weights.push(w);
        sum += w;
    }
    if sum.abs() > 1e-6 {
        for w in weights.iter_mut() {
            *w /= sum;
        }
    }
    let tap_count = offsets.len();
    FilterTaps {
        offsets,
        weights,
        tap_count,
    }
}

use neo_media_core::PixelFormat;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PlaneDesc {
    pub width_shift: u32,
    pub height_shift: u32,
    pub storage_bits: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FormatDesc {
    pub plane_count: usize,
    pub bit_depth: u32,
    pub storage_bits: u32,
    pub planes: [PlaneDesc; 3],
    pub is_rgb: bool,
}

pub fn describe(fmt: PixelFormat) -> FormatDesc {
    const P2: PlaneDesc = PlaneDesc {
        width_shift: 1,
        height_shift: 1,
        storage_bits: 0,
    };
    const P0: PlaneDesc = PlaneDesc {
        width_shift: 0,
        height_shift: 0,
        storage_bits: 0,
    };
    match fmt {
        PixelFormat::Nv12 => FormatDesc {
            plane_count: 2,
            bit_depth: 8,
            storage_bits: 8,
            planes: [P0, P2, P0],
            is_rgb: false,
        },
        PixelFormat::P010 => FormatDesc {
            plane_count: 2,
            bit_depth: 10,
            storage_bits: 16,
            planes: [P0, P2, P0],
            is_rgb: false,
        },
        PixelFormat::P012 => FormatDesc {
            plane_count: 2,
            bit_depth: 12,
            storage_bits: 16,
            planes: [P0, P2, P0],
            is_rgb: false,
        },
        PixelFormat::P016 => FormatDesc {
            plane_count: 2,
            bit_depth: 16,
            storage_bits: 16,
            planes: [P0, P2, P0],
            is_rgb: false,
        },
        PixelFormat::Yuv420p => FormatDesc {
            plane_count: 3,
            bit_depth: 8,
            storage_bits: 8,
            planes: [P0, P2, P2],
            is_rgb: false,
        },
        PixelFormat::Yuv444 => FormatDesc {
            plane_count: 3,
            bit_depth: 8,
            storage_bits: 8,
            planes: [P0, P0, P0],
            is_rgb: false,
        },
        PixelFormat::Rgba8 => FormatDesc {
            plane_count: 1,
            bit_depth: 8,
            storage_bits: 8,
            planes: [P0, P0, P0],
            is_rgb: true,
        },
        PixelFormat::Rgba16Float => FormatDesc {
            plane_count: 1,
            bit_depth: 16,
            storage_bits: 16,
            planes: [P0, P0, P0],
            is_rgb: true,
        },
    }
}

pub fn normalize_shift(desc: FormatDesc) -> u32 {
    desc.storage_bits - desc.bit_depth
}

pub fn normalize_max(desc: FormatDesc) -> f32 {
    ((1u32 << desc.bit_depth) - 1) as f32
}

