}

static inline void neoutl_pack_uniform_std(const float* params, uint32_t count, uint8_t* out_ptr) {
    uint32_t total = neoutl_uniform_size_std(count);
    memset(out_ptr, 0, total);
    if (params && count > 0) {
        memcpy(out_ptr, params, count * sizeof(float));
    }
