[package]
name = "neoutl-sdk"
version = "0.7.5"
edition = "2024"
description = "Official all-in-one SDK for NeoUtl plugin development (Objects, Effects, Easing, Expressions, Extensions)"
license = "GPL-3.0"
authors = ["NeoUtl Core Team"]

[dependencies]
neoutl-shared-abi = { path = "../../../../crates/core/shared-abi" }
neoutl-object-api = { path = "../../../../crates/object/api" }
neoutl-effect-api = { path = "../../../../crates/effect/api" }
