    /* is_dummy: */               0,
    /* use_composition_camera: */ 0
};

/* Embedded WGSL Fragment Shader */
static const char s_wgsl[] =
    "struct VOut { @builtin(position) position: vec4<f32>, @location(0) uv: vec2<f32>, };\n"
    "struct Uniforms { factor: f32, };\n"
    "@group(0) @binding(0) var t_diffuse: texture_2d<f32>;\n"
    "@group(0) @binding(1) var s_diffuse: sampler;\n"
    "@group(0) @binding(2) var<uniform> u: Uniforms;\n"
    "@group(0) @binding(3) var t_aux: texture_2d<f32>;\n"
    "@group(0) @binding(4) var s_aux: sampler;\n"
    "@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VOut {\n"
    "    var out: VOut; let p = vec2<f32>(f32((i << 1u) & 2u), f32(i & 2u));\n"
    "    out.position = vec4<f32>(p * vec2<f32>(2.0, -2.0) + vec2<f32>(-1.0, 1.0), 0.0, 1.0); out.uv = p; return out;\n"
    "}\n"
    "\n"
    "@fragment\n"
    "fn fs_main(in: VOut) -> @location(0) vec4<f32> {\n"
    "    let color = textureSample(t_diffuse, s_diffuse, in.uv);\n"
    "    let inverted = vec3<f32>(1.0 - color.r, 1.0 - color.g, 1.0 - color.b);\n"
    "    return vec4<f32>(mix(color.rgb, inverted, u.factor), color.a);\n"
    "}\n";

