    const neoutl_cache_handle_t* cache, const void* identifier, const char* name,
    uint32_t width, uint32_t height) {
    if (!cache || !cache->create_image) {
        neoutl_cache_image_ref_t empty = { neoutl_resource_cache(NULL), 0, 0, 0 };
        return empty;
    }
    return cache->create_image(identifier, neoutl_str_ref_make(name), width, height);
}
static inline void neoutl_cache_clear_image(
    const neoutl_cache_handle_t* cache, const void* identifier, const char* name) {
    if (cache && cache->clear_image) {
        cache->clear_image(identifier, neoutl_str_ref_make(name));
