serde = { version = "1", features = ["derive"] }
serde_json = "1"

use neoutl_sdk::prelude::*;
use std::sync::OnceLock;

static PARAMS: &[EffectParamSchema] = &[
    float_param("amount", "Amount", 0.0, 1.0, 0.01, 0.5),
    bool_param("enabled", "Enabled", true),
    enum_param("mode", "Mode", enum_options!("soft", "hard"), 0),
];
static META: EffectMeta = EffectMetaBuilder::new(
    "com.example.tint",
    "Example Tint",
    "Color",
    PARAMS,
    EffectKind::Image,
)
.author("Example Author")
.uuid("com.example.tint")
.build();
static SHADER: &[u8] = br#"
struct VOut { @builtin(position) position: vec4<f32>, @location(0) uv: vec2<f32>, };
struct Uniforms { amount: f32, enabled: f32, mode: f32, };
@group(0) @binding(0) var source: texture_2d<f32>;
@group(0) @binding(1) var source_sampler: sampler;
@group(0) @binding(2) var<uniform> u: Uniforms;
@group(0) @binding(3) var aux: texture_2d<f32>;
@group(0) @binding(4) var aux_sampler: sampler;
@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VOut {
    var out: VOut; let p = vec2<f32>(f32((i << 1u) & 2u), f32(i & 2u));
    out.position = vec4<f32>(p * vec2<f32>(2.0, -2.0) + vec2<f32>(-1.0, 1.0), 0.0, 1.0); out.uv = p; return out;
}
@fragment fn fs_main(in: VOut) -> @location(0) vec4<f32> {
    let color = textureSample(source, source_sampler, in.uv);
    return vec4<f32>(mix(color.rgb, color.bgr, u.amount), color.a);
}
"#;
static VTABLE: OnceLock<EffectVTable> = OnceLock::new();

unsafe extern "C" fn meta() -> *const EffectMeta {
    &raw const META
}
unsafe extern "C" fn wgsl() -> WgslSource {
    ffi_slice(SHADER)
}
unsafe extern "C" fn uniform_size() -> u32 {
    uniform_size_std(PARAMS.len() as u32)
}
unsafe extern "C" fn pack_uniform(params: *const f32, count: u32, out: *mut u8) {
    unsafe { pack_uniform_std(params, count, out) }
}

fn vtable() -> *const EffectVTable {
    VTABLE.get_or_init(|| EffectVTableBuilder::new(meta, wgsl, uniform_size, pack_uniform).build())
}
neoutl_sdk::export_effect!(vtable);

fn main() {}

