    "com.example.shape",
    "Example Shape",
    Dimensionality::TwoD,
    GROUPS,
)
.build();
static SHADER: &[u8] = br#"
struct Uniforms { mvp: mat4x4<f32>, opacity: f32, sides: f32, extrude_depth: f32, pad: f32, fill_color: vec4<f32>, };
@group(0) @binding(0) var<uniform> u: Uniforms;
struct VOut { @builtin(position) position: vec4<f32>, @location(0) color: vec4<f32>, };
@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VOut {
    var p = array<vec2<f32>, 3>(vec2<f32>(0.0, 0.5), vec2<f32>(-0.5, -0.5), vec2<f32>(0.5, -0.5));
    var o: VOut; o.position = u.mvp * vec4<f32>(p[i], 0.0, 1.0); o.color = vec4<f32>(0.2, 0.6, 1.0, u.opacity); return o;
}
@fragment fn fs_main(in: VOut) -> @location(0) vec4<f32> { return in.color; }
"#;
static VTABLE: OnceLock<ObjectVTable> = OnceLock::new();

unsafe extern "C" fn meta() -> *const ObjectMeta {
    &raw const META
