    ffi_slice(SHADER)
}
unsafe extern "C" fn render(ctx: *const RenderContext) {
    if let Some(ctx) = unsafe { ctx.as_ref() } {
        let view = unsafe { ObjectRenderContext::from_raw(ctx) };
        let _opacity = view.opacity();
    }
}
fn vtable() -> *const ObjectVTable {
    VTABLE.get_or_init(|| ObjectVTableBuilder::new(meta, vertex_count, wgsl, render).build())
