//! NeoUtl Shared ABI types and low-level data structures.

pub use neoutl_shared_abi::{
    AcceleratorBackend, AcceleratorHandle, CacheHandle, CacheImageRef, ComputeDispatch,
    Dimensionality, EffectKind, FfiSlice, ParamKind, ParamRowOwned, ParamSchema, PropertyWriteback,
    ResourceKind, ResourceRef, Roi, ShaderStage, StrRef, WgslSource, split_enum_options,
};

/// Helper function to create a static StrRef from a string literal.
#[inline(always)]
pub const fn str_ref(s: &'static str) -> StrRef {
    StrRef::from_str(s)
}

/// Helper function to create an empty StrRef.
#[inline(always)]
pub const fn empty_str_ref() -> StrRef {
    StrRef::empty()
}

/// Helper function to create an FfiSlice from a static slice.
#[inline(always)]
pub const fn ffi_slice<T>(items: &'static [T]) -> FfiSlice<T> {
    FfiSlice::from_static(items)
}

/// Builds a floating-point parameter schema entry.
pub const fn float_param(
    key: &'static str,
    label: &'static str,
    min: f32,
    max: f32,
    step: f32,
    default: f32,
) -> ParamSchema {
    ParamSchema {
        key: str_ref(key),
        label: str_ref(label),
        kind: ParamKind::Float,
        min,
        max,
        step,
        default_float: default,
