        default_float: 0.0,
        enum_options: empty_str_ref(),
    }
}

/// Creates a compile-time NUL-separated enum option list.
#[macro_export]
macro_rules! enum_options {
    ($last:literal $(,)?) => { $crate::abi::str_ref($last) };
    ($first:literal, $($rest:literal),+ $(,)?) => {
        $crate::abi::str_ref(concat!($first, "\0", $crate::__enum_options_join!($($rest),+)))
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __enum_options_join {
    ($last:literal) => { $last };
    ($first:literal, $($rest:literal),+) => {
        concat!($first, "\0", $crate::__enum_options_join!($($rest),+))
    };
}

/// Builds a schema entry for any ABI parameter kind, including host-specific marker kinds.
#[allow(clippy::too_many_arguments)]
pub const fn param_schema(
    key: &'static str,
    label: &'static str,
    kind: ParamKind,
    min: f32,
    max: f32,
    step: f32,
    default: f32,
    enum_options: StrRef,
) -> ParamSchema {
    ParamSchema {
        key: str_ref(key),
        label: str_ref(label),
        kind,
        min,
        max,
        step,
        default_float: default,
        enum_options,
    }
}

/// Builds a per-layer boolean section parameter.
pub const fn check_section_param(
    key: &'static str,
    label: &'static str,
    default: bool,
) -> ParamSchema {
    let mut schema = bool_param(key, label, default);
    schema.kind = ParamKind::CheckSection;
    schema
}

