/// Borrowed effect parameter values received by an ABI callback.
#[derive(Clone, Copy)]
pub struct EffectParams<'a>(&'a [f32]);

impl<'a> EffectParams<'a> {
    /// Creates a borrowed view over callback parameters.
    ///
    /// # Safety
    /// For nonzero `count`, `ptr` must address `count` initialized `f32` values
    /// that remain valid for the returned borrow.
    pub unsafe fn from_raw(ptr: *const f32, count: u32) -> Option<Self> {
        if count == 0 {
            return Some(Self(&[]));
        }
        if ptr.is_null() {
            return None;
        }
        Some(Self(unsafe {
            core::slice::from_raw_parts(ptr, count as usize)
        }))
    }
    pub fn as_slice(self) -> &'a [f32] {
        self.0
    }
    pub fn get(self, index: usize) -> Option<f32> {
        self.0.get(index).copied()
    }
    pub fn len(self) -> usize {
        self.0.len()
    }
    pub fn is_empty(self) -> bool {
        self.0.is_empty()
    }
}

impl core::ops::Deref for EffectParams<'_> {
    type Target = [f32];
    fn deref(&self) -> &Self::Target {
        self.0
    }
}

/// Nonzero status returned by a host GPU resource operation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RenderError {
    Host(u32),
    InvalidDimensions,
    InvalidPitch { minimum: u32, provided: u32 },
    BufferTooSmall { required: usize, provided: usize },
    SizeOverflow,
    TooManyResources,
}

/// Lifetime-bound safe access to render operations provided to a custom effect callback.
/// Construct this only while the host render context is valid.
#[derive(Clone, Copy)]
pub struct EffectRenderApi<'a>(&'a EffectRenderContext);

impl<'a> EffectRenderApi<'a> {
    /// # Safety
    /// `ctx` must point to a fully initialized context that remains valid for `'a`.
    pub unsafe fn from_raw(ctx: *const EffectRenderContext) -> Option<Self> {
        unsafe { ctx.as_ref() }.map(Self)
    }

    pub fn cache(self) -> Option<EffectCache<'a>> {
        let handle = unsafe { self.0.cache.as_ref() }?;
        Some(EffectCache {
            handle,
            identifier: self.0.cache_identifier,
        })
    }

    pub fn exec_pixelshader(
        self,
        data: &[u8],
        target: ResourceRef,
        resources: &[ResourceRef],
        constants: &[u8],
    ) -> Result<(), RenderError> {
        let resource_count =
            u32::try_from(resources.len()).map_err(|_| RenderError::TooManyResources)?;
        let status = unsafe {
            (self.0.exec_pixelshader)(
                data.as_ptr(),
                data.len(),
                target,
                resources.as_ptr(),
                resource_count,
                constants.as_ptr(),
                constants.len(),
            )
        };
        if status == 0 {
            Ok(())
        } else {
            Err(RenderError::Host(status))
        }
    }

    pub fn exec_computeshader(
        self,
        data: &[u8],
        targets: &[ResourceRef],
        resources: &[ResourceRef],
        constants: &[u8],
        dispatch: ComputeDispatch,
    ) -> Result<(), RenderError> {
        let target_count =
            u32::try_from(targets.len()).map_err(|_| RenderError::TooManyResources)?;
        let resource_count =
            u32::try_from(resources.len()).map_err(|_| RenderError::TooManyResources)?;
        let status = unsafe {
            (self.0.exec_computeshader)(
                data.as_ptr(),
                data.len(),
                targets.as_ptr(),
                target_count,
                resources.as_ptr(),
                resource_count,
                constants.as_ptr(),
                constants.len(),
                dispatch,
            )
        };
        if status == 0 {
            Ok(())
        } else {
            Err(RenderError::Host(status))
        }
    }

    pub fn resource_size(self, resource: ResourceRef) -> Result<[u32; 2], RenderError> {
        let (mut width, mut height) = (0, 0);
        let status = unsafe { (self.0.get_resource_size)(resource, &mut width, &mut height) };
        if status == 0 {
            Ok([width, height])
        } else {
            Err(RenderError::Host(status))
        }
    }

    pub fn get_resource_data(
        self,
        resource: ResourceRef,
        buffer: &mut [u8],
        width: u32,
        height: u32,
        pitch: u32,
    ) -> Result<(), RenderError> {
        validate_buffer_len(buffer.len(), width, height, pitch)?;
        let status = unsafe {
            (self.0.get_resource_data)(resource, buffer.as_mut_ptr(), width, height, pitch)
        };
        if status == 0 {
            Ok(())
        } else {
            Err(RenderError::Host(status))
        }
    }

    pub fn set_resource_data(
        self,
        resource: ResourceRef,
        buffer: &[u8],
        width: u32,
        height: u32,
        pitch: u32,
    ) -> Result<(), RenderError> {
        validate_buffer_len(buffer.len(), width, height, pitch)?;
        let status =
            unsafe { (self.0.set_resource_data)(resource, buffer.as_ptr(), width, height, pitch) };
        if status == 0 {
            Ok(())
        } else {
            Err(RenderError::Host(status))
        }
    }

    pub fn release_resource(self, resource: ResourceRef) -> Result<(), RenderError> {
        let status = unsafe { (self.0.release_resource)(resource) };
        if status == 0 {
            Ok(())
        } else {
            Err(RenderError::Host(status))
        }
    }
}

fn validate_buffer_len(len: usize, width: u32, height: u32, pitch: u32) -> Result<(), RenderError> {
    if width == 0 || height == 0 {
        return Err(RenderError::InvalidDimensions);
    }
    let minimum_pitch = width.checked_mul(4).ok_or(RenderError::SizeOverflow)?;
    if pitch < minimum_pitch {
        return Err(RenderError::InvalidPitch {
            minimum: minimum_pitch,
            provided: pitch,
        });
    }
    let required = (height as usize)
        .checked_mul(pitch as usize)
        .ok_or(RenderError::SizeOverflow)?;
    if len < required {
        Err(RenderError::BufferTooSmall {
            required,
            provided: len,
        })
    } else {
        Ok(())
    }
}

/// Namespace-aware VRAM image cache access for one effect instance.
#[derive(Clone, Copy)]
pub struct EffectCache<'a> {
    handle: &'a CacheHandle,
    identifier: *const (),
}

impl EffectCache<'_> {
    pub fn get_image(&self, name: &str) -> CacheImageRef {
        unsafe { (self.handle.get_image)(self.identifier, borrowed_str_ref(name)) }
    }
    pub fn create_image(&self, name: &str, width: u32, height: u32) -> CacheImageRef {
        unsafe {
            (self.handle.create_image)(self.identifier, borrowed_str_ref(name), width, height)
        }
    }
    pub fn clear_image(&self, name: &str) {
        unsafe { (self.handle.clear_image)(self.identifier, borrowed_str_ref(name)) }
    }
}

fn borrowed_str_ref(value: &str) -> StrRef {
    StrRef {
        ptr: value.as_ptr(),
        len: value.len(),
    }
}

