/// スクリプトから渡される引数、または関数が返す値。
#[derive(Clone, Debug)]
pub enum ScriptValue {
    Nil,
    Boolean(bool),
    Integer(i64),
    Number(f64),
    String(String),
}

/// スクリプト関数の引数リストへの読み取り専用アクセス。
#[derive(Clone, Copy)]
pub struct ScriptArgs<'a> {
    values: &'a [ScriptValue],
}

impl<'a> ScriptArgs<'a> {
    pub fn new(values: &'a [ScriptValue]) -> Self {
        Self { values }
    }

    pub fn len(&self) -> usize {
        self.values.len()
    }

    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }

    pub fn get_integer(&self, index: usize) -> Option<i64> {
        match self.values.get(index) {
            Some(ScriptValue::Integer(v)) => Some(*v),
            Some(ScriptValue::Number(v)) => Some(*v as i64),
            _ => None,
        }
    }

    pub fn get_number(&self, index: usize) -> Option<f64> {
        match self.values.get(index) {
            Some(ScriptValue::Number(v)) => Some(*v),
            Some(ScriptValue::Integer(v)) => Some(*v as f64),
            _ => None,
        }
    }

    pub fn get_string(&self, index: usize) -> Option<&str> {
        match self.values.get(index) {
            Some(ScriptValue::String(v)) => Some(v.as_str()),
            _ => None,
        }
    }

    pub fn get_boolean(&self, index: usize) -> Option<bool> {
        match self.values.get(index) {
            Some(ScriptValue::Boolean(v)) => Some(*v),
            _ => None,
        }
    }
}

/// スクリプトから呼び出される関数。戻り値の `Ok` は結果値の並び、`Err` はエラーメッセージ。
pub type ScriptFn = fn(&ScriptArgs) -> Result<Vec<ScriptValue>, String>;

/// スクリプトへ公開する関数の登録単位。`name` はLua側から見える識別子。
#[derive(Clone, Copy)]
pub struct ScriptFunctionDescriptor {
    pub name: &'static str,
    pub func: ScriptFn,
}

#[derive(Clone, Debug)]
pub struct CommandDescriptor {
    pub id: String,
    pub name: String,
    pub description: String,
    pub default_shortcut: Option<String>,
}

#[derive(Clone, Debug)]
pub struct FileDropDescriptor {
    pub name: String,
    pub file_extensions: Vec<String>,
}

pub struct ExtensionContext<'a> {
    pub plugin_id: &'a str,
    pub storage: &'a mut ProjectStorage,
    pub edit_session: Option<&'a mut dyn EditSession>,
    pub registered_panels: &'a mut Vec<PanelDescriptor>,
    pub registered_menus: &'a mut Vec<MenuItemDescriptor>,
    pub registered_commands: &'a mut Vec<CommandDescriptor>,
    pub registered_file_drops: &'a mut Vec<FileDropDescriptor>,
    pub registered_script_functions: &'a mut Vec<ScriptFunctionDescriptor>,
    pub toast_messages: &'a mut Vec<String>,
    pub outgoing_events: &'a mut Vec<ExtensionEvent>,
}

impl<'a> ExtensionContext<'a> {
    pub fn register_panel(&mut self, descriptor: PanelDescriptor) {
        self.registered_panels.push(descriptor);
    }

    pub fn register_menu(&mut self, item: MenuItemDescriptor) {
        self.registered_menus.push(item);
    }

    pub fn register_command(&mut self, descriptor: CommandDescriptor) {
        self.registered_commands.push(descriptor);
    }

    pub fn register_file_drop(&mut self, descriptor: FileDropDescriptor) {
        self.registered_file_drops.push(descriptor);
    }

    /// スクリプト(Lua)から呼び出せる関数を登録する。`name` はプラグイン間で一意である必要がある。
    pub fn register_script_function(&mut self, descriptor: ScriptFunctionDescriptor) {
        self.registered_script_functions.push(descriptor);
    }

    pub fn show_toast(&mut self, message: impl Into<String>) {
        self.toast_messages.push(message.into());
    }

    pub fn broadcast_event(&mut self, name: impl Into<String>, payload: serde_json::Value) {
        self.outgoing_events.push(ExtensionEvent::Custom {
            sender: self.plugin_id.to_owned(),
            name: name.into(),
            payload,
        });
    }
}

pub trait ExtensionPlugin: Send + Sync {
    fn metadata(&self) -> ExtensionMetadata;

    fn init(&mut self, ctx: &mut ExtensionContext) -> Result<(), String>;

    #[allow(unused_variables)]
    fn ui(&mut self, panel_id: &str, ui: &mut egui::Ui, ctx: &mut ExtensionContext) {}

    #[allow(unused_variables)]
    fn on_event(&mut self, event: &ExtensionEvent, ctx: &mut ExtensionContext) {}

    #[allow(unused_variables)]
    fn on_command(&mut self, command_id: &str, ctx: &mut ExtensionContext) -> Result<(), String> {
        Ok(())
    }

    #[allow(unused_variables)]
    fn on_file_drop(
        &mut self,
        path: &str,
        layer: i32,
        frame: i32,
        ctx: &mut ExtensionContext,
    ) -> bool {
        false
    }

    #[allow(unused_variables)]
    fn draw_preview_overlay(
        &mut self,
        overlay: &mut PreviewOverlayContext,
        ctx: &mut ExtensionContext,
    ) {
    }

    #[allow(unused_variables)]
    fn draw_timeline_overlay(
        &mut self,
        overlay: &mut TimelineOverlayContext,
        ctx: &mut ExtensionContext,
    ) {
    }

    #[allow(unused_variables)]
    fn shutdown(&mut self, ctx: &mut ExtensionContext) {}
}

//! # NeoUtl All-In-One SDK (v0.8.9)
//!
//! The official Rust SDK for extending NeoUtl with:
//! - **Extensions (Super-Mods)**: Custom egui panels, floating windows, timeline transactions, canvas overlays, and file drop handlers.
//! - **Effects**: Hardware-accelerated WGSL video filters, transitions, and audio DSP.
//! - **Objects**: Custom timeline media elements, 2D/3D procedural shapes, and shaders.
//! - **Easing Engines**: Custom interpolation curves, easing algorithms, and UI curve editors.
//! - **Expression Engines**: Custom formula parsers, scripting runtimes, and parameter math.
//!
//! ## Quick Start: Writing an Extension Plugin
//!
//! ```rust,ignore
//! use neoutl_sdk::prelude::*;
//!
//! #[derive(Default)]
//! pub struct MyToolExtension;
//!
//! impl ExtensionPlugin for MyToolExtension {
//!     fn metadata(&self) -> ExtensionMetadata {
//!         ExtensionMetadata::new("com.example.my_tool", "My Custom Tool")
//!     }
//!
//!     fn init(&mut self, ctx: &mut ExtensionContext) -> Result<(), String> {
//!         ctx.register_panel(PanelDescriptor {
//!             id: "my_tool_panel".to_owned(),
//!             title: "My Tool".to_owned(),
//!             default_size: [300.0, 200.0],
//!             default_open: true,
//!             placement: PanelPlacement::FloatingWindow,
//!         });
//!         Ok(())
//!     }
//!
//!     fn ui(&mut self, panel_id: &str, ui: &mut egui::Ui, ctx: &mut ExtensionContext) {
//!         if panel_id == "my_tool_panel" {
//!             ui.label("Hello from NeoUtl Extension!");
//!             if ui.button("Create Text Clip").clicked() {
//!                 if let Some(session) = &mut ctx.edit_session {
//!                     let _ = session.create_text_object("Hello NeoUtl", 1, 0, 150);
//!                 }
//!             }
//!         }
//!     }
//! }
//!
//! neoutl_sdk::export_extension!(MyToolExtension);
//! ```
//!
//! ## Quick Start: Writing a Video Effect Plugin
//!
//! ```rust,ignore
//! use neoutl_sdk::prelude::*;
//! use std::sync::OnceLock;
//!
//! static PARAM_SCHEMA: &[EffectParamSchema] = &[
//!     float_param("intensity", "強度", 0.0, 1.0, 0.01, 0.5),
//! ];
//!
//! static META: EffectMeta = EffectMetaBuilder::new(
//!     "my_effect", "My Custom Effect", "Filter", PARAM_SCHEMA, EffectKind::Image,
//! ).author("Author").uuid("com.example.my_effect").build();
//!
//! static WGSL: &[u8] = b"/* WGSL Shader code */";
//! static VTABLE: OnceLock<EffectVTable> = OnceLock::new();
//!
//! unsafe extern "C" fn meta() -> *const EffectMeta { &raw const META }
//! unsafe extern "C" fn wgsl() -> WgslSource { WgslSource { ptr: WGSL.as_ptr(), len: WGSL.len() } }
//! unsafe extern "C" fn uniform_size() -> u32 { uniform_size_std(PARAM_SCHEMA.len() as u32) }
//! unsafe extern "C" fn pack_uniform(params_ptr: *const f32, count: u32, out_ptr: *mut u8) {
//!     unsafe { pack_uniform_std(params_ptr, count, out_ptr) }
//! }
//!
//! pub fn get_vtable() -> *const EffectVTable {
//!     VTABLE.get_or_init(|| EffectVTableBuilder::new(meta, wgsl, uniform_size, pack_uniform).build())
//! }
//!
//! neoutl_sdk::export_effect!(get_vtable);
//! ```

pub mod abi;
