//! Macros for exporting NeoUtl plugin entry points.

/// Exports an Extension plugin entry point (`neoutl_extension_create`).
///
/// # Example
/// ```rust,ignore
/// #[derive(Default)]
/// struct MySuperPlugin;
/// impl ExtensionPlugin for MySuperPlugin { ... }
///
/// neoutl_sdk::export_extension!(MySuperPlugin);
/// ```
#[macro_export]
macro_rules! export_extension {
    ($plugin_ty:ty) => {
        #[unsafe(no_mangle)]
        pub fn neoutl_extension_create() -> Box<dyn $crate::extension::ExtensionPlugin> {
            Box::new(<$plugin_ty as ::std::default::Default>::default())
        }
    };
    (new: $constructor:expr) => {
        #[unsafe(no_mangle)]
        pub fn neoutl_extension_create() -> Box<dyn $crate::extension::ExtensionPlugin> {
            Box::new($constructor)
        }
    };
}

/// Exports an Effect plugin entry point (`neoutl_effect_entry_v2`).
///
/// # Example
/// ```rust,ignore
/// neoutl_sdk::export_effect!(get_vtable);
/// ```
#[macro_export]
macro_rules! export_effect {
    ($vtable_getter:path) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn neoutl_effect_entry_v2() -> *const $crate::effect::EffectVTable {
            $vtable_getter()
        }
    };
}

