/// Const-friendly builder for object metadata.
pub struct ObjectMetaBuilder {
    stable_id: &'static str,
    name: &'static str,
    dimensionality: Dimensionality,
    groups: FfiSlice<PropertyGroup>,
}

impl ObjectMetaBuilder {
    pub const fn new(
        stable_id: &'static str,
        name: &'static str,
        dimensionality: Dimensionality,
        groups: &'static [PropertyGroup],
    ) -> Self {
        Self {
            stable_id,
            name,
            dimensionality,
            groups: FfiSlice::from_static(groups),
        }
    }
    pub const fn build(self) -> ObjectMeta {
        ObjectMeta {
            stable_id: StrRef::from_str(self.stable_id),
            name: StrRef::from_str(self.name),
            dimensionality: self.dimensionality,
            property_groups: self.groups,
        }
    }
}

/// Creates a property group backed by a static schema slice.
pub const fn property_group(id: &'static str, schema: &'static [ParamSchema]) -> PropertyGroup {
    PropertyGroup {
        group_id: StrRef::from_str(id),
        schema: FfiSlice::from_static(schema),
    }
}

/// Builder that initializes optional object callbacks to `None`.
pub struct ObjectVTableBuilder {
    meta: unsafe extern "C" fn() -> *const ObjectMeta,
    vertex_count: unsafe extern "C" fn() -> u32,
    wgsl: unsafe extern "C" fn() -> WgslSource,
    render: unsafe extern "C" fn(*const RenderContext),
    read_ref_layer: Option<unsafe extern "C" fn(*const RenderContext, u32) -> *const ()>,
    setup_accelerator: Option<unsafe extern "C" fn(*const AcceleratorHandle) -> u32>,
}

impl ObjectVTableBuilder {
    pub const fn new(
        meta: unsafe extern "C" fn() -> *const ObjectMeta,
        vertex_count: unsafe extern "C" fn() -> u32,
        wgsl: unsafe extern "C" fn() -> WgslSource,
        render: unsafe extern "C" fn(*const RenderContext),
    ) -> Self {
        Self {
            meta,
            vertex_count,
            wgsl,
            render,
            read_ref_layer: None,
            setup_accelerator: None,
        }
    }
    pub const fn read_ref_layer(
        mut self,
        f: unsafe extern "C" fn(*const RenderContext, u32) -> *const (),
    ) -> Self {
        self.read_ref_layer = Some(f);
        self
    }
    pub const fn setup_accelerator(
        mut self,
        f: unsafe extern "C" fn(*const AcceleratorHandle) -> u32,
    ) -> Self {
        self.setup_accelerator = Some(f);
        self
    }
    pub const fn build(self) -> ObjectVTable {
        ObjectVTable {
            meta: self.meta,
            vertex_count: self.vertex_count,
            wgsl: self.wgsl,
            render: self.render,
            read_ref_layer: self.read_ref_layer,
            setup_accelerator: self.setup_accelerator,
        }
    }
}

/// A borrowed view of the raw context passed to an object render callback.
/// The GPU pointers remain opaque; interpreting or dereferencing them requires
/// the renderer's matching graphics API and is unsafe.
#[derive(Clone, Copy)]
pub struct ObjectRenderContext<'a>(&'a RenderContext);

impl<'a> ObjectRenderContext<'a> {
    /// # Safety
    /// `raw` must be a valid context for the duration of `'a`.
    pub unsafe fn from_raw(raw: &'a RenderContext) -> Self {
        Self(raw)
    }
    pub fn raw(self) -> &'a RenderContext {
        self.0
    }
    pub fn version(self) -> u32 {
        self.0.version
    }
    pub fn render_pass_ptr(self) -> *mut () {
        self.0.render_pass_ptr
    }
    pub fn bind_group_ptr(self) -> *const () {
        self.0.bind_group_ptr
    }
    pub fn mvp_matrix(self) -> &'a [f32; 16] {
        &self.0.mvp_matrix
    }
    pub fn vertex_count(self) -> u32 {
        self.0.vertex_count
    }
    pub fn opacity(self) -> f32 {
        self.0.opacity
    }
    pub fn depth_enabled(self) -> bool {
        self.0.depth_enabled
    }
    pub fn ref_layer_texture_ptr(self) -> *const () {
        self.0.ref_layer_texture_ptr
    }
    pub fn ref_layer_texture_count(self) -> u32 {
        self.0.ref_layer_texture_count
    }
}

