use libloading::{Library, Symbol};
use neoutl_easing_api::{ENTRY_SYMBOL, EasingEngineMeta, EasingEngineVTable, EntryFn, KeyframeC};
use neoutl_shared_abi::PluginError;
use std::{
    ffi::OsStr,
    path::{Path, PathBuf},
    sync::OnceLock,
};

pub struct EasingPlugin {
    pub id: String,
    pub name: String,
    pub vtable: &'static EasingEngineVTable,
    _lib: Option<Library>,
}

impl EasingPlugin {
    pub fn evaluate(&self, keyframes: &[(i32, f32, Vec<u8>)], frame: i32, fallback: f32) -> f32 {
        let mut keyframes_c = Vec::with_capacity(keyframes.len());
        for (f, v, payload) in keyframes {
            keyframes_c.push(KeyframeC {
                frame: *f,
                value: *v,
                payload_ptr: if payload.is_empty() {
                    std::ptr::null()
                } else {
                    payload.as_ptr()
                },
                payload_len: payload.len(),
            });
        }

        unsafe { (self.vtable.evaluate)(keyframes_c.as_ptr(), keyframes_c.len(), frame, fallback) }
    }
}

fn read_meta_strings(meta: &'static EasingEngineMeta) -> (String, String) {
    unsafe { (meta.id.as_str().to_owned(), meta.name.as_str().to_owned()) }
}

static REGISTRY: OnceLock<Vec<EasingPlugin>> = OnceLock::new();

pub fn load_all(easings_dir: &Path) {
    REGISTRY.get_or_init(|| {
        let mut plugins = Vec::new();

        let builtin_vtable = unsafe { &*neoutl_easing_standard::neoutl_easing_engine_entry() };
        let meta = unsafe { &*((builtin_vtable.meta)()) };
        let (builtin_id, builtin_name) = read_meta_strings(meta);
        plugins.push(EasingPlugin {
            id: builtin_id,
            name: builtin_name,
            vtable: builtin_vtable,
            _lib: None,
        });

        let candidates: Vec<PathBuf> = match std::fs::read_dir(easings_dir) {
            Ok(entries) => entries
                .flatten()
                .map(|e| e.path())
                .filter(|p| is_dylib(p))
                .collect(),
            Err(err) => {
                eprintln!(
                    "{}",
                    t!(
                        "[NeoUtl] easings/ 読み込み通知: %{arg0} (組み込み標準エンジンのみ使用)",
                        arg0 = format!("{}", err)
                    )
                );
                Vec::new()
            }
        };

        for path in &candidates {
            match load_one(path) {
                Ok(p) => {
                    if !plugins.iter().any(|existing| existing.id == p.id) {
                        plugins.push(p);
                    }
                }
                Err(err) => {
                    eprintln!(
                        "{}",
                        t!(
                            "[NeoUtl] イージングエンジン読み込み失敗 %{arg0}: %{arg1}",
                            arg1 = format!("{}", err)
                        )
                    );
                }
            }
        }

        plugins.sort_by(|a, b| a.id.cmp(&b.id));
        for plugin in &plugins {
            eprintln!(
                "{}",
                t!(
                    "[NeoUtl] イージングエンジン登録: %{arg0} (%{arg1})",
                    arg0 = plugin.id,
                    arg1 = plugin.name
                )
            );
        }
        plugins
    });
}

pub fn registry() -> &'static [EasingPlugin] {
    REGISTRY.get().map_or(&[][..], Vec::as_slice)
}

pub fn by_id(id: &str) -> Option<&'static EasingPlugin> {
    registry()
        .iter()
        .find(|p| p.id == id)
        .or_else(|| registry().iter().find(|p| p.id == "neoutl-easing-standard"))
}

pub fn default_easings_dir() -> PathBuf {
    let Some(exe_dir) = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(Path::to_path_buf))
    else {
        return PathBuf::from("easings");
    };

    #[cfg(target_os = "macos")]
    {
        let resources_dir = exe_dir.join("../Resources/easings");
        if resources_dir.is_dir() {
            return resources_dir;
        }
    }

    exe_dir.join("easings")
}

fn load_one(path: &Path) -> Result<EasingPlugin, PluginError> {
    let lib = unsafe { Library::new(path) }.map_err(|e| PluginError::Load(e.to_string()))?;
    let entry: Symbol<EntryFn> =
        unsafe { lib.get(ENTRY_SYMBOL) }.map_err(|e| PluginError::Load(e.to_string()))?;
    let vtable: &'static EasingEngineVTable = unsafe { &*entry() };
    let meta: &'static EasingEngineMeta = unsafe { &*((vtable.meta)()) };
    let (id, name) = read_meta_strings(meta);
    Ok(EasingPlugin {
        id,
        name,
        vtable,
        _lib: Some(lib),
    })
}

fn is_dylib(path: &Path) -> bool {
    matches!(
        path.extension().and_then(OsStr::to_str),
        Some("so" | "dylib" | "dll")
    )
}

use neoutl_easing_standard::CurveKind;
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};

#[derive(Clone, Serialize, Deserialize)]
pub struct PresetEntry {
    pub name: String,
    pub kind: CurveKind,
}

#[derive(Default)]
pub struct CurveRegistry {
    entries: Vec<PresetEntry>,
    path: PathBuf,
}

impl CurveRegistry {
    pub fn load(path: &Path) -> Self {
        let entries = std::fs::read(path)
            .ok()
            .and_then(|bytes| serde_json::from_slice::<Vec<PresetEntry>>(&bytes).ok())
            .unwrap_or_default();
        Self {
            entries,
            path: path.to_path_buf(),
        }
    }

    pub fn entries(&self) -> &[PresetEntry] {
        &self.entries
    }

    pub fn push_unique(&mut self, kind: CurveKind) -> usize {
        let mut n = self.entries.len() + 1;
        while self
            .entries
            .iter()
            .any(|e| e.name == format!("カスタム {n}"))
        {
            n += 1;
        }
        self.entries.push(PresetEntry {
            name: format!("カスタム {n}"),
            kind,
        });
        self.flush();
        self.entries.len() - 1
    }

    pub fn rename(&mut self, index: usize, name: String) {
        let name = name.trim().to_owned();
        let taken = self
            .entries
            .iter()
            .enumerate()
            .any(|(i, e)| i != index && e.name == name);
        if let Some(entry) = self.entries.get_mut(index)
            && !name.is_empty()
            && !taken
        {
            entry.name = name;
            self.flush();
        }
    }

    pub fn remove(&mut self, index: usize) {
        if index < self.entries.len() {
            self.entries.remove(index);
            self.flush();
        }
    }

    pub fn move_by(&mut self, index: usize, delta: isize) {
        let target = index.saturating_add_signed(delta);
        if index < self.entries.len() && target < self.entries.len() {
            self.entries.swap(index, target);
            self.flush();
        }
    }

    fn flush(&self) {
        if let Some(parent) = self.path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        match serde_json::to_vec_pretty(&self.entries) {
            Ok(bytes) => {
                if let Err(err) = std::fs::write(&self.path, bytes) {
                    eprintln!(
                        "{}",
                        t!(
                            "[NeoUtl] カーブプリセット保存失敗 %{arg0}: %{arg1}",
                            arg0 = self.path.display().to_string(),
                            arg1 = format!("{}", err)
                        )
                    );
                }
            }
            Err(err) => eprintln!(
                "{}",
                t!(
                    "[NeoUtl] カーブプリセット直列化失敗: %{arg0}",
                    arg0 = format!("{}", err)
                )
            ),
        }
    }
}

pub fn default_presets_path(easings_dir: &Path) -> PathBuf {
    easings_dir.join("curve_presets.json")
}

pub fn shared() -> &'static Mutex<CurveRegistry> {
    static SHARED: OnceLock<Mutex<CurveRegistry>> = OnceLock::new();
    SHARED.get_or_init(|| {
        let dir = super::loader::default_easings_dir();
        Mutex::new(CurveRegistry::load(&default_presets_path(&dir)))
    })
}

use maolan_host_adapter::{PluginFormat, PluginParamInfo};
