fn plugin_format_to_i32(format: PluginFormat) -> i32 {
    match format {
        PluginFormat::Vst3 => 0,
        PluginFormat::Clap => 1,
        PluginFormat::Lv2 => 2,
        PluginFormat::Vst2 => 3,
        PluginFormat::Au => 4,
        PluginFormat::Sf2 => 5,
        PluginFormat::Sfz => 6,
        PluginFormat::Jsfx => 7,
        PluginFormat::Internal => 8,
    }
}

fn plugin_format_from_i32(value: i32) -> PluginFormat {
    match value {
        0 => PluginFormat::Vst3,
        1 => PluginFormat::Clap,
        2 => PluginFormat::Lv2,
        3 => PluginFormat::Vst2,
        4 => PluginFormat::Au,
        5 => PluginFormat::Sf2,
        6 => PluginFormat::Sfz,
        7 => PluginFormat::Jsfx,
        _ => PluginFormat::Internal,
    }
}

