type UniqueGroupViews<'v> = (
    UniqueView<'v, TimelineResource>,
    UniqueView<'v, SceneResource>,
    UniqueView<'v, ProjectResource>,
    UniqueView<'v, Camera>,
    UniqueView<'v, SystemSettingsResource>,
);
type SelectorGroupViews<'v> = (
    View<'v, TimeRange>,
    View<'v, KindId>,
    View<'v, SceneId>,
    View<'v, Layer>,
    View<'v, TextContent>,
    View<'v, ShapeParams>,
    View<'v, MediaSource>,
    View<'v, ObjectId>,
    View<'v, SceneObject>,
    View<'v, ClipTarget>,
);
type PayloadGroupViews<'v> = (
    View<'v, Transform>,
    View<'v, KeyframeTracks>,
    View<'v, AudioParams>,
    View<'v, EffectStack>,
    View<'v, GroupControl>,
);
type TimingGroupViews<'v> = (View<'v, TimeRemap>, View<'v, BlendMode>, View<'v, Camera>);

pub(crate) fn is_camera_kind(kind_id: u32) -> bool {
    crate::objects::loader::by_kind_id(kind_id)
        .is_some_and(|p| p.stable_id == neoutl_object_api::CAMERA_STABLE_ID)
}

pub(crate) fn is_light_kind(kind_id: u32) -> bool {
    crate::objects::loader::by_kind_id(kind_id)
        .is_some_and(|p| p.stable_id == neoutl_object_api::LIGHT_STABLE_ID)
}

pub(crate) struct SceneContext {
    pub controllers: Vec<CurtainInfo>,
    pub layer_positions: HashMap<i32, (f32, f32, f32)>,
    pub active_cameras: Vec<ActiveCameraCandidate>,
    pub max_depth: i32,
    pub global_camera: Camera,
}

pub(crate) fn build_scene_context(
    world: &EcsWorld,
    active_scene: i32,
    current: i32,
) -> SceneContext {
    world.world.run(
        |(_timeline, _scenes, project, camera, system_settings): UniqueGroupViews,
         (
            time_ranges,
            kind_ids,
            scene_ids,
            layers,
            _text_contents,
            _shape_params,
            _media_sources,
            _object_ids,
            _scene_objects,
            clip_targets,
        ): SelectorGroupViews,
         (transforms, keyframe_tracks, _audio_params, effect_stacks, group_controls): PayloadGroupViews,
         (_time_remaps, _blend_modes, cameras_view): TimingGroupViews| {
            let project_width = project.width.max(1) as f32;
            let project_height = project.height.max(1) as f32;
            let max_depth = system_settings.max_group_chain_depth;
            let mut controllers = Vec::new();

            for (id, (range, scene, layer, gc)) in
                (&time_ranges, &scene_ids, &layers, &group_controls).iter().with_id()
            {
                if !is_active_at(range, scene, active_scene, current) {
                    continue;
                }
                let mut transform = transforms.get(id).copied().unwrap_or_default();
                if let Ok(kt) = keyframe_tracks.get(id) {
                    kt.apply(&mut transform, current);
                }
                let effects = effect_stacks
                    .get(id)
                    .map(|stack| compute_effect_params_at(stack, current, world))
                    .unwrap_or_default();
                controllers.push(CurtainInfo {
                    entity: id,
                    layer: layer.0,
                    span: (gc.layer_count_down, gc.layer_count_up),
                    matrix: compute_relative_matrix(&transform),
                    effects,
                    opacity: transform.opacity,
                    kind: ControllerKind::Group {
                        generate_framebuffer: gc.generate_framebuffer,
                        hide_captured: gc.hide_captured,
                        camera: gc.camera,
                    },
                    render_self: true,
                });
            }

            for (id, (range, scene, layer, ct)) in
                (&time_ranges, &scene_ids, &layers, &clip_targets).iter().with_id()
            {
                if !ct.enabled || !is_active_at(range, scene, active_scene, current) {
                    continue;
                }
                let mut transform = transforms.get(id).copied().unwrap_or_default();
                if let Ok(kt) = keyframe_tracks.get(id) {
                    kt.apply(&mut transform, current);
                }
                let effects = effect_stacks
                    .get(id)
                    .map(|stack| compute_effect_params_at(stack, current, world))
                    .unwrap_or_default();
                controllers.push(CurtainInfo {
                    entity: id,
                    layer: layer.0,
                    span: (ct.layer_count_down, ct.layer_count_up),
                    matrix: compute_relative_matrix(&transform),
                    effects,
                    opacity: transform.opacity,
                    kind: ControllerKind::Clip {
                        mode: ct.mode,
                        chroma_hue: ct.chroma_hue,
                        chroma_tolerance: ct.chroma_tolerance,
                        blend_edge: ct.blend_edge,
                    },
                    render_self: ct.render_self,
                });
            }

            let mut layer_positions = HashMap::new();
            for (id, (range, scene, layer)) in
                (&time_ranges, &scene_ids, &layers).iter().with_id()
            {
                if !is_active_at(range, scene, active_scene, current) {
                    continue;
                }
                let mut transform = transforms.get(id).copied().unwrap_or_default();
                if let Ok(kt) = keyframe_tracks.get(id) {
                    kt.apply(&mut transform, current);
                }
                layer_positions.insert(layer.0, (transform.x, transform.y, transform.z));
            }

            let mut active_cameras = Vec::new();
            for (id, (range, kind, scene, layer)) in
                (&time_ranges, &kind_ids, &scene_ids, &layers).iter().with_id()
            {
                if !is_active_at(range, scene, active_scene, current) || !is_camera_kind(kind.0) {
                    continue;
                }
                let mut cam = cameras_view
                    .get(id)
                    .ok()
                    .copied()
                    .unwrap_or_else(|| Camera::for_resolution(project_width, project_height));
                if let Ok(transform) = transforms.get(id) {
                    let mut t = *transform;
                    if let Ok(kt) = keyframe_tracks.get(id) {
                        kt.apply(&mut t, current);
                    }
                    cam.pos_x += t.x;
                    cam.pos_y += t.y;
                    cam.pos_z += t.z;
                }
                active_cameras.push(ActiveCameraCandidate { layer: layer.0, camera: cam });
            }
            active_cameras.sort_by_key(|candidate| candidate.layer);

            SceneContext {
                controllers,
                layer_positions,
                active_cameras,
                max_depth,
                global_camera: *camera,
            }
        },
    )
}

pub fn resolve_object_camera(world: &EcsWorld, object_id: usize) -> Camera {
    let active_scene = world.active_scene();
    let current = world.current_frame();
    let context = build_scene_context(world, active_scene, current);
    world
        .world
        .run(|(object_ids, layers): (View<ObjectId>, View<Layer>)| {
            for (entity, object) in object_ids.iter().with_id() {
                if object.0 != object_id {
                    continue;
                }
                let layer = layers.get(entity).map_or(0, |value| value.0);
                let chain = resolve_group_chain(layer, &context.controllers, context.max_depth);
                return resolve_camera(
                    &context.active_cameras,
                    &chain,
                    &context.controllers,
                    &context.layer_positions,
                )
                .map_or(context.global_camera, |(_, camera)| camera);
            }
            context.global_camera
        })
}

pub(crate) fn is_active_at(
    range: &TimeRange,
    scene: &SceneId,
    active_scene: i32,
    frame: i32,
) -> bool {
    scene.0 == active_scene && frame >= range.start_frame && frame < range.end_frame
}

pub fn get_active_objects_system(world: &EcsWorld) -> (Vec<ActiveObject>, CapturedObjects) {
    let active_scene = world.active_scene();
    let current = world.current_frame();
    get_active_objects_system_at(world, active_scene, current)
}

pub fn get_active_objects_system_at(
    world: &EcsWorld,
    active_scene: i32,
    current: i32,
) -> (Vec<ActiveObject>, CapturedObjects) {
    let scene_context = build_scene_context(world, active_scene, current);
    world.world.run(
        move |(_timeline, scenes, project, _camera, _system_settings): UniqueGroupViews,
         (
            time_ranges,
            kind_ids,
            scene_ids,
            layers,
            text_contents,
            shape_params,
            media_sources,
            object_ids,
            scene_objects,
            clip_targets,
        ): SelectorGroupViews,
         (
            transforms,
            keyframe_tracks,
            _audio_params,
            effect_stacks,
            group_controls,
        ): PayloadGroupViews,
         (time_remaps, blend_modes, _cameras_view): TimingGroupViews| {
            let SceneContext {
                controllers,
                layer_positions,
                active_cameras,
                max_depth,
                global_camera,
            } = scene_context;
            let project_width = project.width.max(1) as f32;
            let project_height = project.height.max(1) as f32;

            let mut active = Vec::new();
            let mut captured: CapturedObjects = HashMap::new();

            for (id, (range, kind, scene)) in (&time_ranges, &kind_ids, &scene_ids).iter().with_id()
            {
                if !is_active_at(range, scene, active_scene, current) {
                    continue;
                }
                if group_controls.get(id).is_ok() {
                    continue;
                }
                if clip_targets.get(id).is_ok_and(|t| t.enabled) {
                    continue;
                }
                if is_camera_kind(kind.0) || is_light_kind(kind.0) {
                    continue;
                }
                let keyframes = keyframe_tracks.get(id).ok();

                let mut transform = transforms.get(id).copied().unwrap_or_default();
                if let Some(kt) = keyframes {
                    kt.apply(&mut transform, current);
                }

                let mut text_content = text_contents.get(id).ok().cloned();
                if let (Some(tc), Some(kt)) = (text_content.as_mut(), keyframes) {
                    kt.apply(tc, current);
                }

                let mut shape = shape_params.get(id).ok().copied();
                if let (Some(sp), Some(kt)) = (shape.as_mut(), keyframes) {
                    kt.apply(sp, current);
                }

                let media_source = media_sources.get(id).ok().cloned();
                let layer_frame = current - range.start_frame;
                let remapped_layer_frame = time_remaps
                    .get(id)
                    .map_or(layer_frame, |r| r.resolve(layer_frame, layer_frame));
                let source_frame = media_source.as_ref().map_or(0, |m| {
                    let base = f64::from(remapped_layer_frame);
                    let ratio = if matches!(m.kind, MediaKind::Video) {
                        let src_fps = neoutl_media_runtime::cache::global()
                            .source_fps(&m.path)
                            .unwrap_or(f64::from(project.fps.max(1)));
                        src_fps / f64::from(project.fps.max(1))
                    } else {
                        1.0
                    };
                    m.trim_in_frame + (base * ratio).round() as i64
                });
                let compose_source =
                    scene_objects
                        .get(id)
                        .ok()
                        .map(|s| ComposeSource::NestedScene {
                            target_scene: s.target_scene,
                            local_frame: current - range.start_frame,
                        });

                let matrix = compute_global_matrix(&transform);
                                                let source_size: Option<(f32, f32)> = match &media_source {
                    Some(src) if matches!(src.kind, MediaKind::Video | MediaKind::Image) => {
                        neoutl_media_runtime::cache::global()
                            .dimensions(&src.path)
                            .ok()
                            .map(|(w, h)| (w as f32, h as f32))
                    }
                    _ => match compose_source {
                        Some(ComposeSource::NestedScene { target_scene, .. }) => scenes
                            .find(target_scene)
                            .map(|scene| (scene.width as f32, scene.height as f32)),
                        _ => None,
                    },
                };
                let local_matrix = match source_size {
                    Some((w, h)) => rescale_for_source(&matrix, w, h),
                    None => matrix,
                };
                if let Some((w, h)) = source_size {
                    let object_id = object_ids.get(id).map_or(0, |o| o.0);
                    source_size_cache::global().insert(object_id, w, h);
                }

                let obj_layer = layers.get(id).map_or(0, |l| l.0);
                let chain_idx = resolve_group_chain(obj_layer, &controllers, max_depth);
                let group_idx = group_only(&chain_idx, &controllers);
                let chain_matrices: Vec<GlobalMatrix> =
                    group_idx.iter().map(|&i| controllers[i].matrix).collect();
                let matrix = compute_chained_matrix(&chain_matrices, &local_matrix);

                let active_camera = resolve_camera(&active_cameras, &chain_idx, &controllers, &layer_positions);
                let effective_camera = active_camera.map_or(global_camera, |(_, c)| c);
                let mvp = compute_mvp(
                    &matrix,
                    &effective_camera,
                    project_width,
                    project_height,
                    projection_for(kind.0, effective_camera.fov_deg),
                );
                let zbuffer_depth = match active_camera {
                    Some((camera_layer, cam)) if cam.zbuffer_enabled => {
                        Some(zbuffer_sort_key(camera_layer, &matrix, &cam))
                    }
                    _ => None,
                };
                let mut opacity = transform.opacity;
                for &i in &group_idx {
                    opacity *= controllers[i].opacity;
                }
                let blend_mode = blend_modes.get(id).copied().unwrap_or_default();
                let mut effects = effect_stacks
                    .get(id)
                    .map(|stack| compute_effect_params_at(stack, current, world))
                    .unwrap_or_default();
                for &i in group_idx.iter().rev() {
                    let mut prefixed = controllers[i].effects.clone();
                    prefixed.append(&mut effects);
                    effects = prefixed;
                }

                                                let clip_target = chain_idx.iter().find_map(|&i| match controllers[i].kind {
                    ControllerKind::Clip {
                        mode,
                        chroma_hue,
                        chroma_tolerance,
                        blend_edge,
                    } => Some(ClipTargetInfo {
                        controller: controllers[i].entity,
                        mode,
                        chroma_hue,
                        chroma_tolerance,
                        blend_edge,
                    }),
                    ControllerKind::Group { .. } => None,
                });

                let active_object = ActiveObject {
                    kind_id: kind.0,
                    clip_instance: object_ids.get(id).map_or(0, |o| o.0 as u64),
                    source_frame,
                    text_content,
                    shape_params: shape,
                    media_source,
                    mvp,
                    opacity,
                    effects,
                    compose_source,
                    layer: obj_layer,
                    clip_target,
                    zbuffer_depth,
                    blend_mode,
                };

                let fb_pos = chain_idx.iter().position(|&i| {
                    matches!(
                        controllers[i].kind,
                        ControllerKind::Group {
                            generate_framebuffer: true,
                            ..
                        }
                    )
                });

                if let Some(pos) = fb_pos {
                    let controller = controllers[chain_idx[pos]].entity;
                    let hide_captured = controllers[chain_idx[pos]].hide_captured();
                    let inner_chain = &chain_idx[..pos];
                    let inner_group_idx = group_only(inner_chain, &controllers);
                    let inner_matrices: Vec<GlobalMatrix> = inner_group_idx
                        .iter()
                        .map(|&i| controllers[i].matrix)
                        .collect();
                    let inner_matrix = compute_chained_matrix(&inner_matrices, &local_matrix);
                    let inner_camera = resolve_camera(&active_cameras, inner_chain, &controllers, &layer_positions);
                    let inner_effective_camera = inner_camera.map_or(global_camera, |(_, c)| c);
                    let inner_mvp = compute_mvp(
                        &inner_matrix,
                        &inner_effective_camera,
                        project_width,
                        project_height,
                        projection_for(kind.0, inner_effective_camera.fov_deg),
                    );
                    let inner_zbuffer_depth = match inner_camera {
                        Some((camera_layer, cam)) if cam.zbuffer_enabled => {
                            Some(zbuffer_sort_key(camera_layer, &inner_matrix, &cam))
                        }
                        _ => None,
                    };
                    let mut inner_opacity = transform.opacity;
                    for &i in &inner_group_idx {
                        inner_opacity *= controllers[i].opacity;
                    }
                    let mut inner_effects = effect_stacks
                        .get(id)
                        .map(|stack| compute_effect_params_at(stack, current, world))
                        .unwrap_or_default();
                    for &i in inner_group_idx.iter().rev() {
                        let mut prefixed = controllers[i].effects.clone();
                        prefixed.append(&mut inner_effects);
                        inner_effects = prefixed;
                    }
                    let inner_clip_target = inner_chain.iter().find_map(|&i| match controllers[i].kind {
                        ControllerKind::Clip {
                            mode,
                            chroma_hue,
                            chroma_tolerance,
                            blend_edge,
                        } => Some(ClipTargetInfo {
                            controller: controllers[i].entity,
                            mode,
                            chroma_hue,
                            chroma_tolerance,
                            blend_edge,
                        }),
                        ControllerKind::Group { .. } => None,
                    });
                    let captured_object = ActiveObject {
                        mvp: inner_mvp,
                        opacity: inner_opacity,
                        effects: inner_effects,
                        clip_target: inner_clip_target,
                        zbuffer_depth: inner_zbuffer_depth,
                        ..active_object.clone()
                    };
                    captured
                        .entry(controller)
                        .or_default()
                        .push(captured_object);
                    if !hide_captured {
                        let stationary_chain: Vec<usize> = chain_idx
                            .iter()
                            .copied()
                            .enumerate()
                            .filter(|&(i, _)| i != pos)
                            .map(|(_, v)| v)
                            .collect();
                        let stationary_group_idx = group_only(&stationary_chain, &controllers);
                        let stationary_matrices: Vec<GlobalMatrix> = stationary_group_idx
                            .iter()
                            .map(|&i| controllers[i].matrix)
                            .collect();
                        let stationary_matrix =
                            compute_chained_matrix(&stationary_matrices, &local_matrix);
                        let stationary_camera =
                            resolve_camera(&active_cameras, &stationary_chain, &controllers, &layer_positions);
                        let stationary_effective_camera =
                            stationary_camera.map_or(global_camera, |(_, c)| c);
                        let stationary_mvp = compute_mvp(
                            &stationary_matrix,
                            &stationary_effective_camera,
                            project_width,
                            project_height,
                            projection_for(kind.0, stationary_effective_camera.fov_deg),
                        );
                        let stationary_zbuffer_depth = match stationary_camera {
                            Some((camera_layer, cam)) if cam.zbuffer_enabled => Some(
                                zbuffer_sort_key(camera_layer, &stationary_matrix, &cam),
                            ),
                            _ => None,
                        };
                        let mut stationary_opacity = transform.opacity;
                        for &i in &stationary_group_idx {
                            stationary_opacity *= controllers[i].opacity;
                        }
                        let mut stationary_effects = effect_stacks
                            .get(id)
                            .map(|stack| compute_effect_params_at(stack, current, world))
                            .unwrap_or_default();
                        for &i in stationary_group_idx.iter().rev() {
                            let mut prefixed = controllers[i].effects.clone();
                            prefixed.append(&mut stationary_effects);
                            stationary_effects = prefixed;
                        }
                        active.push(ActiveObject {
                            mvp: stationary_mvp,
                            opacity: stationary_opacity,
                            effects: stationary_effects,
                            zbuffer_depth: stationary_zbuffer_depth,
                            ..active_object
                        });
                    }
                } else {
                    active.push(active_object);
                }
            }

            for c in controllers.iter() {
                if !c.requires_fb() {
                    continue;
                }
                let Ok(kind) = kind_ids.get(c.entity) else {
                    continue;
                };
                let chain_idx = resolve_group_chain(c.layer, &controllers, max_depth);
                let group_idx = group_only(&chain_idx, &controllers);
                let chain_matrices: Vec<GlobalMatrix> =
                    group_idx.iter().map(|&i| controllers[i].matrix).collect();
                let own_matrix = match c.kind {
                    ControllerKind::Group { .. } => {
                        scale_to_pixels(&c.matrix, project_width, project_height)
                    }
                    ControllerKind::Clip { .. } => {
                        scale_to_pixels(&c.matrix, UNIT_SIZE_PX, UNIT_SIZE_PX)
                    }
                };
                let matrix = compute_chained_matrix(&chain_matrices, &own_matrix);
                let self_camera = resolve_camera(&active_cameras, &chain_idx, &controllers, &layer_positions);
                let self_effective_camera = self_camera.map_or(global_camera, |(_, cam)| cam);
                let mvp = compute_mvp(
                    &matrix,
                    &self_effective_camera,
                    project_width,
                    project_height,
                    projection_for(kind.0, self_effective_camera.fov_deg),
                );
                let self_zbuffer_depth = match self_camera {
                    Some((camera_layer, cam)) if cam.zbuffer_enabled => {
                        Some(zbuffer_sort_key(camera_layer, &matrix, &cam))
                    }
                    _ => None,
                };
                let mut opacity = c.opacity;
                for &i in &group_idx {
                    opacity *= controllers[i].opacity;
                }
                let mut effects = c.effects.clone();
                for &i in group_idx.iter().rev() {
                    let mut prefixed = controllers[i].effects.clone();
                    prefixed.append(&mut effects);
                    effects = prefixed;
                }

                match c.kind {
                    ControllerKind::Group { .. } => {
                        if !c.render_self {
                            continue;
                        }
                        let object_id = object_ids.get(c.entity).map_or(0, |o| o.0);
                        source_size_cache::global()
                            .insert(object_id, project_width, project_height);
                        active.push(ActiveObject {
                            kind_id: kind.0,
                            clip_instance: object_ids.get(c.entity).map_or(0, |o| o.0 as u64),
                            source_frame: 0,
                            text_content: None,
                            shape_params: None,
                            media_source: None,
                            mvp,
                            opacity,
                            effects,
                            compose_source: Some(ComposeSource::FrameBuffer {
                                controller: c.entity,
                                kind: FrameBufferKind::Group,
                            }),
                            layer: c.layer,
                            clip_target: None,
                            zbuffer_depth: self_zbuffer_depth,
                            blend_mode: BlendMode::default(),
                        });
                    }
                    ControllerKind::Clip { .. } => {
                        let keyframes = keyframe_tracks.get(c.entity).ok();

                        let mut text_content = text_contents.get(c.entity).ok().cloned();
                        if let (Some(tc), Some(kt)) = (text_content.as_mut(), keyframes) {
                            kt.apply(tc, current);
                        }
                        let mut shape = shape_params.get(c.entity).ok().copied();
                        if let (Some(sp), Some(kt)) = (shape.as_mut(), keyframes) {
                            kt.apply(sp, current);
                        }
                        let media_source = media_sources.get(c.entity).ok().cloned();
                        let source_frame = media_source.as_ref().map_or(0, |m| {
                            let base = time_ranges
                                .get(c.entity)
                                .map_or(0.0, |r| f64::from(current - r.start_frame));
                            let ratio = if matches!(m.kind, MediaKind::Video) {
                                neoutl_media_runtime::cache::global()
                                    .source_fps(&m.path)
                                    .map_or(1.0, |src_fps| src_fps / f64::from(project.fps.max(1)))
                            } else {
                                1.0
                            };
                            m.trim_in_frame + (base * ratio).round() as i64
                        });

                        let mold_object = ActiveObject {
                            kind_id: kind.0,
                            clip_instance: object_ids.get(c.entity).map_or(0, |o| o.0 as u64),
                            source_frame,
                            text_content,
                            shape_params: shape,
                            media_source,
                            mvp,
                            opacity,
                            effects,
                            compose_source: None,
                            layer: c.layer,
                            clip_target: None,
                            zbuffer_depth: self_zbuffer_depth,
                            blend_mode: BlendMode::default(),
                        };
                        captured
                            .entry(c.entity)
                            .or_default()
                            .push(mold_object.clone());
                        if c.render_self {
                            active.push(mold_object);
                        }
                    }
                }
            }

            active.sort_by(|a, b| {
                let ka = a.zbuffer_depth.unwrap_or(a.layer as f32);
                let kb = b.zbuffer_depth.unwrap_or(b.layer as f32);
                ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal)
            });

            (active, captured)
        },
    )
}

use super::EcsWorld;
use super::active_query::is_active_at;
use crate::ecs::components::{
    AudioParams, KeyframeTracks, MediaSource, ObjectId, SceneId, TimeRange,
};
use crate::ecs::resources::{ProjectResource, SceneResource};
use neoutl_media_runtime::MediaKind;
use shipyard::{Get, IntoIter, UniqueView, View};

type AudioSelectorViews<'v> = (
    View<'v, TimeRange>,
    View<'v, SceneId>,
    View<'v, MediaSource>,
    View<'v, ObjectId>,
);
type AudioPayloadViews<'v> = (
    View<'v, AudioParams>,
    View<'v, KeyframeTracks>,
    View<'v, crate::ecs::audio_plugins::PluginChain>,
    View<'v, crate::ecs::effects::EffectStack>,
);

pub fn get_active_audio_system(
    world: &EcsWorld,
    frame: i32,
) -> Vec<crate::audio::mixer::ActiveAudioEntity> {
    world.world.run(
        |(scenes, project): (UniqueView<SceneResource>, UniqueView<ProjectResource>),
         (time_ranges, scene_ids, media_sources, object_ids): AudioSelectorViews,
         (audio_params, keyframe_tracks, plugin_chains, effect_stacks): AudioPayloadViews| {
            let active_scene = scenes.active_scene;
            let fps = f64::from(project.fps.max(1));
            let mut active = Vec::new();

            for (id, (range, scene, media_source)) in
                (&time_ranges, &scene_ids, &media_sources).iter().with_id()
            {
                if !matches!(media_source.kind, MediaKind::Audio) {
                    continue;
                }
                if !is_active_at(range, scene, active_scene, frame) {
                    continue;
                }
                let keyframes = keyframe_tracks.get(id).ok();
                let mut audio = audio_params.get(id).copied().unwrap_or_default();
                if let Some(kt) = keyframes {
                    kt.apply(&mut audio, frame);
                }
                let source_frame =
                    media_source.trim_in_frame + i64::from(frame - range.start_frame);

                active.push(crate::audio::mixer::ActiveAudioEntity {
                    id: object_ids.get(id).map_or(0, |o| o.0 as usize),
                    audio,
                    media_source: Some(media_source.clone()),
                    source_frame,
                    timeline_frame: i64::from(frame),
                    fps,
                    plugin_chain: plugin_chains
                        .get(id)
                        .map(|c| c.0.clone())
                        .unwrap_or_default(),
                    effects: effect_stacks
                        .get(id)
                        .map(|stack| {
                            crate::ecs::effects::compute_effect_params_at(stack, frame, world)
                        })
                        .unwrap_or_default(),
                });
            }
            active
        },
    )
}

use super::curtain::{ControllerKind, CurtainInfo};
use crate::ecs::transform::{Camera, GlobalMatrix, Projection, TargetLayerMode, view_space_depth};
use std::collections::HashMap;

pub(crate) fn projection_for(_kind_id: u32, fov_deg: f32) -> Projection {
    Projection::Perspective { fov_deg }
}

#[derive(Clone, Copy, Debug)]
pub(crate) struct ActiveCameraCandidate {
    pub layer: i32,
    pub camera: Camera,
}

pub(crate) fn resolve_camera(
    active_cameras: &[ActiveCameraCandidate],
    chain_idx: &[usize],
    controllers: &[CurtainInfo],
    layer_positions: &HashMap<i32, (f32, f32, f32)>,
) -> Option<(i32, Camera)> {
    if let Some(candidate) = active_cameras.first() {
        let mut cam = candidate.camera;
        if let TargetLayerMode::Layer(n) = cam.target_layer_mode
            && let Some(&(lx, ly, lz)) = layer_positions.get(&n)
        {
            cam.target_x += lx;
            cam.target_y += ly;
            cam.target_z += lz;
        }
        return Some((candidate.layer, cam));
    }

    for &i in chain_idx {
        let Some(controller) = controllers.get(i) else {
            continue;
        };
        if let ControllerKind::Group {
            camera: Some(cam), ..
        } = controller.kind
        {
            let mut cam = cam;
            if let TargetLayerMode::Layer(n) = cam.target_layer_mode
                && let Some(&(lx, ly, lz)) = layer_positions.get(&n)
            {
                cam.target_x += lx;
                cam.target_y += ly;
                cam.target_z += lz;
            }
            return Some((controller.layer, cam));
        }
    }
    None
}

pub(crate) fn zbuffer_sort_key(camera_layer: i32, global: &GlobalMatrix, cam: &Camera) -> f32 {
    let depth = view_space_depth(global, cam);
    let span = (cam.far - cam.near).max(1e-3);
    let normalized = ((depth - cam.near) / span - 0.5).clamp(-0.5, 0.5);
    camera_layer.to_string().parse::<f32>().unwrap_or_else(|_| {
        if camera_layer.is_negative() {
            f32::MIN
        } else {
            f32::MAX
        }
    }) + normalized
}

use crate::ecs::components::ClipMode;
use crate::ecs::transform::{Camera, GlobalMatrix};
use crate::ecs::types::Value;
use shipyard::EntityId;
use std::collections::HashMap;

#[derive(Clone, Copy)]
pub(crate) enum ControllerKind {
    Group {
        generate_framebuffer: bool,
        hide_captured: bool,
        camera: Option<Camera>,
    },
    Clip {
        mode: ClipMode,
        chroma_hue: f32,
        chroma_tolerance: f32,
        blend_edge: bool,
    },
}

pub(crate) struct CurtainInfo {
    pub(crate) entity: EntityId,
    pub(crate) layer: i32,
    pub(crate) span: (u32, u32),
    pub(crate) matrix: GlobalMatrix,
    pub(crate) effects: Vec<(String, HashMap<String, Value>)>,
    pub(crate) opacity: f32,
    pub(crate) kind: ControllerKind,
    pub(crate) render_self: bool,
}

impl CurtainInfo {
    pub(crate) fn requires_fb(&self) -> bool {
        match self.kind {
            ControllerKind::Group {
                generate_framebuffer,
                ..
            } => generate_framebuffer,
            ControllerKind::Clip { .. } => true,
        }
    }

    pub(crate) fn hide_captured(&self) -> bool {
        match self.kind {
            ControllerKind::Group { hide_captured, .. } => hide_captured,
            ControllerKind::Clip { .. } => false,
        }
    }
}

pub(crate) fn curtain_covers_layer(
    curtain_layer: i32,
    span: (u32, u32),
    target_layer: i32,
) -> bool {
    let (down, up) = span;
    if target_layer > curtain_layer {
        target_layer <= curtain_layer + down as i32
    } else if target_layer < curtain_layer {
        target_layer >= curtain_layer - up as i32
    } else {
        false
    }
}

pub(crate) fn group_only(chain: &[usize], controllers: &[CurtainInfo]) -> Vec<usize> {
    chain
        .iter()
        .copied()
        .filter(|&i| matches!(controllers[i].kind, ControllerKind::Group { .. }))
        .collect()
}

pub(crate) fn resolve_group_chain(
    obj_layer: i32,
    controllers: &[CurtainInfo],
    max_depth: i32,
) -> Vec<usize> {
    let mut chain = Vec::new();
    let mut cursor_layer = obj_layer;
    loop {
        if chain.len() as i32 >= max_depth.max(0) {
            break;
        }
        let mut nearest: Option<(usize, i32)> = None;
        for (idx, c) in controllers.iter().enumerate() {
            if chain.contains(&idx) {
                continue;
            }
            if !curtain_covers_layer(c.layer, c.span, cursor_layer) {
                continue;
            }
            let dist = (cursor_layer - c.layer).abs();
            if nearest.is_none_or(|(_, d)| dist < d) {
                nearest = Some((idx, dist));
            }
        }
        let Some((idx, _)) = nearest else {
            break;
        };
        chain.push(idx);
        cursor_layer = controllers[idx].layer;
    }
    chain
}

use crate::ecs::components::{ObjectId, PropertyExpressions};
use crate::ecs::effects::EffectStack;
use crate::ecs::transform::Transform;
use neoutl_expression_api::{
    ExpressionEvalContext, ExpressionHostVTable, STANDARD_EXPRESSION_ENGINE_VTABLE,
    bind_expression_host,
};
use neoutl_shared_abi::StrRef;
use shipyard::{Get, IntoIter, View, ViewMut, World};
use std::cell::RefCell;
use std::collections::HashMap;
use std::sync::Once;

#[derive(Default)]
pub struct HostContextData {
    pub frame: i32,
    pub fps: f32,
    pub time_seconds: f64,
    pub properties: HashMap<(usize, String), f32>,
    pub object_layers: HashMap<usize, i32>,
}

thread_local! {
    static CURRENT_CONTEXT: RefCell<Option<HostContextData>> = const { RefCell::new(None) };
}

fn with_context<R>(f: impl FnOnce(&HostContextData) -> R) -> R {
    CURRENT_CONTEXT.with(|ctx| {
        let borrow = ctx.borrow();
        if let Some(c) = borrow.as_ref() {
            f(c)
        } else {
            f(&HostContextData::default())
        }
    })
}

unsafe extern "C" fn host_get_property(object_id: usize, prop_name: StrRef, fallback: f32) -> f32 {
    let name = unsafe { prop_name.as_str() };
    with_context(|ctx| {
        ctx.properties
            .get(&(object_id, name.to_string()))
            .copied()
            .unwrap_or(fallback)
    })
}

unsafe extern "C" fn host_get_time_seconds() -> f64 {
    with_context(|ctx| ctx.time_seconds)
}

unsafe extern "C" fn host_get_frame() -> i32 {
    with_context(|ctx| ctx.frame)
}

unsafe extern "C" fn host_get_fps() -> f32 {
    with_context(|ctx| ctx.fps)
}

unsafe extern "C" fn host_get_object_layer(object_id: usize) -> i32 {
    with_context(|ctx| ctx.object_layers.get(&object_id).copied().unwrap_or(0))
}

static HOST_VTABLE: ExpressionHostVTable = ExpressionHostVTable {
    get_property: host_get_property,
    get_time_seconds: host_get_time_seconds,
    get_frame: host_get_frame,
    get_fps: host_get_fps,
    get_object_layer: host_get_object_layer,
};

static INIT_ONCE: Once = Once::new();

pub fn ensure_expression_host_bound() {
    INIT_ONCE.call_once(|| {
        bind_expression_host(&STANDARD_EXPRESSION_ENGINE_VTABLE, &HOST_VTABLE);
    });
}

#[allow(dead_code)]
pub fn evaluate_expressions_for_world(world: &mut World, frame: i32, fps: f32) -> usize {
    ensure_expression_host_bound();

    let fps = if fps <= 0.0 { 30.0 } else { fps };
    let time_seconds = frame as f64 / fps as f64;

    let mut ctx_data = HostContextData {
        frame,
        fps,
        time_seconds,
        properties: HashMap::new(),
        object_layers: HashMap::new(),
    };

    world.run(
        |ids: View<ObjectId>,
         transforms: View<Transform>,
         layers: View<crate::ecs::components::Layer>,
         stacks: View<EffectStack>| {
            for (entity, id) in ids.iter().with_id() {
                let obj_id = id.0;
                if let Ok(layer) = layers.get(entity) {
                    ctx_data.object_layers.insert(obj_id, layer.0);
                }
                if let Ok(tr) = transforms.get(entity) {
                    ctx_data.properties.insert((obj_id, "X".to_string()), tr.x);
                    ctx_data.properties.insert((obj_id, "Y".to_string()), tr.y);
                    ctx_data.properties.insert((obj_id, "Z".to_string()), tr.z);
                    ctx_data
                        .properties
                        .insert((obj_id, "Rotation".to_string()), tr.rot_z);
                    ctx_data
                        .properties
                        .insert((obj_id, "ScaleX".to_string()), tr.scale_x);
                    ctx_data
                        .properties
                        .insert((obj_id, "ScaleY".to_string()), tr.scale_y);
                    ctx_data
                        .properties
                        .insert((obj_id, "ScaleZ".to_string()), 1.0);
                }
                if let Ok(stack) = stacks.get(entity) {
                    for inst in &stack.0 {
                        for (key, param) in &inst.params {
                            if let crate::ecs::types::Value::Number(val) = param.static_value {
                                ctx_data.properties.insert((obj_id, key.clone()), val);
                            }
                        }
                    }
                }
            }
        },
    );

    let mut evaluated_count = 0;

    CURRENT_CONTEXT.with(|ctx| {
        *ctx.borrow_mut() = Some(ctx_data);
    });

    let mut updates: Vec<(usize, String, f32)> = Vec::new();

    world.run(
        |ids: View<ObjectId>, expressions: View<PropertyExpressions>| {
            for (entity, id) in ids.iter().with_id() {
                let obj_id = id.0;
                if let Ok(exprs) = expressions.get(entity) {
                    for (prop_key, binding) in &exprs.bindings {
                        if !binding.enabled || binding.compiled_handle == 0 {
                            continue;
                        }

                        let cur_val = with_context(|c| {
                            c.properties
                                .get(&(obj_id, prop_key.clone()))
                                .copied()
                                .unwrap_or(0.0)
                        });

                        let eval_ctx = ExpressionEvalContext {
                            object_id: obj_id,
                            frame,
                            time_seconds,
                            current_value: cur_val,
                        };

                        let new_val = unsafe {
                            (STANDARD_EXPRESSION_ENGINE_VTABLE.evaluate)(
                                binding.compiled_handle,
                                &eval_ctx,
                            )
                        };

                        updates.push((obj_id, prop_key.clone(), new_val));
                    }
                }
            }
        },
    );

    CURRENT_CONTEXT.with(|ctx| {
        *ctx.borrow_mut() = None;
    });

    for (obj_id, prop_key, new_val) in updates {
        evaluated_count += 1;
        world.run(
            |ids: View<ObjectId>,
             mut transforms: ViewMut<Transform>,
             mut stacks: ViewMut<EffectStack>| {
                for (entity, id) in ids.iter().with_id() {
                    if id.0 == obj_id {
                        if let Ok(mut tr) = (&mut transforms).get(entity) {
                            match prop_key.as_str() {
                                "X" | "x" => tr.x = new_val,
                                "Y" | "y" => tr.y = new_val,
                                "Z" | "z" => tr.z = new_val,
                                "Rotation" | "rot_z" => tr.rot_z = new_val,
                                "ScaleX" | "scale_x" => tr.scale_x = new_val,
                                "ScaleY" | "scale_y" => tr.scale_y = new_val,
                                _ => {}
                            }
                        }

                        if let Ok(mut stack) = (&mut stacks).get(entity) {
                            for inst in &mut stack.0 {
                                if let Some(param) = inst.params.get_mut(&prop_key) {
                                    param.static_value = crate::ecs::types::Value::Number(new_val);
                                }
                            }
                        }
                        break;
                    }
                }
            },
        );
    }

    evaluated_count
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ecs::EcsWorld;
    use crate::ecs::components::PropertyExpressions;
    use shipyard::AddComponent;

    #[test]
    fn test_expression_system_evaluates_and_updates_transform() {
        let mut ecs_world = EcsWorld::new();
        let obj_id = ecs_world.add_shape_object(0, 0, 100, 0, Default::default());

        ecs_world.set_transform(
            obj_id,
            Transform {
                x: 10.0,
                y: 20.0,
                ..Default::default()
            },
        );

        ecs_world
            .world
            .run(|mut exprs: ViewMut<PropertyExpressions>| {
                let entity = ecs_world.find_entity(obj_id).unwrap();
                let mut prop_expr = PropertyExpressions::new();
                prop_expr.set_expression("Y", "prop('X') * 2.5 + time * 10", true);
                let _ = exprs.add_component_unchecked(entity, prop_expr);
            });

        let count = evaluate_expressions_for_world(&mut ecs_world.world, 60, 30.0);
        assert_eq!(count, 1);

        let tr = ecs_world.get_transform(obj_id).unwrap();
        assert_eq!(tr.x, 10.0);
        assert!((tr.y - 45.0).abs() < 1e-4);
    }

    #[test]
    fn test_expression_system_evaluates_and_updates_effect_params() {
        let mut ecs_world = EcsWorld::new();
        let obj_id = ecs_world.add_shape_object(0, 0, 100, 0, Default::default());

        ecs_world.world.run(|mut stacks: ViewMut<EffectStack>| {
            let entity = ecs_world.find_entity(obj_id).unwrap();
            let mut inst = crate::ecs::types::EffectInstance::new("test.blur");
            inst.params.insert(
                "Radius".to_string(),
                crate::ecs::types::EffectParam::new(crate::ecs::types::Value::Number(5.0)),
            );
            if let Ok(mut stack) = (&mut stacks).get(entity) {
                stack.0.push(inst);
            }
        });

        ecs_world
            .world
            .run(|mut exprs: ViewMut<PropertyExpressions>| {
                let entity = ecs_world.find_entity(obj_id).unwrap();
                let mut prop_expr = PropertyExpressions::new();
                prop_expr.set_expression("Radius", "sin(time) * 20 + 25", true);
                let _ = exprs.add_component_unchecked(entity, prop_expr);
            });

        let count = evaluate_expressions_for_world(&mut ecs_world.world, 0, 30.0);
        assert_eq!(count, 1);
        let val = ecs_world.effect_param_f32(obj_id, 0, "Radius").unwrap();
        assert!((val - 25.0).abs() < 1e-4);
    }
}

