        self.world.run(|kind_ids: View<KindId>| {
            kind_ids
                .get(entity)
                .ok()
                .and_then(|k| crate::objects::loader::by_kind_id(k.0))
                .is_some_and(|p| p.stable_id == neoutl_object_api::AUDIO_STABLE_ID)
        })
