use crate::ecs::EcsWorld;
use crate::ecs::audio_plugins;
use crate::ecs::audio_plugins::PluginChain;
use shipyard::{AddComponent, Get, View, ViewMut};
use std::collections::HashMap;

impl EcsWorld {
    pub fn get_plugin_chain(
        &self,
        object_id: usize,
    ) -> Option<Vec<audio_plugins::PluginInstanceRef>> {
        let entity = self.find_entity(object_id)?;
        self.world
            .run(|chains: View<PluginChain>| chains.get(entity).ok().map(|c| c.0.clone()))
    }

    pub fn add_audio_plugin(
        &mut self,
        object_id: usize,
        entry: &maolan_host_adapter::PluginCatalogEntry,
        param_info: Vec<maolan_host_adapter::PluginParamInfo>,
    ) {
        let Some(entity) = self.find_entity(object_id) else {
            return;
        };
        self.world.run(|mut chains: ViewMut<PluginChain>| {
            let instance = audio_plugins::PluginInstanceRef {
                instance_uid: 0,
                format: entry.format,
                path: entry.path.clone(),
                plugin_id: entry.plugin_id.clone(),
                bypass: false,
                params: HashMap::new(),
                param_info,
            };
            if let Ok(mut chain) = (&mut chains).get(entity) {
                chain.0.push(instance);
                chain.repair_instance_uids();
            } else {
                let mut chain = PluginChain(vec![instance]);
                chain.repair_instance_uids();
                chains.add_component_unchecked(entity, chain);
            }
        });
    }

    pub fn remove_audio_plugin(&mut self, object_id: usize, index: usize) {
        let Some(entity) = self.find_entity(object_id) else {
            return;
        };
        self.world.run(|mut chains: ViewMut<PluginChain>| {
            if let Ok(mut chain) = (&mut chains).get(entity) {
                if index < chain.0.len() {
                    chain.0.remove(index);
                }
            }
        });
    }

    pub fn set_audio_plugin_bypass(&mut self, object_id: usize, index: usize, bypass: bool) {
        let Some(entity) = self.find_entity(object_id) else {
            return;
        };
        self.world.run(|mut chains: ViewMut<PluginChain>| {
            if let Ok(mut chain) = (&mut chains).get(entity) {
                if let Some(inst) = chain.0.get_mut(index) {
                    inst.bypass = bypass;
                }
            }
        });
    }

    pub fn reorder_audio_plugin(&mut self, object_id: usize, from: usize, to: usize) {
        let Some(entity) = self.find_entity(object_id) else {
            return;
        };
        self.world.run(|mut chains: ViewMut<PluginChain>| {
            if let Ok(mut chain) = (&mut chains).get(entity) {
                if from < chain.0.len() && to < chain.0.len() {
                    let item = chain.0.remove(from);
                    chain.0.insert(to, item);
                }
            }
        });
    }

    pub fn set_audio_plugin_param(
        &mut self,
        object_id: usize,
        index: usize,
        param_id: u32,
        value: f64,
    ) {
        let Some(entity) = self.find_entity(object_id) else {
            return;
        };
        self.world.run(|mut chains: ViewMut<PluginChain>| {
            if let Ok(mut chain) = (&mut chains).get(entity) {
                if let Some(inst) = chain.0.get_mut(index) {
                    inst.params.insert(param_id, value);
                }
            }
        });
    }
}

use crate::ecs::EcsWorld;
use crate::ecs::history::{self, HistoryCommand, HistoryStack};
use crate::ecs::resources;
use crate::ecs::resources::{
    LayerStates, PresetStore, ProjectResource, SceneResource, SystemSettingsResource,
    TimelineResource,
};
use crate::ecs::transform::Camera;
use shipyard::{AddComponent, Get, UniqueView, UniqueViewMut, World};

impl EcsWorld {
    pub fn new() -> Self {
        let world = World::new();
        world.add_unique(TimelineResource::new());
        world.add_unique(ProjectResource::new());
        world.add_unique(LayerStates::new(resources::DEFAULT_LAYER_COUNT));
        world.add_unique(SceneResource::new());
        world.add_unique(SystemSettingsResource::new());
        world.add_unique(Camera::default());
        world.add_unique(PresetStore::new());
        world.add_unique(HistoryStack::new());
        Self {
            world,
            selected_ids: std::collections::HashSet::new(),
            revision: 0,
        }
    }

    pub(crate) fn touch(&mut self) {
        self.revision += 1;
    }

    pub fn revision(&self) -> u64 {
        self.revision
    }

    pub fn set_selected_ids(&mut self, ids: std::collections::HashSet<usize>) {
        self.selected_ids = ids;
    }

    pub fn selected_ids(&self) -> &std::collections::HashSet<usize> {
        &self.selected_ids
    }

    pub fn clear_selection(&mut self) {
        self.selected_ids.clear();
    }

    pub fn select_id(&mut self, id: usize, clear_others: bool) {
        if clear_others {
            self.selected_ids.clear();
        }
        self.selected_ids.insert(id);
    }

    pub fn is_selected(&self, id: usize) -> bool {
        self.selected_ids.contains(&id)
    }

    #[allow(dead_code)]
    pub fn undo(&mut self) -> bool {
        self.undo_internal()
    }

    #[allow(dead_code)]
    pub fn redo(&mut self) -> bool {
        self.redo_internal()
    }

    #[allow(dead_code)]
    pub fn can_undo(&self) -> bool {
        self.world
            .borrow::<UniqueView<HistoryStack>>()
            .map(|s| s.can_undo())
            .unwrap_or(false)
    }

    #[allow(dead_code)]
    pub fn can_redo(&self) -> bool {
        self.world
            .borrow::<UniqueView<HistoryStack>>()
            .map(|s| s.can_redo())
            .unwrap_or(false)
    }

    #[allow(dead_code)]
    pub fn push_history_command(&mut self, command: Box<dyn HistoryCommand>) {
        if let Ok(mut stack) = self.world.borrow::<UniqueViewMut<HistoryStack>>() {
            stack.push(command);
        }
        self.touch();
    }

    #[allow(dead_code)]
    pub fn history_done_len(&self) -> usize {
        self.world
            .borrow::<UniqueView<HistoryStack>>()
            .map(|s| s.done_len())
            .unwrap_or(0)
    }

    #[allow(dead_code)]
    pub fn history_undone_len(&self) -> usize {
        self.world
            .borrow::<UniqueView<HistoryStack>>()
            .map(|s| s.undone_len())
            .unwrap_or(0)
    }

    #[allow(dead_code)]
    pub fn poll_effect_writebacks(&mut self) -> usize {
        let count = history::poll_all_effect_writebacks(&mut self.world);
        if count > 0 {
            self.touch();
        }
        count
    }

    fn undo_internal(&mut self) -> bool {
        let cmd = match self.world.borrow::<UniqueViewMut<HistoryStack>>() {
            Ok(mut stack) => stack.pop_done(),
            Err(_) => return false,
        };

        if let Some(mut command) = cmd {
            command.revert(&mut self.world);
            if let Ok(mut stack) = self.world.borrow::<UniqueViewMut<HistoryStack>>() {
                stack.push_undone(command);
            }
            self.touch();
            true
        } else {
            false
        }
    }

    fn redo_internal(&mut self) -> bool {
        let cmd = match self.world.borrow::<UniqueViewMut<HistoryStack>>() {
            Ok(mut stack) => stack.pop_undone(),
            Err(_) => return false,
        };

        if let Some(mut command) = cmd {
            command.apply(&mut self.world);
            if let Ok(mut stack) = self.world.borrow::<UniqueViewMut<HistoryStack>>() {
                stack.push_done(command);
            }
            self.touch();
            true
        } else {
            false
        }
    }

    #[allow(dead_code)]
    pub fn set_property_expression(
        &mut self,
        object_id: usize,
        prop_key: &str,
        script: &str,
        enabled: bool,
    ) -> bool {
        let Some(entity) = self.find_entity(object_id) else {
            return false;
        };

        let success = self.world.run(
            |mut exprs: shipyard::ViewMut<crate::ecs::components::PropertyExpressions>| {
                if let Ok(mut comp) = (&mut exprs).get(entity) {
                    comp.set_expression(prop_key, script, enabled)
                } else {
                    let mut comp = crate::ecs::components::PropertyExpressions::new();
                    let ok = comp.set_expression(prop_key, script, enabled);
                    if ok {
                        let _ = exprs.add_component_unchecked(entity, comp);
                    }
                    ok
                }
            },
        );

        if success {
            self.touch();
        }
        success
    }

    #[allow(dead_code)]
    pub fn get_property_expression(
        &self,
        object_id: usize,
        prop_key: &str,
    ) -> Option<(String, bool)> {
        let entity = self.find_entity(object_id)?;
        self.world.run(
            |exprs: shipyard::View<crate::ecs::components::PropertyExpressions>| {
                let comp = exprs.get(entity).ok()?;
                let (script, enabled) = comp.get_expression(prop_key)?;
                Some((script.to_string(), enabled))
            },
        )
    }

    #[allow(dead_code)]
    pub fn remove_property_expression(&mut self, object_id: usize, prop_key: &str) -> bool {
        let Some(entity) = self.find_entity(object_id) else {
            return false;
        };

        let removed = self.world.run(
            |mut exprs: shipyard::ViewMut<crate::ecs::components::PropertyExpressions>| {
                if let Ok(mut comp) = (&mut exprs).get(entity) {
                    comp.remove_expression(prop_key)
                } else {
                    false
                }
            },
        );

        if removed {
            self.touch();
        }
        removed
    }

    #[allow(dead_code)]
    pub fn evaluate_expressions(&mut self, frame: i32, fps: f32) -> usize {
        let count = crate::ecs::systems::expression::evaluate_expressions_for_world(
            &mut self.world,
            frame,
            fps,
        );
        if count > 0 {
            self.touch();
        }
        count
    }
}

