const TRANSFORM_KEYS: [&str; 9] = [
    "x", "y", "z", "scale_x", "scale_y", "rot_x", "rot_y", "rot_z", "opacity",
];

impl EcsWorld {
    pub fn add_object(
        &mut self,
        start: i32,
        duration: i32,
        kind_id: u32,
        layer: i32,
        text: Option<TextContent>,
    ) -> usize {
        let (id, scene_id) = self.world.run(
            |mut timeline: UniqueViewMut<TimelineResource>, scenes: UniqueView<SceneResource>| {
                let id = timeline.next_id;
                timeline.next_id += 1;
                (id, scenes.active_scene)
            },
        );

        let entity = self.world.add_entity((
            ObjectId(id),
            TimeRange {
                start_frame: start,
                end_frame: start + duration,
            },
            KindId(kind_id),
            Layer(layer),
            SceneId(scene_id),
            Transform::default(),
            GlobalMatrix::default(),
            EffectStack::default(),
        ));
        self.world
            .add_component(entity, (BlendMode::default(), TimeRemap::default()));
        let transform = Transform::default();
        let mut tracks = KeyframeTracks::default();
        for key in TRANSFORM_KEYS {
            if let Some(value) = transform.get_param(key) {
                tracks.seed_start(key, start, value);
            }
        }
        self.world.add_component(entity, tracks);

        let is_audio_kind = crate::objects::loader::by_kind_id(kind_id)
            .is_some_and(|p| p.stable_id == neoutl_object_api::AUDIO_STABLE_ID);
        if is_audio_kind {
            self.world.add_component(entity, AudioParams::default());
        }

        if let Some(t) = text {
            self.world.add_component(entity, t);
        }

        self.update_total_frames();
        self.touch();
        id
    }

