                        k.clone(),
                        v.keyframes
                            .iter()
                            .map(Keyframe::try_from)
                            .collect::<Result<Vec<_>, _>>()?,
                    ))
                })
                .collect::<Result<HashMap<_, _>, String>>()?,
        })
    }
}

