use super::*;

static DEVICE_LOST: AtomicBool = AtomicBool::new(false);

pub fn is_device_lost() -> bool {
    DEVICE_LOST.load(Ordering::Relaxed)
}

fn mark_device_lost(reason: &str) {
    eprintln!(
        "{}",
        t!(
            "[NeoUtl] GPUデバイスロスト検知: %{arg0}",
            arg0 = reason.to_string()
        )
    );
    DEVICE_LOST.store(true, Ordering::Relaxed);
}

pub fn install_device_lost_watcher(device: &wgpu::Device) {
    device.set_device_lost_callback(|reason, message| {
        mark_device_lost(&format!("{reason:?}: {message}"));
    });
}

#[allow(dead_code)]
pub fn reset_device_lost() {
    DEVICE_LOST.store(false, Ordering::Relaxed);
}

use super::shaders::EffectObjectDrawKind;
use super::*;
use crate::ecs::components::BlendMode;

impl RenderEngine {
    pub(super) fn apply_effect_chain(
        &mut self,
        world: &crate::ecs::EcsWorld,
        objects: &[ActiveObject],
        captured: &CapturedObjects,
        depth: u32,
        src: &wgpu::Texture,
        dst: &wgpu::Texture,
        chain: &[(String, HashMap<String, Value>)],
        timeline_frame: i32,
        fps: u32,
        initial_roi: neoutl_shared_abi::Roi,
    ) {
        let extent = wgpu::Extent3d {
            width: self.render_width,
            height: self.render_height,
            depth_or_array_layers: 1,
        };

        if chain.is_empty() {
            if std::ptr::eq(src, dst) {
                return;
            }
            let mut encoder = self
                .device
                .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                    label: Some("Effect Passthrough Copy Encoder"),
                });
            encoder.copy_texture_to_texture(src.as_image_copy(), dst.as_image_copy(), extent);
            crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
            return;
        }

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Effect Copy Encoder"),
            });
        encoder.copy_texture_to_texture(
            src.as_image_copy(),
            self.effect_ping.as_image_copy(),
            extent,
        );
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);

        let mut src_is_ping = true;
        let mut roi = initial_roi;
        for (effect_id, params) in chain {
            let Some(source) = effects::loader::by_id(effect_id) else {
                continue;
            };
            if matches!(source.kind(), neoutl_effect_api::EffectKind::Audio) {
                continue;
            }
            let schema = source.param_schema();
            let values: Vec<f32> = schema
                .iter()
                .map(|s| {
                    params
                        .get(s.key.as_str())
                        .map_or(s.default_float, |v| match v {
                            Value::Number(n) => *n,
                            Value::Bool(b) => {
                                if *b {
                                    1.0
                                } else {
                                    0.0
                                }
                            }
                            Value::Enum(idx) => *idx as f32,
                            Value::Text(_) | Value::FilePath(_) | Value::TrackRef(_) => {
                                s.default_float
                            }
                        })
                })
                .collect();
            if let effects::loader::EffectSource::Native(plugin) = source.as_ref()
                && let Some(needs_frame) = plugin.vtable.is_need_render_frame
                && unsafe {
                    needs_frame(
                        values.as_ptr(),
                        values.len() as u32,
                        i64::from(timeline_frame) * 1_000_000 / i64::from(fps.max(1)),
                    )
                } == 0
            {
                continue;
            }

            if let effects::loader::EffectSource::Native(plugin) = source.as_ref()
                && let Some(calc_roi) = plugin.vtable.calc_roi
            {
                let next = unsafe {
                    calc_roi(
                        roi,
                        values.as_ptr(),
                        values.len() as u32,
                        i64::from(timeline_frame) * 1_000_000 / i64::from(fps.max(1)),
                        1.0,
                        1.0,
                    )
                };
                if [next.x, next.y, next.w, next.h]
                    .iter()
                    .all(|v| v.is_finite())
                    && next.w > 0.0
                    && next.h > 0.0
                {
                    roi = next;
                }
            }
            let uniform_size = (source.uniform_size() as usize).max(16);
            let mut bytes = vec![0u8; uniform_size];
            source.pack_uniform(&values, &mut bytes);
            self.queue
                .write_buffer(&self.effect_uniform_buffer, 0, &bytes);

            let requires_tex_idx = source.requires_texture_param_index();
            let resolved_scene_tex: Option<wgpu::Texture> = if let Some(idx) = requires_tex_idx {
                let scene_ref = schema.get(idx as usize).and_then(|s| {
                    params.get(s.key.as_str()).and_then(|v| match v {
                        Value::TrackRef(id) => Some(*id),
                        _ => None,
                    })
                });
                if let Some(scene_id) = scene_ref {
                    self.render_composed_texture(
                        world,
                        objects,
                        captured,
                        self.render_width,
                        self.render_height,
                        ComposeCacheKey::EffectMapScene(scene_id),
                        depth + 1,
                        None,
                        timeline_frame,
                    )
                } else {
                    None
                }
            } else {
                None
            };
            let map_view: wgpu::TextureView = if let Some(t) = &resolved_scene_tex {
                t.create_view(&wgpu::TextureViewDescriptor::default())
            } else if let Some(idx) = requires_tex_idx {
                let path = schema.get(idx as usize).and_then(|s| {
                    params.get(s.key.as_str()).and_then(|v| match v {
                        Value::FilePath(p) => Some(p.clone()),
                        _ => None,
                    })
                });
                match path.and_then(|p| {
                    self.map_texture_cache
                        .get(std::path::Path::new(&p))
                        .cloned()
                }) {
                    Some(t) => t.create_view(&wgpu::TextureViewDescriptor::default()),
                    None => self.dummy_map_texture_view.clone(),
                }
            } else {
                self.dummy_map_texture_view.clone()
            };

            let (src_tex, dst_tex) = if src_is_ping {
                (&self.effect_ping, &self.effect_pong)
            } else {
                (&self.effect_pong, &self.effect_ping)
            };
            let native_vtable = match source.as_ref() {
                effects::loader::EffectSource::Native(plugin) => Some(plugin.vtable),
                effects::loader::EffectSource::Lua(_) => None,
            };
            let namespace = native_vtable.map_or_else(
                || effect_id.as_ptr() as usize,
                |v| unsafe { (v.meta)() as usize },
            );
            let bridge = || {
                super::effect_gpu::Bridge::new(
                    self.device.clone(),
                    self.queue.clone(),
                    src_tex,
                    dst_tex,
                    self.map_texture_cache.clone(),
                    namespace,
                    self.render_width,
                    self.render_height,
                    roi,
                )
            };
            if let Some(render) = native_vtable.and_then(|v| v.custom_render) {
                let mut preserve = self.device.create_command_encoder(&Default::default());
                preserve.copy_texture_to_texture(
                    src_tex.as_image_copy(),
                    dst_tex.as_image_copy(),
                    extent,
                );
                crate::infra::gpu_shared::locked_submit(&self.queue, [preserve.finish()]);
                let status = super::effect_gpu::run_custom(bridge(), |ctx| unsafe {
                    render(ctx as *const _, values.as_ptr(), values.len() as u32)
                });
                if status != 0 {
                    eprintln!(
                        "[NeoUtl] effect custom_render failed: id={effect_id}, code={status}"
                    );
                    continue;
                }
                src_is_ping = !src_is_ping;
                continue;
            }
            if let Some(vtable) = native_vtable
                && let Some(get_shader) = vtable.compute_wgsl
            {
                let shader = unsafe { get_shader() };
                let shader = unsafe { shader.as_slice() };
                if !shader.is_empty() {
                    let dispatch = vtable.compute_dispatch.map_or(
                        neoutl_shared_abi::ComputeDispatch {
                            group_count_x: self.render_width.div_ceil(8),
                            group_count_y: self.render_height.div_ceil(8),
                            group_count_z: 1,
                        },
                        |f| unsafe {
                            f(
                                values.as_ptr(),
                                values.len() as u32,
                                self.render_width,
                                self.render_height,
                            )
                        },
                    );
                    match super::effect_gpu::run_compute(bridge(), shader, &bytes, dispatch) {
                        Ok(()) => src_is_ping = !src_is_ping,
                        Err(code) => eprintln!(
                            "[NeoUtl] effect compute_wgsl failed: id={effect_id}, code={code}"
                        ),
                    }
                    continue;
                }
            }
            let Some((pipeline, vertex_pipeline)) = self.effect_pipelines.get(effect_id).cloned()
            else {
                continue;
            };
            let pipeline = vertex_pipeline.unwrap_or(pipeline);
            let src_view = src_tex.create_view(&wgpu::TextureViewDescriptor::default());
            let dst_view = dst_tex.create_view(&wgpu::TextureViewDescriptor::default());

            let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("Effect Pass BG"),
                layout: &self.effect_bind_group_layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: wgpu::BindingResource::TextureView(&src_view),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: wgpu::BindingResource::Sampler(&self.effect_sampler),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: self.effect_uniform_buffer.as_entire_binding(),
                    },
                    wgpu::BindGroupEntry {
                        binding: 3,
                        resource: wgpu::BindingResource::TextureView(&map_view),
                    },
                    wgpu::BindGroupEntry {
                        binding: 4,
                        resource: wgpu::BindingResource::Sampler(&self.effect_sampler),
                    },
                ],
            });

            let mut encoder = self
                .device
                .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                    label: Some("Effect Pass Encoder"),
                });
            encoder.copy_texture_to_texture(
                src_tex.as_image_copy(),
                dst_tex.as_image_copy(),
                extent,
            );
            {
                let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("Effect Pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &dst_view,
                        resolve_target: None,
                        ops: wgpu::Operations {
                            load: wgpu::LoadOp::Load,
                            store: wgpu::StoreOp::Store,
                        },
                        depth_slice: None,
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: None,
                    occlusion_query_set: None,
                    multiview_mask: None,
                });
                let sx = roi.x.floor().max(0.0).min(self.render_width as f32) as u32;
                let sy = roi.y.floor().max(0.0).min(self.render_height as f32) as u32;
                let ex = (roi.x + roi.w)
                    .ceil()
                    .max(0.0)
                    .min(self.render_width as f32) as u32;
                let ey = (roi.y + roi.h)
                    .ceil()
                    .max(0.0)
                    .min(self.render_height as f32) as u32;
                if ex <= sx || ey <= sy {
                    continue;
                }
                rpass.set_scissor_rect(sx, sy, ex - sx, ey - sy);
                rpass.set_pipeline(&pipeline);
                rpass.set_bind_group(0, &bind_group, &[]);
                rpass.draw(0..3, 0..1);
            }
            crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
            src_is_ping = !src_is_ping;
        }

        let final_src = if src_is_ping {
            &self.effect_ping
        } else {
            &self.effect_pong
        };
        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Effect Finalize Encoder"),
            });
        encoder.copy_texture_to_texture(final_src.as_image_copy(), dst.as_image_copy(), extent);
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
    }

    pub(super) fn draw_standard_pass(
        &self,
        rpass: &mut wgpu::RenderPass,
        obj: &ActiveObject,
        offset: u32,
    ) {
        if let Some((pipelines, vertex_count)) = self.pipelines.get(&obj.kind_id) {
            rpass.set_pipeline(&pipelines[obj.blend_mode.pipeline_index() as usize]);
            rpass.set_bind_group(0, &self.bind_group, &[offset]);
            rpass.draw(0..*vertex_count, 0..1);
        }
    }

    pub(super) fn draw_object_hook(
        &self,
        rpass: &mut wgpu::RenderPass,
        obj: &ActiveObject,
        bind_group: &wgpu::BindGroup,
        depth_enabled: bool,
        vertex_count_override: Option<u32>,
    ) {
        let Some(plugin) = by_kind_id(obj.kind_id) else {
            return;
        };
        let vertex_count =
            vertex_count_override.unwrap_or_else(|| unsafe { (plugin.vtable.vertex_count)() });
        let context = neoutl_object_api::RenderContext {
            version: 1,
            render_pass_ptr: (rpass as *mut wgpu::RenderPass<'_>).cast(),
            bind_group_ptr: (bind_group as *const wgpu::BindGroup).cast(),
            vertex_count,
            mvp_matrix: obj.mvp,
            opacity: obj.opacity,
            depth_enabled,
            ref_layer_texture_ptr: std::ptr::null(),
            ref_layer_texture_count: 0,
        };
        unsafe { (plugin.vtable.render)(&context) };
    }

    pub(super) fn draw_media_pass_with_hook(
        &self,
        rpass: &mut wgpu::RenderPass,
        texture: &wgpu::Texture,
        offset: u32,
        blend_mode: BlendMode,
        obj: &ActiveObject,
        depth_enabled: bool,
    ) {
        let variant = blend_mode.pipeline_index() as usize;
        let is_planar = matches!(texture.format(), wgpu::TextureFormat::NV12);
        if is_planar {
            let plane_y = texture.create_view(&wgpu::TextureViewDescriptor {
                aspect: wgpu::TextureAspect::Plane0,
                ..Default::default()
            });
            let plane_uv = texture.create_view(&wgpu::TextureViewDescriptor {
                aspect: wgpu::TextureAspect::Plane1,
                ..Default::default()
            });
            let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("Video Object BG"),
                layout: &self.video_bind_group_layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: wgpu::BindingResource::Buffer(wgpu::BufferBinding {
                            buffer: &self.media_uniform_buffer,
                            offset: 0,
                            size: wgpu::BufferSize::new(MEDIA_UNIFORM_SIZE),
                        }),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: wgpu::BindingResource::TextureView(&plane_y),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: wgpu::BindingResource::TextureView(&plane_uv),
                    },
                    wgpu::BindGroupEntry {
                        binding: 3,
                        resource: wgpu::BindingResource::Sampler(&self.media_sampler),
                    },
                ],
            });
            rpass.set_pipeline(&self.video_pipeline[variant]);
            rpass.set_bind_group(0, &bind_group, &[offset]);
            rpass.draw(0..6, 0..1);
            self.draw_object_hook(rpass, obj, &bind_group, depth_enabled, Some(6));
        } else {
            let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
            let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some("Media Object BG"),
                layout: &self.media_bind_group_layout,
                entries: &[
                    wgpu::BindGroupEntry {
                        binding: 0,
                        resource: wgpu::BindingResource::Buffer(wgpu::BufferBinding {
                            buffer: &self.media_uniform_buffer,
                            offset: 0,
                            size: wgpu::BufferSize::new(MEDIA_UNIFORM_SIZE),
                        }),
                    },
                    wgpu::BindGroupEntry {
                        binding: 1,
                        resource: wgpu::BindingResource::TextureView(&view),
                    },
                    wgpu::BindGroupEntry {
                        binding: 2,
                        resource: wgpu::BindingResource::Sampler(&self.media_sampler),
                    },
                ],
            });
            rpass.set_pipeline(&self.media_pipeline[variant]);
            rpass.set_bind_group(0, &bind_group, &[offset]);
            rpass.draw(0..6, 0..1);
            self.draw_object_hook(rpass, obj, &bind_group, depth_enabled, Some(6));
        }
    }

    pub(super) fn draw_text_pass_with_hook(
        &self,
        rpass: &mut wgpu::RenderPass,
        clip_instance: u64,
        offset: u32,
        blend_mode: BlendMode,
        obj: &ActiveObject,
        depth_enabled: bool,
    ) {
        let Some(target) = self.text_targets.get(&clip_instance) else {
            return;
        };
        let view = target
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("Text Object BG"),
            layout: &self.media_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::Buffer(wgpu::BufferBinding {
                        buffer: &self.media_uniform_buffer,
                        offset: 0,
                        size: wgpu::BufferSize::new(MEDIA_UNIFORM_SIZE),
                    }),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::TextureView(&view),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::Sampler(&self.media_sampler),
                },
            ],
        });
        rpass.set_pipeline(&self.media_pipeline[blend_mode.pipeline_index() as usize]);
        rpass.set_bind_group(0, &bind_group, &[offset]);
        rpass.draw(0..6, 0..1);
        self.draw_object_hook(rpass, obj, &bind_group, depth_enabled, Some(6));
    }

    pub(super) fn render_effect_object_offscreen(
        &self,
        pool_tex: &wgpu::Texture,
        draw_kind: EffectObjectDrawKind,
        obj: &ActiveObject,
    ) {
        let view = pool_tex.create_view(&wgpu::TextureViewDescriptor::default());
        let depth_view = self
            .effect_object_depth
            .create_view(&wgpu::TextureViewDescriptor::default());
        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Effect Object Encoder"),
            });
        {
            let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("Effect Object Pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                        store: wgpu::StoreOp::Store,
                    },
                    depth_slice: None,
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            match draw_kind {
                EffectObjectDrawKind::Standard { obj, offset } => {
                    self.draw_standard_pass(&mut rpass, obj, offset);
                    self.draw_object_hook(&mut rpass, obj, &self.bind_group, false, None);
                }
                EffectObjectDrawKind::Media {
                    texture,
                    offset,
                    blend_mode,
                } => {
                    self.draw_media_pass_with_hook(
                        &mut rpass, texture, offset, blend_mode, obj, false,
                    );
                }
                EffectObjectDrawKind::Text {
                    clip_instance,
                    offset,
                    blend_mode,
                } => {
                    self.draw_text_pass_with_hook(
                        &mut rpass,
                        clip_instance,
                        offset,
                        blend_mode,
                        obj,
                        false,
                    );
                }
            }
        }
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
    }

    pub(super) fn composite_effect_object(
        &self,
        pool_tex: &wgpu::Texture,
        clear_color: Option<wgpu::Color>,
        blend_mode: BlendMode,
    ) {
        let src_view = pool_tex.create_view(&wgpu::TextureViewDescriptor::default());
        let dst_view = self
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let src_depth_view = self
            .effect_object_depth
            .create_view(&wgpu::TextureViewDescriptor::default());
        let dst_depth_view = self
            .depth_texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("Composite BG"),
            layout: &self.composite_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::TextureView(&src_view),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::Sampler(&self.effect_sampler),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::TextureView(&src_depth_view),
                },
            ],
        });
        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Composite Encoder"),
            });
        {
            let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("Composite Pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &dst_view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: match clear_color {
                            Some(c) => wgpu::LoadOp::Clear(c),
                            None => wgpu::LoadOp::Load,
                        },
                        store: wgpu::StoreOp::Store,
                    },
                    depth_slice: None,
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &dst_depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: match clear_color {
                            Some(_) => wgpu::LoadOp::Clear(1.0),
                            None => wgpu::LoadOp::Load,
                        },
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            rpass.set_pipeline(&self.composite_pipeline[blend_mode.pipeline_index() as usize]);
            rpass.set_bind_group(0, &bind_group, &[]);
            rpass.draw(0..3, 0..1);
        }
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
    }

    pub(super) fn composite_clipped_object(
        &self,
        content_pool_tex: &wgpu::Texture,
        mold_pool_tex: &wgpu::Texture,
        mode: crate::ecs::components::ClipMode,
        chroma_hue: f32,
        chroma_tolerance: f32,
        blend_edge: bool,
        clear_color: Option<wgpu::Color>,
    ) {
        let content_view = content_pool_tex.create_view(&wgpu::TextureViewDescriptor::default());
        let mold_view = mold_pool_tex.create_view(&wgpu::TextureViewDescriptor::default());
        let dst_view = self
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let content_depth_view = self
            .effect_object_depth
            .create_view(&wgpu::TextureViewDescriptor::default());
        let dst_depth_view = self
            .depth_texture
            .create_view(&wgpu::TextureViewDescriptor::default());

        let uniform_data: [u32; 4] = [
            mode as u8 as u32,
            chroma_hue.to_bits(),
            chroma_tolerance.to_bits(),
            u32::from(blend_edge),
        ];
        self.queue.write_buffer(
            &self.clip_uniform_buffer,
            0,
            bytemuck::cast_slice(&uniform_data),
        );

        let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("Clip Composite BG"),
            layout: &self.clip_composite_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::TextureView(&content_view),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::TextureView(&mold_view),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::Sampler(&self.effect_sampler),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: wgpu::BindingResource::TextureView(&content_depth_view),
                },
                wgpu::BindGroupEntry {
                    binding: 4,
                    resource: self.clip_uniform_buffer.as_entire_binding(),
                },
            ],
        });
        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("Clip Composite Encoder"),
            });
        {
            let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("Clip Composite Pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &dst_view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: match clear_color {
                            Some(c) => wgpu::LoadOp::Clear(c),
                            None => wgpu::LoadOp::Load,
                        },
                        store: wgpu::StoreOp::Store,
                    },
                    depth_slice: None,
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &dst_depth_view,
                    depth_ops: Some(wgpu::Operations {
                        load: match clear_color {
                            Some(_) => wgpu::LoadOp::Clear(1.0),
                            None => wgpu::LoadOp::Load,
                        },
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            rpass.set_pipeline(&self.clip_composite_pipeline);
            rpass.set_bind_group(0, &bind_group, &[]);
            rpass.draw(0..3, 0..1);
        }
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
    }
}

use egui_wgpu::wgpu;
use neoutl_effect_api::EffectRenderContext;
use neoutl_shared_abi::{
    CacheHandle, CacheImageRef, ComputeDispatch, ResourceKind, ResourceRef, StrRef,
};
use std::{
    cell::RefCell,
    collections::HashMap,
    path::PathBuf,
    sync::{Arc, Mutex, OnceLock},
};
use wgpu::util::DeviceExt;

thread_local! {
    static ACTIVE: RefCell<Option<Bridge>> = const { RefCell::new(None) };
}

static CACHES: OnceLock<Mutex<HashMap<(usize, usize, String), wgpu::Texture>>> = OnceLock::new();
static CACHE_HANDLE: CacheHandle = CacheHandle {
    get_image: cache_get,
    create_image: cache_create,
    clear_image: cache_clear,
};

pub(super) struct Bridge {
    device: Arc<wgpu::Device>,
    queue: Arc<wgpu::Queue>,
    object: wgpu::Texture,
    framebuffer: wgpu::Texture,
    images: HashMap<PathBuf, wgpu::Texture>,
    random: wgpu::Texture,
    named: HashMap<String, wgpu::Texture>,
    temps: HashMap<String, wgpu::Texture>,
    namespace: usize,
    width: u32,
    height: u32,
    roi: neoutl_shared_abi::Roi,
}

impl Bridge {
    pub(super) fn new(
        device: Arc<wgpu::Device>,
        queue: Arc<wgpu::Queue>,
        object: &wgpu::Texture,
        framebuffer: &wgpu::Texture,
        images: HashMap<PathBuf, wgpu::Texture>,
        namespace: usize,
        width: u32,
        height: u32,
        roi: neoutl_shared_abi::Roi,
    ) -> Self {
        let random = device.create_texture(&wgpu::TextureDescriptor {
            label: Some("Effect Random Resource"),
            size: wgpu::Extent3d {
                width: 256,
                height: 256,
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: wgpu::TextureFormat::Rgba8Unorm,
            usage: wgpu::TextureUsages::TEXTURE_BINDING
                | wgpu::TextureUsages::COPY_DST
                | wgpu::TextureUsages::COPY_SRC,
            view_formats: &[],
        });
        let mut pixels = vec![0u8; 256 * 256 * 4];
        let mut state = 0x9e37_79b9u32;
        for p in pixels.chunks_exact_mut(4) {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            p.copy_from_slice(&[
                (state & 255) as u8,
                ((state >> 8) & 255) as u8,
                ((state >> 16) & 255) as u8,
                255,
            ]);
        }
        queue.write_texture(
            random.as_image_copy(),
            &pixels,
            wgpu::TexelCopyBufferLayout {
                offset: 0,
                bytes_per_row: Some(256 * 4),
                rows_per_image: Some(256),
            },
            random.size(),
        );
        Self {
            device,
            queue,
            object: object.clone(),
            framebuffer: framebuffer.clone(),
            images,
            random,
            named: HashMap::new(),
            temps: HashMap::new(),
            namespace,
            width,
            height,
            roi,
        }
    }

    fn create_storage_texture(&self, label: &str, width: u32, height: u32) -> wgpu::Texture {
        let texture = self.device.create_texture(&wgpu::TextureDescriptor {
            label: Some(label),
            size: wgpu::Extent3d {
                width: width.max(1),
                height: height.max(1),
                depth_or_array_layers: 1,
            },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: wgpu::TextureFormat::Rgba8Unorm,
            usage: wgpu::TextureUsages::TEXTURE_BINDING
                | wgpu::TextureUsages::RENDER_ATTACHMENT
                | wgpu::TextureUsages::STORAGE_BINDING
                | wgpu::TextureUsages::COPY_SRC
                | wgpu::TextureUsages::COPY_DST,
            view_formats: &[],
        });
        let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
        let mut encoder = self.device.create_command_encoder(&Default::default());
        let _pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("Initialize Effect Storage Texture"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: &view,
                resolve_target: None,
                ops: wgpu::Operations {
                    load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                    store: wgpu::StoreOp::Store,
                },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        drop(_pass);
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
        texture
    }

    fn resolve(&mut self, resource: ResourceRef, create: bool) -> Option<wgpu::Texture> {
        let name = unsafe { ref_name(resource.name) }?;
        match resource.kind {
            ResourceKind::Object => Some(self.object.clone()),
            ResourceKind::Framebuffer => Some(self.framebuffer.clone()),
            ResourceKind::Random => Some(self.random.clone()),
            ResourceKind::Image => {
                let path = PathBuf::from(name);
                if let Some(texture) = self.images.get(&path) {
                    return Some(texture.clone());
                }
                let texture = neoutl_media_runtime::cache::global()
                    .frame_at(&path, 0, 0, &self.device, &self.queue)
                    .ok()?;
                self.images.insert(path, texture.clone());
                Some(texture)
            }
            ResourceKind::Named => {
                if create && !self.named.contains_key(&name) {
                    let texture = self.create_storage_texture(
                        "Effect Named Resource",
                        self.width,
                        self.height,
                    );
                    self.named.insert(name.clone(), texture);
                }
                self.named.get(&name).cloned()
            }
            ResourceKind::TempBuffer => {
                let key = if name.is_empty() {
                    "default".to_owned()
                } else {
                    name
                };
                if create && !self.temps.contains_key(&key) {
                    let texture = self.create_storage_texture(
                        "Effect Temporary Resource",
                        self.width,
                        self.height,
                    );
                    self.temps.insert(key.clone(), texture);
                }
                self.temps.get(&key).cloned()
            }
            ResourceKind::Cache => CACHES
                .get_or_init(Default::default)
                .lock()
                .ok()?
                .get(&(
                    self.device.as_ref() as *const _ as usize,
                    self.namespace,
                    name,
                ))
                .cloned(),
        }
    }
}

unsafe fn ref_name(name: StrRef) -> Option<String> {
    if name.len == 0 {
        return Some(String::new());
    }
    if name.ptr.is_null() {
        return None;
    }
    let bytes = unsafe { std::slice::from_raw_parts(name.ptr, name.len) };
    std::str::from_utf8(bytes).ok().map(str::to_owned)
}

fn with_context<R>(bridge: Bridge, f: impl FnOnce(&EffectRenderContext) -> R) -> R {
    ACTIVE.with(|slot| {
        let namespace = bridge.namespace;
        let previous = slot.replace(Some(bridge));
        let context = EffectRenderContext {
            cache: &CACHE_HANDLE,
            cache_identifier: namespace as *const (),
            exec_pixelshader,
            exec_computeshader,
            get_resource_size,
            get_resource_data,
            set_resource_data,
            release_resource,
        };
        struct Restore(*const RefCell<Option<Bridge>>, Option<Bridge>);
        impl Drop for Restore {
            fn drop(&mut self) {
                unsafe {
                    (*self.0).replace(self.1.take());
                }
            }
        }
        let restore = Restore(slot as *const _, previous);
        let result = f(&context);
        drop(restore);
        result
    })
}

fn with_active<R>(f: impl FnOnce(&mut Bridge) -> Result<R, u32>) -> Result<R, u32> {
    ACTIVE.with(|slot| {
        let mut active = slot.try_borrow_mut().map_err(|_| 1u32)?;
        f(active.as_mut().ok_or(1u32)?)
    })
}

unsafe extern "C" fn cache_get(identifier: *const (), name: StrRef) -> CacheImageRef {
    let original_name = name;
    let Some(name) = (unsafe { ref_name(name) }) else {
        return CacheImageRef::empty();
    };
    with_active(|bridge| {
        let key = (
            bridge.device.as_ref() as *const _ as usize,
            identifier as usize,
            name.clone(),
        );
        let caches = CACHES
            .get_or_init(Default::default)
            .lock()
            .map_err(|_| 1u32)?;
        let Some(texture) = caches.get(&key) else {
            return Ok(CacheImageRef::empty());
        };
        Ok(CacheImageRef {
            resource: ResourceRef::cache(original_name),
            width: texture.width(),
            height: texture.height(),
            valid: 1,
        })
    })
    .unwrap_or_else(|_| CacheImageRef::empty())
}

unsafe extern "C" fn cache_create(
    identifier: *const (),
    name: StrRef,
    width: u32,
    height: u32,
) -> CacheImageRef {
    let original_name = name;
    let Some(name) = (unsafe { ref_name(name) }) else {
        return CacheImageRef::empty();
    };
    with_active(|bridge| {
        let key = (
            bridge.device.as_ref() as *const _ as usize,
            identifier as usize,
            name.clone(),
        );
        let mut caches = CACHES
            .get_or_init(Default::default)
            .lock()
            .map_err(|_| 1u32)?;
        let texture = match caches.get(&key) {
            Some(texture)
                if texture.width() == width.max(1) && texture.height() == height.max(1) =>
            {
                texture.clone()
            }
            _ => {
                let texture = bridge.create_storage_texture("Effect VRAM Cache", width, height);
                caches.insert(key, texture.clone());
                texture
            }
        };
        Ok(CacheImageRef {
            resource: ResourceRef::cache(original_name),
            width: texture.width(),
            height: texture.height(),
            valid: 1,
        })
    })
    .unwrap_or_else(|_| CacheImageRef::empty())
}

unsafe extern "C" fn cache_clear(identifier: *const (), name: StrRef) {
    let Some(name) = (unsafe { ref_name(name) }) else {
        return;
    };
    let _ = with_active(|bridge| {
        CACHES
            .get_or_init(Default::default)
            .lock()
            .map_err(|_| 1u32)?
            .remove(&(
                bridge.device.as_ref() as *const _ as usize,
                identifier as usize,
                name,
            ));
        Ok(())
    });
}

unsafe extern "C" fn exec_pixelshader(
    data: *const u8,
    len: usize,
    target: ResourceRef,
    resources: *const ResourceRef,
    resource_count: u32,
    constants: *const u8,
    constant_len: usize,
) -> u32 {
    if data.is_null()
        || (resource_count > 0 && resources.is_null())
        || (constant_len > 0 && constants.is_null())
    {
        return 2;
    }
    if resource_count > 2 {
        return 3;
    }
    let wgsl = unsafe { std::slice::from_raw_parts(data, len) };
    let refs = if resource_count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(resources, resource_count as usize) }
    };
    let constants = if constant_len == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(constants, constant_len) }
    };
    with_active(|bridge| render_pixel(bridge, wgsl, target, refs, constants)).map_or(4, |_| 0)
}

fn render_pixel(
    bridge: &mut Bridge,
    wgsl: &[u8],
    target: ResourceRef,
    resources: &[ResourceRef],
    constants: &[u8],
) -> Result<(), u32> {
    let target_tex = bridge.resolve(target, true).ok_or(2u32)?;
    if matches!(target.kind, ResourceKind::Object) {
        return Err(3);
    }
    let first = if let Some(r) = resources.first() {
        bridge.resolve(*r, false).ok_or(2u32)?
    } else {
        bridge.object.clone()
    };
    let second = if let Some(r) = resources.get(1) {
        bridge.resolve(*r, false).ok_or(2u32)?
    } else {
        bridge.random.clone()
    };
    if resources.iter().any(|r| {
        r.kind == target.kind && unsafe { ref_name(r.name) } == unsafe { ref_name(target.name) }
    }) {
        return Err(3);
    }
    let source = std::str::from_utf8(wgsl).map_err(|_| 4u32)?;
    let module = bridge
        .device
        .create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Effect Custom Pixel Shader"),
            source: wgpu::ShaderSource::Wgsl(source.into()),
        });
    let layout = bridge
        .device
        .create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("Effect Custom Pixel Layout"),
            bind_group_layouts: &[Some(&pixel_bgl(&bridge.device))],
            immediate_size: 0,
        });
    let pipeline = bridge
        .device
        .create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("Effect Custom Pixel Pipeline"),
            layout: Some(&layout),
            vertex: wgpu::VertexState {
                module: &module,
                entry_point: Some("vs_main"),
                buffers: &[],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &module,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: target_tex.format(),
                    blend: None,
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: None,
            multisample: Default::default(),
            multiview_mask: None,
            cache: None,
        });
    let sampler = bridge
        .device
        .create_sampler(&wgpu::SamplerDescriptor::default());
    let mut padded = constants.to_vec();
    padded.resize(padded.len().max(16).div_ceil(16) * 16, 0);
    let uniform = bridge
        .device
        .create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("Effect Custom Constants"),
            contents: &padded,
            usage: wgpu::BufferUsages::UNIFORM,
        });
    let first_view = first.create_view(&Default::default());
    let second_view = second.create_view(&Default::default());
    let target_view = target_tex.create_view(&Default::default());
    let bgl = pixel_bgl(&bridge.device);
    let bind = bridge.device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("Effect Custom Pixel Bind Group"),
        layout: &bgl,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(&first_view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: uniform.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: wgpu::BindingResource::TextureView(&second_view),
            },
            wgpu::BindGroupEntry {
                binding: 4,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
        ],
    });
    let mut encoder = bridge.device.create_command_encoder(&Default::default());
    if target.kind == ResourceKind::Framebuffer {
        copy_input_to_framebuffer(bridge, &mut encoder)?;
    } else if target_tex.width() == first.width()
        && target_tex.height() == first.height()
        && target_tex.format() == first.format()
    {
        encoder.copy_texture_to_texture(
            first.as_image_copy(),
            target_tex.as_image_copy(),
            first.size(),
        );
    }
    {
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("Effect Custom Pixel Pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: &target_view,
                resolve_target: None,
                ops: wgpu::Operations {
                    load: wgpu::LoadOp::Load,
                    store: wgpu::StoreOp::Store,
                },
                depth_slice: None,
            })],
            depth_stencil_attachment: None,
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        });
        let sx = bridge.roi.x.floor().max(0.0).min(target_tex.width() as f32) as u32;
        let sy = bridge
            .roi
            .y
            .floor()
            .max(0.0)
            .min(target_tex.height() as f32) as u32;
        let ex = (bridge.roi.x + bridge.roi.w)
            .ceil()
            .max(0.0)
            .min(target_tex.width() as f32) as u32;
        let ey = (bridge.roi.y + bridge.roi.h)
            .ceil()
            .max(0.0)
            .min(target_tex.height() as f32) as u32;
        if ex <= sx || ey <= sy {
            return Ok(());
        }
        pass.set_scissor_rect(sx, sy, ex - sx, ey - sy);
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind, &[]);
        pass.draw(0..3, 0..1);
    }
    crate::infra::gpu_shared::locked_submit(&bridge.queue, [encoder.finish()]);
    Ok(())
}

fn copy_input_to_framebuffer(
    bridge: &Bridge,
    encoder: &mut wgpu::CommandEncoder,
) -> Result<(), u32> {
    if bridge.object.format() == bridge.framebuffer.format() {
        encoder.copy_texture_to_texture(
            bridge.object.as_image_copy(),
            bridge.framebuffer.as_image_copy(),
            bridge.object.size(),
        );
        return Ok(());
    }
    const WGSL: &str = r#"
struct VOut { @builtin(position) position: vec4<f32>, @location(0) uv: vec2<f32> };
@vertex fn vs_main(@builtin(vertex_index) i:u32)->VOut { var p=array<vec2<f32>,3>(vec2<f32>(-1.0,1.0),vec2<f32>(3.0,1.0),vec2<f32>(-1.0,-3.0)); var o:VOut; o.position=vec4<f32>(p[i],0.0,1.0); o.uv=vec2<f32>((p[i].x+1.0)*0.5,(1.0-p[i].y)*0.5); return o; }
@group(0) @binding(0) var src:texture_2d<f32>; @group(0) @binding(1) var smp:sampler;
@fragment fn fs_main(in:VOut)->@location(0) vec4<f32> { return textureSample(src,smp,in.uv); }
"#;
    let module = bridge
        .device
        .create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Effect Framebuffer Preserve"),
            source: wgpu::ShaderSource::Wgsl(WGSL.into()),
        });
    let bgl = bridge
        .device
        .create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("Effect Framebuffer Preserve BGL"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
    let layout = bridge
        .device
        .create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("Effect Framebuffer Preserve Layout"),
            bind_group_layouts: &[Some(&bgl)],
            immediate_size: 0,
        });
    let pipeline = bridge
        .device
        .create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("Effect Framebuffer Preserve"),
            layout: Some(&layout),
            vertex: wgpu::VertexState {
                module: &module,
                entry_point: Some("vs_main"),
                buffers: &[],
                compilation_options: Default::default(),
            },
            fragment: Some(wgpu::FragmentState {
                module: &module,
                entry_point: Some("fs_main"),
                targets: &[Some(wgpu::ColorTargetState {
                    format: bridge.framebuffer.format(),
                    blend: None,
                    write_mask: wgpu::ColorWrites::ALL,
                })],
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                cull_mode: None,
                ..Default::default()
            },
            depth_stencil: None,
            multisample: Default::default(),
            multiview_mask: None,
            cache: None,
        });
    let src_view = bridge.object.create_view(&Default::default());
    let dst_view = bridge.framebuffer.create_view(&Default::default());
    let sampler = bridge
        .device
        .create_sampler(&wgpu::SamplerDescriptor::default());
    let bind = bridge.device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("Effect Framebuffer Preserve BG"),
        layout: &bgl,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(&src_view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
        ],
    });
    let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
        label: Some("Effect Framebuffer Preserve Pass"),
        color_attachments: &[Some(wgpu::RenderPassColorAttachment {
            view: &dst_view,
            resolve_target: None,
            ops: wgpu::Operations {
                load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                store: wgpu::StoreOp::Store,
            },
            depth_slice: None,
        })],
        depth_stencil_attachment: None,
        timestamp_writes: None,
        occlusion_query_set: None,
        multiview_mask: None,
    });
    pass.set_pipeline(&pipeline);
    pass.set_bind_group(0, &bind, &[]);
    pass.draw(0..3, 0..1);
    drop(pass);
    Ok(())
}

fn pixel_bgl(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("Effect Custom Pixel BGL"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Texture {
                    sample_type: wgpu::TextureSampleType::Float { filterable: true },
                    view_dimension: wgpu::TextureViewDimension::D2,
                    multisampled: false,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 3,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Texture {
                    sample_type: wgpu::TextureSampleType::Float { filterable: true },
                    view_dimension: wgpu::TextureViewDimension::D2,
                    multisampled: false,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 4,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                count: None,
            },
        ],
    })
}

unsafe extern "C" fn exec_computeshader(
    data: *const u8,
    len: usize,
    targets: *const ResourceRef,
    target_count: u32,
    resources: *const ResourceRef,
    resource_count: u32,
    constants: *const u8,
    constant_len: usize,
    dispatch: ComputeDispatch,
) -> u32 {
    if data.is_null()
        || targets.is_null()
        || target_count == 0
        || (resource_count > 0 && resources.is_null())
        || (constant_len > 0 && constants.is_null())
    {
        return 2;
    }
    let wgsl = unsafe { std::slice::from_raw_parts(data, len) };
    let ts = unsafe { std::slice::from_raw_parts(targets, target_count as usize) };
    let rs = if resource_count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(resources, resource_count as usize) }
    };
    let cs = if constant_len == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(constants, constant_len) }
    };
    with_active(|bridge| dispatch_compute(bridge, wgsl, ts, rs, cs, dispatch)).map_or(4, |_| 0)
}

fn dispatch_compute(
    bridge: &mut Bridge,
    wgsl: &[u8],
    targets: &[ResourceRef],
    resources: &[ResourceRef],
    constants: &[u8],
    dispatch: ComputeDispatch,
) -> Result<(), u32> {
    if dispatch.group_count_x == 0 || dispatch.group_count_y == 0 || dispatch.group_count_z == 0 {
        return Err(3);
    }
    let target_textures: Vec<_> = targets
        .iter()
        .map(|r| bridge.resolve(*r, true).ok_or(2u32))
        .collect::<Result<_, _>>()?;
    if targets.iter().any(|t| {
        matches!(
            t.kind,
            ResourceKind::Object
                | ResourceKind::Framebuffer
                | ResourceKind::Image
                | ResourceKind::Random
        )
    }) {
        return Err(3);
    }
    if target_textures
        .iter()
        .any(|t| t.format() != wgpu::TextureFormat::Rgba8Unorm)
    {
        return Err(3);
    }
    if targets.iter().any(|target| {
        resources.iter().any(|resource| {
            target.kind == resource.kind
                && unsafe { ref_name(target.name) } == unsafe { ref_name(resource.name) }
        })
    }) {
        return Err(3);
    }
    let resource_textures: Vec<_> = resources
        .iter()
        .map(|r| bridge.resolve(*r, false).ok_or(2u32))
        .collect::<Result<_, _>>()?;
    let text = std::str::from_utf8(wgsl).map_err(|_| 4u32)?;
    let mut entries = Vec::new();
    for i in 0..targets.len() {
        entries.push(wgpu::BindGroupLayoutEntry {
            binding: i as u32,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::StorageTexture {
                access: wgpu::StorageTextureAccess::WriteOnly,
                format: wgpu::TextureFormat::Rgba8Unorm,
                view_dimension: wgpu::TextureViewDimension::D2,
            },
            count: None,
        });
    }
    for i in 0..resources.len() {
        entries.push(wgpu::BindGroupLayoutEntry {
            binding: (targets.len() + i) as u32,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Texture {
                sample_type: wgpu::TextureSampleType::Float { filterable: false },
                view_dimension: wgpu::TextureViewDimension::D2,
                multisampled: false,
            },
            count: None,
        });
    }
    let uniform_binding = (targets.len() + resources.len()) as u32;
    entries.push(wgpu::BindGroupLayoutEntry {
        binding: uniform_binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Uniform,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    });
    let bgl = bridge
        .device
        .create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("Effect Compute BGL"),
            entries: &entries,
        });
    let layout = bridge
        .device
        .create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("Effect Compute Layout"),
            bind_group_layouts: &[Some(&bgl)],
            immediate_size: 0,
        });
    let module = bridge
        .device
        .create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("Effect Compute WGSL"),
            source: wgpu::ShaderSource::Wgsl(text.into()),
        });
    let pipeline = bridge
        .device
        .create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("Effect Compute Pipeline"),
            layout: Some(&layout),
            module: &module,
            entry_point: Some("cs_main"),
            compilation_options: Default::default(),
            cache: None,
        });
    let mut data = constants.to_vec();
    data.resize(data.len().max(16).div_ceil(16) * 16, 0);
    let uniform = bridge
        .device
        .create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("Effect Compute Uniform"),
            contents: &data,
            usage: wgpu::BufferUsages::UNIFORM,
        });
    let target_views: Vec<_> = target_textures
        .iter()
        .map(|t| t.create_view(&Default::default()))
        .collect();
    let resource_views: Vec<_> = resource_textures
        .iter()
        .map(|t| t.create_view(&Default::default()))
        .collect();
    let mut bindings: Vec<_> = target_views
        .iter()
        .enumerate()
        .map(|(i, v)| wgpu::BindGroupEntry {
            binding: i as u32,
            resource: wgpu::BindingResource::TextureView(v),
        })
        .collect();
    bindings.extend(
        resource_views
            .iter()
            .enumerate()
            .map(|(i, v)| wgpu::BindGroupEntry {
                binding: (targets.len() + i) as u32,
                resource: wgpu::BindingResource::TextureView(v),
            }),
    );
    bindings.push(wgpu::BindGroupEntry {
        binding: uniform_binding,
        resource: uniform.as_entire_binding(),
    });
    let bind = bridge.device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("Effect Compute Bind Group"),
        layout: &bgl,
        entries: &bindings,
    });
    let mut encoder = bridge.device.create_command_encoder(&Default::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("Effect Compute Pass"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind, &[]);
        pass.dispatch_workgroups(
            dispatch.group_count_x,
            dispatch.group_count_y,
            dispatch.group_count_z,
        );
    }
    crate::infra::gpu_shared::locked_submit(&bridge.queue, [encoder.finish()]);
    Ok(())
}

unsafe extern "C" fn get_resource_size(
    resource: ResourceRef,
    width: *mut u32,
    height: *mut u32,
) -> u32 {
    if width.is_null() || height.is_null() {
        return 2;
    }
    with_active(|bridge| {
        let texture = bridge.resolve(resource, false).ok_or(2u32)?;
        unsafe {
            *width = texture.width();
            *height = texture.height();
        }
        Ok(())
    })
    .map_or(1, |_| 0)
}
unsafe extern "C" fn get_resource_data(
    resource: ResourceRef,
    buffer: *mut u8,
    width: u32,
    height: u32,
    pitch: u32,
) -> u32 {
    if buffer.is_null() || width == 0 || height == 0 {
        return 2;
    }
    with_active(|bridge| read_texture(bridge, resource, buffer, width, height, pitch))
        .map_or(4, |_| 0)
}
fn read_texture(
    bridge: &mut Bridge,
    resource: ResourceRef,
    buffer: *mut u8,
    width: u32,
    height: u32,
    pitch: u32,
) -> Result<(), u32> {
    let texture = bridge.resolve(resource, false).ok_or(2u32)?;
    let bpp = 4u32;
    let row = width.checked_mul(bpp).ok_or(3u32)?;
    if pitch < row || texture.width() < width || texture.height() < height {
        return Err(3);
    }
    let padded =
        row.div_ceil(wgpu::COPY_BYTES_PER_ROW_ALIGNMENT) * wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
    let buf = bridge.device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("Effect Resource Readback"),
        size: u64::from(padded) * u64::from(height),
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut enc = bridge.device.create_command_encoder(&Default::default());
    enc.copy_texture_to_buffer(
        texture.as_image_copy(),
        wgpu::TexelCopyBufferInfo {
            buffer: &buf,
            layout: wgpu::TexelCopyBufferLayout {
                offset: 0,
                bytes_per_row: Some(padded),
                rows_per_image: Some(height),
            },
        },
        wgpu::Extent3d {
            width,
            height,
            depth_or_array_layers: 1,
        },
    );
    crate::infra::gpu_shared::locked_submit(&bridge.queue, [enc.finish()]);
    let slice = buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    bridge
        .device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|_| 4u32)?;
    rx.recv().map_err(|_| 4u32)?.map_err(|_| 4u32)?;
    let mapped = slice.get_mapped_range().map_err(|_| 4u32)?;
    for y in 0..height as usize {
        let src_row = mapped.as_ptr().wrapping_add(y * padded as usize);
        let dst_row = unsafe { buffer.add(y * pitch as usize) };
        match texture.format() {
            wgpu::TextureFormat::Rgba8Unorm | wgpu::TextureFormat::Rgba8UnormSrgb => unsafe {
                std::ptr::copy_nonoverlapping(src_row, dst_row, row as usize);
            },
            wgpu::TextureFormat::Rgba16Float => {
                for x in 0..width as usize {
                    for c in 0..4 {
                        let off = (x * 4 + c) * 2;
                        let v = half::f16::from_le_bytes([unsafe { *src_row.add(off) }, unsafe {
                            *src_row.add(off + 1)
                        }])
                        .to_f32()
                        .clamp(0.0, 1.0);
                        unsafe {
                            *dst_row.add(x * 4 + c) = (v * 255.0).round() as u8;
                        }
                    }
                }
            }
            _ => return Err(3),
        }
    }
    drop(mapped);
    buf.unmap();
    Ok(())
}
unsafe extern "C" fn set_resource_data(
    resource: ResourceRef,
    buffer: *const u8,
    width: u32,
    height: u32,
    pitch: u32,
) -> u32 {
    if buffer.is_null() || width == 0 || height == 0 {
        return 2;
    }
    with_active(|bridge| {
        let texture = bridge.resolve(resource, true).ok_or(2u32)?;
        let row = width.checked_mul(4).ok_or(3u32)?;
        if pitch < row || texture.width() < width || texture.height() < height {
            return Err(3);
        }
        if !matches!(
            texture.format(),
            wgpu::TextureFormat::Rgba8Unorm
                | wgpu::TextureFormat::Rgba8UnormSrgb
                | wgpu::TextureFormat::Rgba16Float
        ) {
            return Err(3);
        }
        let length = (pitch as usize).checked_mul(height as usize).ok_or(3u32)?;
        let bytes = unsafe { std::slice::from_raw_parts(buffer, length) };
        let upload = if texture.format() == wgpu::TextureFormat::Rgba16Float {
            let mut converted = Vec::with_capacity(width as usize * height as usize * 8);
            for y in 0..height as usize {
                for px in
                    bytes[y * pitch as usize..y * pitch as usize + row as usize].chunks_exact(4)
                {
                    for channel in px {
                        converted.extend_from_slice(
                            &half::f16::from_f32(*channel as f32 / 255.0).to_le_bytes(),
                        );
                    }
                }
            }
            converted
        } else {
            bytes.to_vec()
        };
        let upload_pitch = if texture.format() == wgpu::TextureFormat::Rgba16Float {
            width * 8
        } else {
            pitch
        };
        bridge.queue.write_texture(
            texture.as_image_copy(),
            &upload,
            wgpu::TexelCopyBufferLayout {
                offset: 0,
                bytes_per_row: Some(upload_pitch),
                rows_per_image: Some(height),
            },
            wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
        );
        Ok(())
    })
    .map_or(4, |_| 0)
}
unsafe extern "C" fn release_resource(resource: ResourceRef) -> u32 {
    let name = unsafe { ref_name(resource.name) }.unwrap_or_default();
    with_active(|bridge| match resource.kind {
        ResourceKind::Named => {
            bridge.named.remove(&name);
            Ok(())
        }
        ResourceKind::TempBuffer => {
            bridge.temps.remove(&name);
            Ok(())
        }
        ResourceKind::Cache => {
            CACHES
                .get_or_init(Default::default)
                .lock()
                .map_err(|_| 1u32)?
                .remove(&(
                    bridge.device.as_ref() as *const _ as usize,
                    bridge.namespace,
                    name,
                ));
            Ok(())
        }
        _ => Err(3),
    })
    .map_or(1, |_| 0)
}

pub(super) fn run_custom<R>(bridge: Bridge, f: impl FnOnce(&EffectRenderContext) -> R) -> R {
    with_context(bridge, f)
}

pub(super) fn run_compute(
    bridge: Bridge,
    shader: &[u8],
    constants: &[u8],
    dispatch: ComputeDispatch,
) -> Result<(), u32> {
    with_context(bridge, |ctx| unsafe {
        let output = ResourceRef::named(StrRef::from_str("compute-output"));
        let input = ResourceRef::object();
        let status = (ctx.exec_computeshader)(shader.as_ptr(), shader.len(), &output, 1,
            &input, 1, constants.as_ptr(), constants.len(), dispatch);
        if status != 0 { return Err(status); }
        const BLIT: &[u8] = br"
struct VOut { @builtin(position) position: vec4<f32>, @location(0) uv: vec2<f32> };
@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VOut { var p = array<vec2<f32>,3>(vec2(-1.0,1.0),vec2(3.0,1.0),vec2(-1.0,-3.0)); var o: VOut; o.position=vec4(p[i],0.0,1.0); o.uv=vec2((p[i].x+1.0)*0.5,(1.0-p[i].y)*0.5); return o; }
@group(0) @binding(0) var image: texture_2d<f32>; @group(0) @binding(1) var image_sampler: sampler; @group(0) @binding(2) var<uniform> unused: vec4<f32>; @group(0) @binding(3) var map: texture_2d<f32>; @group(0) @binding(4) var map_sampler: sampler;
@fragment fn fs_main(in: VOut) -> @location(0) vec4<f32> { return textureSample(image,image_sampler,in.uv); }
";
        let target = ResourceRef::framebuffer();
        let source = ResourceRef::named(StrRef::from_str("compute-output"));
        let zero = [0u8;16];
        Ok((ctx.exec_pixelshader)(BLIT.as_ptr(), BLIT.len(), target, &source, 1, zero.as_ptr(), zero.len()))
    }).and_then(|code| if code == 0 { Ok(()) } else { Err(code) })
}

use super::shaders::EffectObjectDrawKind;
use super::*;

impl RenderEngine {
    pub fn render(
        &mut self,
        world: &crate::ecs::EcsWorld,
        active_objects: &[ActiveObject],
        captured: &CapturedObjects,
        project: &ProjectResource,
    ) {
        let timeline_frame = world.current_frame();
        self.scene_texture_cache.clear();
        self.drain_hot_reload_events();
        if let Some(sys) = &self.lua_system
            && let Err(err) = sys.run_pre_render_hooks()
        {
            eprintln!(
                "{}",
                t!(
                    "[NeoUtl] system.on_pre_render フック実行失敗: %{arg0}",
                    arg0 = format!("{err}")
                )
            );
        }
        self.render_at(
            world,
            active_objects,
            captured,
            project,
            0,
            None,
            timeline_frame,
        );
        self.run_lua_reduce_hooks();
    }

    pub fn read_frame_rgba8(&self) -> Vec<u8> {
        let width = self.render_width;
        let height = self.render_height;
        let unpadded_bytes_per_row = width * 8;
        let align = wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
        let padded_bytes_per_row = unpadded_bytes_per_row.div_ceil(align) * align;
        let buffer_size = (padded_bytes_per_row * height) as wgpu::BufferAddress;

        let output_buffer = self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("Export Readback Buffer"),
            size: buffer_size,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });

        let mut encoder = self
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
        encoder.copy_texture_to_buffer(
            wgpu::TexelCopyTextureInfo {
                texture: &self.texture,
                mip_level: 0,
                origin: wgpu::Origin3d::ZERO,
                aspect: wgpu::TextureAspect::All,
            },
            wgpu::TexelCopyBufferInfo {
                buffer: &output_buffer,
                layout: wgpu::TexelCopyBufferLayout {
                    offset: 0,
                    bytes_per_row: Some(padded_bytes_per_row),
                    rows_per_image: Some(height),
                },
            },
            wgpu::Extent3d {
                width,
                height,
                depth_or_array_layers: 1,
            },
        );
        crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);

        let slice = output_buffer.slice(..);
        let (tx, rx) = std::sync::mpsc::channel();
        slice.map_async(wgpu::MapMode::Read, move |result| {
            tx.send(result).expect(&t!("map_async結果送信失敗"));
        });
        self.device
            .poll(wgpu::PollType::wait_indefinitely())
            .expect(&t!("device poll失敗"));
        rx.recv()
            .expect(&t!("map_async結果受信失敗"))
            .expect(&t!("バッファmap失敗"));

        let padded = slice.get_mapped_range().expect(&t!("get_mapped_range失敗"));
        let mut rgba8 = Vec::with_capacity((width * height * 4) as usize);
        for row in 0..height as usize {
            let start = row * padded_bytes_per_row as usize;
            for pixel in padded[start..start + unpadded_bytes_per_row as usize].chunks_exact(8) {
                for channel in pixel.chunks_exact(2) {
                    let v = half::f16::from_le_bytes([channel[0], channel[1]]).to_f32();
                    rgba8.push((v.clamp(0.0, 1.0) * 255.0).round() as u8);
                }
            }
        }
        drop(padded);
        output_buffer.unmap();
        rgba8
    }

    pub(super) fn render_at(
        &mut self,
        world: &crate::ecs::EcsWorld,
        active_objects: &[ActiveObject],
        captured: &CapturedObjects,
        project: &ProjectResource,
        depth: u32,
        clear_override: Option<wgpu::Color>,
        timeline_frame: i32,
    ) {
        if is_device_lost() {
            return;
        }
        let mut media_frames: Vec<Option<wgpu::Texture>> = Vec::with_capacity(active_objects.len());
        let mut media_color_metas: Vec<neoutl_media_api::ColorMeta> =
            Vec::with_capacity(active_objects.len());
        {
            let cache = neoutl_media_runtime::cache::global();
            for obj in active_objects {
                let stable_id = stable_id_of(obj.kind_id);
                let is_visual = matches!(stable_id, Some(VIDEO_STABLE_ID | IMAGE_STABLE_ID));
                let tex = if is_visual {
                    if let Some(src) = &obj.media_source {
                        let color_meta =
                            cache.color_meta_at(&src.path, obj.clip_instance, obj.source_frame);
                        media_color_metas.push(color_meta);
                        match cache.frame_at(
                            &src.path,
                            obj.clip_instance,
                            obj.source_frame,
                            &self.device,
                            &self.queue,
                        ) {
                            Ok(texture) => Some(texture),
                            Err(err) => {
                                eprintln!(
                                    "{}",
                                    t!(
                                        "[NeoUtl] フレーム取得失敗 kind_id=%{arg0} clip_instance=%{arg4} path=%{arg1} frame=%{arg2}: %{arg3}",
                                        arg0 = format!("{}", obj.kind_id),
                                        arg1 = format!("{}", src.path.display()),
                                        arg2 = format!("{}", obj.source_frame),
                                        arg3 = format!("{err}"),
                                        arg4 = format!("{}", obj.clip_instance)
                                    )
                                );
                                None
                            }
                        }
                    } else {
                        media_color_metas.push(neoutl_media_api::ColorMeta::default());
                        None
                    }
                } else {
                    media_color_metas.push(neoutl_media_api::ColorMeta::default());
                    match obj.compose_source {
                        Some(crate::ecs::systems::ComposeSource::NestedScene {
                            target_scene,
                            local_frame,
                        }) => world.get_scene(target_scene).and_then(|scene| {
                            let (nested, nested_captured) =
                                crate::ecs::systems::get_active_objects_system_at(
                                    world,
                                    target_scene,
                                    local_frame,
                                );
                            self.render_composed_texture(
                                world,
                                &nested,
                                &nested_captured,
                                scene.width,
                                scene.height,
                                ComposeCacheKey::Scene(target_scene),
                                depth + 1,
                                None,
                                timeline_frame,
                            )
                        }),
                        Some(crate::ecs::systems::ComposeSource::FrameBuffer {
                            controller,
                            kind: crate::ecs::systems::FrameBufferKind::Group,
                        }) => {
                            let empty = Vec::new();
                            let objects = captured.get(&controller).unwrap_or(&empty);
                            self.render_composed_texture(
                                world,
                                objects,
                                captured,
                                self.render_width,
                                self.render_height,
                                ComposeCacheKey::FrameBuffer(controller),
                                depth + 1,
                                None,
                                timeline_frame,
                            )
                        }
                        None => None,
                    }
                };
                media_frames.push(tex);
            }
        }
        let mut mold_frames: Vec<Option<wgpu::Texture>> = Vec::with_capacity(active_objects.len());
        for obj in active_objects {
            let tex = match obj.clip_target {
                Some(info) => {
                    let empty = Vec::new();
                    let objects = captured.get(&info.controller).unwrap_or(&empty);
                    self.render_composed_texture(
                        world,
                        objects,
                        captured,
                        self.render_width,
                        self.render_height,
                        ComposeCacheKey::FrameBuffer(info.controller),
                        depth + 1,
                        None,
                        timeline_frame,
                    )
                }
                None => None,
            };
            mold_frames.push(tex);
        }
        let mut media_offsets: Vec<Option<u32>> = Vec::with_capacity(active_objects.len());
        let mut media_next_index = 0u64;
        for ((obj, tex), color_meta) in active_objects
            .iter()
            .zip(media_frames.iter())
            .zip(media_color_metas.iter())
        {
            if tex.is_some() && media_next_index < MAX_OBJECTS {
                let offset = self.write_media_uniform(media_next_index, obj, *color_meta);
                media_offsets.push(Some(offset));
                media_next_index += 1;
            } else {
                media_offsets.push(None);
            }
        }

        let mut offsets: Vec<Option<u32>> = Vec::with_capacity(active_objects.len());
        let mut next_index = 0u64;
        for obj in active_objects {
            if self.pipelines.contains_key(&obj.kind_id) && next_index < MAX_OBJECTS {
                let offset = self.write_standard_uniform(next_index, obj);
                offsets.push(Some(offset));
                next_index += 1;
            } else {
                offsets.push(None);
            }
        }

        let mut effect_pool_index: Vec<Option<usize>> = Vec::with_capacity(active_objects.len());
        {
            let mut next_pool = 0usize;
            for obj in active_objects {
                if (!obj.effects.is_empty() || obj.clip_target.is_some())
                    && next_pool < config::MAX_EFFECT_OBJECTS
                {
                    effect_pool_index.push(Some(next_pool));
                    next_pool += 1;
                } else {
                    effect_pool_index.push(None);
                }
            }
        }

        let mut text_draws: Vec<(u64, u32, usize)> = Vec::new();
        {
            let mut seen: HashSet<u64> = HashSet::with_capacity(active_objects.len());
            for (obj_index, obj) in active_objects.iter().enumerate() {
                let Some(plugin) = by_kind_id(obj.kind_id) else {
                    continue;
                };
                let meta = unsafe { &*((plugin.vtable.meta)()) };
                if unsafe { meta.stable_id.try_as_str() } != Some(neoutl_object_api::TEXT_STABLE_ID)
                {
                    continue;
                }
                let Some(tc) = obj.text_content.as_ref() else {
                    continue;
                };
                if media_next_index >= MAX_OBJECTS {
                    continue;
                }
                let Some(font) =
                    self.resolve_font_stack(&tc.font_family_stack, &tc.text, tc.bold, tc.italic)
                else {
                    continue;
                };

                let text_layout = neoutl_media_runtime::text::layout(
                    &font,
                    &tc.text,
                    tc.font_size,
                    tc.line_height,
                );
                let (tex_w, tex_h) = (text_layout.width, text_layout.height);
                seen.insert(obj.clip_instance);

                let needs_rebuild = match self.text_targets.get(&obj.clip_instance) {
                    Some(t) => t.width != tex_w || t.height != tex_h,
                    None => true,
                };
                if needs_rebuild {
                    self.text_targets.insert(
                        obj.clip_instance,
                        build_text_target(&self.device, &font, tex_w, tex_h),
                    );
                }
                let target = self
                    .text_targets
                    .get_mut(&obj.clip_instance)
                    .expect(&t!("直前にinsert済み"));

                let h_align = match tc.align {
                    crate::ecs::components::TextAlign::Left => {
                        neoutl_media_runtime::text::HAlign::Left
                    }
                    crate::ecs::components::TextAlign::Center => {
                        neoutl_media_runtime::text::HAlign::Center
                    }
                    crate::ecs::components::TextAlign::Right => {
                        neoutl_media_runtime::text::HAlign::Right
                    }
                };
                let sections = neoutl_media_runtime::text::build_sections(
                    tc.color,
                    tc.font_size,
                    h_align,
                    &text_layout,
                    target.width,
                    target.height,
                );
                let section_refs: Vec<&_> = sections.iter().collect();
                {
                    let view = target
                        .texture
                        .create_view(&wgpu::TextureViewDescriptor::default());
                    let _ =
                        target
                            .brush
                            .queue(self.device.as_ref(), self.queue.as_ref(), section_refs);
                    let mut encoder =
                        self.device
                            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                                label: Some("Text Glyph Encoder"),
                            });
                    {
                        let mut glyph_pass =
                            encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                                label: Some("Text Glyph Pass"),
                                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                                    view: &view,
                                    resolve_target: None,
                                    ops: wgpu::Operations {
                                        load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                                        store: wgpu::StoreOp::Store,
                                    },
                                    depth_slice: None,
                                })],
                                depth_stencil_attachment: None,
                                timestamp_writes: None,
                                occlusion_query_set: None,
                                multiview_mask: None,
                            });
                        target.brush.draw(&mut glyph_pass);
                    }
                    crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
                }

                if tc.outline_width > 0.0 {
                    if let Some(t) = self.text_targets.get(&obj.clip_instance) {
                        self.apply_text_outline(t, tc);
                    }
                }

                let ratio_w = tex_w as f32 / UNIT_SIZE_PX;
                let ratio_h = tex_h as f32 / UNIT_SIZE_PX;
                let mut mvp = obj.mvp;
                for i in 0..4 {
                    mvp[i] *= ratio_w;
                    mvp[4 + i] *= ratio_h;
                }

                let offset = self.write_media_uniform_raw(media_next_index, &mvp, obj.opacity);
                media_next_index += 1;
                text_draws.push((obj.clip_instance, offset, obj_index));
            }
            self.text_targets.retain(|k, _| seen.contains(k));
        }

        let text_draw_by_index: HashMap<usize, (u64, u32)> = text_draws
            .iter()
            .map(|(clip_instance, offset, obj_index)| (*obj_index, (*clip_instance, *offset)))
            .collect();

        let clear_color = clear_override.unwrap_or(if depth == 0 {
            wgpu::Color {
                r: 0.05,
                g: 0.05,
                b: 0.07,
                a: 1.0,
            }
        } else {
            wgpu::Color::TRANSPARENT
        });

        let object_count = active_objects.len();
        let mut drawn_any = false;
        let mut idx = 0usize;
        while idx < object_count {
            if let Some(pool_idx) = effect_pool_index[idx] {
                let obj = &active_objects[idx];
                let draw_kind = if let Some(offset) = offsets[idx] {
                    EffectObjectDrawKind::Standard { obj, offset }
                } else if let (Some(texture), Some(offset)) =
                    (&media_frames[idx], media_offsets[idx])
                {
                    EffectObjectDrawKind::Media {
                        texture,
                        offset,
                        blend_mode: obj.blend_mode,
                    }
                } else if let Some((clip_instance, offset)) = text_draw_by_index.get(&idx) {
                    EffectObjectDrawKind::Text {
                        clip_instance: *clip_instance,
                        offset: *offset,
                        blend_mode: obj.blend_mode,
                    }
                } else {
                    idx += 1;
                    continue;
                };

                let pool_tex = self.ensure_effect_object_target(pool_idx).clone();
                let effect_roi = neoutl_shared_abi::Roi {
                    x: 0.0,
                    y: 0.0,
                    w: self.render_width as f32,
                    h: self.render_height as f32,
                };
                self.render_effect_object_offscreen(&pool_tex, draw_kind, obj);
                if !obj.effects.is_empty() {
                    self.apply_effect_chain(
                        world,
                        active_objects,
                        captured,
                        depth,
                        &pool_tex,
                        &pool_tex,
                        &obj.effects,
                        timeline_frame,
                        project.fps,
                        effect_roi,
                    );
                }
                match obj.clip_target {
                    Some(info) => {
                        let mold_tex = mold_frames[idx].as_ref().unwrap_or(&pool_tex);
                        self.composite_clipped_object(
                            &pool_tex,
                            mold_tex,
                            info.mode,
                            info.chroma_hue,
                            info.chroma_tolerance,
                            info.blend_edge,
                            if drawn_any { None } else { Some(clear_color) },
                        );
                    }
                    None => {
                        self.composite_effect_object(
                            &pool_tex,
                            if drawn_any { None } else { Some(clear_color) },
                            obj.blend_mode,
                        );
                    }
                }
                drawn_any = true;
                idx += 1;
                continue;
            }

            let start = idx;
            while idx < object_count && effect_pool_index[idx].is_none() {
                idx += 1;
            }

            let color_load = if drawn_any {
                wgpu::LoadOp::Load
            } else {
                wgpu::LoadOp::Clear(clear_color)
            };
            let depth_load = if drawn_any {
                wgpu::LoadOp::Load
            } else {
                wgpu::LoadOp::Clear(1.0)
            };

            let mut encoder = self
                .device
                .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                    label: Some("Render Segment Encoder"),
                });
            {
                let view = self
                    .texture
                    .create_view(&wgpu::TextureViewDescriptor::default());
                let depth_view = self
                    .depth_texture
                    .create_view(&wgpu::TextureViewDescriptor::default());
                let mut rpass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("Render Pass Segment"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &view,
                        resolve_target: None,
                        ops: wgpu::Operations {
                            load: color_load,
                            store: wgpu::StoreOp::Store,
                        },
                        depth_slice: None,
                    })],
                    depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                        view: &depth_view,
                        depth_ops: Some(wgpu::Operations {
                            load: depth_load,
                            store: wgpu::StoreOp::Store,
                        }),
                        stencil_ops: None,
                    }),
                    timestamp_writes: None,
                    occlusion_query_set: None,
                    multiview_mask: None,
                });

                for i in start..idx {
                    if let Some(offset) = offsets[i] {
                        let object = &active_objects[i];
                        self.draw_standard_pass(&mut rpass, object, offset);
                        self.draw_object_hook(&mut rpass, object, &self.bind_group, true, None);
                    }
                    if let (Some(texture), Some(offset)) = (&media_frames[i], media_offsets[i]) {
                        self.draw_media_pass_with_hook(
                            &mut rpass,
                            texture,
                            offset,
                            active_objects[i].blend_mode,
                            &active_objects[i],
                            true,
                        );
                    }
                    if let Some((clip_instance, offset)) = text_draw_by_index.get(&i) {
                        self.draw_text_pass_with_hook(
                            &mut rpass,
                            *clip_instance,
                            *offset,
                            active_objects[i].blend_mode,
                            &active_objects[i],
                            true,
                        );
                    }
                }
            }
            crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
            drawn_any = true;
        }

        if !drawn_any {
            let mut encoder = self
                .device
                .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                    label: Some("Clear Encoder"),
                });
            {
                let view = self
                    .texture
                    .create_view(&wgpu::TextureViewDescriptor::default());
                let depth_view = self
                    .depth_texture
                    .create_view(&wgpu::TextureViewDescriptor::default());
                encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("Clear Pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &view,
                        resolve_target: None,
                        ops: wgpu::Operations {
                            load: wgpu::LoadOp::Clear(clear_color),
                            store: wgpu::StoreOp::Store,
                        },
                        depth_slice: None,
                    })],
                    depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                        view: &depth_view,
                        depth_ops: Some(wgpu::Operations {
                            load: wgpu::LoadOp::Clear(1.0),
                            store: wgpu::StoreOp::Store,
                        }),
                        stencil_ops: None,
                    }),
                    timestamp_writes: None,
                    occlusion_query_set: None,
                    multiview_mask: None,
                });
            }
            crate::infra::gpu_shared::locked_submit(&self.queue, [encoder.finish()]);
        }
    }
}

use super::*;

impl RenderEngine {
    pub(super) fn drain_hot_reload_events(&mut self) {
        let Some(rx) = &self.hot_reload_rx else {
            return;
        };
        let events: Vec<ReloadEvent> = rx.try_iter().collect();
        for event in events {
            match event {
                ReloadEvent::Object(path) => self.apply_object_reload(&path),
                ReloadEvent::Effect(path) => self.apply_effect_reload(&path),
                ReloadEvent::Script(path) => self.apply_script_reload(&path),
            }
        }
    }

    fn apply_object_reload(&mut self, path: &std::path::Path) {
        if let Err(err) = crate::objects::loader::reload_one(path) {
            eprintln!(
                "{}",
                t!(
                    "[NeoUtl] ホットリロード失敗（objects） %{arg0}: %{arg1}",
                    arg0 = format!("{}", path.display()),
                    arg1 = format!("{err}")
                )
            );
            return;
        }
        self.rebuild_all_object_pipelines();
    }

    fn apply_effect_reload(&mut self, path: &std::path::Path) {
        if let Err(err) = crate::effects::loader::reload_one(path) {
            eprintln!(
                "{}",
                t!(
                    "[NeoUtl] ホットリロード失敗（effects） %{arg0}: %{arg1}",
                    arg0 = format!("{}", path.display()),
                    arg1 = format!("{err}")
                )
            );
            return;
        }
        self.rebuild_all_effect_pipelines();
    }

    fn apply_script_reload(&mut self, _path: &std::path::Path) {
        let Some(sys) = &self.lua_system else {
            return;
        };
        if let Err(err) = sys.reload_dir(&self.scripts_dir) {
            eprintln!(
                "{}",
                t!(
                    "[NeoUtl] ホットリロード失敗（scripts） %{arg0}: %{arg1}",
                    arg0 = format!("{}", self.scripts_dir.display()),
                    arg1 = format!("{err}")
                )
            );
            return;
        }
        self.lua_compute_pipelines =
            build_lua_compute_pipelines(&self.device, &sys.drain_computes());
        crate::effects::loader::reload_lua(sys.drain_effects());
        self.rebuild_all_effect_pipelines();
        eprintln!(
            "{}",
            t!(
                "[NeoUtl] scriptsホットリロード完了: %{arg0}",
                arg0 = format!("{}", self.scripts_dir.display())
            )
        );
    }

    fn rebuild_all_object_pipelines(&mut self) {
        self.pipelines = build_pipelines_from_registry(&self.device, &self.object_pipeline_layout);
    }

    fn rebuild_all_effect_pipelines(&mut self) {
        self.effect_pipelines =
            build_effect_pipelines_from_registry(&self.device, &self.effect_pipeline_layout);
    }
}

