pub(super) fn build_effect_pipelines_from_registry(
    device: &wgpu::Device,
    layout: &wgpu::PipelineLayout,
) -> HashMap<String, (wgpu::RenderPipeline, Option<wgpu::RenderPipeline>)> {
    effects::registry()
        .iter()
        .filter_map(|source| {
            let wgsl = source.wgsl_bytes();
            if wgsl.is_empty() {
                return None;
            }
            match build_effect_pipeline(device, layout, wgsl, source.name()) {
                Ok(pipeline) => {
                    let vertex = match source.as_ref() {
                        effects::loader::EffectSource::Native(plugin) => plugin.vtable.vertex_wgsl.map(|f| unsafe { f().as_slice() }),
                        effects::loader::EffectSource::Lua(_) => None,
                    };
                    let custom_vertex = vertex.and_then(|bytes| {
                        if bytes.is_empty() { return None; }
                        let shader = try_create_shader_module(device, bytes, source.name()).ok()?;
                        Some(device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
                            label: Some(source.name()), layout: Some(layout),
                            vertex: wgpu::VertexState { module: &shader, entry_point: Some("vs_main"), buffers: &[], compilation_options: Default::default() },
                            fragment: Some(wgpu::FragmentState { module: &shader, entry_point: Some("fs_main"), targets: &[Some(wgpu::ColorTargetState { format: wgpu::TextureFormat::Rgba16Float, blend: None, write_mask: wgpu::ColorWrites::ALL })], compilation_options: Default::default() }),
                            primitive: wgpu::PrimitiveState { topology: wgpu::PrimitiveTopology::TriangleList, cull_mode: None, ..Default::default() },
                            depth_stencil: None, multisample: Default::default(), multiview_mask: None, cache: None,
                        }))
                    });
                    Some((source.id().to_owned(), (pipeline, custom_vertex)))
                },
                Err(err) => {
                    eprintln!("{}", t!("[NeoUtl] エフェクトのシェーダコンパイル失敗、除外して継続: id=%{arg0} name=%{arg1} 理由=%{arg2}", arg0 = format!("{}", source.id()), arg1 = format!("{}", source.name()), arg2 = format!("{err}")));
                    None
                }
            }
        })
        .collect()
}

pub(super) fn build_reduce_mean_pipeline(
    device: &wgpu::Device,
    wgsl: &'static str,
) -> (wgpu::ComputePipeline, wgpu::BindGroupLayout) {
    let bgl = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("Reduce Mean BGL"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Texture {
                    sample_type: wgpu::TextureSampleType::Float { filterable: false },
                    view_dimension: wgpu::TextureViewDimension::D2,
                    multisampled: false,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });
    let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("Reduce Mean Pipeline Layout"),
        bind_group_layouts: &[Some(&bgl)],
        immediate_size: 0,
    });
    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("Reduce Mean Shader"),
        source: wgpu::ShaderSource::Wgsl(Cow::Borrowed(wgsl)),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("Reduce Mean Pipeline"),
        layout: Some(&layout),
        module: &shader,
        entry_point: Some("cs_main"),
        compilation_options: Default::default(),
        cache: None,
    });
    (pipeline, bgl)
}

pub(super) fn build_lua_compute_pipelines(
    device: &wgpu::Device,
    defs: &[neoutl_lua_runtime::ComputeDef],
) -> HashMap<String, wgpu::ComputePipeline> {
    defs.iter()
        .filter_map(|def| {
            let error_scope = device.push_error_scope(wgpu::ErrorFilter::Validation);
            let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some(&def.id),
                source: wgpu::ShaderSource::Wgsl(Cow::Borrowed(def.wgsl.as_str())),
            });
            if let Some(err) = pollster::block_on(error_scope.pop()) {
                eprintln!("{}", t!("[NeoUtl] system.register_compute シェーダコンパイル失敗、除外: id=%{arg0} 理由=%{arg1}", arg0 = format!("{}", def.id), arg1 = format!("{err}")));
                return None;
            }
            let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
                label: Some(&def.id),
                layout: None,
                module: &shader,
                entry_point: Some("cs_main"),
                compilation_options: Default::default(),
                cache: None,
            });
            Some((def.id.clone(), pipeline))
        })
        .collect()
}

pub(super) fn build_composite_pipeline(
    device: &wgpu::Device,
    layout: &wgpu::PipelineLayout,
    wgsl: &'static str,
) -> [wgpu::RenderPipeline; BLEND_VARIANT_COUNT] {
    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
