struct VOut {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VOut {
    var uv = vec2<f32>(f32((vertex_index << 1u) & 2u), f32(vertex_index & 2u));
    var out: VOut;
    out.position = vec4<f32>(uv * vec2<f32>(2.0, -2.0) + vec2<f32>(-1.0, 1.0), 0.0, 1.0);
    out.uv = uv;
    return out;
}

struct ClipUniform {
    mode: u32,
    chroma_hue: f32,
    chroma_tolerance: f32,
    blend_edge: u32,
};

@group(0) @binding(0) var content_tex: texture_2d<f32>;
@group(0) @binding(1) var mold_tex: texture_2d<f32>;
@group(0) @binding(2) var clip_sampler: sampler;
@group(0) @binding(3) var content_depth: texture_depth_2d;
@group(0) @binding(4) var<uniform> u: ClipUniform;

fn rgb_to_hue(c: vec3<f32>) -> f32 {
    let mx = max(c.r, max(c.g, c.b));
    let mn = min(c.r, min(c.g, c.b));
    let delta = mx - mn;
    if (delta == 0.0) {
        return 0.0;
    }
    if (mx == c.r) {
        return 60.0 * (((c.g - c.b) / delta) % 6.0);
    }
    if (mx == c.g) {
        return 60.0 * ((c.b - c.r) / delta + 2.0);
    }
    return 60.0 * ((c.r - c.g) / delta + 4.0);
}

fn hue_distance(a: f32, b: f32) -> f32 {
    let d = ((a - b) % 360.0 + 360.0) % 360.0;
    return min(d, 360.0 - d);
}

struct FOut {
    @location(0) color: vec4<f32>,
    @builtin(frag_depth) depth: f32,
};

@fragment
fn fs_main(in: VOut) -> FOut {
    let content = textureSample(content_tex, clip_sampler, in.uv);
    let mold = textureSample(mold_tex, clip_sampler, in.uv);
    var mask: f32;
    switch (u.mode) {
        case 0u: { mask = mold.a; }
        case 1u: { mask = 1.0 - mold.a; }
        case 2u: { mask = dot(mold.rgb, vec3<f32>(0.2126, 0.7152, 0.0722)); }
        case 3u: { mask = 1.0 - dot(mold.rgb, vec3<f32>(0.2126, 0.7152, 0.0722)); }
        default: {
            let d = hue_distance(rgb_to_hue(mold.rgb), u.chroma_hue);
            mask = select(0.0, 1.0, d > u.chroma_tolerance);
        }
    }
    if (u.blend_edge == 0u) {
        mask = select(0.0, 1.0, mask > 0.5);
    }
    var out: FOut;
    out.color = vec4<f32>(content.rgb, content.a * mask);
    out.depth = textureLoad(content_depth, vec2<i32>(in.position.xy), 0);
    return out;
}

struct VOut {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VOut {
    var uv = vec2<f32>(f32((vertex_index << 1u) & 2u), f32(vertex_index & 2u));
    var out: VOut;
    out.position = vec4<f32>(uv * vec2<f32>(2.0, -2.0) + vec2<f32>(-1.0, 1.0), 0.0, 1.0);
    out.uv = uv;
    return out;
}

@group(0) @binding(0) var src_tex: texture_2d<f32>;
@group(0) @binding(1) var src_sampler: sampler;
@group(0) @binding(2) var src_depth: texture_depth_2d;

struct FOut {
    @location(0) color: vec4<f32>,
    @builtin(frag_depth) depth: f32,
};

@fragment
fn fs_main(in: VOut) -> FOut {
    var out: FOut;
    out.color = textureSample(src_tex, src_sampler, in.uv);
    out.depth = textureLoad(src_depth, vec2<i32>(in.position.xy), 0);
    return out;
}

@group(0) @binding(0) var src_tex: texture_2d<f32>;
@group(0) @binding(1) var<storage, read_write> acc: array<atomic<u32>, 5>;

const SCALE: f32 = 1000000.0;

@compute @workgroup_size(8, 8)
fn cs_main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let dims = textureDimensions(src_tex);
    if (gid.x >= dims.x || gid.y >= dims.y) {
        return;
    }
    let c = textureLoad(src_tex, vec2<i32>(gid.xy), 0);
    atomicAdd(&acc[0], u32(clamp(c.r, 0.0, 1.0) * SCALE));
    atomicAdd(&acc[1], u32(clamp(c.g, 0.0, 1.0) * SCALE));
    atomicAdd(&acc[2], u32(clamp(c.b, 0.0, 1.0) * SCALE));
    atomicAdd(&acc[3], u32(clamp(c.a, 0.0, 1.0) * SCALE));
    atomicAdd(&acc[4], 1u);
}

use crate::app::state::SharedAppState;
use crate::ecs::EcsWorld;
use crate::ui::export_dialog::ExportDialog;
use crate::ui::keybindings::KeybindingsWindow;
use crate::ui::preview::PreviewPanel;
use crate::ui::project_settings::ProjectSettingsWindow;
use crate::ui::scene_settings::SceneSettingsWindow;
use crate::ui::system_settings::SystemSettingsWindow;
use std::cell::RefCell;
use std::rc::Rc;
use std::sync::{Arc, Mutex};

pub struct DialogSet {
    pub system_settings: SystemSettingsWindow,
    pub project_settings: ProjectSettingsWindow,
    pub scene_settings: SceneSettingsWindow,
    pub keybindings: KeybindingsWindow,
    pub export_dialog: ExportDialog,
    pub confirm_close_session: Option<usize>,
}

impl DialogSet {
    pub fn new(world_holder: Arc<Mutex<EcsWorld>>) -> Self {
        Self {
            system_settings: SystemSettingsWindow::new(&world_holder),
            project_settings: ProjectSettingsWindow::new(),
            scene_settings: SceneSettingsWindow::new(),
            keybindings: KeybindingsWindow::new(),
            export_dialog: ExportDialog::new(),
            confirm_close_session: None,
        }
    }

    pub fn request_close_session(&mut self, state: &SharedAppState, index: usize) {
        let dirty = state
            .lock()
            .unwrap()
            .sessions
            .get(index)
            .map(|s| s.dirty)
            .unwrap_or(false);
        if dirty {
            self.confirm_close_session = Some(index);
        } else {
            let _ = crate::app::state::close_session(state, index);
        }
    }

    pub fn open_scene_edit(&mut self, state: &SharedAppState, scene_id: i32) {
        self.scene_settings.open_for_edit(state, scene_id);
    }

    pub fn open_scene_create(&mut self, state: &SharedAppState) {
        self.scene_settings.open_for_create(state);
    }

    pub fn sync_preview_requests(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        let mut preview = preview_panel.borrow_mut();
        if std::mem::take(&mut preview.open_system_settings) {
            self.system_settings.open = true;
        }
        if std::mem::take(&mut preview.open_project_settings) {
            self.project_settings.open(state);
        }
        if std::mem::take(&mut preview.open_keybindings) {
            self.keybindings.open = true;
        }
        if std::mem::take(&mut preview.open_export) {
            self.export_dialog.open(state);
        }
    }
}

use crate::infra::localization::tr;
use crate::ui::types::CatalogRow;
use crate::ui::ui_ext::{UiExt, grow_style, row_style_full};
use egui::Ui;
use egui_taffy::{TuiBuilderLogic, tui};
use elegance::{Button, SegmentedControl, TextInput};

pub trait EffectCatalogSource {
    fn categories(&self) -> &[String];
    fn filtered(&self, query: &str, sort_mode: i32, category: &str) -> Vec<CatalogRow>;
}

pub struct EffectAddDialog {
    pub open: bool,
    query: String,
    sort_mode: i32,
    category_filter: String,
}

impl EffectAddDialog {
    pub fn new() -> Self {
        Self {
            open: false,
            query: String::new(),
            sort_mode: 0,
            category_filter: String::new(),
        }
    }

    pub fn open(&mut self) {
        self.query.clear();
        self.sort_mode = 0;
        self.category_filter.clear();
        self.open = true;
    }

    pub fn close(&mut self) {
        self.open = false;
    }

    pub fn show(&mut self, ui: &mut Ui, source: &dyn EffectCatalogSource) -> Option<String> {
        let mut confirmed_id = None;
        let mut close_clicked = false;

        egui::Panel::bottom("add_effect_footer").show(ui, |ui| {
            ui.footer_bar(|ui| {
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ui.add(Button::new(t!("閉じる"))).clicked() {
                        close_clicked = true;
                    }
                });
            });
        });

        egui::CentralPanel::default().show(ui, |ui| {
            ui.page_content(|ui| {
                let row_width = ui.available_width();
                tui(ui, ui.id().with("effect_search_row"))
                    .style(row_style_full(8.0, row_width))
                    .show(|tui| {
                        tui.ui(|ui| {
                            ui.label(t!("検索:"));
                        });
                        tui.style(grow_style()).ui(|ui| {
                            let hint = t!("エフェクト名を検索…").to_string();
                            ui.add(TextInput::new(&mut self.query).hint(hint.as_str()));
                        });
                    });

                {
                    let sort_labels = ["カテゴリ順", "名前順", "最近使用"];
                    let mut sort_idx = self.sort_mode as usize;
                    ui.add(SegmentedControl::new(
                        &mut sort_idx,
                        sort_labels.iter().map(|l| tr(l)),
                    ));
                    self.sort_mode = sort_idx as i32;
                }

                egui::ScrollArea::horizontal()
                    .id_salt("category_tabs")
                    .show(ui, |ui| {
                        let categories = source.categories();
                        let mut labels: Vec<String> = Vec::with_capacity(categories.len() + 1);
                        labels.push(t!("全て").to_string());
                        labels.extend(categories.iter().cloned());
                        let mut cat_idx = labels
                            .iter()
                            .position(|c| c == &self.category_filter)
                            .unwrap_or(0);
                        ui.add(SegmentedControl::new(&mut cat_idx, labels.iter().cloned()));
                        self.category_filter = if cat_idx == 0 {
                            String::new()
                        } else {
                            labels[cat_idx].clone()
                        };
                    });

                ui.separator();

                let rows = source.filtered(&self.query, self.sort_mode, &self.category_filter);
                egui::ScrollArea::vertical()
                    .id_salt("effect_list_scroll")
                    .auto_shrink([false, false])
                    .show(ui, |ui| {
                        if rows.is_empty() {
                            ui.colored_label(
                                egui::Color32::from_rgb(0x88, 0x88, 0x90),
                                t!("該当するエフェクトがありません"),
                            );
                        }
                        for row in &rows {
                            let (clicked, _) = egui::Sides::new().shrink_left().truncate().show(
                                ui,
                                |ui| ui.add(Button::new(&row.name).outline()).clicked(),
                                |ui| {
                                    ui.colored_label(
                                        egui::Color32::from_rgb(0x8a, 0xab, 0xff),
                                        &row.category,
                                    )
                                },
                            );
                            if clicked {
                                confirmed_id = Some(row.id.clone());
                            }
                        }
                    });
            });
        });

        if confirmed_id.is_some() || close_clicked {
            self.close();
        }

        confirmed_id
    }
}

use crate::infra::localization::{effect_category, effect_name};
use crate::ui::effect_add_dialog::EffectCatalogSource;
use crate::ui::types::CatalogRow;
use std::sync::Mutex;

static RECENT_EFFECT_IDS: Mutex<Vec<String>> = Mutex::new(Vec::new());

pub fn mark_effect_used(id: &str) {
    let mut recent = RECENT_EFFECT_IDS.lock().unwrap();
    recent.retain(|x| x != id);
    recent.insert(0, id.to_owned());
    recent.truncate(8);
}

pub struct EffectCatalogState {
    all: Vec<CatalogRow>,
    categories: Vec<String>,
}

impl EffectCatalogState {
    pub fn build_video() -> Self {
        let mut all: Vec<CatalogRow> = crate::effects::loader::registry()
            .iter()
            .map(|p| CatalogRow {
                id: p.id().to_owned(),
                name: effect_name(p.name()),
                category: effect_category(p.category()),
            })
            .collect();
        all.sort_by(|a, b| a.category.cmp(&b.category).then(a.name.cmp(&b.name)));

        let mut categories: Vec<String> = all.iter().map(|r| r.category.clone()).collect();
        categories.sort();
        categories.dedup();

        Self { all, categories }
    }

    pub fn build_audio() -> Self {
        let mut all: Vec<CatalogRow> = crate::audio::plugin_registry::get_all()
            .iter()
            .map(|p| CatalogRow {
                id: p.plugin_id.clone(),
                name: p.name.clone(),
                category: format!("{:?}", p.format),
            })
            .collect();
        all.sort_by(|a, b| a.category.cmp(&b.category).then(a.name.cmp(&b.name)));

        let mut categories: Vec<String> = all.iter().map(|r| r.category.clone()).collect();
        categories.sort();
        categories.dedup();

        Self { all, categories }
    }

    pub fn categories_inner(&self) -> &[String] {
        &self.categories
    }

    pub fn filtered(&self, query: &str, sort_mode: i32, category: &str) -> Vec<CatalogRow> {
        let q = query.to_lowercase();
        let mut rows: Vec<CatalogRow> = self
            .all
            .iter()
            .filter(|r| q.is_empty() || r.name.to_lowercase().contains(&q))
            .filter(|r| category.is_empty() || r.category.as_str() == category)
            .cloned()
            .collect();

        match sort_mode {
            1 => rows.sort_by(|a, b| a.name.cmp(&b.name)),
            2 => {
                let recent = RECENT_EFFECT_IDS.lock().unwrap();
                rows.sort_by_key(|r| {
                    recent
                        .iter()
                        .position(|id| id.as_str() == r.id.as_str())
                        .unwrap_or(usize::MAX)
                });
            }
            _ => rows.sort_by(|a, b| a.category.cmp(&b.category).then(a.name.cmp(&b.name))),
        }
        rows
    }
}

impl EffectCatalogSource for EffectCatalogState {
    fn categories(&self) -> &[String] {
        self.categories_inner()
    }
    fn filtered(&self, query: &str, sort_mode: i32, category: &str) -> Vec<CatalogRow> {
        EffectCatalogState::filtered(self, query, sort_mode, category)
    }
}

use crate::app::state::SharedAppState;
use crate::infra::localization::tr;
use crate::project::export::{EncoderBackend, ExportCodec, ExportJob, ExportPreset};
use crate::ui::ui_ext::{col_style, row_end_style, row_style};
use egui::{Context, Ui};
use egui_taffy::{TuiBuilderLogic, tui};
use elegance::{Button, ProgressBar, SegmentedControl, Slider, TextInput};
use std::sync::{Arc, Mutex};

pub struct ExportDialog {
    pub open: bool,
    presets: Vec<ExportPreset>,
    selected_preset: i32,
    preset_name: String,

    output_path: String,
    codec: i32,
    backend: i32,
    mkv_container: bool,
    average_bitrate_kbps: i32,
    max_bitrate_kbps: i32,
    start_frame: i32,
    end_frame: i32,
    total_frames: i32,

    progress: Arc<Mutex<(i32, i32)>>,
    status_text: String,
    status_is_error: bool,
    active_queue: Option<crate::project::export::RenderQueue>,
}

impl ExportDialog {
    pub fn new() -> Self {
        Self {
            open: false,
            presets: crate::project::export::load_export_presets(),
            selected_preset: -1,
            preset_name: String::new(),
            output_path: String::new(),
            codec: 0,
            backend: 0,
            mkv_container: false,
            average_bitrate_kbps: 8000,
            max_bitrate_kbps: 12000,
            start_frame: 0,
            end_frame: 0,
            total_frames: 0,
            progress: Arc::new(Mutex::new((0, 0))),
            status_text: String::new(),
            status_is_error: false,
            active_queue: None,
        }
    }

    pub fn open(&mut self, state: &SharedAppState) {
        let total_frames = {
            let world_holder = crate::app::state::active_world(state);
            let world = world_holder.lock().unwrap();
            world.total_frames()
        };
        self.total_frames = total_frames;
        self.start_frame = 0;
        self.end_frame = total_frames;
        self.status_text.clear();
        self.presets = crate::project::export::load_export_presets();
        if let Some(first) = self.presets.first() {
            self.selected_preset = 0;
            self.preset_name = first.name.clone();
            self.apply_preset(0);
        } else {
            self.selected_preset = -1;
            self.preset_name.clear();
        }
        self.open = true;
    }

    fn apply_preset(&mut self, index: usize) {
        let Some(preset) = self.presets.get(index) else {
            return;
        };
        self.preset_name = preset.name.clone();
        self.codec = if preset.codec == ExportCodec::H264 {
            0
        } else {
            1
        };
        self.backend = match preset.backend {
            EncoderBackend::GpuVideo => 1,
            EncoderBackend::Gstreamer => 2,
            EncoderBackend::Auto => 0,
        };
        self.average_bitrate_kbps = (preset.average_bitrate / 1000) as i32;
        self.max_bitrate_kbps = (preset.max_bitrate / 1000) as i32;
        self.mkv_container = preset.container_ext.eq_ignore_ascii_case("mkv");
    }

    fn save_preset(&mut self) {
        let name = self.preset_name.trim().to_owned();
        if name.is_empty() {
            return;
        }
        let preset = ExportPreset {
            name: name.clone(),
            codec: if self.codec == 0 {
                ExportCodec::H264
            } else {
                ExportCodec::H265
            },
            backend: match self.backend {
                1 => EncoderBackend::GpuVideo,
                2 => EncoderBackend::Gstreamer,
                _ => EncoderBackend::Auto,
            },
            average_bitrate: self.average_bitrate_kbps.max(0) as u32 * 1000,
            max_bitrate: self.max_bitrate_kbps.max(0) as u32 * 1000,
            container_ext: if self.mkv_container {
                "mkv".into()
            } else {
                "mp4".into()
            },
        };
        if let Some(old) = self.presets.iter_mut().find(|p| p.name == name) {
            *old = preset;
        } else {
            self.presets.push(preset);
        }
        let _ = crate::project::export::save_export_presets(&self.presets);
        self.status_text = t!("プリセットを保存しました");
    }

    fn delete_preset(&mut self) {
        if self.selected_preset < 0 {
            return;
        }
        let index = self.selected_preset as usize;
        if index < self.presets.len() {
            self.presets.remove(index);
        }
        let _ = crate::project::export::save_export_presets(&self.presets);
        self.selected_preset = -1;
        self.preset_name.clear();
        self.status_text = t!("プリセットを削除しました");
    }

    fn pick_output_path(&mut self) {
        let mut picker = rfd::FileDialog::new();
        picker = if self.mkv_container {
            picker.add_filter("Matroska", &["mkv"])
        } else {
            picker.add_filter("MP4", &["mp4"])
        };
        if let Some(path) = picker.save_file() {
            self.output_path = path.to_string_lossy().into_owned();
        }
    }

    fn start_export(&mut self, state: &SharedAppState) {
        if self.output_path.is_empty() {
            return;
        }

        let progress = self.progress.clone();
        let job = ExportJob {
            output_path: self.output_path.clone().into(),
            codec: if self.codec == 0 {
                ExportCodec::H264
            } else {
                ExportCodec::H265
            },
            backend: match self.backend {
                1 => EncoderBackend::GpuVideo,
                2 => EncoderBackend::Gstreamer,
                _ => EncoderBackend::Auto,
            },
            average_bitrate: self.average_bitrate_kbps as u32 * 1000,
            max_bitrate: self.max_bitrate_kbps as u32 * 1000,
            start_frame: self.start_frame,
            end_frame: self.end_frame,
            progress: Some(Box::new(move |current, total| {
                *progress.lock().unwrap() = (current, total);
            })),
            cancel: None,
        };

        self.status_is_error = false;
        self.status_text.clear();

        let project_dir = {
            let s = state.lock().unwrap();
            s.sessions[s.active].meta.dir.clone()
        };
        let queue = {
            let s = state.lock().unwrap();
            s.render_queue.clone()
        };
        queue.enqueue(job, project_dir);
        queue.start(state.clone());
        let pending = queue.pending_count();
        self.active_queue = Some(queue);
        self.status_text = format!("{}({pending}件待機中)", t!("レンダーキューに追加しました"));
    }

    pub fn show(&mut self, _ctx: &Context, ui: &mut Ui, state: &SharedAppState) {
        if !self.open {
            return;
        }

        let (progress_current, progress_total) = *self.progress.lock().unwrap();
        let queue_running = self
            .active_queue
            .as_ref()
            .map(|q| {
                matches!(
                    q.state(),
                    crate::project::export::QueueState::Running
                        | crate::project::export::QueueState::CancelRequested
                )
            })
            .unwrap_or(false);

        let mut close_requested = false;
        egui::CentralPanel::default().show(ui, |ui| {
            ui.label(t!("書き出しプリセット"));
            tui(ui, ui.id().with("preset_row"))
                .style(row_style(8.0))
                .show(|tui| {
                    tui.ui(|ui| {
                        let current = self
                            .presets
                            .get(self.selected_preset.max(0) as usize)
                            .map(|p| p.name.clone())
                            .unwrap_or_else(|| t!("(未選択)"));
                        if ui.add(Button::new(&current)).clicked() && !self.presets.is_empty() {
                            let next =
                                (self.selected_preset + 1).rem_euclid(self.presets.len() as i32);
                            self.selected_preset = next;
                            self.apply_preset(next as usize);
                        }
                    });
                    tui.ui(|ui| {
                        if ui.add(Button::new(t!("保存"))).clicked() {
                            self.save_preset();
                        }
                    });
                    tui.ui(|ui| {
                        ui.add_enabled(self.selected_preset >= 0, Button::new(tr("削除")))
                            .clicked()
                            .then(|| self.delete_preset());
                    });
                });
            ui.add(TextInput::new(&mut self.preset_name));

            ui.label(t!("出力ファイル"));
            tui(ui, ui.id().with("output_path_row"))
                .style(row_style(8.0))
                .show(|tui| {
                    tui.ui(|ui| {
                        let display = if self.output_path.is_empty() {
                            t!("未選択")
                        } else {
                            self.output_path.clone()
                        };
                        ui.label(display);
                    });
                    tui.ui(|ui| {
                        ui.add_enabled(!queue_running, Button::new(tr("選択...")))
                            .clicked()
                            .then(|| self.pick_output_path());
                    });
                });

            ui.label(t!("映像コーデック"));
            {
                let mut codec_idx = self.codec.max(0) as usize;
                if ui
                    .add(SegmentedControl::new(&mut codec_idx, ["H.264", "H.265"]))
                    .changed()
                {
                    self.codec = codec_idx as i32;
                }
            }

            ui.label(t!("エンコーダー"));
            {
                let mut backend_idx = self.backend.max(0) as usize;
                if ui
                    .add(SegmentedControl::new(
                        &mut backend_idx,
                        [t!("自動(HW優先)"), t!("GPU HW固定"), t!("ソフトウェア")],
                    ))
                    .changed()
                {
                    self.backend = backend_idx as i32;
                }
            }

            ui.label(t!("コンテナ"));
            {
                let mut container_idx: usize = if self.mkv_container { 1 } else { 0 };
                if ui
                    .add(SegmentedControl::new(
                        &mut container_idx,
                        ["MP4 + AAC", "MKV + Opus"],
                    ))
                    .changed()
                {
                    self.mkv_container = container_idx == 1;
                }
            }

            tui(ui, ui.id().with("bitrate_row"))
                .style(row_style(16.0))
                .show(|tui| {
                    tui.style(col_style(2.0)).add(|tui| {
                        tui.ui(|ui| {
                            ui.label(t!("平均ビットレート(kbps)"));
                        });
                        tui.ui(|ui| {
                            ui.add(Slider::new(&mut self.average_bitrate_kbps, 500..=200_000));
                        });
                    });
                    tui.style(col_style(2.0)).add(|tui| {
                        tui.ui(|ui| {
                            ui.label(t!("最大ビットレート(kbps)"));
                        });
                        tui.ui(|ui| {
                            ui.add(Slider::new(&mut self.max_bitrate_kbps, 500..=200_000));
                        });
                    });
                });

            let end_max = if self.total_frames > 0 {
                self.total_frames - 1
            } else {
                0
            };
            tui(ui, ui.id().with("frame_range_row"))
                .style(row_style(16.0))
                .show(|tui| {
                    tui.style(col_style(2.0)).add(|tui| {
                        tui.ui(|ui| {
                            ui.label(t!("開始フレーム"));
                        });
                        tui.ui(|ui| {
                            ui.add(Slider::new(&mut self.start_frame, 0..=end_max));
                        });
                    });
                    tui.style(col_style(2.0)).add(|tui| {
                        tui.ui(|ui| {
                            ui.label(t!("終了フレーム"));
                        });
                        tui.ui(|ui| {
                            ui.add(Slider::new(&mut self.end_frame, 1..=self.total_frames));
                        });
                    });
                });

            if queue_running {
                ui.label(
                    t!("書き出し中: {progress_current} / {progress_total}")
                        .replace("{progress_current}", &progress_current.to_string())
                        .replace("{progress_total}", &progress_total.to_string()),
                );
                let fraction = if progress_total > 0 {
                    progress_current as f32 / progress_total as f32
                } else {
                    0.0
                };
                ui.add(ProgressBar::new(fraction));
            }

            if !self.status_text.is_empty() {
                let color = if self.status_is_error {
                    egui::Color32::from_rgb(0xd9, 0x4f, 0x4f)
                } else {
                    egui::Color32::from_rgb(0x4f, 0xd9, 0x7a)
                };
                ui.colored_label(color, &self.status_text);
            }

            ui.separator();
            let actions_row_width = ui.available_width();
            tui(ui, ui.id().with("export_actions_row"))
                .style(row_end_style(8.0, actions_row_width))
                .show(|tui| {
                    tui.ui(|ui| {
                        let close_label = if queue_running {
                            t!("中止")
                        } else {
                            t!("閉じる")
                        };
                        if ui.add(Button::new(close_label).outline()).clicked() {
                            if queue_running {
                                if let Some(queue) = &self.active_queue {
                                    queue.cancel_current();
                                }
                            } else {
                                close_requested = true;
                            }
                        }
                    });
                    tui.ui(|ui| {
                        let start_enabled = !queue_running && !self.output_path.is_empty();
                        if ui
                            .add_enabled(start_enabled, Button::new(tr("書き出し")))
                            .clicked()
                        {
                            self.start_export(state);
                        }
                    });
                });
        });
        self.open = !close_requested;
    }
}

use std::collections::{HashMap, HashSet};
use std::sync::{Mutex, OnceLock};

fn font_has_usable_glyphs(font: &font_kit::font::Font) -> bool {
    let ascii_ok = font.glyph_for_char('A').map(|g| g != 0).unwrap_or(false);
    let kana_ok = font.glyph_for_char('あ').map(|g| g != 0).unwrap_or(false);
    ascii_ok || kana_ok
}

fn installed_fonts() -> &'static Vec<String> {
    static FONTS: OnceLock<Vec<String>> = OnceLock::new();
    FONTS.get_or_init(|| {
        use font_kit::family_name::FamilyName;
        use font_kit::properties::Properties;
        let source = font_kit::source::SystemSource::new();
        let mut names = source.all_families().unwrap_or_default();
        names.sort();
        names.dedup();
        names.retain(|name| {
            let Ok(handle) =
                source.select_best_match(&[FamilyName::Title(name.clone())], &Properties::new())
            else {
                return false;
            };
            let Ok(font) = handle.load() else {
                return false;
            };
            font_has_usable_glyphs(&font)
        });
        names
    })
}

static FONT_BYTES_CACHE: OnceLock<Mutex<HashMap<String, Option<Vec<u8>>>>> = OnceLock::new();

fn bytes_cache() -> &'static Mutex<HashMap<String, Option<Vec<u8>>>> {
    FONT_BYTES_CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

fn load_family_bytes(family: &str) -> Option<Vec<u8>> {
    use font_kit::family_name::FamilyName;
    use font_kit::properties::Properties;
    use font_kit::source::SystemSource;
    let source = SystemSource::new();
    let handle = source
        .select_best_match(&[FamilyName::Title(family.to_owned())], &Properties::new())
        .ok()?;
    let font = handle.load().ok()?;
    font.copy_font_data().map(|d| d.to_vec())
}

pub fn preload_installed_fonts() {
    let families = installed_fonts();
    let cache = bytes_cache();
    for family in families {
        let bytes = load_family_bytes(family);
        cache.lock().unwrap().insert(family.clone(), bytes);
    }
}

fn cached_bytes(family: &str) -> Option<Vec<u8>> {
    if let Some(entry) = bytes_cache().lock().unwrap().get(family) {
        return entry.clone();
    }
    let bytes = load_family_bytes(family);
    bytes_cache()
        .lock()
        .unwrap()
        .insert(family.to_owned(), bytes.clone());
    bytes
}

struct UiFontState {
    registered_at: HashMap<String, u64>,
    failed: HashSet<String>,
    defs: egui::FontDefinitions,
}

static UI_FONT_STATE: Mutex<Option<UiFontState>> = Mutex::new(None);

fn ensure_font_loaded(ctx: &egui::Context, family: &str) -> bool {
    if family.is_empty() {
        return false;
    }
    let current_pass = ctx.cumulative_pass_nr();
    let mut guard = UI_FONT_STATE.lock().unwrap();
    let state = guard.get_or_insert_with(|| UiFontState {
        registered_at: HashMap::new(),
        failed: HashSet::new(),
        defs: ctx.fonts(|f| f.definitions().clone()),
    });
    if state.failed.contains(family) {
        return false;
    }
    if let Some(&pass) = state.registered_at.get(family) {
        return current_pass > pass;
    }
    let Some(bytes) = cached_bytes(family) else {
        state.failed.insert(family.to_owned());
        return false;
    };
    state
        .defs
        .font_data
        .insert(family.to_owned(), egui::FontData::from_owned(bytes).into());
    state.defs.families.insert(
        egui::FontFamily::Name(family.to_owned().into()),
        vec![family.to_owned()],
    );
    state.registered_at.insert(family.to_owned(), current_pass);
    ctx.set_fonts(state.defs.clone());
    ctx.request_repaint();
    false
}

fn font_label(ui: &egui::Ui, family: &str) -> egui::RichText {
    let resolved = !family.is_empty() && ensure_font_loaded(ui.ctx(), family);
    let text = if family.is_empty() {
        t!("(システム標準)").to_string()
    } else {
        family.to_owned()
    };
    let font_id = if resolved {
        egui::FontId::new(14.0, egui::FontFamily::Name(family.to_owned().into()))
    } else {
        egui::FontId::new(14.0, egui::FontFamily::Proportional)
    };
    egui::RichText::new(text).font(font_id)
}

pub fn font_stack_row(
    ui: &mut egui::Ui,
    id_source: impl std::hash::Hash + std::fmt::Debug,
    current: &mut String,
) -> Option<String> {
    let fonts = installed_fonts();
    let selected_index: usize = fonts
        .iter()
        .position(|f| f == current)
        .map(|i| i + 1)
        .unwrap_or(0);
    let selected_label = font_label(ui, current);
    let mut result: Option<String> = None;
    egui::ComboBox::from_id_salt(id_source)
        .selected_text(selected_label)
        .show_ui(ui, |ui| {
            if ui
                .selectable_label(selected_index == 0, font_label(ui, ""))
                .clicked()
                && selected_index != 0
            {
                result = Some(String::new());
            }
            for (i, name) in fonts.iter().enumerate() {
                if ui
                    .selectable_label(selected_index == i + 1, font_label(ui, name))
                    .clicked()
                    && selected_index != i + 1
                {
                    result = Some(name.clone());
                }
            }
        });
    result
}

use crate::app::shortcuts::{self, ALL_COMMANDS, CommandId, OwnedBinding, Scope};
use crate::ui::ui_ext::{fixed_style, row_between_style, row_style};
use egui::{Context, Ui};
use egui_taffy::{TuiBuilderLogic, tui};

fn scope_label(s: Scope) -> String {
    match s {
        Scope::Unspecified => t!("未定義"),
        Scope::Global => t!("全体"),
        Scope::Timeline => t!("タイムライン"),
        Scope::Properties => t!("設定ダイアログ"),
        Scope::Preview => t!("プレビュー"),
    }
}

fn key_display(b: &OwnedBinding) -> String {
    let mut parts = Vec::new();
    if b.ctrl {
        parts.push("Ctrl");
    }
    if b.shift {
        parts.push("Shift");
    }
    if b.alt {
        parts.push("Alt");
    }
    parts.push(b.key.as_str());
    parts.join("+")
}

#[derive(Clone)]
struct Row {
    command: CommandId,
    label: String,
    scope_label: String,
    key_display: String,
}

fn build_rows() -> Vec<Row> {
    let keymap = shortcuts::active_keymap().lock().unwrap();
    ALL_COMMANDS
        .iter()
        .map(|&command| {
            let (scope, binding) = keymap.binding_of(command);
            Row {
                command,
                label: shortcuts::label(command).into(),
                scope_label: scope_label(scope),
                key_display: key_display(&binding),
            }
        })
        .collect()
}

pub struct KeybindingsWindow {
    pub open: bool,
    rows: Vec<Row>,
    save_status: String,
    conflict_message: String,
    capturing: Option<CommandId>,
    pending_binding: Option<OwnedBinding>,
}

impl KeybindingsWindow {
    pub fn new() -> Self {
        Self {
            open: false,
            rows: build_rows(),
            save_status: String::new(),
            conflict_message: String::new(),
            capturing: None,
            pending_binding: None,
        }
    }

    fn sync(&mut self) {
        self.rows = build_rows();
    }

    fn apply_capture(&mut self, command: CommandId, binding: OwnedBinding) {
        let mut keymap = shortcuts::active_keymap().lock().unwrap();
        let (scope, _) = keymap.binding_of(command);
        if let Some(other) = keymap.conflict_of(command, scope, &binding) {
            self.conflict_message = t!("競合: {}").replace("{}", &shortcuts::label(other));
            return;
        }
        self.conflict_message.clear();
        keymap.set_binding(command, scope, binding);
        drop(keymap);
        self.sync();
    }

    fn cancel_capture(&mut self) {
        self.capturing = None;
        self.pending_binding = None;
    }

    pub fn set_open(&mut self, open: bool) {
        self.open = open;
        if !open {
            self.cancel_capture();
        }
    }

    pub fn show(&mut self, ctx: &Context, ui: &mut Ui) {
        if !self.open {
            return;
        }

        if let Some(command) = self.capturing {
            let (newly_pressed, released) = ctx.input(|i| {
                let modifiers = i.modifiers;
                let mut newly_pressed = None;
                let mut released = None;
                for e in &i.events {
                    let egui::Event::Key { key, pressed, .. } = e else {
                        continue;
                    };
                    let name = key.name();
                    if *pressed {
                        newly_pressed = Some(OwnedBinding {
                            ctrl: modifiers.ctrl,
                            shift: modifiers.shift,
                            alt: modifiers.alt,
                            key: name.to_string(),
                        });
                    } else if self
                        .pending_binding
                        .as_ref()
                        .is_some_and(|b| b.key.eq_ignore_ascii_case(name))
                    {
                        released = self.pending_binding.clone();
                    }
                }
                (newly_pressed, released)
            });
            if let Some(binding) = newly_pressed {
                self.pending_binding = Some(binding);
            }
            if let Some(binding) = released {
                self.capturing = None;
                self.pending_binding = None;
                self.apply_capture(command, binding);
            }
        }

        egui::CentralPanel::default().show(ui, |ui| {
            if !self.conflict_message.is_empty() {
                ui.colored_label(egui::Color32::RED, &self.conflict_message);
            }

            egui::ScrollArea::vertical()
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    let row_height = 24.0;
                    let key_btn_w = 130.0;
                    let reset_btn_w = 90.0;

                    for (i, row) in self.rows.clone().into_iter().enumerate() {
                        let fill = if i % 2 == 1 {
                            ui.visuals().faint_bg_color
                        } else {
                            egui::Color32::TRANSPARENT
                        };
                        egui::Frame::default().fill(fill).show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            let row_width = ui.available_width();
                            tui(ui, ui.id().with(("keybind_row", i)))
                                .style(row_between_style(row_width))
                                .show(|tui| {
                                    tui.style(row_style(12.0)).add(|tui| {
                                        tui.ui(|ui| {
                                            ui.label(&row.label);
                                        });
                                        tui.ui(|ui| {
                                            ui.label(&row.scope_label);
                                        });
                                    });
                                    tui.style(row_style(4.0)).add(|tui| {
                                        let capturing = self.capturing == Some(row.command);
                                        let text = if capturing {
                                            t!("入力待ち…")
                                        } else {
                                            row.key_display.clone()
                                        };
                                        tui.style(fixed_style(key_btn_w, row_height)).ui(|ui| {
                                            if ui
                                                .add_sized(
                                                    [key_btn_w, row_height],
                                                    egui::Button::new(text),
                                                )
                                                .clicked()
                                            {
                                                self.capturing = Some(row.command);
                                                self.pending_binding = None;
                                            }
                                        });

                                        tui.style(fixed_style(reset_btn_w, row_height)).ui(|ui| {
                                            if ui
                                                .add_sized(
                                                    [reset_btn_w, row_height],
                                                    egui::Button::new(t!("既定へ")),
                                                )
                                                .clicked()
                                            {
                                                shortcuts::active_keymap()
                                                    .lock()
                                                    .unwrap()
                                                    .reset_to_default(row.command);
                                                self.sync();
                                            }
                                        });
                                    });
                                });
                        });
                    }
                });

            ui.separator();
            tui(ui, ui.id().with("keybind_actions"))
                .style(row_style(8.0))
                .show(|tui| {
                    tui.ui(|ui| {
                        if ui.button(t!("全て既定へ")).clicked() {
                            shortcuts::active_keymap().lock().unwrap().reset_all();
                            self.sync();
                        }
                    });
                    tui.ui(|ui| {
                        if ui.button(t!("保存")).clicked() {
                            let result = shortcuts::save_to_disk(
                                &shortcuts::active_keymap().lock().unwrap(),
                            );
                            self.save_status = match result {
                                Ok(()) => t!("保存完了"),
                                Err(_) => t!("保存失敗"),
                            };
                        }
                    });
                    tui.ui(|ui| {
                        if ui.button(t!("再読込")).clicked() {
                            let loaded = shortcuts::load_from_disk().unwrap_or_default();
                            *shortcuts::active_keymap().lock().unwrap() = loaded;
                            self.sync();
                            self.save_status = t!("再読込完了");
                        }
                    });
                    tui.ui(|ui| {
                        ui.label(&self.save_status);
                    });
                });
        });
    }
}

use crate::project::{self, ProjectMeta};
