use shipyard::UniqueView;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CameraViewMode {
    Camera,
    Edit,
    Front,
    Left,
    Top,
    Back,
    Right,
    Bottom,
}

impl CameraViewMode {
    const ALL: [Self; 8] = [
        Self::Camera,
        Self::Edit,
        Self::Front,
        Self::Left,
        Self::Top,
        Self::Back,
        Self::Right,
        Self::Bottom,
    ];

    fn label(self) -> &'static str {
        match self {
            Self::Camera => "カメラ",
            Self::Edit => "エディット",
            Self::Front => "前",
            Self::Left => "左",
            Self::Top => "上",
            Self::Back => "後",
            Self::Right => "右",
            Self::Bottom => "下",
        }
    }
}

pub fn show(
    ctx: &egui::Context,
    open: &mut bool,
    mode: &mut CameraViewMode,
    texture_id: Option<TextureId>,
    world: &EcsWorld,
    interaction: &mut InteractionState,
    state: &SharedAppState,
) {
    egui::Window::new("カメラ視点")
        .open(open)
        .default_size([520.0, 360.0])
        .resizable(true)
        .show(ctx, |ui| {
            ui.horizontal(|ui| {
                for candidate in CameraViewMode::ALL {
                    if ui
                        .selectable_label(*mode == candidate, candidate.label())
                        .clicked()
                    {
                        *mode = candidate;
                    }
                }
            });
            ui.separator();

            let available = ui.available_size();
            let (response, painter) = ui.allocate_painter(available, egui::Sense::click_and_drag());
            interaction.handle(&response, response.rect, state);
            if *mode == CameraViewMode::Camera {
                if let Some(texture_id) = texture_id {
                    painter.image(
                        texture_id,
                        response.rect,
                        Rect::from_min_max(Pos2::ZERO, Pos2::new(1.0, 1.0)),
                        Color32::WHITE,
                    );
                }
            } else {
                draw_edit_view(&painter, response.rect, world, *mode);
            }
        });
}

fn draw_edit_view(painter: &egui::Painter, rect: Rect, world: &EcsWorld, mode: CameraViewMode) {
    painter.rect_filled(rect, 0.0, Color32::from_rgb(12, 14, 18));
    let center = rect.center();
    let scale = (rect.width().min(rect.height()) / 900.0).max(0.2);
    let grid_color = Color32::from_rgba_unmultiplied(150, 160, 175, 75);

    for index in -10..=10 {
        let offset = index as f32 * 40.0 * scale;
        painter.line_segment(
            [
                Pos2::new(center.x + offset, rect.top()),
                Pos2::new(center.x + offset, rect.bottom()),
            ],
            Stroke::new(1.0, grid_color),
        );
        painter.line_segment(
            [
                Pos2::new(rect.left(), center.y + offset),
                Pos2::new(rect.right(), center.y + offset),
            ],
            Stroke::new(1.0, grid_color),
        );
    }

    let camera = world.world.run(|camera: UniqueView<Camera>| *camera);
    let project = world.get_project();
    let (active, _) = get_active_objects_system(world);
    let object_color = Color32::from_rgb(220, 225, 235);
    for object in active {
        let Some(transform) = world.get_transform(object.clip_instance as usize) else {
            continue;
        };
        let position = view_position(mode, transform.x, transform.y, transform.z, center, scale);
        painter.circle_filled(position, 4.0, object_color);
    }

    let camera_pos = view_position(
        mode,
        camera.pos_x,
        camera.pos_y,
        camera.pos_z,
        center,
        scale,
    );
    let target_pos = view_position(
        mode,
        camera.target_x,
        camera.target_y,
        camera.target_z,
        center,
        scale,
    );
    painter.circle_filled(camera_pos, 6.0, Color32::from_rgb(245, 80, 80));
    painter.line_segment(
        [camera_pos, target_pos],
        Stroke::new(2.0, Color32::from_rgb(245, 80, 80)),
    );
    painter.circle_filled(target_pos, 4.0, Color32::from_rgb(245, 210, 70));
    painter.text(
        rect.left_top() + Vec2::splat(10.0),
        egui::Align2::LEFT_TOP,
        format!("{}  {}x{}", mode.label(), project.width, project.height),
        egui::FontId::monospace(12.0),
        Color32::from_rgb(210, 215, 225),
    );
}

fn view_position(mode: CameraViewMode, x: f32, y: f32, z: f32, center: Pos2, scale: f32) -> Pos2 {
    let (horizontal, vertical) = match mode {
        CameraViewMode::Left | CameraViewMode::Right => (z, y),
        CameraViewMode::Top | CameraViewMode::Bottom => (x, z),
        _ => (x, y),
    };
    let horizontal = if matches!(
        mode,
        CameraViewMode::Back | CameraViewMode::Right | CameraViewMode::Bottom
    ) {
        -horizontal
    } else {
        horizontal
    };
    Pos2::new(center.x + horizontal * scale, center.y - vertical * scale)
}

//! ハンドル位置は `hit_test::anchor_screen_pos` と同一の計算を用いる。
//! 描画のみを扱い、入力判定は持たない。

use super::hit_test::{AnchorKind, anchor_screen_pos};
use super::projection::{project_object_corners, project_object_origin};
use crate::ecs::EcsWorld;
use crate::ecs::resources::source_size_cache;

const HANDLE_RADIUS: f32 = 5.0;
const ORIGIN_RADIUS: f32 = 3.0;

pub fn draw(painter: &egui::Painter, world: &EcsWorld, selected: &[usize], image_rect: egui::Rect) {
    let line_color = egui::Color32::from_rgb(0x8a, 0xab, 0xff);
    let handle_color = egui::Color32::from_rgb(0x3a, 0x6d, 0xf0);
    let origin_color = egui::Color32::from_rgb(0xe8, 0xe8, 0xee);

    for &id in selected {
        let Some(origin) = project_object_origin(world, id, image_rect) else {
            continue;
        };
        painter.circle_filled(origin, ORIGIN_RADIUS, origin_color);

        if let Some((sw, sh)) = source_size_cache::global().get(id)
            && let Some(corners) = project_object_corners(world, id, sw, sh, image_rect)
        {
            for (from, to) in corners.iter().zip(corners.iter().cycle().skip(1)).take(4) {
                painter.line_segment([*from, *to], egui::Stroke::new(1.0, line_color));
            }
        }

        for kind in [AnchorKind::Scale, AnchorKind::Rotate] {
            let Some(pos) = anchor_screen_pos(world, id, image_rect, kind) else {
                continue;
            };
            painter.line_segment([origin, pos], egui::Stroke::new(1.0, line_color));
            match kind {
                AnchorKind::Scale => {
                    let rect = egui::Rect::from_center_size(
                        pos,
                        egui::vec2(HANDLE_RADIUS * 2.0, HANDLE_RADIUS * 2.0),
                    );
                    painter.rect_filled(rect, 1.0, handle_color);
                }
                AnchorKind::Rotate => {
                    painter.circle_filled(pos, HANDLE_RADIUS, handle_color);
                }
            }
        }
    }
}

//! アンカーはオブジェクトの外形 (SourceSizeCache から解決した4隅) を基準に配置する。
//! SourceSizeCache に未登録のオブジェクト (シェイプ・テキスト等、外形未解決の種別、
//! またはまだ1フレームも `get_active_objects_system` を通っていないオブジェクト) は、
//! 原点からの固定オフセットへフォールバックする。

use super::projection::{project_object_corners, project_object_origin};
use crate::ecs::EcsWorld;
use crate::ecs::resources::source_size_cache;
use crate::ecs::systems::get_active_objects_system;

pub const ANCHOR_OFFSET_PX: f32 = 48.0;
pub const ANCHOR_HIT_RADIUS_PX: f32 = 8.0;
pub const OBJECT_PICK_RADIUS_PX: f32 = 24.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AnchorKind {
    Scale,
    Rotate,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HitTarget {
    Anchor(usize, AnchorKind),
    Object(usize),
    None,
}

/// 凸四角形の内外判定 (2Dクロス積による符号一致判定)。
/// `corners` は `project_object_corners` の出力 (時計回り/反時計回りいずれでも可) を想定する。
fn point_in_quad(p: egui::Pos2, corners: &[egui::Pos2; 4]) -> bool {
    let mut sign: Option<bool> = None;
    for i in 0..4 {
        let a = corners[i];
        let b = corners[(i + 1) % 4];
        let cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        let s = cross > 0.0;
        match sign {
            None => sign = Some(s),
            Some(prev) if prev != s => return false,
            _ => {}
        }
    }
    true
}

pub fn anchor_screen_pos(
    world: &EcsWorld,
    object_id: usize,
    image_rect: egui::Rect,
    kind: AnchorKind,
) -> Option<egui::Pos2> {
    let origin = project_object_origin(world, object_id, image_rect)?;

    if let Some((sw, sh)) = source_size_cache::global().get(object_id) {
        if let Some(corners) = project_object_corners(world, object_id, sw, sh, image_rect) {
            return Some(match kind {
                AnchorKind::Scale => corners[2],
                AnchorKind::Rotate => {
                    let mid_top = egui::pos2(
                        (corners[0].x + corners[1].x) * 0.5,
                        (corners[0].y + corners[1].y) * 0.5,
                    );
                    let dir = (mid_top - origin).normalized();
                    mid_top + dir * 16.0
                }
            });
        }
    }

    Some(match kind {
        AnchorKind::Scale => origin + egui::vec2(ANCHOR_OFFSET_PX, ANCHOR_OFFSET_PX),
        AnchorKind::Rotate => origin + egui::vec2(0.0, -ANCHOR_OFFSET_PX),
    })
}

pub fn hit_test(
    pointer: egui::Pos2,
    selected: &[usize],
    world: &EcsWorld,
    image_rect: egui::Rect,
) -> HitTarget {
    for &id in selected {
        for kind in [AnchorKind::Rotate, AnchorKind::Scale] {
            if let Some(pos) = anchor_screen_pos(world, id, image_rect, kind) {
                if pos.distance(pointer) <= ANCHOR_HIT_RADIUS_PX {
                    return HitTarget::Anchor(id, kind);
                }
            }
        }
    }

    let (active, _captured) = get_active_objects_system(world);
    let mut nearest: Option<(usize, f32)> = None;
    for obj in &active {
        let id = obj.clip_instance as usize;

        if let Some((sw, sh)) = source_size_cache::global().get(id) {
            if let Some(corners) = project_object_corners(world, id, sw, sh, image_rect) {
                if point_in_quad(pointer, &corners) {
                    nearest = Some((id, 0.0));
                    continue;
                }
            }
        }

        let Some(pos) = project_object_origin(world, id, image_rect) else {
            continue;
        };
        let d = pos.distance(pointer);
        if d <= OBJECT_PICK_RADIUS_PX && nearest.map_or(true, |(_, nd)| d < nd) {
            nearest = Some((id, d));
        }
    }
    nearest.map_or(HitTarget::None, |(id, _)| HitTarget::Object(id))
}

//!   - オブジェクト本体のドラッグ           → 選択オブジェクト群の平行移動
//!   - Scaleアンカーのドラッグ              → 単一オブジェクトの拡大率変更 (scale_x, scale_y 同時)
//!   - Alt+オブジェクトドラッグ             → 単一オブジェクトの拡大率変更
//!   - Alt+Scaleアンカーのドラッグ          → 単一オブジェクトのZ回転
//!   - Rotateアンカーのドラッグ             → 単一オブジェクトの rot_z 変更
//!   - Ctrl+Alt+ドラッグ                    → 単一オブジェクトの中心座標 (center_x, center_y) 変更
//!   - オブジェクト本体のクリック           → 選択
//!   - 空白のクリック                       → 選択解除
//!
//! 対応範囲外:
//!   - Scale / Rotate のドラッグ量計算はスクリーン空間の比率・角度で完結しており、
//!     カメラ設定に依存しない。
//!   - Move / CenterOffset はドラッグ開始時に対象オブジェクトの実効カメラを解決し、
//!     その ViewportState をドラッグ中に再利用する。

use super::hit_test::{self, AnchorKind, HitTarget};
use super::projection;
use super::viewport::ViewportState;
use crate::app::state::{self as app_state, SharedAppState};
use crate::ecs::components::ObjectId;
use crate::ecs::history::HistoryCommand;
use crate::ecs::systems::resolve_object_camera;
use crate::ecs::transform::{Camera, GlobalMatrix, Transform, compute_global_matrix};
use neoutl_object_api::UNIT_SIZE_PX;
use shipyard::{Get, IntoIter, View, ViewMut, World};

enum ActiveDrag {
    Move {
        object_ids: Vec<usize>,
        start: Vec<(usize, Transform)>,
        viewport: ViewportState,
    },
    Scale {
        object_id: usize,
        start: Transform,
        origin_screen: egui::Pos2,
        start_vec: egui::Vec2,
    },
    Rotate {
        object_id: usize,
        start: Transform,
        origin_screen: egui::Pos2,
        start_angle_deg: f32,
    },
    CenterOffset {
        object_id: usize,
        start: Transform,
        viewport: ViewportState,
    },
    Camera {
        object_id: usize,
        start: Camera,
        mode: CameraDragMode,
    },
}

#[derive(Clone, Copy)]
enum CameraDragMode {
    Orbit,
    Dolly,
    Pan,
}

pub struct InteractionState {
    active: Option<ActiveDrag>,
}

impl InteractionState {
    pub fn new() -> Self {
        Self { active: None }
    }

    pub fn handle(
        &mut self,
        response: &egui::Response,
        image_rect: egui::Rect,
        state: &SharedAppState,
    ) {
        if response.drag_started_by(egui::PointerButton::Secondary) {
            self.start_camera_drag(response, state);
            if self.active.is_some() {
                return;
            }
        }
        if response.drag_started() {
            self.start_drag(response, image_rect, state);
        }
        if response.dragged() && self.active.is_some() {
            self.apply_drag(response, state);
        }
        if response.drag_stopped() {
            self.commit_drag(state);
        }
        if response.clicked() {
            self.handle_click(response, image_rect, state);
        }
    }

    fn start_camera_drag(&mut self, response: &egui::Response, state: &SharedAppState) {
        let modifiers = response.ctx.input(|i| i.modifiers);
        let world_holder = app_state::active_world(state);
        let world = world_holder.lock().unwrap();
        let object_id = world
            .selected_ids()
            .iter()
            .find(|&&id| world.get_camera_params(id).is_some())
            .copied();
        let Some(object_id) = object_id else {
            return;
        };
        let Some(start) = world.get_camera_params(object_id) else {
            return;
        };
        let mode = if modifiers.ctrl {
            CameraDragMode::Dolly
        } else if modifiers.shift {
            CameraDragMode::Pan
        } else {
            CameraDragMode::Orbit
        };
        self.active = Some(ActiveDrag::Camera {
            object_id,
            start,
            mode,
        });
    }

    fn start_drag(
        &mut self,
        response: &egui::Response,
        image_rect: egui::Rect,
        state: &SharedAppState,
    ) {
        let Some(pointer) = response.interact_pointer_pos() else {
            return;
        };
        let modifiers = response.ctx.input(|i| i.modifiers);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let selected: Vec<usize> = world.selected_ids().iter().copied().collect();

        if modifiers.ctrl && modifiers.alt {
            let target = hit_test::hit_test(pointer, &selected, &world, image_rect);
            if let HitTarget::Object(id) = target {
                if let Some(start) = world.get_transform(id) {
                    let project = world.get_project();
                    let camera = resolve_object_camera(&world, id);
                    self.active = Some(ActiveDrag::CenterOffset {
                        object_id: id,
                        start,
                        viewport: ViewportState::new(
                            image_rect,
                            project.width,
                            project.height,
                            &camera,
                        ),
                    });
                    return;
                }
            }
            self.active = None;
            return;
        }

        let target = hit_test::hit_test(pointer, &selected, &world, image_rect);

        self.active = match target {
            HitTarget::Anchor(id, AnchorKind::Scale) => world
                .get_transform(id)
                .zip(projection::project_object_origin(&world, id, image_rect))
                .map(|(start, origin_screen)| {
                    let start_vec = pointer - origin_screen;
                    if modifiers.alt {
                        ActiveDrag::Rotate {
                            object_id: id,
                            start,
                            origin_screen,
                            start_angle_deg: start_vec.y.atan2(start_vec.x).to_degrees(),
                        }
                    } else {
                        ActiveDrag::Scale {
                            object_id: id,
                            start,
                            origin_screen,
                            start_vec,
                        }
                    }
                }),
            HitTarget::Anchor(id, AnchorKind::Rotate) => world
                .get_transform(id)
                .zip(projection::project_object_origin(&world, id, image_rect))
                .map(|(start, origin_screen)| {
                    let v = pointer - origin_screen;
                    ActiveDrag::Rotate {
                        object_id: id,
                        start,
                        origin_screen,
                        start_angle_deg: v.y.atan2(v.x).to_degrees(),
                    }
                }),
            HitTarget::Object(id) => {
                if !selected.contains(&id) {
                    world.select_id(id, true);
                }
                if modifiers.alt {
                    world
                        .get_transform(id)
                        .zip(projection::project_object_origin(&world, id, image_rect))
                        .map(|(start, origin_screen)| ActiveDrag::Scale {
                            object_id: id,
                            start,
                            origin_screen,
                            start_vec: pointer - origin_screen,
                        })
                } else {
                    let object_ids = if selected.contains(&id) {
                        selected
                    } else {
                        vec![id]
                    };
                    let start = object_ids
                        .iter()
                        .filter_map(|&oid| world.get_transform(oid).map(|t| (oid, t)))
                        .collect();
                    let project = world.get_project();
                    let camera = resolve_object_camera(&world, id);
                    Some(ActiveDrag::Move {
                        object_ids,
                        start,
                        viewport: ViewportState::new(
                            image_rect,
                            project.width,
                            project.height,
                            &camera,
                        ),
                    })
                }
            }
            HitTarget::None => None,
        };
    }

    fn apply_drag(&mut self, response: &egui::Response, state: &SharedAppState) {
        let Some(drag) = &self.active else {
            return;
        };
        let delta = response.drag_delta();
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();

        match drag {
            ActiveDrag::Move {
                object_ids,
                start,
                viewport,
            } => {
                if delta == egui::Vec2::ZERO {
                    return;
                }
                let (dx, dy) = viewport.screen_delta_to_scene(delta);
                for &id in object_ids {
                    if let Some((_, initial)) = start.iter().find(|(start_id, _)| *start_id == id) {
                        let mut t = *initial;
                        t.x += dx;
                        t.y += dy;
                        world.set_transform(id, t);
                    }
                }
            }
            ActiveDrag::Scale {
                object_id,
                start,
                origin_screen,
                start_vec,
            } => {
                let Some(pointer) = response.interact_pointer_pos() else {
                    return;
                };
                let current_vec = pointer - *origin_screen;
                let start_len = start_vec.length().max(1.0);
                let ratio = (current_vec.length() / start_len).max(0.01);
                let mut t = *start;
                t.scale_x = start.scale_x * ratio;
                t.scale_y = start.scale_y * ratio;
                world.set_transform(*object_id, t);
            }
            ActiveDrag::Rotate {
                object_id,
                start,
                origin_screen,
                start_angle_deg,
            } => {
                let Some(pointer) = response.interact_pointer_pos() else {
                    return;
                };
                let v = pointer - *origin_screen;
                let angle_deg = v.y.atan2(v.x).to_degrees();
                let mut t = *start;
                t.rot_z = start.rot_z + (angle_deg - start_angle_deg);
                world.set_transform(*object_id, t);
            }
            ActiveDrag::CenterOffset {
                object_id,
                start,
                viewport,
            } => {
                if delta == egui::Vec2::ZERO {
                    return;
                }
                let (dx, dy) = viewport.screen_delta_to_scene(delta);
                let object_id = *object_id;
                let mut t = *start;
                t.center_x += dx / UNIT_SIZE_PX;
                t.center_y += dy / UNIT_SIZE_PX;
                world.set_transform(object_id, t);
            }
            ActiveDrag::Camera {
                object_id,
                start,
                mode,
            } => {
                let drag_delta = response.drag_delta();
                let next = camera_after_drag(*start, drag_delta, *mode);
                set_camera(&mut world, *object_id, next);
            }
        }
    }

    fn commit_drag(&mut self, state: &SharedAppState) {
        let Some(drag) = self.active.take() else {
            return;
        };
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();

        if let ActiveDrag::Camera {
            object_id, start, ..
        } = &drag
        {
            if let Some(new) = world.get_camera_params(*object_id) {
                if new != *start {
                    world.push_history_command(Box::new(CameraChangeCommand {
                        object_id: *object_id,
                        old: *start,
                        new,
                    }));
                }
            }
            return;
        }

        let changes: Vec<(usize, Transform, Transform)> = match drag {
            ActiveDrag::Move { start, .. } => start
                .into_iter()
                .filter_map(|(id, old)| world.get_transform(id).map(|new| (id, old, new)))
                .filter(|(_, old, new)| !transforms_equal(old, new))
                .collect(),
            ActiveDrag::Scale {
                object_id, start, ..
            } => world
                .get_transform(object_id)
                .filter(|new| !transforms_equal(&start, new))
                .map(|new| vec![(object_id, start, new)])
                .unwrap_or_default(),
            ActiveDrag::Rotate {
                object_id, start, ..
            } => world
                .get_transform(object_id)
                .filter(|new| !transforms_equal(&start, new))
                .map(|new| vec![(object_id, start, new)])
                .unwrap_or_default(),
            ActiveDrag::CenterOffset {
                object_id, start, ..
            } => world
                .get_transform(object_id)
                .filter(|new| !transforms_equal(&start, new))
                .map(|new| vec![(object_id, start, new)])
                .unwrap_or_default(),
            ActiveDrag::Camera { .. } => unreachable!(),
        };

        if !changes.is_empty() {
            world.push_history_command(Box::new(TransformChangeCommand { changes }));
        }
    }

    fn handle_click(
        &mut self,
        response: &egui::Response,
        image_rect: egui::Rect,
        state: &SharedAppState,
    ) {
        let Some(pointer) = response.interact_pointer_pos() else {
            return;
        };
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let selected: Vec<usize> = world.selected_ids().iter().copied().collect();
        match hit_test::hit_test(pointer, &selected, &world, image_rect) {
            HitTarget::Object(id) => world.select_id(id, true),
            HitTarget::None => world.clear_selection(),
            HitTarget::Anchor(..) => {}
        }
    }
}

fn camera_after_drag(start: Camera, delta: egui::Vec2, mode: CameraDragMode) -> Camera {
    let mut camera = start;
    let dx = delta.x * 0.35;
    let dy = delta.y * 0.35;
    let offset = [
        start.pos_x - start.target_x,
        start.pos_y - start.target_y,
        start.pos_z - start.target_z,
    ];
    let radius = (offset[0] * offset[0] + offset[1] * offset[1] + offset[2] * offset[2])
        .sqrt()
        .max(1.0);

    match mode {
        CameraDragMode::Orbit => {
            let yaw = offset[0].atan2(offset[2]) + dx.to_radians();
            let pitch = (offset[1] / radius).asin() + dy.to_radians();
            let pitch = pitch.clamp(-1.5, 1.5);
            let horizontal = radius * pitch.cos();
            camera.pos_x = start.target_x + horizontal * yaw.sin();
            camera.pos_y = start.target_y + radius * pitch.sin();
            camera.pos_z = start.target_z + horizontal * yaw.cos();
        }
        CameraDragMode::Dolly => {
            let distance = (radius + dy * 4.0).max(1.0);
            let scale = distance / radius;
            camera.pos_x = start.target_x + offset[0] * scale;
            camera.pos_y = start.target_y + offset[1] * scale;
            camera.pos_z = start.target_z + offset[2] * scale;
        }
        CameraDragMode::Pan => {
            let forward = normalize3([
                start.target_x - start.pos_x,
                start.target_y - start.pos_y,
                start.target_z - start.pos_z,
            ]);
            let right = normalize3([forward[2], 0.0, -forward[0]]);
            let up = normalize3([
                right[1] * forward[2] - right[2] * forward[1],
                right[2] * forward[0] - right[0] * forward[2],
                right[0] * forward[1] - right[1] * forward[0],
            ]);
            let movement = [
                (right[0] * dx - up[0] * dy) * 2.0,
                (right[1] * dx - up[1] * dy) * 2.0,
                (right[2] * dx - up[2] * dy) * 2.0,
            ];
            camera.pos_x += movement[0];
            camera.pos_y += movement[1];
            camera.pos_z += movement[2];
            camera.target_x += movement[0];
            camera.target_y += movement[1];
            camera.target_z += movement[2];
        }
    }
    camera
}

fn normalize3(v: [f32; 3]) -> [f32; 3] {
    let length = (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt().max(1e-6);
    [v[0] / length, v[1] / length, v[2] / length]
}

fn set_camera(world: &mut crate::ecs::EcsWorld, object_id: usize, camera: Camera) {
    world.set_camera_params(object_id, camera);
}

fn transforms_equal(a: &Transform, b: &Transform) -> bool {
    a.x == b.x
        && a.y == b.y
        && a.scale_x == b.scale_x
        && a.scale_y == b.scale_y
        && a.rot_z == b.rot_z
        && a.center_x == b.center_x
        && a.center_y == b.center_y
        && a.center_z == b.center_z
}

struct TransformChangeCommand {
    changes: Vec<(usize, Transform, Transform)>,
}

struct CameraChangeCommand {
    object_id: usize,
    old: Camera,
    new: Camera,
}

impl HistoryCommand for CameraChangeCommand {
    fn description(&self) -> &str {
        "Move Camera"
    }

    fn apply(&mut self, world: &mut World) {
        set_camera_raw(world, self.object_id, self.new);
    }

    fn revert(&mut self, world: &mut World) {
        set_camera_raw(world, self.object_id, self.old);
    }
}

impl HistoryCommand for TransformChangeCommand {
    fn description(&self) -> &str {
        "Transform Object"
    }

    fn apply(&mut self, world: &mut World) {
        for (id, _old, new) in &self.changes {
            set_transform_raw(world, *id, *new);
        }
    }

    fn revert(&mut self, world: &mut World) {
        for (id, old, _new) in &self.changes {
            set_transform_raw(world, *id, *old);
        }
    }
}

fn set_transform_raw(world: &mut World, object_id: usize, t: Transform) {
    world.run(
        |ids: View<ObjectId>,
         mut transforms: ViewMut<Transform>,
         mut matrices: ViewMut<GlobalMatrix>| {
            for (entity, id) in ids.iter().with_id() {
                if id.0 == object_id {
                    if let Ok(mut slot) = (&mut transforms).get(entity) {
                        *slot = t;
                    }
                    if let Ok(mut matrix) = (&mut matrices).get(entity) {
                        *matrix = compute_global_matrix(&t);
                    }
                    break;
                }
            }
        },
    );
}

fn set_camera_raw(world: &mut World, object_id: usize, camera: Camera) {
    world.run(|ids: View<ObjectId>, mut cameras: ViewMut<Camera>| {
        for (entity, id) in ids.iter().with_id() {
            if id.0 == object_id {
                if let Ok(mut slot) = (&mut cameras).get(entity) {
                    *slot = camera;
                }
                break;
            }
        }
    });
}

