                            .clicked()
                        {
                            self.apply_frame(self.current_frame + 1, state);
                        }
                    });
                    tui.ui(|ui| {
                        let icon = if self.is_playing { "⏸" } else { "▶" };
                        if ui
                            .add_sized([28.0, 28.0], elegance::Button::new(icon))
                            .clicked()
                        {
                            self.is_playing = !self.is_playing;
                            let mixer = app_state::active_audio_mixer(state);
                            if self.is_playing {
                                self.playback_anchor = Some((Instant::now(), self.current_frame));
                                mixer.lock().unwrap().play();
                            } else {
                                self.playback_anchor = None;
                                mixer.lock().unwrap().pause();
                            }
                        }
                    });
                    tui.ui(|ui| {
                        if ui
                            .add_sized([28.0, 28.0], elegance::Button::new("⏮"))
                            .clicked()
                        {
                            self.apply_frame(self.current_frame - 1, state);
                        }
                    });
                    tui.ui(|ui| {
                        let digits = self.total_frames.max(1).to_string().len();
                        ui.monospace(format!(
                            "{:0width$} / {}",
                            self.current_frame,
                            self.total_frames,
                            width = digits
                        ));
                    });
                });
            });
        if open_export {
            self.open_export = true;
        }
        if open_system_settings {
            self.open_system_settings = true;
        }
        if open_project_settings {
            self.open_project_settings = true;
        }
        if open_keybindings {
            self.open_keybindings = true;
        }
        if open_timeline {
            self.open_timeline = true;
        }
        if open_properties {
            self.open_properties = true;
        }
    }

    fn tab_bar(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        let (names, active_index) = {
            let s = state.lock().unwrap();
            let names: Vec<String> = s
                .sessions
                .iter()
                .map(|sess| sess.meta.name.clone())
                .collect();
            (names, s.active)
        };
        let closable = names.len() > 1;

        let mut tabs = BrowserTabs::new("session-tabs").show_new_button(false);
        for (index, name) in names.iter().enumerate() {
            tabs = tabs.with_tab(BrowserTab::new(index.to_string(), name.clone()));
        }
        tabs.set_selected(active_index.to_string());

        tabs.show(ui);

        let mut switch_target: Option<usize> = None;
        let mut close_target: Option<usize> = None;
        for event in tabs.take_events() {
            match event {
                BrowserTabsEvent::Activated(id) => switch_target = id.parse().ok(),
                BrowserTabsEvent::Closed(id) => {
                    if closable {
                        close_target = id.parse().ok();
                    }
                }
                BrowserTabsEvent::NewRequested => {}
            }
        }

        if let Some(i) = switch_target {
            {
                let mut s = state.lock().unwrap();
                s.active = i;
            }
            self.playback_anchor = None;
            self.texture_id = None;
            self.sync_active_session(state);
        }
        if let Some(i) = close_target {
            dialogs.borrow_mut().request_close_session(state, i);
        }
    }

    fn switch_relative(&mut self, state: &SharedAppState, delta: i32) {
        {
            let mut s = state.lock().unwrap();
            let len = s.sessions.len() as i32;
            if len <= 1 {
                return;
            }
            s.active = (s.active as i32 + delta).rem_euclid(len) as usize;
        }
        self.playback_anchor = None;
        self.texture_id = None;
        self.sync_active_session(state);
    }

    fn handle_project_shortcuts(
        &mut self,
        ui: &egui::Ui,
        state: &SharedAppState,
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        let (ctrl, shift, alt, keys) = ui.input(|i| {
            (
                i.modifiers.ctrl,
                i.modifiers.shift,
                i.modifiers.alt,
                i.events
                    .iter()
                    .filter_map(|e| match e {
                        egui::Event::Key {
                            key, pressed: true, ..
                        } => Some(egui_key_name(*key)),
                        _ => None,
                    })
                    .collect::<Vec<_>>(),
            )
        });
        for key in keys {
            let Some(cmd) = shortcuts::resolve_active(Scope::Global, ctrl, shift, alt, &key) else {
                continue;
            };
            match cmd {
                CommandId::NextProjectTab => self.switch_relative(state, 1),
                CommandId::PrevProjectTab => self.switch_relative(state, -1),
                CommandId::CloseProjectTab => {
                    let active = state.lock().unwrap().active;
                    dialogs.borrow_mut().request_close_session(state, active);
                }
                _ => {}
            }
        }
    }

    fn confirm_close_dialog(
        &mut self,
        ctx: &egui::Context,
        state: &SharedAppState,
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        let Some(index) = dialogs.borrow().confirm_close_session else {
            return;
        };
        let mut save_and_close = false;
        let mut discard_and_close = false;
        let mut cancel = false;
        let mut modal_open = true;
        elegance::Modal::new("confirm_close_session", &mut modal_open)
            .heading(t!("未保存の変更"))
            .show(ctx, |ui| {
                ui.label(t!(
                    "保存されていない変更があります。閉じる前に保存しますか？"
                ));
                tui(ui, ui.id().with("confirm_close_session_actions"))
                    .style(row_style(8.0))
                    .show(|tui| {
                        tui.ui(|ui| {
                            if ui
                                .add(elegance::Button::new(t!("保存して閉じる")))
                                .clicked()
                            {
                                save_and_close = true;
                            }
                        });
                        tui.ui(|ui| {
                            if ui
                                .add(elegance::Button::new(t!("保存せず閉じる")).outline())
                                .clicked()
                            {
                                discard_and_close = true;
                            }
                        });
                        tui.ui(|ui| {
                            if ui
                                .add(elegance::Button::new(t!("キャンセル")).outline())
                                .clicked()
                            {
                                cancel = true;
                            }
                        });
                    });
            });
        if !modal_open {
            cancel = true;
        }
        if save_and_close {
            app_state::save_session(state, index);
            let _ = app_state::close_session(state, index);
        } else if discard_and_close {
            let _ = app_state::close_session(state, index);
        } else if !cancel {
            return;
        }
        dialogs.borrow_mut().confirm_close_session = None;
        if save_and_close || discard_and_close {
            self.playback_anchor = None;
            self.texture_id = None;
            self.sync_active_session(state);
        }
    }

    fn playback_controls(&mut self, ui: &mut egui::Ui, state: &SharedAppState) {
        let mut frame = self.current_frame;
        let slider = ui.add_sized(
            [ui.available_width(), 20.0],
            elegance::Slider::new(&mut frame, 0..=self.total_frames.max(1)).show_value(false),
        );
        if slider.changed() {
            self.apply_frame(frame, state);
            if self.is_playing {
                self.playback_anchor = Some((Instant::now(), self.current_frame));
            }
        }
    }

    pub fn sync_active_session(&mut self, state: &SharedAppState) {
        let world_holder = app_state::active_world(state);
        let world = world_holder.lock().unwrap();
        let proj = world.get_project();
        self.total_frames = world.total_frames();
        drop(world);
        app_state::active_audio_mixer(state).lock().unwrap().pause();
        self.current_frame = 0;
        self.is_playing = false;
        self.sync_resolution_fps(&proj);
        self.session_generation += 1;
    }

    pub fn show(
        &mut self,
        ui: &mut egui::Ui,
        egui_renderer: &mut EguiRenderer,
        state: &SharedAppState,
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        self.handle_project_shortcuts(ui, state, dialogs);
        self.menu_bar(ui, state);
        self.tab_bar(ui, state, dialogs);
        self.confirm_close_dialog(&ui.ctx().clone(), state, dialogs);

        self.render_frame(egui_renderer, state);

        egui::Panel::bottom("preview_playback_bar")
            .frame(egui::Frame::default().inner_margin(egui::Margin::symmetric(6, 4)))
            .show(ui, |ui| {
                self.playback_controls(ui, state);
            });

        egui::CentralPanel::default()
            .frame(egui::Frame::default())
            .show(ui, |ui| {
                if let Some(texture_id) = self.texture_id {
                    let (w, h) = self.texture_dims;
                    let aspect = w as f32 / h.max(1) as f32;
                    let avail = ui.available_size();
                    let size = if avail.x / avail.y > aspect {
                        egui::vec2(avail.y * aspect, avail.y)
                    } else {
                        egui::vec2(avail.x, avail.x / aspect)
                    };
                    let response = ui.centered_and_justified(|ui| {
                        ui.add(
                            egui::Image::new((texture_id, size))
                                .fit_to_exact_size(size)
                                .sense(egui::Sense::click_and_drag()),
                        )
                    });

                    let image_rect = response.inner.rect;
                    let painter = ui.painter_at(image_rect);
                    let (res_w, res_h, fps, cur_frame, selected) = {
                        let world_holder = app_state::active_world(state);
                        let world = world_holder.lock().unwrap();
                        let proj = world.get_project();
                        (
                            proj.width,
                            proj.height,
                            proj.fps,
                            world.current_frame(),
                            world.selected_ids().iter().copied().collect::<Vec<_>>(),
                        )
                    };

                    self.interaction.handle(&response.inner, image_rect, state);

                    {
                        let world_holder = app_state::active_world(state);
                        let world = world_holder.lock().unwrap();
                        gizmo::draw(&painter, &world, &selected, image_rect);
                    }

                    let mut overlay_ctx = neoutl_sdk::extension::PreviewOverlayContext {
                        painter: &painter,
                        viewport_rect: image_rect,
                        scene_resolution: [res_w, res_h],
                        current_frame: cur_frame,
                        fps,
                        is_playing: self.is_playing,
                        selected_object_ids: &selected,
                    };
                    crate::extensions::global_extension_manager()
                        .lock()
                        .unwrap()
                        .draw_preview_overlay(&mut overlay_ctx, Some(state));
                }
            });

        if self.open_camera_view {
            let world_holder = app_state::active_world(state);
            let world = world_holder.lock().unwrap();
            camera_view::show(
                ui.ctx(),
                &mut self.open_camera_view,
                &mut self.camera_view_mode,
                self.texture_id,
                &world,
                &mut self.interaction,
                state,
            );
        }

        if self.is_playing {
            self.advance_playback(state);
            ui.ctx()
                .request_repaint_after(std::time::Duration::from_millis(PLAYBACK_TICK_MS));
        }
    }
}

//! Transform の原点 (ローカル座標 0,0,0) を、レンダラが実際に使用する
//! View×Projection (`compute_mvp`) と同じ式でスクリーン座標へ投影する。
//! 対応範囲: グローバルカメラユニーク1つのみ。レイヤー別カメラ・グループ内カメラ等、
//! `resolve_camera` が解決するカメラ差し替えは対象外
//! (差し替えの解決にはカーテンチェーン全体の再構築が必要なため)。
//! 対応範囲外: オブジェクトの外形（描画サイズ）。原点1点のみを扱う。

use crate::ecs::EcsWorld;
use crate::ecs::transform::{Camera, Projection, compute_global_matrix, compute_mvp};
use neoutl_object_api::UNIT_SIZE_PX;
use shipyard::UniqueView;

fn transform_point(m: &[f32; 16], p: [f32; 4]) -> [f32; 4] {
    let mut out = [0.0f32; 4];
    let first = m.iter().take(4);
    let second = m.iter().skip(4).take(4);
    let third = m.iter().skip(8).take(4);
    let fourth = m.iter().skip(12).take(4);
    for (slot, (((m0, m1), m2), m3)) in out.iter_mut().zip(first.zip(second).zip(third).zip(fourth))
    {
        *slot = m0.mul_add(p[0], m1.mul_add(p[1], m2.mul_add(p[2], m3 * p[3])));
    }
    out
}

fn resolution_to_f32(value: u32) -> f32 {
    f32::from(u16::try_from(value).unwrap_or(u16::MAX))
}

pub fn project_object_origin(
    world: &EcsWorld,
    object_id: usize,
    image_rect: egui::Rect,
) -> Option<egui::Pos2> {
    let transform = world.get_transform(object_id)?;
    let global = compute_global_matrix(&transform);
    let cam: Camera = world.world.run(|cam: UniqueView<Camera>| *cam);
    let proj = world.get_project();
    let proj_width = resolution_to_f32(proj.width.max(1));
    let proj_height = resolution_to_f32(proj.height.max(1));

    let mvp = compute_mvp(
        &global,
        &cam,
        proj_width,
        proj_height,
        Projection::Perspective {
            fov_deg: cam.fov_deg,
        },
    );
    let clip = transform_point(&mvp, [0.0, 0.0, 0.0, 1.0]);
    if clip[3].abs() < 1e-6 {
        return None;
    }
    let ndc_x = clip[0] / clip[3];
    let ndc_y = clip[1] / clip[3];
    let px = (ndc_x * 0.5 + 0.5) * proj_width;
    let py = (1.0 - (ndc_y * 0.5 + 0.5)) * proj_height;

    let scale = image_rect.width() / proj_width;
    Some(egui::pos2(
        image_rect.left() + px * scale,
        image_rect.top() + py * scale,
    ))
}

/// オブジェクトのソースサイズに基づく4隅をスクリーン座標へ投影する。
/// `project_object_origin` と同じ MVP (`compute_mvp`) を用いるため、
/// 原点投影・4隅投影は常に同一のカメラ・射影設定と整合する。
/// `source_w`/`source_h` は `SourceSizeCache` から取得したピクセル単位のサイズ。
pub fn project_object_corners(
    world: &EcsWorld,
    object_id: usize,
    source_w: f32,
    source_h: f32,
    image_rect: egui::Rect,
) -> Option<[egui::Pos2; 4]> {
    let transform = world.get_transform(object_id)?;
    let global = compute_global_matrix(&transform);
    let cam: Camera = world.world.run(|cam: UniqueView<Camera>| *cam);
    let proj = world.get_project();
    let proj_width = resolution_to_f32(proj.width.max(1));
    let proj_height = resolution_to_f32(proj.height.max(1));

    let mvp = compute_mvp(
        &global,
        &cam,
        proj_width,
        proj_height,
        Projection::Perspective {
            fov_deg: cam.fov_deg,
        },
    );

    let hw = source_w * 0.5 / UNIT_SIZE_PX;
    let hh = source_h * 0.5 / UNIT_SIZE_PX;
    let corners_local = [
        [-hw, hh, 0.0],
        [hw, hh, 0.0],
        [hw, -hh, 0.0],
        [-hw, -hh, 0.0],
    ];

    let mut result = [egui::Pos2::ZERO; 4];
    let scale = image_rect.width() / proj_width;
    for (slot, &[lx, ly, lz]) in result.iter_mut().zip(corners_local.iter()) {
        let clip = transform_point(&mvp, [lx, ly, lz, 1.0]);
        if clip[3].abs() < 1e-6 {
            return None;
        }
        let ndc_x = clip[0] / clip[3];
        let ndc_y = clip[1] / clip[3];
        let px = (ndc_x * 0.5 + 0.5) * proj_width;
        let py = (1.0 - (ndc_y * 0.5 + 0.5)) * proj_height;
        *slot = egui::pos2(
            image_rect.left() + px * scale,
            image_rect.top() + py * scale,
        );
    }
    Some(result)
}

//! スクリーン座標のデルタをシーン座標 (z=0平面) のデルタへ変換する。
//! カメラのView-Projection逆行列を用いてレイキャスト (アンプロジェクト) するため、
//! `Camera::for_resolution` の既定カメラに限らず、任意のカメラ設定 (位置・tilt・fov) で正確に成立する。
//! 逆行列が求まらない場合 (射影が特異になる極端な near/far/fov 設定等) は、
//! 既定カメラを前提とした等倍アフィン変換にフォールバックする。
//! ドラッグ開始時に対象オブジェクトのカーテンチェーンから解決したカメラを受け取り、
//! そのカメラに対してスクリーン座標をシーン座標へ変換する。

use crate::ecs::transform::{
    Camera, compute_perspective_matrix, compute_view_matrix, mat4_inverse, mat4_mul,
};
use std::ops::Add;

fn transform_point(m: &[f32; 16], p: [f32; 4]) -> [f32; 4] {
    let mut out = [0.0f32; 4];
    let first = m.iter().take(4);
    let second = m.iter().skip(4).take(4);
    let third = m.iter().skip(8).take(4);
    let fourth = m.iter().skip(12).take(4);
    for (slot, (((m0, m1), m2), m3)) in out.iter_mut().zip(first.zip(second).zip(third).zip(fourth))
    {
        *slot = m0.mul_add(p[0], m1.mul_add(p[1], m2.mul_add(p[2], m3 * p[3])));
    }
    out
}

fn resolution_to_f32(value: u32) -> f32 {
    f32::from(u16::try_from(value).unwrap_or(u16::MAX))
}

#[derive(Clone, Copy, Debug)]
pub struct ViewportState {
    image_rect: egui::Rect,
    scene_width: f32,
    scene_height: f32,
    inv_vp: Option<[f32; 16]>,
}

impl ViewportState {
    pub fn new(
        image_rect: egui::Rect,
        scene_width: u32,
        scene_height: u32,
        camera: &Camera,
    ) -> Self {
        let sw = resolution_to_f32(scene_width.max(1));
        let sh = resolution_to_f32(scene_height.max(1));
        let view = compute_view_matrix(camera);
        let aspect = sw / sh;
        let proj = compute_perspective_matrix(camera.fov_deg, aspect, camera.near, camera.far);
        let vp = mat4_mul(&proj, &view);
        Self {
            image_rect,
            scene_width: sw,
            scene_height: sh,
            inv_vp: mat4_inverse(&vp),
        }
    }

    fn scale(&self) -> f32 {
        self.scene_width / self.image_rect.width().max(1.0)
    }

    /// スクリーン座標を z=0 平面上のシーン座標へアンプロジェクトする。
    /// NDC上の同一(x,y)についてnear/far2点をワールド空間へ逆投影し、
    /// z=0平面とのレイ交点を求める (レイキャスト)。
    fn unproject_to_z0(&self, screen_pos: egui::Pos2) -> Option<(f32, f32)> {
        let inv_vp = self.inv_vp?;
        let scale = self.scale();
        let px = (screen_pos.x - self.image_rect.left()) * scale;
        let py = (screen_pos.y - self.image_rect.top()) * scale;
        let ndc_x = (px / self.scene_width) * 2.0 - 1.0;
        let ndc_y = 1.0 - (py / self.scene_height) * 2.0;

        let near_clip = transform_point(&inv_vp, [ndc_x, ndc_y, -1.0, 1.0]);
        let far_clip = transform_point(&inv_vp, [ndc_x, ndc_y, 1.0, 1.0]);
        if near_clip[3].abs() < 1e-6 || far_clip[3].abs() < 1e-6 {
            return None;
        }
        let near = [
            near_clip[0] / near_clip[3],
            near_clip[1] / near_clip[3],
            near_clip[2] / near_clip[3],
        ];
        let far = [
            far_clip[0] / far_clip[3],
            far_clip[1] / far_clip[3],
            far_clip[2] / far_clip[3],
        ];
        let dz = far[2] - near[2];
        if dz.abs() < 1e-6 {
            return None;
        }
        let t = -near[2] / dz;
        Some((
            near[0] + t * (far[0] - near[0]),
            near[1] + t * (far[1] - near[1]),
        ))
    }

    /// スクリーン上の移動量をシーン座標系の移動量へ変換する。
    /// スクリーンYは下方向が正、シーンYは上方向が正のため符号を反転する
    /// (フォールバック経路のみ。逆行列経路は行列自体がこの反転を含む)。
    pub fn screen_delta_to_scene(&self, delta: egui::Vec2) -> (f32, f32) {
        let center = self.image_rect.center();
        if let (Some((x0, y0)), Some((x1, y1))) = (
            self.unproject_to_z0(center),
            self.unproject_to_z0(egui::pos2(center.x.add(delta.x), center.y.add(delta.y))),
        ) {
            return (x1 - x0, y1 - y0);
        }
        let scale = self.scale();
        (delta.x * scale, -delta.y * scale)
    }
}

use crate::app::state::{self as app_state, SharedAppState};
use crate::project;
use crate::ui::system_settings::fields::name_field;
use crate::ui::ui_ext::{UiExt, row_end_style, row_style};
use egui::{Context, Ui};
use egui_taffy::{TuiBuilderLogic, tui};

pub struct ProjectSettingsWindow {
    pub open: bool,
    project_name: String,
    fps: u32,
    width: u32,
    height: u32,
    audio_sample_rate: u32,
    audio_channels: u32,
}

impl ProjectSettingsWindow {
    pub fn new() -> Self {
        Self {
            open: false,
            project_name: "Project".into(),
            fps: 30,
            width: 1920,
            height: 1080,
            audio_sample_rate: 48000,
            audio_channels: 2,
        }
    }

    pub fn open(&mut self, state: &SharedAppState) {
        let world_holder = app_state::active_world(state);
        let world = world_holder.lock().unwrap();
        let project = world.get_project();
        drop(world);

        self.project_name = project.name;
        self.fps = project.fps;
        self.width = project.width;
        self.height = project.height;
        self.audio_sample_rate = project.audio_sample_rate;
        self.audio_channels = project.audio_channels;
        self.open = true;
    }

    fn confirm(&mut self, state: &SharedAppState) {
        let name = self.project_name.clone();
        let sample_rate = self.audio_sample_rate.max(1);
        let channels = self.audio_channels.clamp(1, 8);

        let world_holder = app_state::active_world(state);
        app_state::snapshot_before_edit(state);
        let mut world = world_holder.lock().unwrap();
        let dir = world
            .get_project()
            .dir
            .unwrap_or_else(project::projects_dir);
        world.set_project_meta(name.clone(), dir);
        world.set_fps(self.fps);
        world.set_resolution(self.width, self.height);
        world.set_audio_format(sample_rate, channels);
        let _ = project::save_from_world(&world);
        drop(world);
        app_state::active_audio_mixer(state)
            .lock()
            .unwrap()
            .set_sample_rate(sample_rate);

        {
            let mut s = state.lock().unwrap();
            let active = s.active;
            s.sessions[active].meta.name = name;
        }

        self.open = false;
    }

    pub fn show(&mut self, _ctx: &Context, ui: &mut Ui, state: &SharedAppState) -> bool {
        if !self.open {
            return false;
        }
        let mut confirmed = false;
        let mut close_requested = false;

        egui::Panel::bottom("project_setting_footer").show(ui, |ui| {
            ui.footer_bar(|ui| {
                let row_width = ui.available_width();
