                            }
                        });
                        tui.ui(|ui| {
                            if ui.button(t!("OK")).clicked() {
                                confirmed = true;
                            }
                        });
                    });
            });
        });

        egui::CentralPanel::default().show(ui, |ui| {
            ui.page_content(|ui| {
                ui.section(t!("基本設定"), |ui| {
                    egui::Grid::new("project_settings_basic")
                        .num_columns(2)
                        .show(ui, |ui| {
                            name_field(ui, "プロジェクト名:", &mut self.project_name);
                        });
                });

                ui.section(t!("映像フォーマット"), |ui| {
                    tui(ui, ui.id().with("project_settings_video_format"))
                        .style(row_style(8.0))
                        .show(|tui| {
                            tui.ui(|ui| {
                                ui.add(
                                    egui::DragValue::new(&mut self.fps)
                                        .range(1..=240)
                                        .suffix(" fps"),
                                );
                            });
                            tui.ui(|ui| {
                                ui.add(
                                    egui::DragValue::new(&mut self.width)
                                        .range(16..=7680)
                                        .suffix(" px"),
                                );
                            });
                            tui.ui(|ui| {
                                ui.add(
                                    egui::DragValue::new(&mut self.height)
                                        .range(16..=7680)
                                        .suffix(" px"),
                                );
                            });
                        });
                });

                ui.section(t!("音声フォーマット"), |ui| {
                    tui(ui, ui.id().with("project_settings_audio_format"))
                        .style(row_style(8.0))
                        .show(|tui| {
                            tui.ui(|ui| {
                                ui.add(
                                    egui::DragValue::new(&mut self.audio_channels)
                                        .range(1..=8)
                                        .suffix(" ch"),
                                );
                            });
                            tui.ui(|ui| {
                                ui.add(
                                    egui::DragValue::new(&mut self.audio_sample_rate)
                                        .range(8000..=192_000)
                                        .suffix(" Hz"),
                                );
                            });
                        });
                });
            });
        });

        if confirmed {
            self.confirm(state);
            return true;
        }
        self.open = !close_requested;
        false
    }
}

use egui::{Pos2, Rect, Vec2, pos2};
use neoutl_easing_standard::{CurveKind, EasingPayload, ease};

pub struct CurveView {
    origin: Pos2,
    scale: f32,
}

impl CurveView {
    pub const PAD: f32 = 28.0;

    pub fn fit(rect: Rect, y_lo: f32, y_hi: f32, zoom: f32, pan: Vec2) -> Self {
        let inner = rect.shrink(Self::PAD);
        let scale = inner.width().min(inner.height() / (y_hi - y_lo)) * zoom;
        Self {
            origin: pos2(
                inner.center().x - 0.5 * scale + pan.x,
                inner.center().y + 0.5 * (y_lo + y_hi) * scale + pan.y,
            ),
            scale,
        }
    }

    pub fn to_screen(&self, x: f32, y: f32) -> Pos2 {
        pos2(
            self.origin.x + x * self.scale,
            self.origin.y - y * self.scale,
        )
    }

    pub fn to_data(&self, p: Pos2) -> (f32, f32) {
        (
            (p.x - self.origin.x) / self.scale,
            (self.origin.y - p.y) / self.scale,
        )
    }

    pub fn scale(&self) -> f32 {
        self.scale
    }
}

pub fn y_range(samples: &[[f32; 2]], handle_ys: impl Iterator<Item = f32>) -> (f32, f32) {
    let (mut lo, mut hi) = (0.0_f32, 1.0_f32);
    for y in samples.iter().map(|p| p[1]).chain(handle_ys) {
        if y.is_finite() {
            lo = lo.min(y);
            hi = hi.max(y);
        }
    }
    ((lo - 0.12).max(-4.0), (hi + 0.12).min(5.0))
}

pub fn sample(payload: &EasingPayload, resolution: usize) -> Vec<[f32; 2]> {
    if payload.modifiers.is_empty()
        && let CurveKind::Bezier {
            handle_left: l,
            handle_right: r,
        } = &payload.kind
    {
        let bez = kurbo::CubicBez::new(
            (0.0, 0.0),
            (l[0] as f64, l[1] as f64),
            (r[0] as f64, r[1] as f64),
            (1.0, 1.0),
        );
        return (0..=resolution)
            .map(|i| {
                let p = kurbo::ParamCurve::eval(&bez, i as f64 / resolution as f64);
                [p.x as f32, p.y as f32]
            })
            .collect();
    }
    (0..=resolution)
        .map(|i| {
            let t = i as f32 / resolution as f32;
            [t, ease(payload, t)]
        })
        .collect()
}

pub fn interpolate(samples: &[[f32; 2]], t: f32) -> f32 {
    let n = samples.len();
    if n < 2 {
        return t;
    }
    let f = t.clamp(0.0, 1.0) * (n - 1) as f32;
    let i = (f as usize).min(n - 2);
    let u = f - i as f32;
    samples[i][1] + (samples[i + 1][1] - samples[i][1]) * u
}

pub fn fmt(v: f32) -> String {
    let s = format!("{v:.3}");
    s.trim_end_matches('0').trim_end_matches('.').to_owned()
}

pub fn grid_step(scale: f32) -> f32 {
    [0.05, 0.1, 0.25, 0.5, 1.0, 2.0]
        .into_iter()
        .find(|s| s * scale >= 32.0)
        .unwrap_or(2.0)
}

use neoutl_easing_standard::{CurveKind, CurveSegment};

pub const SNAP_STEP: f32 = 0.25;
const AMP_EDGE_INSET: f32 = 0.08;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum PointRef {
    BezierLeft,
    BezierRight,
    BounceHandle,
    ElasticAmp,
    ElasticFreqDecay,
    NormalBoundary(usize),
}

pub struct ControlPoint {
    pub point: PointRef,
    pub pos: [f32; 2],
    pub label: String,
}

pub fn control_points(kind: &CurveKind) -> Vec<ControlPoint> {
    use neoutl_easing_standard as es;
    let cp = |point, pos: [f32; 2], label: String| ControlPoint { point, pos, label };
    match kind {
        CurveKind::Bezier {
            handle_left: l,
            handle_right: r,
        } => vec![
            cp(
                PointRef::BezierLeft,
                *l,
                format!("P1 ({:.2}, {:.2})", l[0], l[1]),
            ),
            cp(
                PointRef::BezierRight,
                *r,
                format!("P2 ({:.2}, {:.2})", r[0], r[1]),
            ),
        ],
        CurveKind::Bounce {
            cor,
            period,
            reversed,
        } => {
            let (x, y) = es::bounce_handle(*cor, *period, *reversed);
            vec![cp(
                PointRef::BounceHandle,
                [x, y],
                format!("反発 {cor:.2} / 周期 {period:.2}"),
            )]
        }
        CurveKind::Elastic {
            amplitude,
            frequency,
            decay,
            reversed,
        } => {
            let amp_x = if *reversed {
                1.0 - AMP_EDGE_INSET
            } else {
                AMP_EDGE_INSET
            };
            let (fx, fy) = es::elastic_freq_decay_handle(*frequency, *decay, *reversed);
            vec![
                cp(
                    PointRef::ElasticAmp,
                    [amp_x, es::elastic_amp_handle_y(*amplitude)],
                    format!("振幅 {amplitude:.2}"),
                ),
                cp(
                    PointRef::ElasticFreqDecay,
                    [fx, fy],
                    format!("周波数 {frequency:.2} / 減衰 {decay:.2}"),
                ),
            ]
        }
        CurveKind::Normal { segments } => segments
            .iter()
            .enumerate()
            .take(segments.len().saturating_sub(1))
            .map(|(i, s)| {
                cp(
                    PointRef::NormalBoundary(i),
                    s.anchor_end,
                    format!(
                        "頂点{} ({:.2}, {:.2})",
                        i + 1,
                        s.anchor_end[0],
                        s.anchor_end[1]
                    ),
                )
            })
            .collect(),
        CurveKind::Linear | CurveKind::Standard { .. } | CurveKind::Script { .. } => Vec::new(),
    }
}

fn snap(v: f32, on: bool) -> f32 {
    if on {
        (v / SNAP_STEP).round() * SNAP_STEP
    } else {
        v
    }
}

pub fn apply_drag(kind: &mut CurveKind, point: PointRef, data: (f32, f32), mods: egui::Modifiers) {
    use neoutl_easing_standard as es;
    let (px, py) = (snap(data.0, mods.shift), snap(data.1, mods.shift));
    match (kind, point) {
        (
            CurveKind::Bezier {
                handle_left: l,
                handle_right: r,
            },
            p @ (PointRef::BezierLeft | PointRef::BezierRight),
        ) => {
            let (moved, other) = if p == PointRef::BezierLeft {
                (l, r)
            } else {
                (r, l)
            };
            *moved = [px.clamp(0.0, 1.0), py.clamp(-2.0, 3.0)];
            if mods.command {
                *other = [1.0 - moved[0], 1.0 - moved[1]];
            }
        }
        (
            CurveKind::Bounce {
                cor,
                period,
                reversed,
            },
            PointRef::BounceHandle,
        ) => {
            (*cor, *period) = es::bounce_set_handle(px, py, *reversed);
        }
        (CurveKind::Elastic { amplitude, .. }, PointRef::ElasticAmp) => {
            *amplitude = es::elastic_set_amp(py);
        }
        (
            CurveKind::Elastic {
                frequency,
                decay,
                reversed,
                ..
            },
            PointRef::ElasticFreqDecay,
        ) => (*frequency, *decay) = es::elastic_set_freq_decay(px, py, *reversed),
        (CurveKind::Normal { segments }, PointRef::NormalBoundary(i)) => {
            set_boundary(segments, i, px.clamp(0.0, 1.0), py.clamp(-2.0, 3.0))
        }
        _ => {}
    }
}

pub fn set_boundary(segments: &mut [CurveSegment], i: usize, x: f32, y: f32) {
    neoutl_easing_standard::drag_anchor_x(segments, i + 1, x);
    if i + 1 < segments.len() {
        segments[i].anchor_end[1] = y;
        segments[i + 1].anchor_start[1] = y;
    }
}

pub fn nearest(
    points: &[ControlPoint],
    to_screen: impl Fn([f32; 2]) -> egui::Pos2,
    at: egui::Pos2,
    radius: f32,
) -> Option<usize> {
    points
        .iter()
        .map(|p| to_screen(p.pos).distance(at))
        .enumerate()
        .filter(|(_, d)| *d <= radius)
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .map(|(i, _)| i)
}

pub fn reset_label(kind: &CurveKind) -> &'static str {
    if matches!(kind, CurveKind::Normal { .. }) {
        "頂点を結合 (削除)"
    } else {
        "ハンドルを初期値へ"
    }
}

pub fn reset_point(kind: &mut CurveKind, point: PointRef) -> bool {
    match (kind, point) {
        (CurveKind::Bezier { handle_left, .. }, PointRef::BezierLeft) => *handle_left = [0.42, 0.0],
        (CurveKind::Bezier { handle_right, .. }, PointRef::BezierRight) => {
            *handle_right = [0.58, 1.0]
        }
        (CurveKind::Bounce { cor, period, .. }, PointRef::BounceHandle) => {
            (*cor, *period) = (0.6, 0.5)
        }
        (CurveKind::Elastic { amplitude, .. }, PointRef::ElasticAmp) => *amplitude = 1.0,
        (
            CurveKind::Elastic {
                frequency, decay, ..
            },
            PointRef::ElasticFreqDecay,
        ) => (*frequency, *decay) = (5.0, 6.0),
        (CurveKind::Normal { segments }, PointRef::NormalBoundary(i)) => {
            if segments.len() <= 1 || i + 1 >= segments.len() {
                return false;
            }
            segments[i].anchor_end = segments[i + 1].anchor_end;
            segments.remove(i + 1);
        }
        _ => return false,
    }
    true
}

