    icon: impl Into<&'static str>,
    text: &str,
    hint: &str,
) -> egui::Response {
    let icon: &str = icon.into();
    let label = if text.is_empty() {
        icon.to_owned()
    } else {
        format!("{icon} {text}")
    };
    ui.add(egui::Button::new(label).min_size(vec2(24.0, 24.0)))
        .on_hover_text(hint)
}

pub fn show(ctx: &egui::Context, ui: &mut egui::Ui, world: &mut EcsWorld) -> bool {
    let Some(mut st) = ACTIVE.lock().unwrap().take() else {
        return false;
    };
    let keep = run(ctx, ui, world, &mut st);
    if keep {
        *ACTIVE.lock().unwrap() = Some(st);
    }
    true
}

fn finish(world: &mut EcsWorld, st: &mut EditorState) {
    if let Some(before) = st.pending_before.take() {
        let after = track::read(world, &st.target);
        track::push_history(world, &st.target, before, after);
    }
}

fn commit(world: &mut EcsWorld, st: &mut EditorState, edit: impl FnOnce(&mut Vec<Keyframe>)) {
    finish(world, st);
    let before = track::read(world, &st.target);
    let mut after = before.clone();
    edit(&mut after);
    track::write(world, &st.target, &after);
    track::push_history(world, &st.target, before, after);
}

fn run(ctx: &egui::Context, ui: &mut egui::Ui, world: &mut EcsWorld, st: &mut EditorState) -> bool {
    ui.style_mut().interaction.tooltip_delay = 0.0;
    let now = ui.input(|i| i.time);
    let track = track::read(world, &st.target);
    let playhead = world.current_frame();
    let mut actions = Vec::new();

    if track.is_empty() {
        let keys = track::start_only(world, &st.target);
        commit(world, st, |k| *k = keys);
        return true;
    }

    if track.len() < 2 {
        let (_, clip_end) = track::clip_bounds(world, &st.target);
        match track.first() {
            None => {}
            Some(first) => {
                ui.label(format!(
                    "始点 f{} のみです。終点は任意で、追加すると区間が生まれます。",
                    first.frame
                ));
                let at = clip_end;
                if ui
                    .add_enabled(
                        at > first.frame,
                        egui::Button::new(format!(
                            "{} 終点を追加 (f{at})",
                            <&str>::from(icons::ICON_ADD)
                        )),
                    )
                    .on_hover_text("クリップ終端に終点を追加")
                    .on_disabled_hover_text("始点がクリップ終端以降のため追加できません")
                    .clicked()
                {
                    actions.push(Action::AddEnd);
                }
            }
        }
        if ui.button("閉じる").clicked() {
            actions.push(Action::Close);
        }
        return apply_actions(
            world,
            st,
            &track,
            0,
            &EasingPayload::linear(),
            now,
            actions,
            ctx,
        );
    }

    if st.follow_playhead && playhead != st.last_playhead {
        st.last_playhead = playhead;
        let last = track.len() - 1;
        if (track[0].frame..=track[last].frame).contains(&playhead) {
            let i = track
                .iter()
                .rposition(|k| k.frame <= playhead)
                .unwrap_or(0)
                .min(last - 1);
            st.selected_frame = Some(track[i].frame);
        }
    }
    let sel = st
        .selected_frame
        .and_then(|fr| track.iter().position(|k| k.frame <= fr && fr == k.frame))
        .filter(|i| i + 1 < track.len())
        .unwrap_or(0);
    if st.selected_frame != Some(track[sel].frame) {
        st.selected_frame = Some(track[sel].frame);
        st.selected_point = None;
    }

    let mut payload = parse_payload(&track[sel].engine_payload);
    if matches!(payload.kind, CurveKind::Linear) {
        payload.kind = CurveKind::Bezier {
            handle_left: [1.0 / 3.0, 1.0 / 3.0],
            handle_right: [2.0 / 3.0, 2.0 / 3.0],
        };
    }
    if let (Some((frame, text)), CurveKind::Script { source }) = (&st.script_buf, &mut payload.kind)
        && *frame == track[sel].frame
    {
        source.clone_from(text);
    }
    let stored_script = match parse_payload(&track[sel].engine_payload).kind {
        CurveKind::Script { source } => Some(source),
        _ => None,
    };

    let mut f = Frame {
        st,
        ctx: ctx.clone(),
        now,
        track,
        sel,
        payload,
        playhead,
        can_undo: world.can_undo(),
        can_redo: world.can_redo(),
        edit: Edit::default(),
        actions,
        out: presets::Out::default(),
    };

    if ui.ui_contains_pointer() && !ctx.egui_wants_keyboard_input() {
        let pasted = ui.input(|i| {
            i.events.iter().find_map(|e| match e {
                egui::Event::Paste(s) => Some(s.clone()),
                _ => None,
            })
        });
        if let Some(text) = pasted {
            match serde_json::from_str::<EasingPayload>(&text) {
                Ok(p) => {
                    f.payload = p;
                    f.st.script_buf = None;
                    f.edit.changed = true;
                    f.st.notify(now, "貼り付けました");
                }
                Err(_) => {
                    f.st.notify(now, "貼り付け失敗: イージングのJSONではありません")
                }
            }
        }
    }

    let width = finite_width(ui);
    egui::ScrollArea::vertical()
        .id_salt("easing_editor_scroll")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            ui.set_max_width(width);
            toolbar(&mut f, ui);
            ui.separator();
            if width >= 640.0 {
                ui.columns(2, |cols| {
                    left(&mut f, &mut cols[0]);
                    right(&mut f, &mut cols[1]);
                });
            } else {
                left(&mut f, ui);
                ui.separator();
                right(&mut f, ui);
            }
        });

    if let Some(kind) = f.out.apply.take() {
        f.set_kind(kind);
    }
    f.st.hover_preview = f.out.hover.take();
    if let Some(text) = f.out.notice.take() {
        f.st.notify(now, text);
    }
    if f.st.hover_preview.is_some() || f.st.preview_start.is_some() {
        ctx.request_repaint();
    }

    let script_dirty = match (&f.payload.kind, &stored_script) {
        (CurveKind::Script { source }, Some(stored)) => source != stored,
        _ => false,
    };
    let mut script_pending = false;
    if script_dirty && f.st.script_error.is_none() {
        if now >= f.st.script_hold {
            f.edit.changed = true;
        } else {
            script_pending = true;
            ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
    }
    if script_dirty && f.st.script_error.is_some() {
        f.edit.changed = f.edit.changed && !matches!(f.payload.kind, CurveKind::Script { .. });
    }

    let esc_close = ui.ui_contains_pointer()
        && !ctx.egui_wants_keyboard_input()
        && ui.input_mut(|i| i.consume_key(Modifiers::NONE, Key::Escape));
    if esc_close {
        f.actions.push(Action::Close);
    }

    let Frame {
        st,
        track,
        sel,
        mut payload,
        edit,
        actions,
        ..
    } = f;
    if sel == 0 {
        payload.apply_mode = ApplyMode::Normal;
    }
    if edit.changed {
        if st.pending_before.is_none() {
            st.pending_before = Some(track.clone());
        }
        let mut keys = track.clone();
        keys[sel].engine_payload = encode_payload(&payload);
        keys[sel].edit_seq = next_edit_seq();
        track::write(world, &st.target, &keys);
    }
    if !edit.live && st.dragging.is_none() && !script_pending {
        finish(world, st);
    }
    apply_actions(world, st, &track, sel, &payload, now, actions, ctx)
}

#[allow(clippy::too_many_arguments)]
fn apply_actions(
    world: &mut EcsWorld,
    st: &mut EditorState,
    track: &[Keyframe],
    sel: usize,
    payload: &EasingPayload,
    now: f64,
    actions: Vec<Action>,
    ctx: &egui::Context,
) -> bool {
    let mut keep = true;
    for action in actions {
        match action {
            Action::Close => keep = false,
            Action::Undo => {
                finish(world, st);
                st.script_buf = None;
                world.undo();
            }
            Action::Redo => {
                finish(world, st);
                st.script_buf = None;
                world.redo();
            }
            Action::Select(i) => {
                if let Some(k) = track.get(i) {
                    st.selected_frame = Some(k.frame);
                    st.selected_point = None;
                    st.script_buf = None;
                }
            }
            Action::Pin => {
                st.reference = Some(Reference {
                    label: effect_param_label(&st.label).to_string(),
                    samples: st.last_curve.clone(),
                });
                st.notify(now, "現在の曲線を参照に固定しました");
            }
            Action::AddEnd => match track::with_end(world, &st.target, track) {
                Some(keys) => {
                    commit(world, st, |k| *k = keys);
                    st.notify(now, "終点を追加しました");
                }
                None => st.notify(
                    now,
                    "追加できません: 終点が既に存在するか、クリップが1フレームです",
                ),
            },
            Action::Reset => {
                st.script_buf = None;
                commit(world, st, |k| {
                    k[sel].engine_payload = encode_payload(&EasingPayload::linear());
                    k[sel].edit_seq = next_edit_seq();
                });
                st.notify(now, "直線に初期化しました (Undo可)");
            }
            Action::Apply(from, to) => {
                let encoded = encode_payload(payload);
                commit(world, st, |k| {
                    for key in k.iter_mut().take(to).skip(from) {
                        key.engine_payload = encoded.clone();
                        key.edit_seq = next_edit_seq();
                    }
                });
                st.notify(now, format!("{}区間に適用しました (Undo可)", to - from));
            }
            Action::DeleteEnd => {
                if let Some(end) = track.get(sel + 1) {
                    let removed = end.frame;
                    commit(world, st, |k| {
                        let _ = k.remove_point(sel + 1);
                    });
                    st.notify(
                        now,
                        format!("終点 f{removed} を削除しました (始点は残ります)"),
                    );
                }
            }
            Action::SetTimeControl(on) => commit(world, st, |k| k.set_time_control(on)),
            Action::MoveControl(index, time) => commit(world, st, |k| {
                let _ = k.move_control(index, time);
            }),
            Action::AddKeyframe => add_keyframe(world, st, track, sel, now),
        }
    }
    let _ = ctx;
    keep
}

fn add_keyframe(
    world: &mut EcsWorld,
    st: &mut EditorState,
    track: &[Keyframe],
    sel: usize,
    now: f64,
) {
    let playhead = world.current_frame();
    let (a, b) = (track[sel].frame, track[sel + 1].frame);
    let frame = if a < playhead && playhead < b {
        playhead
    } else {
        a + (b - a) / 2
    };
    let mut inserted = false;
    commit(world, st, |k| {
        inserted = k.insert_point(frame).is_ok();
    });
    if inserted {
        st.selected_frame = Some(frame);
        st.selected_point = None;
        st.notify(now, format!("f{frame} にキーフレームを追加しました"));
    } else {
        st.notify(now, "挿入できません: 区間が1フレーム以下です");
    }
}

fn toolbar(f: &mut Frame, ui: &mut egui::Ui) {
    ui.horizontal_wrapped(|ui| {
        ui.label(egui::RichText::new(effect_param_label(&f.st.label)).strong());
        ui.separator();
        if ui
            .add_enabled(
                f.can_undo,
                egui::Button::new(icons::ICON_UNDO).min_size(vec2(24.0, 24.0)),
            )
            .on_hover_text("元に戻す")
            .clicked()
        {
            f.actions.push(Action::Undo);
        }
        if ui
            .add_enabled(
                f.can_redo,
                egui::Button::new(icons::ICON_REDO).min_size(vec2(24.0, 24.0)),
            )
            .on_hover_text("やり直す")
            .clicked()
        {
            f.actions.push(Action::Redo);
        }
        if button(
            ui,
            icons::ICON_CONTENT_COPY,
            "コピー",
            "曲線をJSONでコピー (Ctrl+Vで貼り付け)",
        )
        .clicked()
        {
            f.ctx
                .copy_text(serde_json::to_string_pretty(&f.payload).unwrap_or_default());
            f.st.notify(f.now, "コピーしました。Ctrl+V で貼り付けできます");
        }
        if button(
            ui,
            icons::ICON_LIBRARY_ADD,
            "保存",
            "現在の曲線をプリセットとして保存 (再起動後も残ります)",
        )
        .clicked()
        {
            presets::save(f.payload.kind.clone(), &mut f.st.presets);
            f.st.notify(f.now, "保存しました。名前は保存済み一覧で変更できます");
        }
        if button(
            ui,
            icons::ICON_REFRESH,
            "直線に初期化",
            "この区間を直線へ戻す",
        )
        .clicked()
        {
            f.actions.push(Action::Reset);
        }
        if button(
            ui,
            icons::ICON_PUSH_PIN,
            "参照に固定",
            "現在の曲線を点線で残し、別の項目と比較",
        )
        .clicked()
        {
            f.actions.push(Action::Pin);
        }
        if button(ui, icons::ICON_CLOSE, "閉じる", "エディタを閉じる (Esc)").clicked() {
            f.actions.push(Action::Close);
        }
    });
    ui.horizontal_wrapped(|ui| {
        let current = category_index(&f.payload.kind);
        for (i, label) in CATEGORY_LABELS.iter().enumerate() {
            if ui.selectable_label(current == i, *label).clicked() && current != i {
                f.set_kind(category_default(i));
            }
        }
    });
    ui.horizontal_wrapped(|ui| {
        let segments = f.track.len() - 1;
        if button(ui, icons::ICON_CHEVRON_LEFT, "", "前の区間").clicked() && f.sel > 0 {
            f.actions.push(Action::Select(f.sel - 1));
        }
        ui.label(format!("{} / {}", f.sel + 1, segments));
        if button(ui, icons::ICON_CHEVRON_RIGHT, "", "次の区間").clicked() && f.sel + 1 < segments
        {
            f.actions.push(Action::Select(f.sel + 1));
        }
        if button(
            ui,
            icons::ICON_ADD,
            "再生位置に追加",
            "再生位置にキーフレームを挿入 (値は現在の評価値)",
        )
        .clicked()
        {
            f.actions.push(Action::AddKeyframe);
        }
        let is_track_tail = f.sel + 2 == f.track.len();
        let (del_label, del_hint) = if is_track_tail {
            (
                "終点を削除".to_owned(),
                "トラック末尾のキーフレームを削除します (始点は削除不可)",
            )
        } else {
            (
                format!("f{} で統合", f.track[f.sel + 1].frame),
                "次のキーフレームを削除し、前後の区間を1つに統合します",
            )
        };
        if ui
            .add(
                egui::Button::new(format!(
                    "{} {}",
                    <&str>::from(icons::ICON_REMOVE),
                    del_label
                ))
                .min_size(vec2(24.0, 24.0)),
            )
            .on_hover_text(del_hint)
            .clicked()
        {
            f.actions.push(Action::DeleteEnd);
        }
        ui.checkbox(&mut f.st.follow_playhead, "再生位置に追従")
            .on_hover_text("再生ヘッドが動くと、その区間を選択");
        let mut time_control = f.track.time_controlled();
        if ui
            .checkbox(&mut time_control, "時間制御")
            .on_hover_text("中間点の時間を無視し、制御点の時間で区間を決定")
            .changed()
        {
            f.actions.push(Action::SetTimeControl(time_control));
        }
        if time_control && f.sel + 2 < f.track.len() {
            let index = f.sel + 1;
            let mut time = f.track.time_of(index);
            if ui
                .add(egui::DragValue::new(&mut time).prefix("制御点 f"))
                .changed()
            {
                f.actions.push(Action::MoveControl(index, time));
            }
        }
        if button(
            ui,
            icons::ICON_PLAY_ARROW,
            "プレビュー",
            "曲線に沿った動きを再生",
        )
        .clicked()
        {
            f.st.preview_start = Some(f.now);
        }
        if button(
            ui,
            icons::ICON_FIT_SCREEN,
            "表示リセット",
            "ズームとパンを初期化",
        )
        .clicked()
        {
            f.st.zoom = 1.0;
            f.st.pan = Vec2::ZERO;
        }
    });
    ui.horizontal_wrapped(|ui| {
        let reversible = matches!(
            f.payload.kind,
            CurveKind::Bounce { .. } | CurveKind::Elastic { .. }
        );
        if ui
            .add_enabled(
                reversible,
                egui::Button::new(format!("{} 反転", <&str>::from(icons::ICON_SWAP_HORIZ)))
                    .min_size(vec2(24.0, 24.0)),
            )
            .on_disabled_hover_text("反転は「振動」「バウンス」でのみ使えます")
            .clicked()
        {
            if let CurveKind::Bounce { reversed, .. } | CurveKind::Elastic { reversed, .. } =
                &mut f.payload.kind
            {
                *reversed = !*reversed;
            }
            f.edit.changed = true;
        }
        ui.separator();
        let target_frame = f.track[f.sel].frame;
        let is_track_head = f.sel == 0;
        ui.label(format!("補間モード (対象: f{target_frame})"));
        for (mode, (label, help)) in MODES.iter().zip(MODE_HELP) {
            let enabled = !is_track_head || *mode == ApplyMode::Normal;
            let selected = f.payload.apply_mode == *mode;
            let resp = ui
                .add_enabled_ui(enabled, |ui| ui.selectable_label(selected, label))
                .inner;
            let resp = if enabled {
                resp.on_hover_text(help)
            } else {
                resp.on_disabled_hover_text(
                    "トラック先頭のキーフレームは常に評価対象のため無視・補間を設定できません",
                )
            };
            if resp.clicked() {
                f.payload.apply_mode = *mode;
                f.edit.changed = true;
            }
        }
    });
    ui.label(egui::RichText::new(HINT).weak().small());
    if let Some((text, at)) = &f.st.notice
        && f.now - at < NOTICE_SECONDS
    {
        ui.colored_label(ui.visuals().warn_fg_color, text);
        f.ctx
            .request_repaint_after(std::time::Duration::from_millis(500));
    }
}

fn left(f: &mut Frame, ui: &mut egui::Ui) {
    let (k0, k1) = (f.track[f.sel].clone(), f.track[f.sel + 1].clone());
    let pts = handles::control_points(&f.payload.kind);
    ui.horizontal_wrapped(|ui| {
        ui.label(egui::RichText::new(CATEGORY_LABELS[category_index(&f.payload.kind)]).strong());
        ui.weak(format!(
            "区間 {}/{}　f{} → f{} ({}f)　値 {} → {}",
            f.sel + 1,
            f.track.len() - 1,
            k0.frame,
            k1.frame,
            k1.frame - k0.frame,
            fmt(k0.value),
            fmt(k1.value)
        ));
        match f.st.selected_point.and_then(|i| pts.get(i)) {
            Some(p) => ui.weak(format!("選択中のハンドル: {}", p.label)),
            None => ui.weak("ハンドル未選択"),
        };
        if let Some(r) = &f.st.reference {
            ui.weak(format!("参照: {}", r.label));
            if ui
                .small_button(icons::ICON_CLOSE)
                .on_hover_text("参照を消去")
                .clicked()
            {
                f.st.reference = None;
            }
        }
    });
    graph(f, ui, &pts, &k0, &k1);
    if let Some(i) = strip::show(ui, &f.track, f.sel, f.playhead) {
        f.actions.push(Action::Select(i));
    }
    ui.group(|ui| {
        ui.set_min_width(ui.available_width());
        params::show(ui, &mut f.payload.kind, &mut f.edit);
    });
    apply_row(f, ui);
}

fn apply_row(f: &mut Frame, ui: &mut egui::Ui) {
    let total = f.track.len() - 1;
    let from = if f.st.scope == ApplyScope::All {
        0
    } else {
        f.sel
    };
    let encoded = encode_payload(&f.payload);
    let differs = |i: usize| f.track[i].engine_payload != encoded;
    let others = (from..total).filter(|&i| i != f.sel && differs(i)).count();
    let confirming =
        f.st.confirm_apply
            .is_some_and(|t| f.now - t < CONFIRM_SECONDS);
    ui.horizontal_wrapped(|ui| {
        ui.selectable_value(&mut f.st.scope, ApplyScope::All, "全区間");
        ui.selectable_value(&mut f.st.scope, ApplyScope::FromSelected, "この区間以降");
        let label = if confirming {
            format!("上書きを確定 ({others}区間を変更)")
        } else {
            format!("この曲線を適用 ({}区間)", total - from)
        };
        let clicked = ui
            .add_enabled(
                others > 0,
                egui::Button::new(label).min_size(vec2(0.0, 28.0)),
            )
            .on_hover_text("この区間の曲線を範囲内の各区間へコピー (Undo可)")
            .on_disabled_hover_text("範囲内はすべて同じ曲線です")
            .clicked();
        if clicked {
            if confirming {
                f.actions.push(Action::Apply(from, total));
                f.st.confirm_apply = None;
            } else {
                f.st.confirm_apply = Some(f.now);
                f.ctx
                    .request_repaint_after(std::time::Duration::from_secs_f64(CONFIRM_SECONDS));
            }
        }
    });
}

fn right(f: &mut Frame, ui: &mut egui::Ui) {
    if let CurveKind::Script { source } = &mut f.payload.kind {
        let mut buffer = source.clone();
        if script_pane::show(ui, &mut buffer, f.st.script_error.as_deref()) {
            f.st.script_error = script_pane::validate(&buffer).err();
            f.st.script_hold = f.now + SCRIPT_DEBOUNCE;
            f.st.script_buf = Some((f.track[f.sel].frame, buffer.clone()));
            *source = buffer;
        }
        ui.separator();
    }
    presets::show(ui, &mut f.st.presets, &f.payload.kind, &mut f.out);
}

fn graph(
    f: &mut Frame,
    ui: &mut egui::Ui,
    pts: &[handles::ControlPoint],
    k0: &Keyframe,
    k1: &Keyframe,
) {
    let v = ui.visuals().clone();
    let (accent, weak, guide, grid_col, ink, outline) = (
        v.selection.stroke.color,
        v.weak_text_color(),
        v.widgets.inactive.fg_stroke.color,
        v.widgets.noninteractive.bg_stroke.color,
        v.text_color(),
        v.extreme_bg_color,
    );
    let is_script = matches!(f.payload.kind, CurveKind::Script { .. });
    let samples: Vec<[f32; 2]> = match &f.payload.kind {
        CurveKind::Script { source }
            if f.st.script_error.is_some() && f.st.script_cache.is_some() =>
        {
            let _ = source;
            f.st.script_cache
                .as_ref()
                .map(|(_, p)| p.clone())
                .unwrap_or_default()
        }
        CurveKind::Script { source } => {
            script_pane::samples(&mut f.st.script_cache, source).to_vec()
        }
        _ => curve_view::sample(&f.payload, 160),
    };
    let (y_lo, y_hi) = curve_view::y_range(&samples, pts.iter().map(|p| p.pos[1]));
    let width = finite_width(ui).clamp(200.0, 1600.0);
    let height = (width * (y_hi - y_lo)).clamp(260.0, 480.0);
    let (rect, response) = ui.allocate_exact_size(vec2(width, height), Sense::click_and_drag());
    let mut view = CurveView::fit(rect, y_lo, y_hi, f.st.zoom, f.st.pan);

    if response.hovered() {
        let scroll = ui.input(|i| i.smooth_scroll_delta.y);
        if let (true, Some(p)) = (scroll != 0.0, response.hover_pos()) {
            ui.ctx().input_mut(|i| i.smooth_scroll_delta = Vec2::ZERO);
            let anchor = view.to_data(p);
            f.st.zoom = (f.st.zoom * (scroll * 0.004).exp()).clamp(0.25, 16.0);
            view = CurveView::fit(rect, y_lo, y_hi, f.st.zoom, f.st.pan);
            f.st.pan += p - view.to_screen(anchor.0, anchor.1);
            view = CurveView::fit(rect, y_lo, y_hi, f.st.zoom, f.st.pan);
        }
    }
    let to_screen = |p: [f32; 2]| view.to_screen(p[0], p[1]);
    let hover_hit = response
        .hover_pos()
        .and_then(|p| handles::nearest(pts, to_screen, p, HIT_RADIUS));
    let pointer = response.interact_pointer_pos();

    if response.drag_started_by(PointerButton::Primary) {
        let hit = pointer.and_then(|p| handles::nearest(pts, to_screen, p, HIT_RADIUS));
        f.st.dragging = hit;
        f.st.panning = hit.is_none();
        if hit.is_some() {
            f.st.selected_point = hit;
        }
    }
    if response.dragged_by(PointerButton::Middle) {
        f.st.pan += response.drag_delta();
    }
    if response.dragged_by(PointerButton::Primary) {
        match (f.st.dragging, pointer) {
            (Some(i), Some(p)) => {
                if let Some(cp) = pts.get(i) {
                    let mods = ui.input(|i| i.modifiers);
                    handles::apply_drag(&mut f.payload.kind, cp.point, view.to_data(p), mods);
                    f.edit.changed = true;
                    f.edit.live = true;
                }
            }
            _ if f.st.panning => f.st.pan += response.drag_delta(),
            _ => {}
        }
    }
    if response.drag_stopped() {
        f.st.dragging = None;
        f.st.panning = false;
    }
    if response.clicked() {
        f.st.selected_point = pointer.and_then(|p| handles::nearest(pts, to_screen, p, HIT_RADIUS));
    }
    if response.double_clicked()
        && hover_hit.is_none()
        && let (CurveKind::Normal { segments }, Some(p)) = (&mut f.payload.kind, pointer)
    {
        neoutl_easing_standard::add_segment(segments, view.to_data(p).0.clamp(0.05, 0.95));
        f.edit.changed = true;
    }
    if response.secondary_clicked() {
        f.st.menu_point = pointer.and_then(|p| handles::nearest(pts, to_screen, p, HIT_RADIUS));
        f.st.menu_data = pointer.map(|p| view.to_data(p));
    }
    response.context_menu(|ui| {
        if let Some(cp) = f.st.menu_point.and_then(|i| pts.get(i)) {
            if ui.button(handles::reset_label(&f.payload.kind)).clicked() {
                if handles::reset_point(&mut f.payload.kind, cp.point) {
                    f.edit.changed = true;
                    f.st.selected_point = None;
                }
                ui.close();
            }
        }
        if let (CurveKind::Normal { segments }, Some((x, _))) =
            (&mut f.payload.kind, f.st.menu_data)
            && ui.button("ここに頂点を追加").clicked()
        {
            neoutl_easing_standard::add_segment(segments, x.clamp(0.05, 0.95));
            f.edit.changed = true;
            ui.close();
        }
        if ui.button("表示をリセット").clicked() {
            f.st.zoom = 1.0;
            f.st.pan = Vec2::ZERO;
            ui.close();
        }
    });

    if (response.has_focus() || response.hovered()) && !ui.ctx().egui_wants_keyboard_input() {
        let (delta, del, tab, esc) = ui.input_mut(|i| {
            let mut d = Vec2::ZERO;
            for (mods, step) in [(Modifiers::NONE, 0.01), (Modifiers::SHIFT, 0.05)] {
                for (key, dir) in [
                    (Key::ArrowLeft, vec2(-1.0, 0.0)),
                    (Key::ArrowRight, vec2(1.0, 0.0)),
                    (Key::ArrowUp, vec2(0.0, 1.0)),
                    (Key::ArrowDown, vec2(0.0, -1.0)),
                ] {
                    if i.consume_key(mods, key) {
                        d += dir * step;
                    }
                }
            }
            (
                d,
                i.consume_key(Modifiers::NONE, Key::Delete)
                    || i.consume_key(Modifiers::NONE, Key::Backspace),
                response.has_focus() && i.consume_key(Modifiers::NONE, Key::Tab),
                f.st.selected_point.is_some() && i.consume_key(Modifiers::NONE, Key::Escape),
            )
        });
        if tab && !pts.is_empty() {
            f.st.selected_point = Some(f.st.selected_point.map_or(0, |i| (i + 1) % pts.len()));
        }
        if esc {
            f.st.selected_point = None;
        }
        if let Some(cp) = f.st.selected_point.and_then(|i| pts.get(i)) {
            if delta != Vec2::ZERO {
                handles::apply_drag(
                    &mut f.payload.kind,
                    cp.point,
                    (cp.pos[0] + delta.x, cp.pos[1] + delta.y),
                    Modifiers::NONE,
                );
                f.edit.changed = true;
            }
            if del && handles::reset_point(&mut f.payload.kind, cp.point) {
                f.edit.changed = true;
                f.st.selected_point = None;
            }
        }
    }
    if f.st.dragging.is_some() || f.st.panning {
        ui.ctx().set_cursor_icon(egui::CursorIcon::Grabbing);
    } else if hover_hit.is_some() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::Grab);
    }

    let samples = if f.edit.changed && !is_script {
        curve_view::sample(&f.payload, 160)
    } else {
        samples
    };
    let pts = &handles::control_points(&f.payload.kind);
    let shown = f.payload.clone();
    let value_at = |t: f32| {
        if is_script {
            curve_view::interpolate(&samples, t)
        } else {
            ease(&shown, t)
        }
    };
    let painter = ui.painter_at(rect);
    painter.rect_filled(rect, 4.0, outline);
    if !(view.scale().is_finite() && view.scale() > 1.0) {
        f.st.last_curve = samples;
        return;
    }
    let step = curve_view::grid_step(view.scale());
    let (x_min, y_top) = view.to_data(rect.left_top());
    let (x_max, y_bottom) = view.to_data(rect.right_bottom());
    let font = egui::FontId::proportional(10.0);
    let mut gx = (x_min / step).floor() * step;
    let mut guard = 0;
    while gx <= x_max && guard < 512 {
        guard += 1;
        let sx = view.to_screen(gx, 0.0).x;
        painter.vline(sx, rect.y_range(), Stroke::new(1.0, grid_col));
        painter.text(
            pos2(sx + 2.0, rect.bottom() - 2.0),
            egui::Align2::LEFT_BOTTOM,
            fmt(gx),
            font.clone(),
            weak,
        );
        gx += step;
    }
    let mut gy = (y_bottom / step).floor() * step;
    guard = 0;
    while gy <= y_top && guard < 512 {
        guard += 1;
        let sy = view.to_screen(0.0, gy).y;
        painter.hline(rect.x_range(), sy, Stroke::new(1.0, grid_col));
        painter.text(
            pos2(rect.left() + 3.0, sy - 1.0),
            egui::Align2::LEFT_BOTTOM,
            fmt(gy),
            font.clone(),
            weak,
        );
        gy += step;
    }
    painter.rect_stroke(
        egui::Rect::from_two_pos(view.to_screen(0.0, 1.0), view.to_screen(1.0, 0.0)),
        0.0,
        Stroke::new(1.5, guide),
        egui::StrokeKind::Middle,
    );
    painter.text(
        pos2(rect.right() - 4.0, view.to_screen(1.0, 0.0).y - 2.0),
        egui::Align2::RIGHT_BOTTOM,
        format!("始 {}", fmt(k0.value)),
        font.clone(),
        ink,
    );
    painter.text(
        pos2(rect.right() - 4.0, view.to_screen(1.0, 1.0).y + 2.0),
        egui::Align2::RIGHT_TOP,
        format!("終 {}", fmt(k1.value)),
        font.clone(),
        ink,
    );

    let polyline = |points: &[[f32; 2]]| -> Vec<egui::Pos2> {
        points.iter().map(|p| view.to_screen(p[0], p[1])).collect()
    };
    if let Some(r) = &f.st.reference {
        painter.extend(egui::Shape::dashed_line(
            &polyline(&r.samples),
            Stroke::new(1.5, weak),
            6.0,
            4.0,
        ));
    }
    if let Some(kind) = &f.st.hover_preview
        && !matches!(kind, CurveKind::Script { .. })
    {
        let ghost = EasingPayload {
            kind: kind.clone(),
            ..Default::default()
        };
        painter.add(egui::Shape::line(
            polyline(&curve_view::sample(&ghost, 96)),
            Stroke::new(2.0, accent.linear_multiply(0.5)),
        ));
    }
    match &f.payload.kind {
        CurveKind::Bezier {
            handle_left: l,
            handle_right: r,
        } => {
            painter.line_segment(
                [view.to_screen(0.0, 0.0), view.to_screen(l[0], l[1])],
                Stroke::new(1.0, guide),
            );
            painter.line_segment(
                [view.to_screen(1.0, 1.0), view.to_screen(r[0], r[1])],
                Stroke::new(1.0, guide),
            );
        }
        CurveKind::Elastic { reversed, .. } => {
            if let Some(cp) = pts.first() {
                let base_y = if *reversed { 0.0 } else { 1.0 };
                painter.line_segment(
                    [view.to_screen(cp.pos[0], base_y), to_screen(cp.pos)],
                    Stroke::new(1.0, guide),
                );
            }
        }
        CurveKind::Normal { segments } => {
            for s in segments {
                painter.vline(
                    view.to_screen(s.anchor_start[0], 0.0).x,
                    rect.y_range(),
                    Stroke::new(1.0, guide),
                );
            }
        }
        _ => {}
    }
    painter.add(egui::Shape::line(
        polyline(&samples),
        Stroke::new(3.0, accent),
    ));

    let t_play = (f.playhead - k0.frame) as f32 / (k1.frame - k0.frame).max(1) as f32;
    if (0.0..=1.0).contains(&t_play) {
        let x = view.to_screen(t_play, 0.0).x;
        painter.extend(egui::Shape::dashed_line(
            &[pos2(x, rect.top()), pos2(x, rect.bottom())],
            Stroke::new(1.0, v.warn_fg_color),
            4.0,
            4.0,
        ));
        let y = value_at(t_play);
        painter.circle_filled(view.to_screen(t_play, y), 4.0, v.warn_fg_color);
        painter.text(
            view.to_screen(t_play, y) + vec2(6.0, -6.0),
            egui::Align2::LEFT_BOTTOM,
            format!(
                "f{}: {}",
                f.playhead,
                fmt(k0.value + (k1.value - k0.value) * y)
            ),
            font.clone(),
            v.warn_fg_color,
        );
    }
    if let Some(start) = f.st.preview_start {
        let t = ((f.now - start) / PREVIEW_SECONDS) as f32;
        if t >= 1.0 {
            f.st.preview_start = None;
        } else {
            let y = value_at(t);
            let dot = view.to_screen(t, y);
            painter.hline(
                dot.x..=rect.right(),
                dot.y,
                Stroke::new(1.0, accent.linear_multiply(0.6)),
            );
            painter.circle_filled(dot, 6.0, Color32::from_rgb(0xff, 0x9e, 0x3d));
            painter.text(
                pos2(rect.right() - 4.0, dot.y - 3.0),
                egui::Align2::RIGHT_BOTTOM,
                fmt(k0.value + (k1.value - k0.value) * y),
                font.clone(),
                ink,
            );
        }
    }

    let start = view.to_screen(0.0, 0.0);
    painter.circle_stroke(start, 6.0, Stroke::new(2.0, ink));
    painter.text(
        start + vec2(9.0, 4.0),
        egui::Align2::LEFT_TOP,
        "始点 (固定)",
        font.clone(),
        weak,
    );
    let end = view.to_screen(1.0, 1.0);
    painter.circle_filled(end, 5.0, ink);
    painter.text(
        end + vec2(-9.0, -4.0),
        egui::Align2::RIGHT_BOTTOM,
        format!("終点 f{}", k1.frame),
        font.clone(),
        weak,
    );
    for (i, cp) in pts.iter().enumerate() {
        let center = to_screen(cp.pos);
        let selected = f.st.selected_point == Some(i);
        let hot = selected || hover_hit == Some(i) || f.st.dragging == Some(i);
        let radius = 6.0 + if hot { 2.0 } else { 0.0 };
        painter.circle(
            center,
            radius,
            if selected { accent } else { ink },
            Stroke::new(2.0, outline),
        );
        if selected {
            painter.circle_stroke(center, radius + 4.0, Stroke::new(1.5, accent));
        }
        let galley = painter.layout_no_wrap(cp.label.clone(), font.clone(), ink);
        let label_rect =
            egui::Rect::from_min_size(center + vec2(10.0, -22.0), galley.size()).expand(3.0);
        painter.rect_filled(label_rect, 3.0, outline.gamma_multiply(0.85));
        painter.galley(label_rect.shrink(3.0).min, galley, ink);
    }
    f.st.last_curve = samples;
}

use super::handles::set_boundary;
use neoutl_easing_standard::{CurveKind, add_segment};
use std::ops::RangeInclusive;

#[derive(Default)]
pub struct Edit {
    pub changed: bool,
    pub live: bool,
}

impl Edit {
    pub fn absorb(&mut self, r: &egui::Response) {
        self.changed |= r.changed();
        self.live |= r.dragged();
    }
}

fn field(ui: &mut egui::Ui, edit: &mut Edit, label: &str, v: &mut f32, range: RangeInclusive<f32>) {
    ui.label(label);
    let r = ui.add(
        egui::DragValue::new(v)
            .speed(0.005)
            .range(range)
            .fixed_decimals(3),
    );
    edit.absorb(&r);
}

pub fn show(ui: &mut egui::Ui, kind: &mut CurveKind, edit: &mut Edit) {
    ui.horizontal_wrapped(|ui| match kind {
        CurveKind::Bezier {
            handle_left: l,
            handle_right: r,
        } => {
            field(ui, edit, "x1", &mut l[0], 0.0..=1.0);
            field(ui, edit, "y1", &mut l[1], -2.0..=3.0);
            field(ui, edit, "x2", &mut r[0], 0.0..=1.0);
            field(ui, edit, "y2", &mut r[1], -2.0..=3.0);
        }
        CurveKind::Bounce { cor, period, .. } => {
            field(ui, edit, "反発係数", cor, 0.0..=1.0);
            field(ui, edit, "周期", period, 0.01..=2.0);
        }
        CurveKind::Elastic {
            amplitude,
            frequency,
            decay,
            ..
        } => {
            field(ui, edit, "振幅", amplitude, 0.0..=1.0);
            field(ui, edit, "周波数", frequency, 0.5..=30.0);
            field(ui, edit, "減衰", decay, 0.0..=30.0);
        }
        CurveKind::Normal { segments } => {
            for i in 0..segments.len().saturating_sub(1) {
                let [mut x, mut y] = segments[i].anchor_end;
                ui.label(format!("頂点{}", i + 1));
                let before = edit.changed;
                field(ui, edit, "x", &mut x, 0.0..=1.0);
                field(ui, edit, "y", &mut y, -2.0..=3.0);
                if edit.changed && !before {
                    set_boundary(segments, i, x, y);
                }
            }
            if ui
                .button("頂点追加")
                .on_hover_text("最も広い区間の中央に追加")
                .clicked()
            {
                let (x0, x1) = segments
                    .iter()
                    .map(|s| (s.anchor_start[0], s.anchor_end[0]))
                    .max_by(|a, b| (a.1 - a.0).total_cmp(&(b.1 - b.0)))
                    .unwrap_or((0.0, 1.0));
                add_segment(segments, (x0 + x1) * 0.5);
                edit.changed = true;
            }
        }
        CurveKind::Standard { name } => {
            ui.label(format!("標準イージング: {name} (数値パラメータなし)"));
        }
        CurveKind::Linear => {
            ui.label("直線 (パラメータなし)");
        }
        CurveKind::Script { .. } => {
            ui.label("Lua式で定義 (右のエディタで編集)");
        }
    });
}

use crate::easings::registry;
use egui::{Rect, Sense, Stroke, Vec2, pos2, vec2};
use neoutl_easing_standard::{CurveKind, curve::evaluate_kind};
use std::sync::OnceLock;

const CARD_MIN_WIDTH: f32 = 84.0;
const CARD_HEIGHT: f32 = 76.0;

struct Preset {
    id: String,
    label: String,
}
struct Group {
    title: &'static str,
    items: Vec<Preset>,
}

const FAMILIES: [(&str, &str); 8] = [
    ("Sine", "サイン"),
    ("Quad", "2次"),
    ("Cubic", "3次"),
    ("Quart", "4次"),
    ("Quint", "5次"),
    ("Expo", "指数"),
    ("Circ", "円"),
    ("Back", "バック"),
];
const VARIANTS: [(&str, &str); 4] = [
    ("In", "イン"),
    ("Out", "アウト"),
    ("InOut", "イン・アウト"),
    ("OutIn", "アウト・イン"),
];

fn builtins() -> &'static [Group] {
    static GROUPS: OnceLock<Vec<Group>> = OnceLock::new();
    GROUPS.get_or_init(|| {
        let make = |family: &str, variants: &[(&str, &str)]| {
            variants
                .iter()
                .map(|(v, jp)| Preset {
                    id: format!("ease{v}{family}"),
                    label: (*jp).to_owned(),
                })
                .collect::<Vec<_>>()
        };
        let mut groups = vec![Group {
            title: "基本",
            items: vec![Preset {
                id: "linear".into(),
                label: "直線".into(),
            }],
        }];
        for (family, jp) in FAMILIES {
            groups.push(Group {
                title: jp,
                items: make(family, &VARIANTS),
            });
        }
        groups.push(Group {
            title: "弾性",
            items: make("Elastic", &VARIANTS[..2]),
        });
        groups.push(Group {
            title: "バウンド",
            items: make("Bounce", &VARIANTS[..2]),
        });
        groups
    })
}

#[derive(Default)]
pub struct PresetUi {
    pub search: String,
    pub focus_search: bool,
    rename: Option<(usize, String)>,
}

impl PresetUi {
    pub fn focused() -> Self {
        Self {
            focus_search: true,
            ..Default::default()
        }
    }
}

#[derive(Default)]
pub struct Out {
    pub apply: Option<CurveKind>,
    pub hover: Option<CurveKind>,
    pub notice: Option<String>,
}

fn default_for(id: &str) -> CurveKind {
    CurveKind::standard(id)
}

fn same_shape(a: &CurveKind, b: &CurveKind) -> bool {
    if matches!(a, CurveKind::Script { .. }) || matches!(b, CurveKind::Script { .. }) {
        return false;
    }
    (0..=8).all(|i| {
        let t = i as f32 / 8.0;
        (evaluate_kind(a, t) - evaluate_kind(b, t)).abs() < 1e-3
    })
}

fn card(
    ui: &mut egui::Ui,
    size: Vec2,
    label: &str,
    kind: &CurveKind,
    active: bool,
) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(size, Sense::click());
    let v = ui.visuals().clone();
    let painter = ui.painter();
    let fill = if response.hovered() {
        v.widgets.hovered.bg_fill
    } else {
        v.widgets.inactive.bg_fill
    };
    painter.rect_filled(rect, 4.0, fill);
    if active {
        painter.rect_stroke(
            rect,
            4.0,
            Stroke::new(2.0, v.selection.stroke.color),
            egui::StrokeKind::Inside,
        );
    }
    let chart = Rect::from_min_max(
        rect.min + vec2(6.0, 6.0),
        pos2(rect.max.x - 6.0, rect.max.y - 20.0),
    );
    painter.rect_stroke(
        chart,
        2.0,
        Stroke::new(1.0, v.widgets.noninteractive.bg_stroke.color),
        egui::StrokeKind::Inside,
    );
    let line = (0..=32)
        .map(|i| {
            let t = i as f32 / 32.0;
            let y = if matches!(kind, CurveKind::Script { .. }) {
                t
            } else {
                evaluate_kind(kind, t)
            };
            pos2(
                chart.left() + chart.width() * t,
                chart.bottom() - chart.height() * y.clamp(-0.2, 1.2),
            )
        })
        .collect();
    painter
        .with_clip_rect(rect)
        .add(egui::Shape::line(line, Stroke::new(1.5, v.text_color())));
    painter.text(
        pos2(rect.center().x, rect.bottom() - 9.0),
        egui::Align2::CENTER_CENTER,
        label,
        egui::TextStyle::Small.resolve(ui.style()),
        v.text_color(),
    );
    response
}

fn grid(
    ui: &mut egui::Ui,
    items: &[(String, String, CurveKind)],
    current: &CurveKind,
    out: &mut Out,
    mut menu: impl FnMut(&mut egui::Ui, usize, &mut Out),
) {
    let gap = ui.spacing().item_spacing.x;
    let avail = super::finite_width(ui);
    let cols = (((avail + gap) / (CARD_MIN_WIDTH + gap)) as usize).clamp(1, 12);
    let width = ((avail - gap * (cols - 1) as f32) / cols as f32).max(CARD_MIN_WIDTH * 0.5);
    for (row, chunk) in items.chunks(cols).enumerate() {
        ui.horizontal(|ui| {
            for (col, (id, label, kind)) in chunk.iter().enumerate() {
                let r = card(
                    ui,
                    vec2(width, CARD_HEIGHT),
                    label,
                    kind,
                    same_shape(kind, current),
                )
                .on_hover_text(id);
                if r.hovered() {
                    out.hover = Some(kind.clone());
                }
                if r.clicked() {
                    out.apply = Some(kind.clone());
                }
                r.context_menu(|ui| menu(ui, row * cols + col, &mut *out));
            }
        });
    }
}

pub fn show(ui: &mut egui::Ui, state: &mut PresetUi, current: &CurveKind, out: &mut Out) {
    ui.horizontal(|ui| {
        ui.label(egui_material_icons::icons::ICON_SEARCH);
        let r = ui.add(
            egui::TextEdit::singleline(&mut state.search)
                .hint_text("名前で検索 (日本語/英語)")
                .desired_width((super::finite_width(ui) - 32.0).max(80.0)),
        );
        if std::mem::take(&mut state.focus_search) {
            r.request_focus();
        }
        if r.has_focus()
            && ui.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::Escape))
        {
            state.search.clear();
            r.surrender_focus();
        }
        if ui
            .add_enabled(
                !state.search.is_empty(),
                egui::Button::new(egui_material_icons::icons::ICON_CLOSE),
            )
            .on_hover_text("検索をクリア (Esc)")
            .clicked()
        {
            state.search.clear();
        }
    });
    let query = state.search.to_lowercase();
    let hit = |texts: &[&str]| {
        query.is_empty() || texts.iter().any(|t| t.to_lowercase().contains(&query))
    };

    let saved: Vec<(usize, String, CurveKind)> = registry::shared()
        .lock()
        .map(|r| {
            r.entries()
                .iter()
                .enumerate()
                .map(|(i, e)| (i, e.name.clone(), e.kind.clone()))
                .collect()
        })
        .unwrap_or_default();
    let mut shown = 0usize;
    egui::ScrollArea::vertical()
        .id_salt("preset_scroll")
        .max_height((ui.ctx().content_rect().height() * 0.6).clamp(240.0, 720.0))
        .show(ui, |ui| {
            let saved_hits: Vec<_> = saved
                .iter()
                .filter(|(_, n, _)| hit(&[n, "保存済み"]))
                .collect();
            shown += saved_hits.len();
            egui::CollapsingHeader::new(format!("保存済み ({})", saved_hits.len()))
                .default_open(true)
                .show(ui, |ui| {
                    if saved_hits.is_empty() {
                        ui.weak("保存済みのカーブはありません。上の「保存」で追加します。");
                    }
                    if let Some((i, text)) = state.rename.as_mut() {
                        let mut done = None;
                        ui.horizontal(|ui| {
                            let edit =
                                ui.add(egui::TextEdit::singleline(text).desired_width(140.0));
                            edit.request_focus();
                            let enter =
                                edit.lost_focus() && ui.input(|s| s.key_pressed(egui::Key::Enter));
                            if ui.button("決定").clicked() || enter {
                                done = Some(true);
                            }
                            if ui.button("取消").clicked()
                                || ui.input(|s| s.key_pressed(egui::Key::Escape))
                            {
                                done = Some(false);
                            }
                        });
                        if let Some(commit) = done {
                            if commit {
                                if let Ok(mut r) = registry::shared().lock() {
                                    r.rename(*i, std::mem::take(text));
                                }
                                out.notice = Some("名前を変更しました".into());
                            }
                            state.rename = None;
                        }
                    }
                    let items: Vec<_> = saved_hits
                        .iter()
                        .map(|(_, n, k)| (n.clone(), n.clone(), k.clone()))
                        .collect();
                    let indices: Vec<usize> = saved_hits.iter().map(|(i, _, _)| *i).collect();
                    grid(ui, &items, current, out, |ui, pos, out| {
                        let Some(&index) = indices.get(pos) else {
                            return;
                        };
                        if ui.button("名前を変更").clicked() {
                            state.rename = Some((index, items_name(&saved, index)));
                            ui.close();
                        }
                        if ui.button("前へ").clicked() {
                            if let Ok(mut r) = registry::shared().lock() {
                                r.move_by(index, -1);
                            }
                            ui.close();
                        }
                        if ui.button("後ろへ").clicked() {
                            if let Ok(mut r) = registry::shared().lock() {
                                r.move_by(index, 1);
                            }
                            ui.close();
                        }
                        if ui.button("削除").clicked() {
                            if let Ok(mut r) = registry::shared().lock() {
                                r.remove(index);
                            }
                            out.notice = Some("削除しました".into());
                            ui.close();
                        }
                    });
                });
            for group in builtins() {
                let items: Vec<_> = group
                    .items
                    .iter()
                    .filter(|p| hit(&[&p.id, &p.label, group.title]))
                    .map(|p| (p.id.clone(), p.label.clone(), default_for(&p.id)))
                    .collect();
                if items.is_empty() {
                    continue;
                }
                shown += items.len();
                egui::CollapsingHeader::new(format!("{} ({})", group.title, items.len()))
                    .default_open(true)
                    .show(ui, |ui| {
                        grid(ui, &items, current, out, |_, _, _| {});
                    });
            }
            if shown == 0 {
                ui.weak("一致するプリセットがありません");
            }
        });
}

fn items_name(saved: &[(usize, String, CurveKind)], index: usize) -> String {
    saved
        .iter()
        .find(|(i, _, _)| *i == index)
        .map(|(_, n, _)| n.clone())
        .unwrap_or_default()
}

pub fn save(kind: CurveKind, state: &mut PresetUi) -> usize {
    let (index, name) = registry::shared()
        .lock()
        .map(|mut r| {
            let i = r.push_unique(kind);
            (i, r.entries()[i].name.clone())
        })
        .unwrap_or_default();
    state.rename = Some((index, name));
    index
}

use egui_code_editor::{CodeEditor, ColorTheme, Syntax};
use neoutl_easing_standard::script::evaluate_checked;

pub type Cache = Option<(String, Vec<[f32; 2]>)>;

pub fn validate(source: &str) -> Result<(), String> {
    [0.0, 0.5, 1.0]
        .into_iter()
        .try_for_each(|t| evaluate_checked(source, t).map(|_| ()))
}

pub fn samples<'a>(cache: &'a mut Cache, source: &str) -> &'a [[f32; 2]] {
    if cache.as_ref().is_none_or(|(s, _)| s != source) {
        let points = (0..=96)
            .map(|i| {
                let t = i as f32 / 96.0;
                [t, evaluate_checked(source, t).unwrap_or(t)]
            })
            .collect();
        *cache = Some((source.to_owned(), points));
    }
    cache.as_ref().map_or(&[], |(_, p)| p.as_slice())
}

pub fn show(ui: &mut egui::Ui, buffer: &mut String, error: Option<&str>) -> bool {
    let theme = if ui.visuals().dark_mode {
        ColorTheme::GRUVBOX
    } else {
        ColorTheme::GITHUB_LIGHT
    };
    let changed = CodeEditor::default()
        .id_source("easing_script_editor")
        .with_rows(10)
        .with_fontsize(13.0)
        .with_theme(theme)
        .with_numlines(true)
        .show(ui, buffer, &Syntax::lua())
        .0
        .response
        .changed();
    ui.label(
        egui::RichText::new(
            "変数: t (0〜1), st, ed / 関数: noise(振幅, 周波数, 位相, オクターブ, シード)",
        )
        .weak()
        .small(),
    );
    match error {
        Some(message) => {
            ui.colored_label(ui.visuals().error_fg_color, format!("評価失敗: {message}"));
        }
        None => {
            ui.colored_label(ui.visuals().weak_text_color(), "評価成功");
        }
    }
    changed
}

use super::curve_view::fmt;
use crate::ecs::types::Keyframe;
use egui::{Rect, Sense, Stroke, pos2, vec2};
use neoutl_easing_standard::{CurveKind, ease, parse_payload};

pub fn show(
    ui: &mut egui::Ui,
    track: &[Keyframe],
    selected: usize,
    playhead: i32,
) -> Option<usize> {
    let (rect, response) = ui.allocate_exact_size(
        vec2(super::finite_width(ui).max(80.0), 64.0),
        Sense::click(),
    );
    let visuals = ui.visuals().clone();
    let painter = ui.painter_at(rect);
    painter.rect_filled(rect, 4.0, visuals.extreme_bg_color);
    let body = Rect::from_min_max(
        rect.min + vec2(4.0, 4.0),
        pos2(rect.max.x - 4.0, rect.max.y - 18.0),
    );
    let first = track.first()?.frame;
    let span = (track.last()?.frame - first).max(1) as f32;
    let x_of = |frame: i32| body.left() + body.width() * (frame - first) as f32 / span;
    let accent = visuals.selection.stroke.color;
    let mut picked = None;
    let mut last_label_x = f32::MIN;
    for (i, w) in track.windows(2).enumerate() {
        let seg = Rect::from_min_max(
            pos2(x_of(w[0].frame), body.top()),
            pos2(x_of(w[1].frame), body.bottom()),
        );
        if i == selected {
            painter.rect_filled(seg, 2.0, visuals.selection.bg_fill.linear_multiply(0.5));
        }
        painter.rect_stroke(
            seg,
            2.0,
            Stroke::new(
                if i == selected { 2.0 } else { 1.0 },
                if i == selected {
                    accent
                } else {
                    visuals.widgets.noninteractive.bg_stroke.color
                },
            ),
            egui::StrokeKind::Inside,
        );
        let payload = parse_payload(&w[0].engine_payload);
        let inner = seg.shrink2(vec2(2.0, 4.0));
        let is_script = matches!(payload.kind, CurveKind::Script { .. });
        let line: Vec<egui::Pos2> = (0..=24)
            .map(|k| {
                let t = k as f32 / 24.0;
                let y = if is_script { t } else { ease(&payload, t) };
                pos2(
                    inner.left() + inner.width() * t,
                    inner.bottom() - inner.height() * y.clamp(-0.2, 1.2),
                )
            })
            .collect();
        painter.with_clip_rect(seg).add(egui::Shape::line(
            line,
            Stroke::new(1.5, visuals.text_color()),
        ));
        let x = x_of(w[0].frame);
        if x - last_label_x >= 34.0 {
            painter.text(
                pos2(x + 2.0, rect.bottom() - 2.0),
                egui::Align2::LEFT_BOTTOM,
                format!("{}", w[0].frame),
                egui::FontId::proportional(10.0),
                visuals.weak_text_color(),
            );
            last_label_x = x;
        }
        if let Some(pos) = response.hover_pos()
            && seg.x_range().contains(pos.x)
        {
            if response.clicked() {
                picked = Some(i);
            }
            response.clone().on_hover_text(format!(
                "区間 {}: f{} → f{} ({}f)\n値 {} → {}",
                i + 1,
                w[0].frame,
                w[1].frame,
                w[1].frame - w[0].frame,
                fmt(w[0].value),
                fmt(w[1].value)
            ));
        }
    }
    if (first..=first + span as i32).contains(&playhead) {
        let x = x_of(playhead);
        painter.line_segment(
            [pos2(x, rect.top()), pos2(x, rect.bottom() - 14.0)],
            Stroke::new(2.0, visuals.warn_fg_color),
        );
    }
    picked
}

use crate::ecs::EcsWorld;
use crate::ecs::components::{KeyframeTracks, ObjectId, ParamAccess};
use crate::ecs::effects::EffectStack;
use crate::ecs::history::HistoryCommand;
use crate::ecs::track::Track;
use crate::ecs::types::{EffectParam, Keyframe, Value};
use neoutl_easing_standard::{EasingPayload, encode_payload};
use shipyard::{Get, IntoIter, View, ViewMut, World};

pub const ENGINE_ID: &str = "neoutl-easing-standard";

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum TrackTarget {
    Object {
        object_id: usize,
        key: String,
    },
    Effect {
        object_id: usize,
        effect_index: usize,
        key: String,
    },
}

impl TrackTarget {
    pub fn object_id(&self) -> usize {
        match self {
            Self::Object { object_id, .. } | Self::Effect { object_id, .. } => *object_id,
        }
    }
}

pub fn read(world: &EcsWorld, target: &TrackTarget) -> Vec<Keyframe> {
    match target {
        TrackTarget::Object { object_id, key } => world.get_keyframes(*object_id, key),
        TrackTarget::Effect {
            object_id,
            effect_index,
            key,
        } => world.get_effect_keyframes(*object_id, *effect_index, key),
    }
}

fn assign(world: &mut World, target: &TrackTarget, keys: &[Keyframe]) {
    let id = target.object_id();
    let Some(entity) = world.run(|ids: View<ObjectId>| {
        ids.iter()
            .with_id()
            .find(|(_, o)| o.0 == id)
            .map(|(e, _)| e)
    }) else {
        return;
    };
    match target {
        TrackTarget::Object { key, .. } => {
            let mut tracks = world
                .run(|v: View<KeyframeTracks>| v.get(entity).ok().cloned())
                .unwrap_or_default();
            tracks.0.insert(key.clone(), keys.to_vec());
            world.add_component(entity, tracks);
        }
        TrackTarget::Effect {
            effect_index, key, ..
        } => world.run(|mut stacks: ViewMut<EffectStack>| {
            if let Ok(mut stack) = (&mut stacks).get(entity)
                && let Some(effect) = stack.0.get_mut(*effect_index)
            {
                effect
                    .params
                    .entry(key.clone())
                    .or_insert_with(|| {
                        EffectParam::new(Value::Number(keys.first().map_or(0.0, |k| k.value)))
                    })
                    .keyframes = keys.to_vec();
            }
        }),
    }
}

pub fn write(world: &mut EcsWorld, target: &TrackTarget, keys: &[Keyframe]) {
    assign(&mut world.world, target, keys);
    world.touch();
}

pub fn same(a: &[Keyframe], b: &[Keyframe]) -> bool {
    a.len() == b.len()
        && a.iter().zip(b).all(|(x, y)| {
            x.frame == y.frame
                && x.value == y.value
                && x.engine_id == y.engine_id
                && x.engine_payload == y.engine_payload
        })
}

struct TrackEdit {
    target: TrackTarget,
    before: Vec<Keyframe>,
    after: Vec<Keyframe>,
}

impl HistoryCommand for TrackEdit {
    fn description(&self) -> &str {
        "Edit easing"
    }
    fn apply(&mut self, world: &mut World) {
        assign(world, &self.target, &self.after);
    }
    fn revert(&mut self, world: &mut World) {
        assign(world, &self.target, &self.before);
    }
}

pub fn push_history(
    world: &mut EcsWorld,
    target: &TrackTarget,
    before: Vec<Keyframe>,
    after: Vec<Keyframe>,
) {
    if !same(&before, &after) {
        world.push_history_command(Box::new(TrackEdit {
            target: target.clone(),
            before,
            after,
        }));
    }
}

pub fn new_keyframe(frame: i32, value: f32, payload: &EasingPayload) -> Keyframe {
    Keyframe::new(frame, value, ENGINE_ID.to_owned(), encode_payload(payload))
}

pub fn clip_bounds(world: &EcsWorld, target: &TrackTarget) -> (i32, i32) {
    let (start, end) = world
        .get_timeline_objects()
        .into_iter()
        .find(|o| o.id as usize == target.object_id())
        .map(|o| (o.start_frame, o.end_frame))
        .unwrap_or((0, 1));
    (start, end.max(start + 1))
}

fn base_value(world: &EcsWorld, target: &TrackTarget) -> f32 {
    match target {
        TrackTarget::Object { object_id, key } => world
            .get_transform(*object_id)
            .and_then(|v| v.get_param(key))
            .or_else(|| {
                world
                    .get_audio_params(*object_id)
                    .and_then(|v| v.get_param(key))
            })
            .or_else(|| world.get_text(*object_id).and_then(|v| v.get_param(key)))
            .or_else(|| world.get_shape(*object_id).and_then(|v| v.get_param(key)))
            .unwrap_or_default(),
        TrackTarget::Effect {
            object_id,
            effect_index,
            key,
        } => world
            .get_effects(*object_id)
            .get(*effect_index)
            .and_then(|effect| effect.params.get(key))
            .and_then(|param| match param.static_value {
                Value::Number(value) => Some(value),
                _ => None,
            })
            .unwrap_or_default(),
    }
}

pub fn start_only(world: &EcsWorld, target: &TrackTarget) -> Vec<Keyframe> {
    let (start, _) = clip_bounds(world, target);
    vec![new_keyframe(
        start,
        base_value(world, target),
        &EasingPayload::linear(),
    )]
}

pub fn with_end(
    world: &EcsWorld,
    target: &TrackTarget,
    track: &[Keyframe],
) -> Option<Vec<Keyframe>> {
    let (_, clip_end) = clip_bounds(world, target);
    let mut keys = track.to_vec();
    keys.add_end(clip_end).ok()?;
    Some(keys)
}

pub fn seed_start(
    world: &mut EcsWorld,
    target: &TrackTarget,
    clip_start: i32,
    base_value: f32,
) -> Vec<Keyframe> {
    let mut keys = read(world, target);
    if keys.is_empty() {
        keys.seed_start(clip_start, base_value);
        write(world, target, &keys);
    }
    keys
}

pub fn edit(world: &mut EcsWorld, target: &TrackTarget, f: impl FnOnce(&mut Vec<Keyframe>)) {
    let before = read(world, target);
    let mut after = before.clone();
    f(&mut after);
    write(world, target, &after);
    push_history(world, target, before, after);
}

