pub(super) fn clip_bounds(world: &EcsWorld, id: usize) -> (i32, i32) {
    world
        .get_timeline_objects()
        .into_iter()
        .find(|o| usize::try_from(o.id).is_ok_and(|oid| oid == id))
        .map_or((0, 0), |o| (o.start_frame, o.end_frame))
}

use crate::ecs::track::Track;
use crate::ecs::types::Keyframe;

#[derive(Clone, Copy, Debug)]
pub struct Segment {
    pub start_frame: i32,
    pub end_frame: i32,
    pub start_value: f32,
    pub end_value: f32,
}

pub fn boundary_frames(track: &[Keyframe]) -> Vec<i32> {
    track.iter().map(|k| k.frame).collect()
}

pub fn resolve_segment(track: &[Keyframe], current_frame: i32, base_value: f32) -> Segment {
    let owned = track.to_vec();
    match (owned.first(), owned.locate(current_frame)) {
        (None, _) => Segment {
            start_frame: current_frame,
            end_frame: current_frame,
            start_value: base_value,
            end_value: base_value,
        },
        (Some(only), None) => Segment {
            start_frame: only.frame,
            end_frame: only.frame,
            start_value: only.value,
            end_value: only.value,
        },
        (Some(_), Some(loc)) => {
            let (a, b) = (&owned[loc.section], &owned[loc.section + 1]);
            Segment {
                start_frame: a.frame,
                end_frame: b.frame,
                start_value: a.value,
                end_value: b.value,
            }
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DragKind {
    Single,
    Suffix,
    Prefix,
}

#[derive(Clone, Copy, Debug)]
pub struct DragCommit {
    pub from: i32,
    pub to: i32,
    pub kind: DragKind,
}

impl DragCommit {
    pub fn apply(&self, track: &mut Vec<crate::ecs::types::Keyframe>) {
        use crate::ecs::track::Track;
        let Some(index) = track.index_of(self.from) else {
            return;
        };
        let inner_last = track.len().saturating_sub(2);
        let delta = self.to - self.from;
        let _ = match self.kind {
            DragKind::Single => track.move_point(index, self.to).map(|_| ()),
            DragKind::Suffix => track.move_range(index, inner_last, delta).map(|_| ()),
            DragKind::Prefix => track.move_range(1, index, delta).map(|_| ()),
        };
    }
}

pub struct TrackOutcome {
    pub point_clicked: Option<i32>,
    pub add_point: Option<i32>,
    pub remove_point: Option<i32>,
    pub drag_committed: Option<DragCommit>,
    pub equalize: bool,
}

impl TrackOutcome {
    fn empty() -> Self {
        Self {
            point_clicked: None,
            add_point: None,
            remove_point: None,
            drag_committed: None,
            equalize: false,
        }
    }
}

const POINT_RADIUS: f32 = 4.0;
const HEIGHT: f32 = 12.0;

static DRAG_ORIGIN: std::sync::Mutex<Option<std::collections::HashMap<egui::Id, i32>>> =
    std::sync::Mutex::new(None);

static CONTEXT_HIT: std::sync::Mutex<
    Option<std::collections::HashMap<egui::Id, (Option<(usize, i32, f32)>, f32)>>,
> = std::sync::Mutex::new(None);

pub fn keyframe_track(
    ui: &mut egui::Ui,
    id_source: impl std::hash::Hash + std::fmt::Debug,
    boundary_frames: &[i32],
    clip_start: i32,
    clip_end: i32,
    current_frame: i32,
    segment_start: i32,
    segment_end: i32,
    is_real: impl Fn(i32) -> bool,
) -> TrackOutcome {
    keyframe_track_colored(
        ui,
        id_source,
        boundary_frames,
        clip_start,
        clip_end,
        current_frame,
        segment_start,
        segment_end,
        |_| None,
        is_real,
    )
}

pub fn keyframe_track_colored(
    ui: &mut egui::Ui,
    id_source: impl std::hash::Hash + std::fmt::Debug,
    boundary_frames: &[i32],
    clip_start: i32,
    clip_end: i32,
    current_frame: i32,
    segment_start: i32,
    segment_end: i32,
    marker_color: impl Fn(i32) -> Option<egui::Color32>,
    is_real: impl Fn(i32) -> bool,
) -> TrackOutcome {
    let track_id = ui.make_persistent_id(id_source);
    let mut out = TrackOutcome::empty();
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), HEIGHT),
        egui::Sense::click_and_drag(),
    );
    let span = (clip_end - clip_start).max(1) as f32;
    let frac = |f: i32| ((f - clip_start) as f32 / span).clamp(0.0, 1.0);
    let x_at = |f: i32| rect.left() + rect.width() * frac(f);
    let frame_at = |x: f32| -> i32 {
        let t = ((x - rect.left()) / rect.width().max(1.0)).clamp(0.0, 1.0);
        clip_start + (t * span + 0.5) as i32
    };

    let painter = ui.painter();
    painter.rect_filled(rect, 2.0, egui::Color32::from_rgb(0x13, 0x13, 0x18));
    painter.rect_stroke(
        rect,
        2.0,
        egui::Stroke::new(1.0, egui::Color32::from_rgb(0x24, 0x24, 0x2c)),
        egui::StrokeKind::Outside,
    );

    let seg_rect = egui::Rect::from_min_max(
        egui::pos2(x_at(segment_start), rect.top()),
        egui::pos2(x_at(segment_end), rect.bottom()),
    );
    painter.rect_filled(
        seg_rect,
        0.0,
        egui::Color32::from_rgba_unmultiplied(0x2a, 0x4d, 0xb8, 90),
    );

    let cx = x_at(current_frame);
    painter.line_segment(
        [egui::pos2(cx, rect.top()), egui::pos2(cx, rect.bottom())],
        egui::Stroke::new(1.0, egui::Color32::from_rgb(0xe8, 0xe8, 0xee)),
    );

    let last = boundary_frames.len().saturating_sub(1);
    let mut origins = DRAG_ORIGIN.lock().unwrap();
    let origins = origins.get_or_insert_with(std::collections::HashMap::new);
    if !response.dragged() && !response.drag_started() && !response.drag_stopped() {
        origins.remove(&track_id);
    }
    let dragging_origin = origins.get(&track_id).copied();
    let drag_preview_x = dragging_origin.and_then(|_| {
        if response.dragged() {
            response
                .interact_pointer_pos()
                .map(|p| p.x.clamp(rect.left(), rect.right()))
        } else {
            None
        }
    });

    let mut nearest: Option<(usize, i32, f32)> = None;
    for (idx, &f) in boundary_frames.iter().enumerate() {
        let is_endpoint = idx == 0 || idx == last;
        let is_dragged_point = dragging_origin == Some(f);
        let px = if is_dragged_point {
            drag_preview_x.unwrap_or_else(|| x_at(f))
        } else {
            x_at(f)
        };
        let color = match marker_color(f) {
            Some(c) => c,
            None if is_endpoint => egui::Color32::from_rgb(0x6a, 0x6a, 0x76),
            None if is_dragged_point => egui::Color32::from_rgb(0x8a, 0xab, 0xff),
            None => egui::Color32::from_rgb(0x3a, 0x6d, 0xf0),
        };
        painter.circle_filled(egui::pos2(px, rect.center().y), POINT_RADIUS, color);
        if dragging_origin.is_none() {
            if let Some(pos) = response.hover_pos().or(response.interact_pointer_pos()) {
                let d = (pos.x - px).abs();
                if d <= POINT_RADIUS * 2.5 && nearest.map(|(_, _, nd)| d < nd).unwrap_or(true) {
                    nearest = Some((idx, f, d));
                }
            }
        }
    }
    let drag_locked = |idx: usize, _f: i32| idx == 0 || idx == last;
    let deletable = |idx: usize, f: i32| idx != 0 && is_real(f);

    if response.drag_started() {
        if let Some((idx, f, _)) = nearest {
            if !drag_locked(idx, f) {
                origins.insert(track_id, f);
            }
        }
    }
    if response.drag_stopped() {
        if let (Some(origin), Some(pos)) =
            (origins.remove(&track_id), response.interact_pointer_pos())
        {
            let to = frame_at(pos.x).clamp(clip_start, clip_end);
            if to != origin {
                let (shift, ctrl) = ui.input(|i| (i.modifiers.shift, i.modifiers.command));
                let kind = match (shift, ctrl) {
                    (true, true) => DragKind::Prefix,
                    (true, false) => DragKind::Suffix,
                    _ => DragKind::Single,
                };
                out.drag_committed = Some(DragCommit {
                    from: origin,
                    to,
                    kind,
                });
            }
        }
    }
    if response.clicked() && !origins.contains_key(&track_id) {
        if let Some(pos) = response.interact_pointer_pos() {
            out.point_clicked = match nearest {
                Some((_, f, _)) => Some(f),
                None => Some(frame_at(pos.x)),
            };
        }
    }

    let equalize_cell = std::cell::Cell::new(false);
    let add_cell = std::cell::Cell::new(None);
    let remove_cell = std::cell::Cell::new(None);

    if response.secondary_clicked() {
        if let Some(pos) = response.interact_pointer_pos() {
            let mut hits = CONTEXT_HIT.lock().unwrap();
            let hits = hits.get_or_insert_with(std::collections::HashMap::new);
            hits.insert(track_id, (nearest, pos.x));
        }
    }

    elegance::ContextMenu::new(track_id).show(&response, |ui| {
        let hits = CONTEXT_HIT.lock().unwrap();
        let Some(&(fixed_nearest, pos_x)) = hits.as_ref().and_then(|m| m.get(&track_id)) else {
            return;
        };
        match fixed_nearest {
            Some((idx, f, d)) if d <= POINT_RADIUS * 2.5 && deletable(idx, f) => {
                if ui
                    .add(elegance::Button::new(t!("キーフレーム削除")))
                    .clicked()
                {
                    remove_cell.set(Some(f));
                    ui.close();
                }
            }
            _ => {
                let f = frame_at(pos_x);
                if ui
                    .add(elegance::Button::new(t!("キーフレーム追加")))
                    .clicked()
                {
                    add_cell.set(Some(f));
                    ui.close();
                }
            }
        }
        if boundary_frames.len() > 2
            && ui
                .add(elegance::Button::new(t!("中間点を時間で均等配置")))
                .clicked()
        {
            equalize_cell.set(true);
            ui.close();
        }
    });
    out.equalize = equalize_cell.get();
    out.add_point = add_cell.get();
    out.remove_point = remove_cell.get();
    out
}

use crate::app::state::{self as app_state, SharedAppState};
use crate::ecs::SceneSettings;
use crate::project;
use crate::ui::system_settings::fields::{
    choice_field, float_text_field, int_text_field, name_field, toggle_field,
};
use crate::ui::ui_ext::UiExt;
use egui::{Context, Ui};

pub struct SceneSettingsWindow {
    pub open: bool,
    is_creation_mode: bool,
    target_scene_id: i32,

    scene_name: String,
    scene_width: i32,
    scene_height: i32,
    scene_fps: f32,

    enable_snap: bool,
    magnetic_snap_range: i32,
    grid_mode: i32,
    grid_bpm: f32,
    grid_offset: f32,
    grid_interval: i32,
    grid_subdivision: i32,
}

impl SceneSettingsWindow {
    pub fn new() -> Self {
        Self {
            open: false,
            is_creation_mode: true,
            target_scene_id: -1,
            scene_name: "Scene".into(),
            scene_width: 1920,
            scene_height: 1080,
            scene_fps: 30.0,
            enable_snap: true,
            magnetic_snap_range: 10,
            grid_mode: 0,
            grid_bpm: 120.0,
            grid_offset: 0.0,
            grid_interval: 10,
            grid_subdivision: 4,
        }
    }

    pub fn open_for_create(&mut self, state: &SharedAppState) {
        let world_holder = app_state::active_world(state);
        let world = world_holder.lock().unwrap();
        let project = world.get_project();
        let count = world.scenes().len();
        drop(world);

        let settings_holder = app_state::settings_world(state);
        let system_settings = settings_holder.lock().unwrap().get_system_settings();
        let defaults = crate::ecs::resources::SceneMeta::new_with_defaults(
            -1,
            "",
            system_settings.default_snap,
            system_settings.magnetic_snap_range,
        );

        self.is_creation_mode = true;
        self.target_scene_id = -1;
        self.scene_name = format!("Scene {}", count + 1);
        self.scene_width = project.width as i32;
        self.scene_height = project.height as i32;
        self.scene_fps = project.fps as f32;
        self.enable_snap = defaults.enable_snap;
        self.magnetic_snap_range = defaults.magnetic_snap_range;
        self.grid_mode = defaults.grid_mode;
        self.grid_bpm = defaults.grid_bpm;
        self.grid_offset = defaults.grid_offset;
        self.grid_interval = defaults.grid_interval;
        self.grid_subdivision = defaults.grid_subdivision;
        self.open = true;
    }

    pub fn open_for_edit(&mut self, state: &SharedAppState, scene_id: i32) {
        let world_holder = app_state::active_world(state);
        let world = world_holder.lock().unwrap();
        let Some(s) = world.get_scene(scene_id) else {
            return;
        };
        drop(world);

        self.is_creation_mode = false;
        self.target_scene_id = scene_id;
        self.scene_name = s.name;
        self.scene_width = s.width as i32;
        self.scene_height = s.height as i32;
        self.scene_fps = s.fps as f32;
        self.enable_snap = s.enable_snap;
        self.magnetic_snap_range = s.magnetic_snap_range;
        self.grid_mode = s.grid_mode;
        self.grid_bpm = s.grid_bpm;
        self.grid_offset = s.grid_offset;
        self.grid_interval = s.grid_interval;
        self.grid_subdivision = s.grid_subdivision;
        self.open = true;
    }

    fn confirm(&mut self, state: &SharedAppState) {
        let settings = SceneSettings {
            name: self.scene_name.clone(),
            width: self.scene_width.max(1) as u32,
            height: self.scene_height.max(1) as u32,
            fps: self.scene_fps.max(1.0) as u32,
            grid_mode: self.grid_mode,
            grid_bpm: self.grid_bpm,
            grid_offset: self.grid_offset,
            grid_interval: self.grid_interval,
            grid_subdivision: self.grid_subdivision,
            enable_snap: self.enable_snap,
            magnetic_snap_range: self.magnetic_snap_range,
        };

        let world_holder = app_state::active_world(state);
        app_state::snapshot_before_edit(state);
        let mut world = world_holder.lock().unwrap();

        let scene_id = if self.is_creation_mode {
            let id = world.add_scene(settings.name.clone());
            world.switch_scene(id);
            id
        } else {
            self.target_scene_id
        };
        world.update_scene_settings(scene_id, settings);
        let _ = project::save_from_world(&world);
        drop(world);

        self.open = false;
    }

    pub fn show(&mut self, ctx: &Context, ui: &mut Ui, state: &SharedAppState) -> bool {
        if !self.open {
            return false;
        }
        let title = if self.is_creation_mode {
            t!("新規シーン作成")
        } else {
            t!("シーン設定")
        };
        let mut confirmed = false;
        let mut close_requested = false;

        ctx.send_viewport_cmd(egui::ViewportCommand::Title(title));

        egui::Panel::bottom("add_scene_footer").show(ui, |ui| {
            ui.footer_bar(|ui| {
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if ui.button(t!("OK")).clicked() {
                        confirmed = true;
                    }
                    if ui.button(t!("キャンセル")).clicked() {
                        close_requested = true;
                    }
                });
            });
        });

        egui::CentralPanel::default().show(ui, |ui| {
            ui.page_content(|ui| {
                ui.section(t!("基本設定"), |ui| {
                    egui::Grid::new("scene_settings_basic")
                        .num_columns(2)
                        .show(ui, |ui| {
                            name_field(ui, "シーン名:", &mut self.scene_name);
                            int_text_field(ui, "幅:", &mut self.scene_width, 1, 8000);
                            int_text_field(ui, "高さ:", &mut self.scene_height, 1, 8000);
                            float_text_field(ui, "FPS:", &mut self.scene_fps, 1.0, 1000.0);
                        });
                });

                ui.section(t!("編集とスナップ"), |ui| {
                    egui::Grid::new("scene_settings_snap")
                        .num_columns(2)
                        .show(ui, |ui| {
                            toggle_field(ui, "スナップを有効にする", &mut self.enable_snap);
                            int_text_field(
                                ui,
                                "磁力スナップ範囲:",
                                &mut self.magnetic_snap_range,
                                1,
                                100,
                            );
                            let grid_mode_options = [
                                "自動 (秒/フレーム)".to_string(),
                                "BPM (音楽)".to_string(),
                                "フレーム数固定".to_string(),
                            ];
                            choice_field(
                                ui,
                                "グリッドモード:",
                                &grid_mode_options,
                                &mut self.grid_mode,
                            );
                        });
                });

                if self.grid_mode == 1 {
                    ui.section(t!("BPM設定"), |ui| {
                        egui::Grid::new("scene_settings_bpm")
                            .num_columns(2)
                            .show(ui, |ui| {
                                float_text_field(ui, "BPM:", &mut self.grid_bpm, 1.0, 999.0);
                                int_text_field(
                                    ui,
                                    "拍子 (分割数):",
                                    &mut self.grid_subdivision,
                                    1,
                                    32,
                                );
                                float_text_field(
                                    ui,
                                    "オフセット (秒):",
                                    &mut self.grid_offset,
                                    -3600.0,
                                    3600.0,
                                );
                            });
                    });
                }

                if self.grid_mode == 2 {
                    ui.section(t!("フレーム設定"), |ui| {
                        egui::Grid::new("scene_settings_frame")
                            .num_columns(2)
                            .show(ui, |ui| {
                                int_text_field(
                                    ui,
                                    "間隔 (Frames):",
                                    &mut self.grid_interval,
                                    1,
                                    1000,
                                );
                            });
                    });
                }
            });
        });

        if confirmed {
            self.confirm(state);
            return true;
        }
        self.open = !close_requested;
        false
    }
}

use crate::infra::localization::tr;
use crate::ui::ui_ext::fixed_style;
use egui::Ui;
use egui_taffy::taffy;
use egui_taffy::{TuiBuilderLogic, tui};
use elegance::{Select, Slider, Switch, TextInput};

pub fn field_height(ui: &Ui) -> f32 {
    ui.text_style_height(&egui::TextStyle::Body) + 2.0 * ui.spacing().button_padding.y
}

fn field_label(ui: &mut Ui, label: &str) {
    let height = field_height(ui);
    let width = ui.available_width();
    let style = taffy::Style {
        align_items: Some(taffy::AlignItems::Center),
        ..fixed_style(width, height)
    };
    tui(ui, ui.id().with(("field_label", label)))
        .style(style)
        .show(|tui| {
            tui.ui(|ui| {
                ui.label(tr(label));
            });
        });
}

pub fn name_field(ui: &mut Ui, label: &str, value: &mut String) -> bool {
    field_label(ui, label);
    let changed = ui
        .add_sized(
            egui::vec2(ui.available_width(), field_height(ui)),
            TextInput::new(value),
        )
        .changed();
    ui.end_row();
    changed
}

pub fn toggle_field(ui: &mut Ui, label: &str, value: &mut bool) -> bool {
    field_label(ui, label);
    let changed = ui.add(Switch::new(value, "")).changed();
    ui.end_row();
    changed
}

pub fn int_field(ui: &mut Ui, label: &str, value: &mut i32, min: i32, max: i32) -> bool {
    field_label(ui, label);
    let changed = ui.add(Slider::new(value, min..=max)).changed();
    *value = (*value).clamp(min, max);
    ui.end_row();
    changed
}

pub fn int_text_field(ui: &mut Ui, label: &str, value: &mut i32, min: i32, max: i32) -> bool {
    field_label(ui, label);
    let id = ui.id().with(label);
    let mut buf = ui
        .data_mut(|d| d.get_temp::<String>(id))
        .unwrap_or_else(|| value.to_string());
    let resp = ui.add_sized(
        egui::vec2(ui.available_width(), field_height(ui)),
        TextInput::new(&mut buf),
    );
    let mut changed = false;
    if resp.changed()
        && let Ok(parsed) = buf.trim().parse::<i32>()
    {
        let clamped = parsed.clamp(min, max);
        if clamped != *value {
            *value = clamped;
            changed = true;
        }
    }
    if !resp.has_focus() {
        buf = value.to_string();
    }
    ui.data_mut(|d| d.insert_temp(id, buf));
    ui.end_row();
    changed
}

pub fn float_text_field(ui: &mut Ui, label: &str, value: &mut f32, min: f32, max: f32) -> bool {
    field_label(ui, label);
    let id = ui.id().with(label);
    let mut buf = ui
        .data_mut(|d| d.get_temp::<String>(id))
        .unwrap_or_else(|| value.to_string());
    let resp = ui.add_sized(
        egui::vec2(ui.available_width(), field_height(ui)),
        TextInput::new(&mut buf),
    );
    let mut changed = false;
    if resp.changed()
        && let Ok(parsed) = buf.trim().parse::<f32>()
        && parsed.is_finite()
    {
        let clamped = parsed.clamp(min, max);
        if clamped != *value {
            *value = clamped;
            changed = true;
        }
    }
    if !resp.has_focus() {
        buf = value.to_string();
    }
    ui.data_mut(|d| d.insert_temp(id, buf));
    ui.end_row();
    changed
}

pub fn choice_field(ui: &mut Ui, label: &str, options: &[String], selected: &mut i32) -> bool {
    field_label(ui, label);
    let mut changed = false;
    let height = field_height(ui);
    let width = ui.available_width();
    let style = taffy::Style {
        align_items: Some(taffy::AlignItems::Center),
        ..fixed_style(width, height)
    };
    tui(ui, ui.id().with(("choice_field", label)))
        .style(style)
        .show(|tui| {
            tui.ui(|ui| {
                let mut idx = (*selected).max(0) as usize;
                let resp = ui.add(
                    Select::new((ui.id(), "choice_field"), &mut idx)
                        .options(options.iter().enumerate().map(|(i, o)| (i, tr(o)))),
                );
                if resp.changed() {
                    *selected = idx as i32;
                    changed = true;
                }
            });
        });
    ui.end_row();
    changed
}

use crate::ecs::resources::SystemSettingsResource;
use std::path::PathBuf;

#[derive(Clone, Default)]
pub(super) enum ScanStatus {
    #[default]
    Idle,
    Scanning,
    Done,
    Error(String),
}

pub(super) fn category_label(index: usize) -> &'static str {
    super::window::CATEGORIES[index].0
}

pub(super) fn hw_backend_display_name(id: &str) -> String {
    match id {
        "cuda" => "CUDA (NVIDIA)".to_owned(),
        "qsv" => "QSV (Intel)".to_owned(),
        "d3d11va" => "D3D11VA (Windows)".to_owned(),
        "d3d12va" => "D3D12VA (Windows)".to_owned(),
        "dxva2" => "DXVA2 (Windows)".to_owned(),
        "videotoolbox" => "VideoToolbox (macOS)".to_owned(),
        "vulkan" => "Vulkan".to_owned(),
        "opencl" => "OpenCL".to_owned(),
        "vdpau" => "VDPAU (Linux)".to_owned(),
        "amf" => "AMF (AMD)".to_owned(),
        "mediacodec" => "MediaCodec (Android)".to_owned(),
        "drm" => "DRM (Linux)".to_owned(),
        "vaapi" => "VAAPI (Linux)".to_owned(),
        other => other.to_owned(),
    }
}

pub(super) fn settings_path() -> PathBuf {
    std::env::current_exe()
        .ok()
        .and_then(|p| {
            p.parent()
                .map(|d| d.join("settings").join("system-settings.npb"))
        })
        .unwrap_or_else(|| PathBuf::from("settings/system-settings.npb"))
}

pub(super) fn save_to_disk(s: &SystemSettingsResource) -> std::io::Result<()> {
    let path = settings_path();
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let encoded = crate::project::schema::encode_schema(s);
    std::fs::write(path, encoded)
}

pub(crate) fn load_from_disk() -> Option<SystemSettingsResource> {
    let bytes = std::fs::read(settings_path()).ok()?;
    crate::project::schema::decode_schema::<SystemSettingsResource>(&bytes).ok()
}

pub(super) fn easing_engine_ids_and_names() -> (Vec<String>, Vec<String>) {
    let ids = crate::easings::loader::registry()
        .iter()
        .map(|e| e.id.clone())
        .collect();
    let names = crate::easings::loader::registry()
        .iter()
        .map(|e| e.name.clone())
        .collect();
    (ids, names)
}

pub(super) fn index_of(ids: &[String], id: &str) -> i32 {
    ids.iter().position(|i| i == id).map_or(0, |i| i as i32)
}

