    pub(super) fn toggle_layer_visible(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        layer: i32,
    ) {
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let visible = world
            .layer_states()
            .get(layer as usize)
            .map_or(true, |s| s.0);
        world.set_layer_visible(layer as usize, !visible);
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn toggle_layer_locked(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        layer: i32,
    ) {
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let locked = world
            .layer_states()
            .get(layer as usize)
            .map_or(false, |s| s.1);
        world.set_layer_locked(layer as usize, !locked);
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn switch_scene_tab(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        id: i32,
    ) {
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        if world.switch_scene(id) {
            drop(world);
            self.selected_ids.clear();
            preview_panel.borrow_mut().refresh_total_frames(state);
        }
    }

    pub(super) fn cut_selection_range(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        let Some((range_start, range_end)) = self.select_range else {
            return;
        };
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        remove_range_content(&mut world, range_start, range_end);
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn cut_selection_range_and_pack(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        let Some((range_start, range_end)) = self.select_range else {
            return;
        };
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        remove_range_content(&mut world, range_start, range_end);
        let shift = range_end - range_start;
        let followers: Vec<(usize, i32, i32)> = world
            .get_timeline_objects()
            .iter()
            .filter(|o| o.start_frame >= range_end)
            .map(|o| (o.id as usize, o.start_frame, o.layer))
            .collect();
        for (id, start, layer) in followers {
            world.move_object(id, start - shift, layer);
        }
        self.select_range = None;
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn pack_left(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        ids: &[usize],
    ) {
        if ids.is_empty() {
            return;
        }
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let objects = world.get_timeline_objects();
        for &id in ids {
            let Some(target) = objects.iter().find(|o| o.id as usize == id) else {
                continue;
            };
            let prev_end = objects
                .iter()
                .filter(|o| o.layer == target.layer && o.id as usize != id)
                .filter(|o| o.end_frame <= target.start_frame)
                .map(|o| o.end_frame)
                .max()
                .unwrap_or(0);
            world.move_object(id, prev_end, target.layer);
        }
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn cut_and_pack(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        ids: &[usize],
    ) {
        if ids.is_empty() {
            return;
        }
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        let removed: Vec<(i32, i32, i32)> = world
            .get_timeline_objects()
            .iter()
            .filter(|o| ids.contains(&(o.id as usize)))
            .map(|o| (o.start_frame, o.end_frame, o.layer))
            .collect();
        let docs = world.cut_objects(ids);
        drop(world);
        app_state::set_clipboard(state, docs);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        for (start, end, layer) in removed {
            let shift = end - start;
            let followers: Vec<(usize, i32)> = world
                .get_timeline_objects()
                .iter()
                .filter(|o| o.layer == layer && o.start_frame >= end)
                .map(|o| (o.id as usize, o.start_frame))
                .collect();
            for (id, follower_start) in followers {
                world.move_object(id, follower_start - shift, layer);
            }
        }
        for &id in ids {
            self.selected_ids.remove(&(id as i32));
        }
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn extract_selection(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        ids: &[usize],
    ) {
        let Some((range_start, range_end)) = self.select_range else {
            return;
        };
        if ids.is_empty() {
            return;
        }
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        for &id in ids {
            trim_object_to_range(&mut world, id, range_start, range_end);
        }
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn close_scene_tab(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        id: i32,
    ) {
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        if world.scenes().len() > 1 {
            if world.remove_scene(id) {
                drop(world);
                preview_panel.borrow_mut().refresh_total_frames(state);
            } else {
                eprintln!(
                    "{}",
                    tr("[NeoUtl] シーン削除を拒否: id={id}（他シーンのSceneObjectから参照中）")
                        .replace("{id}", &id.to_string())
                );
            }
        }
    }
}

use super::util::{brighten, darken, readable_text_color};
use super::{
    ClipDrag, DragMode, HANDLE_WIDTH, KEYFRAME_SIZE, KeyframeDrag, LAYER_HEIGHT, TimelineWindow,
};
use crate::app::state::SharedAppState;
use crate::ui::preview::PreviewPanel;
use crate::ui::types::TimelineObject;
use egui::{Color32, Painter, Pos2, Rect, Sense, Stroke, Vec2};
use std::cell::RefCell;
use std::rc::Rc;

const GROUP_CURTAIN_COLOR: Color32 = Color32::from_rgb(90, 140, 220);
const CLIP_CURTAIN_COLOR: Color32 = Color32::from_rgb(220, 120, 60);

fn draw_group_curtain(painter: &Painter, ui: &egui::Ui, rect: Rect) {
    let _ = ui;
    painter.rect_filled(rect, 0.0, GROUP_CURTAIN_COLOR.gamma_multiply(0.18));
    painter.rect_stroke(
        rect,
        0.0,
        Stroke::new(1.0, GROUP_CURTAIN_COLOR.gamma_multiply(0.55)),
        egui::StrokeKind::Inside,
    );
}

fn draw_clip_curtain(painter: &Painter, ui: &egui::Ui, rect: Rect) {
    let _ = ui;
    painter.rect_filled(rect, 0.0, CLIP_CURTAIN_COLOR.gamma_multiply(0.18));
    painter.rect_stroke(
        rect,
        0.0,
        Stroke::new(1.0, CLIP_CURTAIN_COLOR.gamma_multiply(0.55)),
        egui::StrokeKind::Inside,
    );
}

impl TimelineWindow {
    pub(super) fn clip_ui(
        &mut self,
        ui: &mut egui::Ui,
        painter: &Painter,
        view_rect: Rect,
        state: &SharedAppState,
        _preview_panel: &Rc<RefCell<PreviewPanel>>,
        _props_weak: &(),
        obj: &TimelineObject,
        locked: bool,
        total_frames: i32,
        layer_count: i32,
    ) {
        let _ = total_frames;
        let (preview_start, preview_end, preview_layer) = match &self.drag {
            Some(d) if d.id == obj.id => (d.preview_start, d.preview_end, d.preview_layer),
            _ => (obj.start_frame, obj.end_frame, obj.layer),
        };

        let x = view_rect.min.x + self.frame_to_x(preview_start);
        let h = LAYER_HEIGHT * 0.75;
        let y = view_rect.min.y + self.layer_to_y(preview_layer) + (LAYER_HEIGHT - h) * 0.5;
        let w = ((preview_end - preview_start) as f32 * self.zoom_scale).max(4.0);
        let clip_rect = Rect::from_min_size(Pos2::new(x, y), Vec2::new(w, h));
        if clip_rect.max.x < view_rect.min.x || clip_rect.min.x > view_rect.max.x {
            return;
        }
        if clip_rect.max.y < view_rect.min.y || clip_rect.min.y > view_rect.max.y {
            return;
        }

        if obj.group_layer_count_down > 0 {
            let curtain_rect = Rect::from_min_size(
                Pos2::new(clip_rect.min.x, clip_rect.min.y + h),
                Vec2::new(w, obj.group_layer_count_down as f32 * LAYER_HEIGHT),
            );
            draw_group_curtain(painter, ui, curtain_rect);
        }
        if obj.group_layer_count_up > 0 {
            let up_height = obj.group_layer_count_up as f32 * LAYER_HEIGHT;
            let curtain_rect = Rect::from_min_size(
                Pos2::new(clip_rect.min.x, clip_rect.min.y - up_height),
                Vec2::new(w, up_height),
            );
            draw_group_curtain(painter, ui, curtain_rect);
        }
        if obj.clip_layer_count_down > 0 {
            let curtain_rect = Rect::from_min_size(
                Pos2::new(clip_rect.min.x, clip_rect.min.y + h),
                Vec2::new(w, obj.clip_layer_count_down as f32 * LAYER_HEIGHT),
            );
            draw_clip_curtain(painter, ui, curtain_rect);
        }
        if obj.clip_layer_count_up > 0 {
            let up_height = obj.clip_layer_count_up as f32 * LAYER_HEIGHT;
            let curtain_rect = Rect::from_min_size(
                Pos2::new(clip_rect.min.x, clip_rect.min.y - up_height),
                Vec2::new(w, up_height),
            );
            draw_clip_curtain(painter, ui, curtain_rect);
        }

        let palette = [
            Color32::from_rgb(0x2a, 0x4d, 0xb8),
            Color32::from_rgb(0x25, 0x6e, 0x3c),
            Color32::from_rgb(0x6a, 0x2d, 0xb8),
            Color32::from_rgb(0xb8, 0x86, 0x2a),
            Color32::from_rgb(0x2a, 0xb8, 0xa8),
            Color32::from_rgb(0xb8, 0x2a, 0x5f),
        ];
        let base = if !obj.kind_known {
            Color32::from_rgb(0x5a, 0x5a, 0x5a)
        } else {
            palette[(obj.kind.max(0) as usize) % palette.len()]
        };
        let color = if obj.selected {
            brighten(base, 0.5)
        } else {
            base
        };
        let visuals = ui.visuals().clone();
        let label_color = readable_text_color(color);
        let keyframe_color = visuals.warn_fg_color;

        if obj.selected {
            painter.rect_filled(clip_rect, 0.0, color);
        } else {
            let mut mesh = egui::Mesh::default();
            let left_color = darken(color, 0.5);
            mesh.colored_vertex(clip_rect.left_top(), left_color);
            mesh.colored_vertex(clip_rect.left_bottom(), left_color);
            mesh.colored_vertex(clip_rect.right_top(), color);
            mesh.colored_vertex(clip_rect.right_bottom(), color);
            mesh.add_triangle(0, 1, 2);
            mesh.add_triangle(1, 3, 2);
            painter.add(mesh);
        }

        if obj.has_waveform && self.show_waveform {
            if let Some(tex) = obj.waveform {
                let wx = clip_rect.min.x
                    + 3.0
                    + (obj.waveform_origin_frame - preview_start) as f32 * self.zoom_scale;
                let ww = (obj.waveform_duration_frames as f32 * self.zoom_scale).max(1.0);
                let wave_rect = Rect::from_min_size(
                    Pos2::new(wx, clip_rect.min.y + 3.0),
                    Vec2::new(ww, (clip_rect.height() - 6.0).max(1.0)),
                );
                let tint = if obj.selected {
                    Color32::from_white_alpha(230)
                } else {
                    Color32::from_white_alpha(166)
                };
                let clipped = painter.with_clip_rect(clip_rect.intersect(view_rect));
                clipped.image(
                    tex,
                    wave_rect,
                    Rect::from_min_max(Pos2::ZERO, Pos2::new(1.0, 1.0)),
                    tint,
                );
            }
        }

        {
            let text_clip = clip_rect.intersect(view_rect);
            if text_clip.width() > 0.0 && text_clip.height() > 0.0 {
                let label_x = clip_rect.min.x.max(view_rect.min.x) + 6.0;
                let label_x = label_x.min(clip_rect.max.x - 2.0);
                painter.with_clip_rect(text_clip).text(
                    Pos2::new(label_x, clip_rect.center().y),
                    egui::Align2::LEFT_CENTER,
                    &obj.label,
                    egui::FontId::proportional(10.0),
                    label_color,
                );
            }
        }

        for &f in &obj.keyframe_frames {
            let dragged_delta = match &self.kdrag {
                Some(k) if k.id == obj.id && k.frame == f => k.delta_frames,
                _ => 0,
            };
            let span = (obj.end_frame - obj.start_frame).max(1) as f32;
            let kx = clip_rect.min.x
                + (f + dragged_delta - obj.start_frame) as f32 * clip_rect.width() / span;
            let ky = clip_rect.center().y;
            let marker_rect = Rect::from_center_size(Pos2::new(kx, ky), Vec2::splat(KEYFRAME_SIZE));
            painter.rect_filled(marker_rect, 0.0, keyframe_color);
            painter.rect_stroke(
                marker_rect,
                0.0,
                Stroke::new(1.0, darken(keyframe_color, 0.4)),
                egui::StrokeKind::Outside,
            );

            let kid = ui.id().with(("keyframe", obj.id, f));
            let kresp = ui.interact(marker_rect, kid, Sense::click_and_drag());
            if !locked {
                if kresp.drag_started() {
                    if let Some(pos) = kresp.interact_pointer_pos() {
                        self.kdrag = Some(KeyframeDrag {
                            id: obj.id,
                            frame: f,
                            press: pos,
                            delta_frames: 0,
                        });
                    }
                }
                if kresp.dragged() {
                    if let (Some(pos), Some(kdrag)) =
                        (kresp.interact_pointer_pos(), &mut self.kdrag)
                    {
                        kdrag.delta_frames =
                            ((pos.x - kdrag.press.x) / self.zoom_scale).round() as i32;
                    }
                }
                if kresp.drag_stopped() {
                    if let Some(kdrag) = self.kdrag.take() {
                        if kdrag.delta_frames != 0 {
                            let new_frame =
                                (f + kdrag.delta_frames).clamp(obj.start_frame, obj.end_frame);
                            self.keyframe_moved(state, obj.id, f, new_frame);
                        } else if kresp.clicked() {
                        }
                    }
                }
            }
        }

        let body_rect = Rect::from_min_size(
            Pos2::new(clip_rect.min.x + HANDLE_WIDTH, clip_rect.min.y),
            Vec2::new(
                (clip_rect.width() - 2.0 * HANDLE_WIDTH).max(0.0),
                clip_rect.height(),
            ),
        );
        let left_rect =
            Rect::from_min_size(clip_rect.min, Vec2::new(HANDLE_WIDTH, clip_rect.height()));
        let right_rect = Rect::from_min_size(
            Pos2::new(clip_rect.max.x - HANDLE_WIDTH, clip_rect.min.y),
            Vec2::new(HANDLE_WIDTH, clip_rect.height()),
        );

        let left_id = ui.id().with(("clip-left", obj.id));
        let left_resp = ui.interact(left_rect, left_id, Sense::click_and_drag());
        let right_id = ui.id().with(("clip-right", obj.id));
        let right_resp = ui.interact(right_rect, right_id, Sense::click_and_drag());
        let body_id = ui.id().with(("clip-body", obj.id));
        let body_resp = ui.interact(body_rect, body_id, Sense::click_and_drag());

        if locked {
            return;
        }

        if left_resp.hovered() || left_resp.dragged() {
            ui.ctx().set_cursor_icon(egui::CursorIcon::ResizeWest);
        }
        if right_resp.hovered() || right_resp.dragged() {
            ui.ctx().set_cursor_icon(egui::CursorIcon::ResizeEast);
        }
        if body_resp.hovered() || body_resp.dragged() {
            ui.ctx().set_cursor_icon(if body_resp.dragged() {
                egui::CursorIcon::Grabbing
            } else {
                egui::CursorIcon::Grab
            });
        }

        if left_resp.drag_started() {
            if let Some(pos) = left_resp.interact_pointer_pos() {
                self.drag = Some(ClipDrag {
                    id: obj.id,
                    mode: DragMode::ResizeLeft,
                    press: pos,
                    start_frame: obj.start_frame,
                    end_frame: obj.end_frame,
                    layer: obj.layer,
                    duration: obj.end_frame - obj.start_frame,
                    preview_start: obj.start_frame,
                    preview_end: obj.end_frame,
                    preview_layer: obj.layer,
                });
            }
        }
        if right_resp.drag_started() {
            if let Some(pos) = right_resp.interact_pointer_pos() {
                self.drag = Some(ClipDrag {
                    id: obj.id,
                    mode: DragMode::ResizeRight,
                    press: pos,
                    start_frame: obj.start_frame,
                    end_frame: obj.end_frame,
                    layer: obj.layer,
                    duration: obj.end_frame - obj.start_frame,
                    preview_start: obj.start_frame,
                    preview_end: obj.end_frame,
                    preview_layer: obj.layer,
                });
            }
        }
        if body_resp.drag_started() {
            self.select_object(state, &(), obj.id, false);
            if let Some(pos) = body_resp.interact_pointer_pos() {
                self.drag = Some(ClipDrag {
                    id: obj.id,
                    mode: DragMode::Move,
                    press: pos,
                    start_frame: obj.start_frame,
                    end_frame: obj.end_frame,
                    layer: obj.layer,
                    duration: obj.end_frame - obj.start_frame,
                    preview_start: obj.start_frame,
                    preview_end: obj.end_frame,
                    preview_layer: obj.layer,
                });
            }
        }
        if body_resp.clicked() && self.drag.is_none() {
            let additive = ui.input(|i| i.modifiers.ctrl || i.modifiers.command);
            if additive {
                if self.selected_ids.contains(&obj.id) {
                    self.selected_ids.remove(&obj.id);
                } else {
                    self.selected_ids.insert(obj.id);
                }
            } else {
                self.select_object(state, &(), obj.id, false);
            }
        }
        if body_resp.secondary_clicked() {
            if !self.selected_ids.contains(&obj.id) {
                self.select_object(state, &(), obj.id, false);
            }
            if let Some(pos) = body_resp.interact_pointer_pos() {
                self.open_context_menu(ui, state, pos, obj.start_frame, obj.layer, obj.id);
            }
        }

        if let Some(drag) = &mut self.drag {
            if drag.id == obj.id {
                match drag.mode {
                    DragMode::Move => {
                        if let Some(pos) = body_resp
                            .interact_pointer_pos()
                            .or(ui.ctx().pointer_hover_pos())
                        {
                            let dx = ((pos.x - drag.press.x) / self.zoom_scale).round() as i32;
                            let dy = ((pos.y - drag.press.y) / LAYER_HEIGHT).round() as i32;
                            drag.preview_start = (drag.start_frame + dx).max(0);
                            drag.preview_end = drag.preview_start + drag.duration;
                            let max_layer = (layer_count - 1).max(0);
                            drag.preview_layer = (drag.layer + dy).clamp(0, max_layer);
                        }
                    }
                    DragMode::ResizeLeft => {
                        if let Some(pos) = left_resp
                            .interact_pointer_pos()
                            .or(ui.ctx().pointer_hover_pos())
                        {
                            let dx = ((pos.x - drag.press.x) / self.zoom_scale).round() as i32;
                            drag.preview_start =
                                (drag.start_frame + dx).clamp(0, drag.end_frame - 1);
                        }
                    }
                    DragMode::ResizeRight => {
                        if let Some(pos) = right_resp
                            .interact_pointer_pos()
                            .or(ui.ctx().pointer_hover_pos())
                        {
                            let dx = ((pos.x - drag.press.x) / self.zoom_scale).round() as i32;
                            drag.preview_end = (drag.end_frame + dx).max(drag.start_frame + 1);
                        }
                    }
                }
            }
        }
    }
}

use super::util::build_context_menu;
use super::{DragMode, MenuState, TimelineWindow};
use crate::app::state::{self as app_state, SharedAppState};
use crate::objects::registry;
use crate::ui::dialogs::DialogSet;
use crate::ui::preview::PreviewPanel;
use crate::ui::types::{ContextMenuItem, ObjectKindItem};
use egui::{Pos2, Rect};
use egui_material_icons::icons;
use std::cell::RefCell;
use std::rc::Rc;

const MENU_WIDTH: f32 = 220.0;
const ROW_HEIGHT: f32 = 24.0;

fn icon_glyph(icon: &str) -> &'static str {
    match icon {
        "scissors" => icons::ICON_CONTENT_CUT.into(),
        "copy" => icons::ICON_CONTENT_COPY.into(),
        "paste" => icons::ICON_CONTENT_PASTE.into(),
        "trash" => icons::ICON_DELETE.into(),
        "copy-plus" => icons::ICON_LIBRARY_ADD.into(),
        "circle-plus" => icons::ICON_ADD_CIRCLE.into(),
        "mouse-pointer-click" => icons::ICON_ADS_CLICK.into(),
        "list" => icons::ICON_LIST.into(),
        "grid" => icons::ICON_GRID_ON.into(),
        "audio-lines" => icons::ICON_GRAPHIC_EQ.into(),
        "eye" => icons::ICON_VISIBILITY.into(),
        "lock" => icons::ICON_LOCK.into(),
        "settings" => icons::ICON_SETTINGS.into(),
        _ => icons::ICON_CIRCLE.into(),
    }
}

pub(super) fn menu_row(
    ui: &mut egui::Ui,
    item: &ContextMenuItem,
    has_submenu: bool,
) -> egui::Response {
    let desired = egui::vec2(ui.available_width(), ROW_HEIGHT);
    let (rect, resp) = ui.allocate_exact_size(desired, egui::Sense::click());
    let resp = if item.enabled {
        resp
    } else {
        resp.on_hover_cursor(egui::CursorIcon::NotAllowed)
    };
    if ui.is_rect_visible(rect) {
        let visuals = ui.visuals();
        if item.enabled && resp.hovered() {
            ui.painter()
                .rect_filled(rect, 2.0, visuals.selection.bg_fill.gamma_multiply(0.55));
        }
        let text_color = if item.enabled {
            visuals.text_color()
        } else {
            visuals.weak_text_color()
        };
        let check_x = rect.min.x + 8.0;
        if let Some(checked) = item.checked {
            if checked {
                ui.painter().text(
                    egui::pos2(check_x, rect.center().y),
                    egui::Align2::LEFT_CENTER,
                    <&str>::from(icons::ICON_CHECK),
                    egui::FontId::proportional(13.0),
                    text_color,
                );
            }
        }
        let icon_x = if item.checked.is_some() {
            check_x + 16.0
        } else {
            rect.min.x + 10.0
        };
        let label_x = if item.icon.is_empty() {
            icon_x
        } else {
            ui.painter().text(
                egui::pos2(icon_x, rect.center().y),
                egui::Align2::LEFT_CENTER,
                icon_glyph(&item.icon),
                egui::FontId::proportional(12.0),
                text_color.gamma_multiply(0.75),
            );
            icon_x + 18.0
        };
        ui.painter().text(
            egui::pos2(label_x, rect.center().y),
            egui::Align2::LEFT_CENTER,
            &item.label,
            egui::FontId::proportional(13.0),
            text_color,
        );
        if has_submenu {
            ui.painter().text(
                egui::pos2(rect.max.x - 10.0, rect.center().y),
                egui::Align2::RIGHT_CENTER,
                <&str>::from(icons::ICON_CHEVRON_RIGHT),
                egui::FontId::proportional(13.0),
                text_color,
            );
        }
    }
    resp
}

impl TimelineWindow {
    pub(super) fn finish_drag_if_released(
        &mut self,
        ui: &egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        if self.drag.is_none() {
            return;
        }
        if !ui.input(|i| i.pointer.any_released()) {
            return;
        }
        let drag = self.drag.take().unwrap();
        let exists = app_state::active_world(state)
            .lock()
            .unwrap()
            .object_exists(drag.id as usize);
        if !exists {
            return;
        }
        app_state::snapshot_before_edit(state);
        let world_holder = app_state::active_world(state);
        let mut world = world_holder.lock().unwrap();
        match drag.mode {
            DragMode::Move => {
                if self.ripple_mode {
                    world.ripple_move_object(drag.id as usize, drag.preview_start);
                } else {
                    world.move_object(drag.id as usize, drag.preview_start, drag.preview_layer);
                }
            }
            DragMode::ResizeLeft => {
                world.resize_object(drag.id as usize, drag.preview_start, drag.preview_end);
            }
            DragMode::ResizeRight => {
                if self.ripple_mode {
                    world.ripple_resize_object(drag.id as usize, drag.preview_end);
                } else {
                    world.resize_object(drag.id as usize, drag.preview_start, drag.preview_end);
                }
            }
        }
        drop(world);
        preview_panel.borrow_mut().refresh_total_frames(state);
    }

    pub(super) fn open_context_menu(
        &mut self,
        ui: &egui::Ui,
        state: &SharedAppState,
        pos: Pos2,
        frame: i32,
        layer: i32,
        hit_id: i32,
    ) {
        let clipboard_empty = app_state::clipboard(state).is_empty();
        let kinds: Vec<ObjectKindItem> = registry()
            .iter()
            .enumerate()
            .map(|(kind_id, plugin)| ObjectKindItem {
                kind: kind_id as i32,
                name: crate::infra::localization::object_name(&plugin.name),
            })
            .collect();
        let registry_snapshot = registry();
        let objects: Vec<(i32, String)> = app_state::active_world(state)
            .lock()
            .unwrap()
            .get_timeline_objects()
            .iter()
            .map(|o| {
                let label = registry_snapshot.get(o.kind as usize).map_or_else(
                    || crate::infra::localization::tr("Unknown"),
                    |p| crate::infra::localization::object_name(&p.name),
                );
                (o.id, format!("[{}] {}", o.id, label))
            })
            .collect();
        let mut items = build_context_menu(
            hit_id,
            clipboard_empty,
            &kinds,
            &objects,
            self.show_grid,
            self.show_waveform,
            self.select_range,
        );

        let location = if hit_id >= 0 {
            neoutl_sdk::extension::MenuLocation::TimelineClipContext
        } else {
            neoutl_sdk::extension::MenuLocation::TimelineLayerContext
        };
        let ext_items = {
            let mgr = crate::extensions::global_extension_manager()
                .lock()
                .unwrap();
            mgr.menus_for_location(&location)
                .into_iter()
                .cloned()
                .collect::<Vec<_>>()
        };
        if !ext_items.is_empty() {
            items.push(ContextMenuItem {
                label: String::new(),
                action: 4,
                kind: -1,
                enabled: false,
                icon: String::new(),
                checked: None,
                submenu: Vec::new(),
            });
            for (idx, item) in ext_items.into_iter().enumerate() {
                items.push(ContextMenuItem {
                    label: item.label,
                    action: 2000 + idx as i32,
                    kind: -1,
                    enabled: item.enabled,
                    icon: "circle-plus".to_owned(),
                    checked: item.checked,
                    submenu: Vec::new(),
                });
            }
        }

        let _ = ui;
        self.menu = Some(MenuState {
            pos,
            hit_id,
            frame,
            layer,
            items,
            open_submenu: None,
            just_opened: true,
        });
    }

    pub(super) fn context_menu_layer(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        dialogs: &Rc<RefCell<DialogSet>>,
        current_frame: i32,
        _kinds: &[ObjectKindItem],
    ) {
        self.finish_drag_if_released(ui, state, preview_panel);

        let Some(mut menu) = self.menu.take() else {
            return;
        };
        let mut keep_open = true;
        let mut fire: Option<ContextMenuItem> = None;
        let mut row_rects: Vec<Rect> = Vec::with_capacity(menu.items.len());

        let menu_area = egui::Area::new(ui.id().with("timeline-context-menu"))
            .fixed_pos(menu.pos)
            .order(egui::Order::Foreground)
            .show(ui.ctx(), |ui| {
                egui::Frame::popup(ui.style())
                    .inner_margin(egui::Margin::symmetric(0, 4))
                    .show(ui, |ui| {
                        ui.set_width(MENU_WIDTH);
                        ui.spacing_mut().item_spacing.y = 0.0;
                        for item in &menu.items {
                            if item.action == 4 {
                                ui.add_space(2.0);
                                ui.separator();
                                ui.add_space(2.0);
                                row_rects.push(Rect::NOTHING);
                                continue;
                            }
                            let has_submenu = !item.submenu.is_empty() || item.action == 17;
                            let resp = menu_row(ui, item, has_submenu);
                            row_rects.push(resp.rect);
                            if resp.hovered() && item.enabled && has_submenu {
                                menu.open_submenu = row_rects.len().checked_sub(1);
                            }
                            if resp.clicked() && item.enabled {
                                if has_submenu {
                                    let idx = row_rects.len() - 1;
                                    menu.open_submenu = if menu.open_submenu == Some(idx) {
                                        None
                                    } else {
                                        Some(idx)
                                    };
                                } else {
                                    fire = Some(item.clone());
                                }
                            }
                        }
                    });
            })
            .response;

        let mut occupied_rect = menu_area.rect;

        if let Some(idx) = menu.open_submenu {
            if let (Some(anchor), Some(item)) = (row_rects.get(idx), menu.items.get(idx)) {
                if !item.submenu.is_empty() {
                    let sub_pos = Pos2::new(anchor.max.x, anchor.min.y);
                    let submenu_area = egui::Area::new(ui.id().with("timeline-context-submenu"))
                        .fixed_pos(sub_pos)
                        .order(egui::Order::Foreground)
                        .show(ui.ctx(), |ui| {
                            egui::Frame::popup(ui.style())
                                .inner_margin(egui::Margin::symmetric(0, 4))
                                .show(ui, |ui| {
                                    ui.set_width(MENU_WIDTH);
                                    ui.spacing_mut().item_spacing.y = 0.0;
                                    for sub in &item.submenu {
                                        let resp = menu_row(ui, sub, false);
                                        if resp.clicked() && sub.enabled {
                                            fire = Some(sub.clone());
                                        }
                                    }
                                });
                        })
                        .response;
                    occupied_rect = occupied_rect.union(submenu_area.rect);
                }
            }
        }

        if let Some(item) = fire {
            self.apply_menu_action(state, preview_panel, dialogs, &menu, &item, current_frame);
            keep_open = false;
        }

        let just_opened = menu.just_opened;
        menu.just_opened = false;

        if keep_open
            && !just_opened
            && ui.input(|i| i.pointer.any_click())
            && ui
                .ctx()
                .pointer_interact_pos()
                .map_or(false, |p| !occupied_rect.contains(p))
        {
            keep_open = false;
        }
        if keep_open {
            self.menu = Some(menu);
        }
    }

    pub(super) fn apply_menu_action(
        &mut self,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        dialogs: &Rc<RefCell<DialogSet>>,
        menu: &MenuState,
        item: &ContextMenuItem,
        current_frame: i32,
    ) {
        match item.action {
            0 => {
                let ids = self.selection_target_ids(menu.hit_id);
                self.split_objects_at(state, preview_panel, &ids, current_frame);
            }
            1 => {
                let ids = self.selection_target_ids(menu.hit_id);
                self.delete_objects(state, preview_panel, &ids);
            }
            2 => self.add_object_at(state, preview_panel, menu.frame, menu.layer, item.kind),
            3 => self.ripple_mode = !self.ripple_mode,
            5 => {
                if app_state::undo_active(state) {
                    self.after_structural_edit(state, preview_panel);
                }
            }
            6 => {
                if app_state::redo_active(state) {
                    self.after_structural_edit(state, preview_panel);
                }
            }
            7 => self.duplicate_requested(state, preview_panel, menu.hit_id),
            8 => self.cut_requested(state, preview_panel, menu.hit_id),
            9 => self.copy_requested(state, menu.hit_id),
            10 => self.paste_requested(state, preview_panel),
            12 => self.cut_selection_range(state, preview_panel),
            13 => self.cut_selection_range_and_pack(state, preview_panel),
            14 => self.select_object(state, &(), item.kind, false),
            15 => self.show_grid = !self.show_grid,
            16 => self.show_waveform = !self.show_waveform,
            18 => {
                let ids = self.selection_target_ids(menu.hit_id);
                self.pack_left(state, preview_panel, &ids);
            }
            19 => {
                let ids = self.selection_target_ids(menu.hit_id);
                self.cut_and_pack(state, preview_panel, &ids);
            }
            20 => {
                let ids = self.selection_target_ids(menu.hit_id);
                self.extract_selection(state, preview_panel, &ids);
            }
            29 => {
                let child = menu.hit_id as usize;
                let parent = item.kind as usize;
                app_state::active_world(state)
                    .lock()
                    .unwrap()
                    .set_parent(child, Some(parent));
                self.after_structural_edit(state, preview_panel);
            }
            30 => {
                let child = menu.hit_id as usize;
                app_state::active_world(state)
                    .lock()
                    .unwrap()
                    .set_parent(child, None);
                self.after_structural_edit(state, preview_panel);
            }
            31 => {
                let target = menu.hit_id as usize;
                let source = item.kind as usize;
                app_state::active_world(state)
                    .lock()
                    .unwrap()
                    .set_track_matte_by_id(
                        target,
                        Some(source),
                        crate::ecs::components::ClipMode::Alpha,
                    );
                self.after_structural_edit(state, preview_panel);
            }
            32 => {
                let target = menu.hit_id as usize;
                app_state::active_world(state)
                    .lock()
                    .unwrap()
                    .set_track_matte_by_id(target, None, crate::ecs::components::ClipMode::Alpha);
                self.after_structural_edit(state, preview_panel);
            }
            53 => self.select_range = None,
            40 => self.toggle_layer_locked(state, preview_panel, item.kind),
            41 => self.toggle_layer_visible(state, preview_panel, item.kind),
            50 => {
                let scene_id = app_state::active_world(state)
                    .lock()
                    .unwrap()
                    .active_scene();
                dialogs.borrow_mut().open_scene_edit(state, scene_id);
            }
            51 => dialogs.borrow_mut().project_settings.open(state),
            52 => dialogs.borrow_mut().system_settings.open = true,
            action if action >= 2000 => {
                let idx = (action - 2000) as usize;
                let location = if menu.hit_id >= 0 {
                    neoutl_sdk::extension::MenuLocation::TimelineClipContext
                } else {
                    neoutl_sdk::extension::MenuLocation::TimelineLayerContext
                };
                let cmd = {
                    let mgr = crate::extensions::global_extension_manager()
                        .lock()
                        .unwrap();
                    mgr.menus_for_location(&location)
                        .get(idx)
                        .map(|m| m.command_id.clone())
                };
                if let Some(cmd_id) = cmd {
                    let _ = crate::extensions::global_extension_manager()
                        .lock()
                        .unwrap()
                        .execute_command(&cmd_id, Some(state));
                }
            }
            _ => {}
        }
    }
}

use super::TimelineWindow;
use crate::objects::registry;
use crate::ui::types::TimelineObject;
use egui::Color32;

impl TimelineWindow {
    pub(super) fn as_egui(
        &mut self,
        ctx: &egui::Context,
        data: &crate::ecs::TimelineData,
        fps: f64,
    ) -> TimelineObject {
        let registry_snapshot = registry();
        let plugin = usize::try_from(data.kind)
            .ok()
            .and_then(|kind| registry_snapshot.get(kind));
        let is_audio = plugin.is_some_and(|p| p.name == "Audio");
        let waveform = data
            .media_path
            .as_deref()
            .filter(|_| is_audio)
            .and_then(|path| self.waveform_texture(ctx, path));
        let waveform_duration_frames = data
            .media_path
            .as_deref()
            .filter(|_| is_audio)
            .and_then(|path| {
                neoutl_media_runtime::cache::global()
                    .load_audio(path)
                    .ok()
                    .map(|audio| {
                        let frame_count = audio
                            .frame_count()
                            .to_string()
                            .parse::<f64>()
                            .unwrap_or(f64::MAX);
                        let sample_rate = f64::from(audio.sample_rate.max(1));
                        (frame_count / sample_rate * fps)
                            .ceil()
                            .to_string()
                            .parse::<i32>()
                            .unwrap_or(i32::MAX)
                    })
            })
            .unwrap_or(0);
        TimelineObject {
            id: data.id,
            start_frame: data.start_frame,
            end_frame: data.end_frame,
            kind: data.kind,
            kind_known: plugin.is_some(),
            layer: data.layer,
            label: plugin.map_or_else(
                || crate::infra::localization::tr("Unknown"),
                |p| crate::infra::localization::object_name(&p.name),
            ),
            selected: false,
            keyframe_frames: Vec::new(),
            waveform: waveform.map(|h| h.id()),
            has_waveform: waveform_duration_frames > 0,
            waveform_origin_frame: i64_to_i32(data.media_trim_in_frame).saturating_neg(),
            waveform_duration_frames,
            group_layer_count_down: data.group_layer_count_down,
            group_layer_count_up: data.group_layer_count_up,
            clip_layer_count_down: data.clip_layer_count_down,
            clip_layer_count_up: data.clip_layer_count_up,
        }
    }

    pub(super) fn waveform_texture(
        &mut self,
        ctx: &egui::Context,
        path: &std::path::Path,
    ) -> Option<egui::TextureHandle> {
        let key = path.to_path_buf();
        if let Some(handle) = self.waveform_cache.get(&key) {
            return Some(handle.clone());
        }
        let audio = neoutl_media_runtime::cache::global()
            .load_audio(path)
            .ok()?;
        let asset = neoutl_media_runtime::waveform::get(path).unwrap_or_else(|| {
            let asset = neoutl_media_runtime::waveform::build(path, &audio);
            neoutl_media_runtime::waveform::insert(asset.clone());
            asset
        });
        let peaks = neoutl_media_runtime::waveform::level_for_columns(&asset, 512);
        let visible_peaks = peaks.as_ref();
        let width = 512usize;
        let height = 48usize;
        let wave_color = ctx.style_of(ctx.theme()).visuals.selection.bg_fill;
        let mut pixels = vec![Color32::TRANSPARENT; width * height];
        for x in 0..width {
            let peak_index = x
                .saturating_mul(visible_peaks.len())
                .checked_div(width)
                .unwrap_or(0);
            let Some(peak) = visible_peaks.get(peak_index) else {
                continue;
            };
            let center = 24.0;
            let top = f32_to_i32((1.0 - peak.max.clamp(-1.0, 1.0)) * center);
            let bottom = f32_to_i32((1.0 - peak.min.clamp(-1.0, 1.0)) * center);
            for y in top.max(0)..bottom.min(48) {
                let pixel_index = usize::try_from(y)
                    .unwrap_or(0)
                    .saturating_mul(width)
                    .saturating_add(x);
                if let Some(px) = pixels.get_mut(pixel_index) {
                    *px = wave_color.gamma_multiply(0.82);
                }
            }
        }
        let image = egui::ColorImage {
            size: [width, height],
            source_size: egui::vec2(
                f32::from(u16::try_from(width).unwrap_or(u16::MAX)),
                f32::from(u16::try_from(height).unwrap_or(u16::MAX)),
            ),
            pixels,
        };
        let handle = ctx.load_texture(
            format!("waveform-{}", path.display()),
            image,
            egui::TextureOptions::LINEAR,
        );
        self.waveform_cache.insert(key, handle.clone());
        Some(handle)
    }
}

fn i64_to_i32(value: i64) -> i32 {
    i32::try_from(value).unwrap_or_else(|_| {
        if value.is_negative() {
            i32::MIN
        } else {
            i32::MAX
        }
    })
}

fn f32_to_i32(value: f32) -> i32 {
    if !value.is_finite() {
        return 0;
    }
    value.round().to_string().parse().unwrap_or_else(|_| {
        if value.is_sign_negative() {
            i32::MIN
        } else {
            i32::MAX
        }
    })
}

use super::{LAYER_HEIGHT, TimelineWindow};
use egui::{Color32, Painter, Pos2, Rect, Stroke, Vec2};

impl TimelineWindow {
    pub(super) fn draw_grid(
        &self,
        painter: &Painter,
        rect: Rect,
        layer_count: i32,
        grid_interval: i32,
    ) {
        let frame_interval = grid_interval.max(1);
        for i in 0..layer_count {
            let y = rect.min.y + self.layer_to_y(i);
            if y + LAYER_HEIGHT < rect.min.y || y > rect.max.y {
                continue;
            }
            let row = Rect::from_min_size(
                Pos2::new(rect.min.x, y),
                Vec2::new(rect.width(), LAYER_HEIGHT),
            );
            if i % 2 == 0 {
                painter.rect_filled(row, 0.0, Color32::from_rgba_unmultiplied(255, 255, 255, 5));
            }
            painter.line_segment(
                [
                    Pos2::new(row.min.x, row.max.y),
                    Pos2::new(row.max.x, row.max.y),
                ],
                Stroke::new(1.0, Color32::from_rgba_unmultiplied(255, 255, 255, 13)),
            );
        }

        let line_count = if self.zoom_scale > 0.0 {
            f32_to_i32((rect.width() / (self.zoom_scale * i32_to_f32(frame_interval))).ceil())
                .saturating_add(1)
        } else {
            0
        };
        let first_visible =
            f32_to_i32((self.scroll_x / self.zoom_scale / i32_to_f32(frame_interval)).floor());
        for i in 0..line_count {
            let frame = first_visible
                .saturating_add(i)
                .saturating_mul(frame_interval);
            let x = rect.min.x + self.frame_to_x(frame);
            painter.line_segment(
                [Pos2::new(x, rect.min.y), Pos2::new(x, rect.max.y)],
                Stroke::new(1.0, Color32::from_rgba_unmultiplied(255, 255, 255, 20)),
            );
        }
    }
}

fn i32_to_f32(value: i32) -> f32 {
    value.to_string().parse().unwrap_or_else(|_| {
        if value.is_negative() {
            f32::MIN
        } else {
            f32::MAX
        }
    })
}

fn f32_to_i32(value: f32) -> i32 {
    if !value.is_finite() {
        return 0;
    }
    value.round().to_string().parse().unwrap_or_else(|_| {
        if value.is_sign_negative() {
            i32::MIN
        } else {
            i32::MAX
        }
    })
}

use super::{HEADER_WIDTH, LAYER_HEIGHT, TimelineWindow};
use crate::app::state::SharedAppState;
use crate::ui::preview::PreviewPanel;
use crate::ui::types::LayerState;
use egui::{Pos2, Rect, Sense, Stroke, Vec2};
use egui_material_icons::icons;
use std::cell::RefCell;
use std::rc::Rc;

impl TimelineWindow {
    pub(super) fn layer_header(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        layer_count: i32,
        layer_states: &[LayerState],
        content_height: f32,
    ) {
        let visuals = ui.visuals().clone();
        let base_bg = visuals.panel_fill;
        let stripe_bg = visuals.faint_bg_color;
        let hidden_bg = visuals.extreme_bg_color;
        let locked_bg = visuals.warn_fg_color.gamma_multiply(0.25);
        let selected_bg = visuals.selection.bg_fill;
        let separator = visuals.widgets.noninteractive.bg_stroke.color;
        let text_normal = visuals.text_color();
        let text_weak = visuals.weak_text_color();
        let text_locked = visuals.warn_fg_color;
        let text_selected = visuals.strong_text_color();

        let (rect, response) = ui.allocate_exact_size(
            Vec2::new(HEADER_WIDTH, content_height),
            Sense::click_and_drag(),
        );
        let painter = ui.painter_at(rect);
        painter.rect_filled(rect, 0.0, base_bg);

        for i in 0..layer_count {
            let y = rect.min.y + self.layer_to_y(i);
            if y + LAYER_HEIGHT < rect.min.y || y > rect.max.y {
                continue;
            }
            let default_state = LayerState {
                visible: true,
                locked: false,
            };
            let ls = layer_states
                .get(i as usize)
                .copied()
                .unwrap_or(default_state);
            let selected = i == self.selected_layer;
            let row = Rect::from_min_size(
                Pos2::new(rect.min.x, y),
                Vec2::new(HEADER_WIDTH, LAYER_HEIGHT),
            );
            let bg = if selected {
                selected_bg
            } else if !ls.visible {
                hidden_bg
            } else if ls.locked {
                locked_bg
            } else if i % 2 == 0 {
                stripe_bg
            } else {
                base_bg
            };
            painter.rect_filled(row, 0.0, bg);
            if selected {
                painter.rect_stroke(
                    row,
                    0.0,
                    Stroke::new(2.0, selected_bg.gamma_multiply(1.4)),
                    egui::StrokeKind::Inside,
                );
            } else {
                painter.line_segment(
                    [
                        Pos2::new(row.min.x, row.max.y),
                        Pos2::new(row.max.x, row.max.y),
                    ],
                    Stroke::new(1.0, separator),
                );
            }
            let text_color = if !ls.visible {
                text_weak
            } else if ls.locked {
                text_locked
            } else if selected {
                text_selected
            } else {
                text_normal
            };
            painter.text(
                row.center(),
                egui::Align2::CENTER_CENTER,
                (i + 1).to_string(),
                egui::FontId::proportional(11.0),
                text_color,
            );

            let select_id = ui.id().with(("layer-select", i));
            let select_rect =
                Rect::from_min_size(row.min, Vec2::new(HEADER_WIDTH - 16.0, LAYER_HEIGHT));
            let select_resp = ui.interact(select_rect, select_id, Sense::click());
            if select_resp.clicked() {
                self.selected_layer = i;
            }
            if select_resp.secondary_clicked() {
                self.selected_layer = i;
                if let Some(pos) = select_resp.interact_pointer_pos() {
                    self.open_layer_menu(pos, i, layer_states);
                }
            }

            let vis_id = ui.id().with(("layer-vis", i));
            let vis_rect = Rect::from_min_size(
                Pos2::new(row.max.x - 16.0, row.min.y),
                Vec2::new(16.0, LAYER_HEIGHT),
            );
            let vis_resp = ui.interact(vis_rect, vis_id, Sense::click());
            if vis_resp.clicked() {
                self.toggle_layer_visible(state, preview_panel, i);
            }
            if ls.locked {
                painter.text(
                    Pos2::new(vis_rect.min.x + 2.0, vis_rect.min.y + 2.0),
                    egui::Align2::LEFT_TOP,
                    <&str>::from(icons::ICON_LOCK),
                    egui::FontId::proportional(9.0),
                    text_locked,
                );
            }
            if !ls.visible {
                painter.text(
                    Pos2::new(vis_rect.min.x + 2.0, vis_rect.max.y - 12.0),
                    egui::Align2::LEFT_TOP,
                    <&str>::from(icons::ICON_VISIBILITY_OFF),
                    egui::FontId::proportional(8.0),
                    text_weak,
                );
            }
        }

        if response.hovered() {
            let scroll = ui.input(|i| i.smooth_scroll_delta.y);
            if scroll != 0.0 {
                let max_scroll = (layer_count as f32 * LAYER_HEIGHT - content_height).max(0.0);
                self.scroll_y = (self.scroll_y - scroll).clamp(0.0, max_scroll);
            }
        }
    }
}

use super::context_menu::menu_row;
use super::util::build_layer_menu;
use super::{MenuState, TimelineWindow};
use crate::app::state::SharedAppState;
use crate::ui::dialogs::DialogSet;
use crate::ui::preview::PreviewPanel;
use crate::ui::types::{ContextMenuItem, LayerState};
use egui::{Pos2, Rect};
use std::cell::RefCell;
use std::rc::Rc;

const MENU_WIDTH: f32 = 220.0;

impl TimelineWindow {
    pub(super) fn open_layer_menu(&mut self, pos: Pos2, layer: i32, layer_states: &[LayerState]) {
        let states: Vec<(bool, bool)> =
            layer_states.iter().map(|s| (s.visible, s.locked)).collect();
        let items = build_layer_menu(layer, &states, self.show_grid, self.show_waveform);
        self.layer_menu = Some(MenuState {
            pos,
            hit_id: -2,
            frame: 0,
            layer,
            items,
            open_submenu: None,
            just_opened: true,
        });
    }

    pub(super) fn layer_menu_layer(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        let Some(mut menu) = self.layer_menu.take() else {
            return;
        };
        let mut keep_open = true;
        let mut fire: Option<ContextMenuItem> = None;
        let mut row_rects: Vec<Rect> = Vec::with_capacity(menu.items.len());

        let menu_area = egui::Area::new(ui.id().with("timeline-layer-menu"))
            .fixed_pos(menu.pos)
            .order(egui::Order::Foreground)
            .show(ui.ctx(), |ui| {
                egui::Frame::popup(ui.style())
                    .inner_margin(egui::Margin::symmetric(0, 4))
                    .show(ui, |ui| {
                        ui.set_width(MENU_WIDTH);
                        ui.spacing_mut().item_spacing.y = 0.0;
                        for item in &menu.items {
                            if item.action == 4 {
                                ui.add_space(2.0);
                                ui.separator();
                                ui.add_space(2.0);
                                row_rects.push(Rect::NOTHING);
                                continue;
                            }
                            let has_submenu = !item.submenu.is_empty() || item.action == 17;
                            let resp = menu_row(ui, item, has_submenu);
                            row_rects.push(resp.rect);
                            if resp.hovered() && item.enabled && has_submenu {
                                menu.open_submenu = row_rects.len().checked_sub(1);
                            }
                            if resp.clicked() && item.enabled {
                                if has_submenu {
                                    let idx = row_rects.len() - 1;
                                    menu.open_submenu = if menu.open_submenu == Some(idx) {
                                        None
                                    } else {
                                        Some(idx)
                                    };
                                } else {
                                    fire = Some(item.clone());
                                }
                            }
                        }
                    });
            })
            .response;
        let mut occupied_rect = menu_area.rect;

        if let Some(idx) = menu.open_submenu {
            if let (Some(anchor), Some(item)) = (row_rects.get(idx), menu.items.get(idx)) {
                if !item.submenu.is_empty() {
                    let sub_pos = Pos2::new(anchor.max.x, anchor.min.y);
                    let submenu_area = egui::Area::new(ui.id().with("timeline-layer-submenu"))
                        .fixed_pos(sub_pos)
                        .order(egui::Order::Foreground)
                        .show(ui.ctx(), |ui| {
                            egui::Frame::popup(ui.style())
                                .inner_margin(egui::Margin::symmetric(0, 4))
                                .show(ui, |ui| {
                                    ui.set_width(MENU_WIDTH);
                                    ui.spacing_mut().item_spacing.y = 0.0;
                                    for sub in &item.submenu {
                                        let resp = menu_row(ui, sub, false);
                                        if resp.clicked() && sub.enabled {
                                            fire = Some(sub.clone());
                                        }
                                    }
                                });
                        })
                        .response;
                    occupied_rect = occupied_rect.union(submenu_area.rect);
                }
            }
        }

        if let Some(item) = fire {
            self.apply_menu_action(state, preview_panel, dialogs, &menu, &item, 0);
            keep_open = false;
        }

        let just_opened = menu.just_opened;
        menu.just_opened = false;

        if keep_open
            && !just_opened
            && ui.input(|i| i.pointer.any_click())
            && ui
                .ctx()
                .pointer_interact_pos()
                .map_or(false, |p| !occupied_rect.contains(p))
        {
            keep_open = false;
        }
        if keep_open {
            self.layer_menu = Some(menu);
        }
    }
}

