    selected_layer: i32,
    ripple_mode: bool,
    scroll_x: f32,
    scroll_y: f32,
    selected_ids: HashSet<i32>,
    last_generation: u64,
    drag: Option<ClipDrag>,
    kdrag: Option<KeyframeDrag>,
    range: Option<RangeSelect>,
    pub(super) select_range: Option<(i32, i32)>,
    select_range_anchor: Option<i32>,
    menu: Option<MenuState>,
    layer_menu: Option<MenuState>,
    waveform_cache: HashMap<PathBuf, egui::TextureHandle>,
    show_grid: bool,
    show_waveform: bool,
}

impl TimelineWindow {
    pub fn new() -> Self {
        Self {
            open: false,
            zoom_scale: 1.0,
            selected_layer: 0,
            ripple_mode: false,
            scroll_x: 0.0,
            scroll_y: 0.0,
            selected_ids: HashSet::new(),
            last_generation: 0,
            drag: None,
            kdrag: None,
            range: None,
            select_range: None,
            select_range_anchor: None,
            menu: None,
            layer_menu: None,
            waveform_cache: HashMap::new(),
            show_grid: true,
            show_waveform: true,
        }
    }

    pub(super) fn reset_session(&mut self, world: &EcsWorld) {
        self.selected_ids.clear();
        self.selected_layer = 0;
        self.scroll_x = 0.0;
        self.scroll_y = 0.0;
        self.zoom_scale = world.zoom();
        self.drag = None;
        self.kdrag = None;
        self.range = None;
        self.select_range = None;
        self.select_range_anchor = None;
        self.menu = None;
        self.layer_menu = None;
    }

    pub(super) fn frame_to_x(&self, frame: i32) -> f32 {
        frame as f32 * self.zoom_scale - self.scroll_x
    }

    pub(super) fn px_to_frame(&self, px: f32) -> i32 {
        ((px + self.scroll_x) / self.zoom_scale).floor().max(0.0) as i32
    }

    pub(super) fn layer_to_y(&self, layer: i32) -> f32 {
        layer as f32 * LAYER_HEIGHT - self.scroll_y
    }

    pub(super) fn px_to_layer(&self, py: f32) -> i32 {
        ((py + self.scroll_y) / LAYER_HEIGHT).floor().max(0.0) as i32
    }

    pub fn show(
        &mut self,
        _ctx: &egui::Context,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        _props_weak: &(),
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        if std::mem::take(&mut preview_panel.borrow_mut().open_timeline) {
            self.open = true;
        }
        if !self.open {
            return;
        }

        let generation = preview_panel.borrow().session_generation();
        if generation != self.last_generation {
            self.last_generation = generation;
            let world_holder = app_state::active_world(state);
            let world = world_holder.lock().unwrap();
            self.reset_session(&world);
        }

        {
            let world_holder = app_state::active_world(state);
            world_holder
                .lock()
                .unwrap()
                .set_selected_ids(self.selected_ids.iter().map(|&id| id as usize).collect());
        }

        egui::CentralPanel::default().show(ui, |ui| {
            self.body(ui, state, preview_panel, &(), dialogs);
        });
    }

    pub(super) fn body(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        _props_weak: &(),
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        self.handle_shortcuts(ui, state, preview_panel, &());

        let world_holder = app_state::active_world(state);
        let (fps, total_frames, layer_count, layer_states, objects, scene_tabs, kinds) = {
            let world = world_holder.lock().unwrap();
            let fps = world.get_project().fps as f64;
            let selected = self.selected_ids.clone();
            let objects: Vec<TimelineObject> = world
                .get_timeline_objects()
                .iter()
                .map(|data| {
                    let mut o = self.as_egui(ui.ctx(), data, fps);
                    o.selected = selected.contains(&o.id);
                    o
                })
                .collect();
            let layer_states: Vec<LayerState> = world
                .layer_states()
                .iter()
                .map(|&(visible, locked)| LayerState { visible, locked })
                .collect();
            let active_scene = world.active_scene();
            let scene_tabs: Vec<SceneTabItem> = world
                .scenes()
                .iter()
                .map(|s| SceneTabItem {
                    id: s.id,
                    name: s.name.clone(),
                    active: s.id == active_scene,
                })
                .collect();
            let kinds: Vec<ObjectKindItem> = registry()
                .iter()
                .enumerate()
                .map(|(kind_id, plugin)| ObjectKindItem {
                    kind: kind_id as i32,
                    name: crate::infra::localization::object_name(&plugin.name),
                })
                .collect();
            (
                fps,
                world.total_frames(),
                world.layer_count(),
                layer_states,
                objects,
                scene_tabs,
                kinds,
            )
        };
        let _ = fps;
        let current_frame = world_holder.lock().unwrap().current_frame();

        self.scene_tab_bar(ui, state, preview_panel, &scene_tabs, dialogs);
        self.ruler(ui, state, preview_panel, current_frame, total_frames);

        let content_height = ui.available_height();
        ui.spacing_mut().item_spacing.x = 0.0;
        ui.horizontal(|ui| {
            self.layer_header(
                ui,
                state,
                preview_panel,
                layer_count,
                &layer_states,
                content_height,
            );
            self.timeline_view(
                ui,
                state,
                preview_panel,
                &(),
                current_frame,
                total_frames,
                layer_count,
                &objects,
                &layer_states,
                content_height,
            );
        });

        self.context_menu_layer(ui, state, preview_panel, dialogs, current_frame, &kinds);
        self.layer_menu_layer(ui, state, preview_panel, dialogs);
    }

    pub(super) fn handle_shortcuts(
        &mut self,
        ui: &egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        _props_weak: &(),
    ) {
        let (ctrl, shift, alt, keys) = ui.input(|i| {
            (
                i.modifiers.ctrl,
                i.modifiers.shift,
                i.modifiers.alt,
                i.events
                    .iter()
                    .filter_map(|e| match e {
                        egui::Event::Key {
                            key, pressed: true, ..
                        } => Some(egui_key_name(*key)),
                        _ => None,
                    })
                    .collect::<Vec<_>>(),
            )
        });
        for key in keys {
            let Some(cmd) = shortcuts::resolve_active(Scope::Timeline, ctrl, shift, alt, &key)
            else {
                continue;
            };
            let hit_id = self.selected_ids.iter().next().copied().unwrap_or(-1);
            match cmd {
                CommandId::DeleteSelected => {
                    let ids: Vec<usize> = self.selected_ids.iter().map(|&id| id as usize).collect();
                    self.delete_objects(state, preview_panel, &ids);
                }
                CommandId::SplitAtPlayhead => {
                    let ids: Vec<usize> = self.selected_ids.iter().map(|&id| id as usize).collect();
                    if !ids.is_empty() {
                        let frame = app_state::active_world(state)
                            .lock()
                            .unwrap()
                            .current_frame();
                        self.split_objects_at(state, preview_panel, &ids, frame);
                    }
                }
                CommandId::Duplicate => self.duplicate_requested(state, preview_panel, hit_id),
                CommandId::Cut => self.cut_requested(state, preview_panel, hit_id),
                CommandId::Copy => self.copy_requested(state, hit_id),
                CommandId::Paste => self.paste_requested(state, preview_panel),
                CommandId::ToggleRipple => self.ripple_mode = !self.ripple_mode,
                CommandId::CutRange => self.cut_selection_range(state, preview_panel),
                CommandId::CutRangeAndPack => {
                    self.cut_selection_range_and_pack(state, preview_panel)
                }
                CommandId::ZoomIn => self.zoom_scale = (self.zoom_scale * 1.25).min(10.0),
                CommandId::ZoomOut => self.zoom_scale = (self.zoom_scale * 0.8).max(0.1),
                CommandId::SeekHome => self.seek(state, preview_panel, 0),
                CommandId::SeekEnd => {
                    let total = app_state::active_world(state)
                        .lock()
                        .unwrap()
                        .total_frames();
                    self.seek(state, preview_panel, total);
                }
                CommandId::Undo => {
                    if app_state::undo_active(state) {
                        self.after_structural_edit(state, preview_panel);
                    }
                }
                CommandId::Redo => {
                    if app_state::redo_active(state) {
                        self.after_structural_edit(state, preview_panel);
                    }
                }
                _ => {}
            }
        }
    }
}

use super::{HEADER_WIDTH, RULER_HEIGHT, TimelineWindow};
use crate::app::state::{self as app_state, SharedAppState};
use crate::ui::preview::PreviewPanel;
use egui::{Pos2, Rect, Sense, Stroke, Vec2};
use std::cell::RefCell;
use std::rc::Rc;

impl TimelineWindow {
    pub(super) fn ruler(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        current_frame: i32,
        total_frames: i32,
    ) {
        let _ = total_frames;
        let visuals = ui.visuals().clone();
        let bg = visuals.panel_fill;
        let header_bg = visuals.faint_bg_color;
        let text_color = visuals.text_color();
        let weak_text = visuals.weak_text_color();
        let tick_major = visuals.text_color();
        let tick_minor = visuals.weak_text_color();
        let accent = visuals.selection.bg_fill;

        let (rect, response) = ui.allocate_exact_size(
            Vec2::new(ui.available_width(), RULER_HEIGHT),
            Sense::click_and_drag(),
        );
        let painter = ui.painter_at(rect);
        painter.rect_filled(rect, 0.0, bg);

        let header_rect = Rect::from_min_size(rect.min, Vec2::new(HEADER_WIDTH, RULER_HEIGHT));
        painter.rect_filled(header_rect, 0.0, header_bg);
        let mut zoom_percent = f32_to_i32(self.zoom_scale * 100.0);
        let mut child = ui.new_child(egui::UiBuilder::new().max_rect(header_rect));
        let inner = child.add_sized(
            header_rect.size(),
            egui::DragValue::new(&mut zoom_percent)
                .range(10..=400)
                .suffix("%"),
        );
        if inner.changed() {
            let new_scale = (i32_to_f32(zoom_percent) / 100.0).clamp(0.1, 4.0);
            self.zoom_scale = new_scale;
            app_state::active_world(state)
                .lock()
                .unwrap()
                .set_zoom(new_scale);
        }

        let body_rect =
            Rect::from_min_max(Pos2::new(rect.min.x + HEADER_WIDTH, rect.min.y), rect.max);
        let grid_interval = {
            let world_holder = app_state::active_world(state);
            let world = world_holder.lock().unwrap();
            let active_scene = world.active_scene();
            world
                .scenes()
                .into_iter()
                .find(|scene| scene.id == active_scene)
                .map_or(30, |scene| scene.effective_grid_interval())
        };
        let start_tick =
            f32_to_i32((self.scroll_x / self.zoom_scale / i32_to_f32(grid_interval)).floor())
                .saturating_mul(grid_interval);
        let tick_count =
            f32_to_i32((body_rect.width() / self.zoom_scale / i32_to_f32(grid_interval)).ceil())
                .saturating_add(2);
        for i in 0..tick_count {
            let frame = start_tick.saturating_add(i.saturating_mul(grid_interval));
            let x = body_rect.min.x + self.frame_to_x(frame);
            if x < body_rect.min.x || x > body_rect.max.x {
                continue;
            }
            let is_second = frame % 30 == 0;
            let h = if is_second {
                rect.height()
            } else {
                rect.height() * 0.5
            };
            painter.line_segment(
                [Pos2::new(x, rect.max.y), Pos2::new(x, rect.max.y - h)],
                Stroke::new(1.0, if is_second { tick_major } else { tick_minor }),
            );
            let label = if is_second {
                format!("{}s", frame / 30)
            } else {
                frame.to_string()
            };
            painter.text(
                Pos2::new(x + 3.0, rect.min.y + 2.0),
                egui::Align2::LEFT_TOP,
                label,
                egui::FontId::proportional(9.0),
                if is_second { text_color } else { weak_text },
            );
        }
        let playhead_x = body_rect.min.x + self.frame_to_x(current_frame);
        painter.line_segment(
            [
                Pos2::new(playhead_x, rect.min.y),
                Pos2::new(playhead_x, rect.max.y),
            ],
            Stroke::new(2.0, accent),
        );

        self.handle_ruler_pointer(&response, body_rect, state, preview_panel);

        self.handle_ruler_zoom(ui, body_rect, state);
    }

    fn handle_ruler_pointer(
        &mut self,
        response: &egui::Response,
        body_rect: Rect,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        if response.drag_started()
            && let Some(pos) = response.interact_pointer_pos()
        {
            self.select_range_anchor = Some(self.px_to_frame(pos.x - body_rect.min.x).max(0));
        }
        if response.dragged()
            && let (Some(anchor_frame), Some(pos)) =
                (self.select_range_anchor, response.interact_pointer_pos())
        {
            let current_frame = self.px_to_frame(pos.x - body_rect.min.x).max(0);
            self.select_range = Some((
                anchor_frame.min(current_frame),
                anchor_frame.max(current_frame),
            ));
        } else if response.double_clicked() {
            self.select_range = None;
            self.select_range_anchor = None;
        } else if response.hovered()
            && response.clicked()
            && let Some(pos) = response.interact_pointer_pos()
        {
            self.seek(
                state,
                preview_panel,
                self.px_to_frame(pos.x - body_rect.min.x),
            );
        }
    }

    fn handle_ruler_zoom(&mut self, ui: &egui::Ui, body_rect: Rect, state: &SharedAppState) {
        if !ui
            .input(|input| input.pointer.hover_pos())
            .is_some_and(|pos| body_rect.contains(pos))
        {
            return;
        }
        let scroll = ui.input(|input| input.smooth_scroll_delta.y);
        if scroll == 0.0 {
            return;
        }
        let anchor_pos = ui
            .input(|input| input.pointer.hover_pos())
            .unwrap_or(body_rect.min);
        let anchor_frame = self.px_to_frame(anchor_pos.x - body_rect.min.x);
        let new_scale = if scroll > 0.0 {
            self.zoom_scale * 1.1
        } else {
            self.zoom_scale * 0.9
        }
        .clamp(0.1, 10.0);
        self.scroll_x =
            (self.scroll_x + (new_scale - self.zoom_scale) * i32_to_f32(anchor_frame)).max(0.0);
        self.zoom_scale = new_scale;
        app_state::active_world(state)
            .lock()
            .unwrap()
            .set_zoom(new_scale);
    }
}

fn i32_to_f32(value: i32) -> f32 {
    value.to_string().parse().unwrap_or_else(|_| {
        if value.is_negative() {
            f32::MIN
        } else {
            f32::MAX
        }
    })
}

fn f32_to_i32(value: f32) -> i32 {
    if !value.is_finite() {
        return 0;
    }
    value.round().to_string().parse().unwrap_or_else(|_| {
        if value.is_sign_negative() {
            i32::MIN
        } else {
            i32::MAX
        }
    })
}

use super::TimelineWindow;
use crate::app::state::SharedAppState;
use crate::ui::dialogs::DialogSet;
use crate::ui::preview::PreviewPanel;
use crate::ui::types::SceneTabItem;
use elegance::{BrowserTab, BrowserTabs, BrowserTabsEvent};
use std::cell::RefCell;
use std::rc::Rc;

const ROOT_SCENE_ID: i32 = 0;

impl TimelineWindow {
    pub(super) fn scene_tab_bar(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        scene_tabs: &[SceneTabItem],
        dialogs: &Rc<RefCell<DialogSet>>,
    ) {
        let mut tabs = BrowserTabs::new("timeline-scene-tabs").show_new_button(true);
        for tab in scene_tabs {
            tabs = tabs.with_tab(BrowserTab::new(tab.id.to_string(), tab.name.clone()));
        }
        if let Some(active) = scene_tabs.iter().find(|tab| tab.active) {
            tabs.set_selected(active.id.to_string());
        }

        let response = tabs.show(ui);
        let hovered = response.hovered();
        let double_clicked = ui.input(|input| {
            input
                .pointer
                .button_double_clicked(egui::PointerButton::Primary)
        });

        let mut switch_target: Option<i32> = None;
        let mut close_target: Option<i32> = None;
        let mut add_clicked = false;
        for event in tabs.take_events() {
            match event {
                BrowserTabsEvent::Activated(id) => switch_target = id.parse().ok(),
                BrowserTabsEvent::Closed(id) => close_target = id.parse().ok(),
                BrowserTabsEvent::NewRequested => add_clicked = true,
            }
        }

        let active_id = tabs.selected().and_then(|id| id.parse::<i32>().ok());
        let rename_target = if hovered && double_clicked {
            active_id
        } else {
            None
        };

        if let Some(id) = switch_target {
            self.switch_scene_tab(state, preview_panel, id);
        }
        if let Some(id) = rename_target {
            dialogs.borrow_mut().open_scene_edit(state, id);
        }
        if let Some(id) = close_target {
            if id != ROOT_SCENE_ID {
                self.close_scene_tab(state, preview_panel, id);
            }
        }
        if add_clicked {
            dialogs.borrow_mut().open_scene_create(state);
        }
    }
}

use super::{RangeSelect, TimelineWindow};
use crate::app::state::{self as app_state, SharedAppState};
use crate::ui::preview::PreviewPanel;
use crate::ui::types::{LayerState, TimelineObject};
use egui::{Pos2, Rect, Sense, Stroke, Vec2};
use std::cell::RefCell;
use std::rc::Rc;

fn world_grid_interval(state: &SharedAppState) -> i32 {
    let world_holder = app_state::active_world(state);
    let world = world_holder.lock().unwrap();
    let active_scene = world.active_scene();
    world
        .scenes()
        .into_iter()
        .find(|scene| scene.id == active_scene)
        .map_or(30, |scene| scene.effective_grid_interval())
}

impl TimelineWindow {
    pub(super) fn timeline_view(
        &mut self,
        ui: &mut egui::Ui,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
        _props_weak: &(),
        current_frame: i32,
        total_frames: i32,
        layer_count: i32,
        objects: &[TimelineObject],
        layer_states: &[LayerState],
        content_height: f32,
    ) {
        let visuals = ui.visuals().clone();
        let bg = visuals.extreme_bg_color;
        let select_fill = visuals.selection.bg_fill.gamma_multiply(0.4);
        let select_stroke = visuals.selection.bg_fill;
        let accent = visuals.warn_fg_color;

        let (rect, response) = ui.allocate_exact_size(
            Vec2::new(ui.available_width(), content_height),
            Sense::click_and_drag(),
        );
        let painter = ui.painter_at(rect);
        painter.rect_filled(rect, 0.0, bg);

        if self.show_grid {
            let grid_interval = world_grid_interval(state);
            self.draw_grid(&painter, rect, layer_count, grid_interval);
        }

        self.handle_background_input(ui, &response, state, preview_panel);

        if let Some((start_frame, end_frame)) = self.select_range {
            let x0 = rect.min.x + self.frame_to_x(start_frame);
            let x1 = rect.min.x + self.frame_to_x(end_frame);
            let band = Rect::from_min_max(Pos2::new(x0, rect.min.y), Pos2::new(x1, rect.max.y));
            let purple = egui::Color32::from_rgb(160, 90, 220);
            painter.rect_filled(band, 0.0, purple.gamma_multiply(0.28));
            painter.rect_stroke(
                band,
                0.0,
                Stroke::new(1.5, purple),
                egui::StrokeKind::Outside,
            );
        }

        if let Some(range) = &self.range {
            let a = rect.min + range.anchor.to_vec2();
            let c = rect.min + range.cur.to_vec2();
            let sel = Rect::from_two_pos(a, c);
            painter.rect_filled(sel, 0.0, select_fill);
            painter.rect_stroke(
                sel,
                0.0,
                Stroke::new(1.0, select_stroke),
                egui::StrokeKind::Outside,
            );
        }

        for obj in objects {
            let locked = layer_states
                .get(obj.layer as usize)
                .map_or(false, |s| s.locked);
            self.clip_ui(
                ui,
                &painter,
                rect,
                state,
                preview_panel,
                &(),
                obj,
                locked,
                total_frames,
                layer_count,
            );
        }

        let playhead_x = rect.min.x + self.frame_to_x(current_frame);
        painter.line_segment(
            [
                Pos2::new(playhead_x, rect.min.y),
                Pos2::new(playhead_x, rect.max.y),
            ],
            Stroke::new(2.0, accent),
        );

        let selected: Vec<usize> = self.selected_ids.iter().map(|&id| id as usize).collect();
        let frame_to_x_fn = |f: i32| rect.min.x + self.frame_to_x(f);
        let layer_to_y_fn = |l: i32| rect.min.y + self.layer_to_y(l);
        let fps = {
            let world_holder = app_state::active_world(state);
            world_holder.lock().unwrap().get_project().fps
        };
        let mut overlay_ctx = neoutl_sdk::extension::TimelineOverlayContext {
            painter: &painter,
            timeline_rect: rect,
            visible_frame_range: (self.px_to_frame(0.0), self.px_to_frame(rect.width())),
            current_frame,
            fps,
            bpm: None,
            selected_object_ids: &selected,
            frame_to_x: &frame_to_x_fn,
            layer_to_y: &layer_to_y_fn,
        };
        crate::extensions::global_extension_manager()
            .lock()
            .unwrap()
            .draw_timeline_overlay(&mut overlay_ctx, Some(state));

        if response.hovered() {
            let scroll = ui.input(|i| i.smooth_scroll_delta.y);
            if scroll != 0.0 {
                let max_scroll = (total_frames as f32 * self.zoom_scale - rect.width()).max(0.0);
                self.scroll_x = (self.scroll_x - scroll).clamp(0.0, max_scroll);
            }
        }
    }

    pub(super) fn handle_background_input(
        &mut self,
        ui: &egui::Ui,
        response: &egui::Response,
        state: &SharedAppState,
        preview_panel: &Rc<RefCell<PreviewPanel>>,
    ) {
        if self.drag.is_some() || self.kdrag.is_some() {
            return;
        }
        if response.drag_started() {
            if let Some(pos) = response.interact_pointer_pos() {
                let local = pos - response.rect.min;
                self.seek(state, preview_panel, self.px_to_frame(local.x));
                self.range = Some(RangeSelect {
                    anchor: Pos2::new(local.x, local.y),
                    cur: Pos2::new(local.x, local.y),
                });
            }
        }
        if response.dragged() && self.range.is_some() {
            if let Some(pos) = response.interact_pointer_pos() {
                let local = pos - response.rect.min;
                if let Some(range) = &mut self.range {
                    range.cur = Pos2::new(local.x, local.y);
                }
            }
        }
        if response.drag_stopped() {
            if let Some(range) = self.range.take() {
                if (range.cur.x - range.anchor.x).abs() > 3.0
                    || (range.cur.y - range.anchor.y).abs() > 3.0
                {
                    let start_frame = self.px_to_frame(range.anchor.x.min(range.cur.x));
                    let end_frame = self.px_to_frame(range.anchor.x.max(range.cur.x));
                    let start_layer = self.px_to_layer(range.anchor.y.min(range.cur.y));
                    let end_layer = self.px_to_layer(range.anchor.y.max(range.cur.y));
                    let world_holder = app_state::active_world(state);
                    let world = world_holder.lock().unwrap();
                    self.selected_ids = world
                        .get_timeline_objects()
                        .iter()
                        .filter(|o| {
                            o.start_frame < end_frame
                                && o.end_frame > start_frame
                                && o.layer >= start_layer
                                && o.layer <= end_layer
                        })
                        .map(|o| o.id)
                        .collect();
                }
            }
        }
        if response.secondary_clicked() {
            if let Some(pos) = response.interact_pointer_pos() {
                let local = pos - response.rect.min;
                self.open_context_menu(
                    ui,
                    state,
                    pos,
                    self.px_to_frame(local.x),
                    self.px_to_layer(local.y),
                    -1,
                );
            }
        }
    }
}

use egui::{Color32, Frame, Margin, RichText, Ui};
use egui_taffy::taffy;
use egui_taffy::taffy::Style;

pub fn configure_taffy(ctx: &egui::Context) {
    ctx.options_mut(|options| {
        options.max_passes = std::num::NonZeroUsize::new(2).unwrap();
    });
    ctx.all_styles_mut(|style| {
        style.wrap_mode = Some(egui::TextWrapMode::Extend);
    });
}

pub fn row_style(gap: f32) -> Style {
    Style {
        flex_direction: taffy::FlexDirection::Row,
        align_items: Some(taffy::AlignItems::Center),
        gap: taffy::Size {
            width: taffy::LengthPercentage::length(gap),
            height: taffy::LengthPercentage::length(gap),
        },
        ..Default::default()
    }
}

pub fn col_style(gap: f32) -> Style {
    Style {
        flex_direction: taffy::FlexDirection::Column,
        gap: taffy::Size {
            width: taffy::LengthPercentage::length(gap),
            height: taffy::LengthPercentage::length(gap),
        },
        ..Default::default()
    }
}

pub fn row_between_style(width: f32) -> Style {
    Style {
        flex_direction: taffy::FlexDirection::Row,
        justify_content: Some(taffy::JustifyContent::SpaceBetween),
        align_items: Some(taffy::AlignItems::Center),
        size: taffy::Size {
            width: taffy::Dimension::length(width),
            height: taffy::Dimension::auto(),
        },
        ..Default::default()
    }
}

pub fn row_style_full(gap: f32, width: f32) -> Style {
    let mut style = row_style(gap);
    style.size = taffy::Size {
        width: taffy::Dimension::length(width),
        height: taffy::Dimension::auto(),
    };
    style
}

pub fn row_end_style(gap: f32, width: f32) -> Style {
    Style {
        flex_direction: taffy::FlexDirection::Row,
        justify_content: Some(taffy::JustifyContent::End),
        align_items: Some(taffy::AlignItems::Center),
        gap: taffy::Size {
            width: taffy::LengthPercentage::length(gap),
            height: taffy::LengthPercentage::length(gap),
        },
        size: taffy::Size {
            width: taffy::Dimension::length(width),
            height: taffy::Dimension::auto(),
        },
        ..Default::default()
    }
}

pub fn fixed_style(width: f32, height: f32) -> Style {
    Style {
        size: taffy::Size {
            width: taffy::Dimension::length(width),
            height: taffy::Dimension::length(height),
        },
        flex_shrink: 0.0,
        ..Default::default()
    }
}

pub fn grow_style() -> Style {
    Style {
        flex_grow: 1.0,
        ..Default::default()
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Density;

pub fn density() -> Density {
    Density
}

impl Density {
    fn scale(self) -> f32 {
        1.0
    }

    fn px(self, base: f32) -> i8 {
        (base * self.scale()).round() as i8
    }

    pub fn page_margin(self) -> Margin {
        Margin::same(self.px(16.0))
    }

    pub fn bar_margin(self) -> Margin {
        Margin::symmetric(self.px(16.0), self.px(12.0))
    }

    pub fn footer_margin(self) -> Margin {
        Margin::same(self.px(4.0))
    }

    pub fn sidebar_margin(self) -> Margin {
        Margin::symmetric(self.px(8.0), self.px(12.0))
    }

    pub fn section_gap(self) -> f32 {
        12.0 * self.scale()
    }

    pub fn sidebar_content_width(self) -> f32 {
        150.0 * self.scale()
    }

    pub fn sidebar_panel_width(self) -> f32 {
        let m = self.sidebar_margin();
        self.sidebar_content_width() + f32::from(m.left) + f32::from(m.right)
    }

    pub fn sidebar_frame(self, fill: Color32) -> Frame {
        Frame::default()
            .fill(fill)
            .corner_radius(self.px(10.0) as u8)
            .stroke(egui::Stroke::NONE)
            .inner_margin(self.sidebar_margin())
            .outer_margin(Margin::same(self.px(8.0)))
    }
}

#[inline]
pub fn section_heading_color(ui: &Ui) -> Color32 {
    ui.visuals().hyperlink_color
}

#[inline]
pub fn page_title(text: impl Into<String>) -> RichText {
    RichText::new(text).heading().strong()
}

pub trait UiExt {
    fn page_content<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R;

    fn header_bar<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R;

    fn footer_bar<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R;

    fn section<R>(
        &mut self,
        heading: impl Into<String>,
        add_contents: impl FnOnce(&mut Ui) -> R,
    ) -> R;
}

impl UiExt for Ui {
    fn page_content<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
        Frame::default()
            .inner_margin(density().page_margin())
            .show(self, add_contents)
            .inner
    }

    fn header_bar<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
        Frame::default()
            .inner_margin(density().bar_margin())
            .show(self, add_contents)
            .inner
    }

    fn footer_bar<R>(&mut self, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
        Frame::default()
            .inner_margin(density().footer_margin())
            .show(self, add_contents)
            .inner
    }

    fn section<R>(
        &mut self,
        heading: impl Into<String>,
        add_contents: impl FnOnce(&mut Ui) -> R,
    ) -> R {
        let color = section_heading_color(self);
        self.label(RichText::new(heading.into()).strong().color(color));
        let result = add_contents(self);
        self.add_space(density().section_gap());
        result
    }
}

use serde::Deserialize;
use std::fs;
use std::io::{Cursor, Read};
use std::path::{Path, PathBuf};

const RELEASES_API_URL: &str =
    "https://api.github.com/repos/microsoft/DirectXShaderCompiler/releases/latest";
const VERSION_MARKER_FILENAME: &str = ".dxc-version";

#[derive(Deserialize)]
struct ReleaseAsset {
    name: String,
    browser_download_url: String,
}

#[derive(Deserialize)]
struct ReleaseInfo {
    tag_name: String,
    assets: Vec<ReleaseAsset>,
}

pub fn install_dir(workspace_root: &Path) -> PathBuf {
    workspace_root.join("dxc")
}

fn arch_dir() -> &'static str {
    if cfg!(target_arch = "aarch64") {
        "arm64"
    } else if cfg!(target_arch = "x86") {
        "x86"
    } else {
        "x64"
    }
}

pub fn bin_dir(workspace_root: &Path) -> PathBuf {
    install_dir(workspace_root).join("bin").join(arch_dir())
}

pub fn dxcompiler_path(workspace_root: &Path) -> PathBuf {
    bin_dir(workspace_root).join("dxcompiler.dll")
}

fn version_marker_path(dxc_dir: &Path) -> PathBuf {
    dxc_dir.join(VERSION_MARKER_FILENAME)
}

fn read_installed_tag(dxc_dir: &Path) -> Option<String> {
    let text = fs::read_to_string(version_marker_path(dxc_dir)).ok()?;
    let tag = text.trim();
    (!tag.is_empty()).then(|| tag.to_string())
}

fn write_installed_tag(dxc_dir: &Path, tag_name: &str) {
    if let Err(err) = fs::write(version_marker_path(dxc_dir), tag_name) {
        eprintln!("[xtask][dxc] バージョン記録失敗: {err}");
    }
}

fn github_token() -> Option<String> {
    std::env::var("GITHUB_TOKEN")
        .or_else(|_| std::env::var("GH_TOKEN"))
        .ok()
        .filter(|t| !t.is_empty())
}

fn fetch_latest_release() -> Result<ReleaseInfo, String> {
    let mut req = ureq::get(RELEASES_API_URL)
        .header("User-Agent", "NeoUtl-xtask")
        .header("Accept", "application/vnd.github+json");
    if let Some(token) = github_token() {
        req = req.header("Authorization", &format!("Bearer {token}"));
    }
    req.call()
        .map_err(|err| format!("GitHub Releases API取得失敗: {err}"))?
        .body_mut()
        .read_json::<ReleaseInfo>()
        .map_err(|err| format!("GitHub Releases APIレスポンス解析失敗: {err}"))
}

fn select_asset(assets: &[ReleaseAsset]) -> Option<&ReleaseAsset> {
    assets.iter().find(|asset| {
        let name = asset.name.to_ascii_lowercase();
        name.starts_with("dxc_") && name.ends_with(".zip")
    })
}

fn download_asset_bytes(url: &str) -> Result<Vec<u8>, String> {
    let mut req = ureq::get(url).header("User-Agent", "NeoUtl-xtask");
    if let Some(token) = github_token() {
        req = req.header("Authorization", &format!("Bearer {token}"));
    }
    let mut response = req
        .call()
        .map_err(|err| format!("dxcアセットダウンロード失敗: {err}"))?;
    let mut bytes = Vec::new();
    response
        .body_mut()
        .as_reader()
        .read_to_end(&mut bytes)
        .map_err(|err| format!("dxcアセット読込失敗: {err}"))?;
    Ok(bytes)
}

fn extract_zip(bytes: &[u8], dxc_dir: &Path) -> Result<(), String> {
    if dxc_dir.exists() {
        fs::remove_dir_all(dxc_dir).map_err(|err| format!("既存dxc削除失敗: {err}"))?;
    }
    fs::create_dir_all(dxc_dir).map_err(|err| format!("dxcディレクトリ作成失敗: {err}"))?;

    let mut archive =
        zip::ZipArchive::new(Cursor::new(bytes)).map_err(|err| format!("zip解析失敗: {err}"))?;

    for index in 0..archive.len() {
        let mut entry = archive
            .by_index(index)
            .map_err(|err| format!("zipエントリ読込失敗: {err}"))?;
        let Some(relative_path) = entry.enclosed_name() else {
            eprintln!("[xtask][dxc] 不正なzipエントリを無視: index={index}");
            continue;
        };
        let dest_path = dxc_dir.join(&relative_path);

        if entry.is_dir() {
            fs::create_dir_all(&dest_path).map_err(|err| format!("展開先作成失敗: {err}"))?;
            continue;
        }

        if let Some(parent) = dest_path.parent() {
            fs::create_dir_all(parent).map_err(|err| format!("展開先作成失敗: {err}"))?;
        }
        let mut out_file =
            fs::File::create(&dest_path).map_err(|err| format!("展開ファイル作成失敗: {err}"))?;
        std::io::copy(&mut entry, &mut out_file).map_err(|err| format!("展開失敗: {err}"))?;
    }
    Ok(())
}

pub fn ensure_installed(workspace_root: &Path, offline: bool) {
    if !cfg!(windows) {
        return;
    }

    let dxc_dir = install_dir(workspace_root);
    let installed_tag = read_installed_tag(&dxc_dir);
    let local_installed = installed_tag.is_some() && dxcompiler_path(workspace_root).is_file();

    if offline {
        if local_installed {
            eprintln!(
                "[xtask][dxc] --offline指定のため更新確認をスキップ: 導入済み {}",
                installed_tag.as_deref().unwrap_or("")
            );
            return;
        }
        panic!(
            "[xtask][dxc] --offline指定だがdxc未導入（{}が存在しません）",
            dxc_dir.display()
        );
    }

    let release = match fetch_latest_release() {
        Ok(release) => release,
        Err(err) => {
            if local_installed {
                eprintln!(
                    "[xtask][dxc] 更新確認をスキップ（{err}）。導入済みのdxcを継続利用します"
                );
                return;
            }
            panic!("[xtask][dxc] dxc未導入かつ取得失敗のためビルド続行不可: {err}");
        }
    };

    if installed_tag.as_deref() == Some(release.tag_name.as_str()) && local_installed {
        eprintln!("[xtask][dxc] 最新版導入済み: {}", release.tag_name);
        return;
    }

    let Some(asset) = select_asset(&release.assets) else {
        panic!(
            "[xtask][dxc] リリース{}に対応アセットなし",
            release.tag_name
        );
    };

    eprintln!(
        "[xtask][dxc] 導入開始: {} ({})",
        release.tag_name, asset.browser_download_url
    );
    let bytes = download_asset_bytes(&asset.browser_download_url)
        .unwrap_or_else(|err| panic!("[xtask][dxc] ダウンロード失敗: {err}"));
    extract_zip(&bytes, &dxc_dir).unwrap_or_else(|err| panic!("[xtask][dxc] 展開失敗: {err}"));
    write_installed_tag(&dxc_dir, &release.tag_name);
    eprintln!("[xtask][dxc] 導入完了: {}", dxc_dir.display());
}

use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
};

const REQUIRED_EDITION: &str = "2024";
const EDITION_EXEMPT: &[&str] = &[
    "neoutl-shared-abi",
    "neoutl-effect-shader-build",
    "neoutl-object-shader-build",
];
const DEP_TABLES: &[&str] = &["dependencies", "build-dependencies", "dev-dependencies"];

struct Manifest {
    path: PathBuf,
    doc: toml::Table,
    package_name: Option<String>,
}

fn discover_manifests(root: &Path) -> Vec<Manifest> {
    let mut result = Vec::new();
    collect_manifests(&root.join("crates"), &mut result);
    if let Ok(text) = fs::read_to_string(root.join("Cargo.toml")) {
        if let Ok(doc) = text.parse::<toml::Table>() {
            result.push(Manifest {
                path: root.join("Cargo.toml"),
                package_name: doc
                    .get("package")
                    .and_then(|p| p.get("name"))
                    .and_then(|n| n.as_str())
                    .map(str::to_owned),
                doc,
            });
        }
    }
    result
}

fn collect_manifests(dir: &Path, out: &mut Vec<Manifest>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_manifests(&path, out);
            continue;
        }
        if path.file_name().and_then(|n| n.to_str()) != Some("Cargo.toml") {
            continue;
        }
        let Ok(text) = fs::read_to_string(&path) else {
            continue;
        };
        let Ok(doc) = text.parse::<toml::Table>() else {
            continue;
        };
        let package_name = doc
            .get("package")
            .and_then(|p| p.get("name"))
            .and_then(|n| n.as_str())
            .map(str::to_owned);
        out.push(Manifest {
            path,
            doc,
            package_name,
        });
    }
}

fn is_workspace_true(value: &toml::Value) -> bool {
    value
        .get("workspace")
        .and_then(|w| w.as_bool())
        .unwrap_or(false)
}

fn dep_tables_in<'a>(doc: &'a toml::Table) -> Vec<(&'a str, &'a toml::Table)> {
    let mut out = Vec::new();
    for name in DEP_TABLES {
        if let Some(toml::Value::Table(t)) = doc.get(*name) {
            out.push((*name, t));
        }
    }
    if let Some(toml::Value::Table(targets)) = doc.get("target") {
        for (_, cfg) in targets {
            if let toml::Value::Table(cfg_table) = cfg {
                for name in DEP_TABLES {
                    if let Some(toml::Value::Table(t)) = cfg_table.get(*name) {
                        out.push((*name, t));
                    }
                }
            }
        }
    }
    out
}

pub fn run(root: &Path) -> bool {
    let manifests = discover_manifests(root);
    let member_names: BTreeSet<String> = manifests
        .iter()
        .filter_map(|m| m.package_name.clone())
        .collect();

    let workspace_dep_names: BTreeSet<String> = manifests
        .iter()
        .find(|m| m.path == root.join("Cargo.toml"))
        .and_then(|m| m.doc.get("workspace"))
        .and_then(|w| w.get("dependencies"))
        .and_then(|d| d.as_table())
        .map(|t| t.keys().cloned().collect())
        .unwrap_or_default();

    let mut violations: Vec<String> = Vec::new();
    let mut external_direct: BTreeMap<String, Vec<String>> = BTreeMap::new();

    for m in &manifests {
        let rel = m
            .path
            .strip_prefix(root)
            .unwrap_or(&m.path)
            .display()
            .to_string();

        if let Some(edition) = m
            .doc
            .get("package")
            .and_then(|p| p.get("edition"))
            .and_then(|e| e.as_str())
        {
            let exempt = m
                .package_name
                .as_deref()
                .map(|n| EDITION_EXEMPT.contains(&n))
                .unwrap_or(false);
            if edition != REQUIRED_EDITION && !exempt {
                violations.push(format!(
                    "{rel}: edition={edition} (期待値={REQUIRED_EDITION})"
                ));
            }
        }

        for (table_name, table) in dep_tables_in(&m.doc) {
            for (dep_name, value) in table {
                if member_names.contains(dep_name) {
                    if !is_workspace_true(value) {
                        violations.push(format!(
                            "{rel} [{table_name}] {dep_name}: workspace.dependencies未使用 (path/version直書き)"
                        ));
                    }
                    continue;
                }
                if workspace_dep_names.contains(dep_name) {
                    if !is_workspace_true(value) {
                        violations.push(format!(
                            "{rel} [{table_name}] {dep_name}: workspace.dependencies登録済みだが直書き"
                        ));
                    }
                    continue;
                }
                if !is_workspace_true(value) {
                    external_direct
                        .entry(dep_name.clone())
                        .or_default()
                        .push(rel.clone());
                }
            }
        }
    }

    for (dep_name, locations) in &external_direct {
        if locations.len() > 1 {
            violations.push(format!(
                "{dep_name}: 複数crateで直書き重複 ({}) — workspace.dependencies集約対象",
                locations.join(", ")
            ));
        }
    }

    if violations.is_empty() {
        eprintln!("[xtask lint] 違反0件");
        true
    } else {
        eprintln!("[xtask lint] 違反{}件", violations.len());
        for v in &violations {
            eprintln!("  - {v}");
        }
        false
    }
}

use std::{
    env, fs,
    path::{Path, PathBuf},
    process::Command,
};

mod dxc;
mod lint;
mod slang;

struct DiscoveredCrate {
    package_name: String,
    lib_name: String,
    source_dir: PathBuf,
}

const WORKSPACE_EXCLUDED_DIRS: &[&str] =
    &["gstreamer-encoder", "gpuvideo-decoder", "gpuvideo-encoder"];

fn discover_crates(workspace_root: &Path, subdir: &str) -> Vec<DiscoveredCrate> {
    let scan_dir = workspace_root.join(subdir);
    let mut result = Vec::new();

    let entries = match fs::read_dir(&scan_dir) {
        Ok(e) => e,
        Err(err) => {
            eprintln!("[xtask] {} 読取失敗: {err}", scan_dir.display());
            return result;
        }
    };

    for entry in entries.flatten() {
        let manifest_dir = entry.path();
        if !manifest_dir.is_dir() {
            continue;
        }
        if manifest_dir
            .file_name()
            .and_then(|n| n.to_str())
            .is_some_and(|name| WORKSPACE_EXCLUDED_DIRS.contains(&name))
        {
            continue;
        }
        let manifest_path = manifest_dir.join("Cargo.toml");
        let Ok(text) = fs::read_to_string(&manifest_path) else {
            continue;
        };
        let Ok(doc) = text.parse::<toml::Table>() else {
            eprintln!("[xtask] 解析失敗: {}", manifest_path.display());
            continue;
        };

        let package_name = doc
            .get("package")
            .and_then(|p| p.get("name"))
            .and_then(|n| n.as_str())
            .map(str::to_owned);

        let Some(package_name) = package_name else {
            continue;
        };

        let lib_name = doc
            .get("lib")
            .and_then(|l| l.get("name"))
            .and_then(|n| n.as_str())
            .map(str::to_owned)
            .unwrap_or_else(|| package_name.replace('-', "_"));

        result.push(DiscoveredCrate {
            package_name,
            lib_name,
            source_dir: manifest_dir,
        });
    }

    result.sort_by(|a, b| a.package_name.cmp(&b.package_name));
    result
}

fn dylib_filename(lib_name: &str) -> String {
    if cfg!(target_os = "windows") {
        format!("{lib_name}.dll")
    } else if cfg!(target_os = "macos") {
        format!("lib{lib_name}.dylib")
    } else {
        format!("lib{lib_name}.so")
    }
}

fn target_dir(workspace_root: &Path, profile: &str, target: Option<&str>) -> PathBuf {
    match target {
        Some(triple) => workspace_root.join("target").join(triple).join(profile),
        None => workspace_root.join("target").join(profile),
    }
}

fn exe_filename(bin_name: &str) -> String {
    if cfg!(target_os = "windows") {
        format!("{bin_name}.exe")
    } else {
        bin_name.to_owned()
    }
}

fn build_all<'a>(
    workspace_root: &Path,
    profile: &str,
    target: Option<&str>,
    offline: bool,
    groups: &[(&str, &'a [DiscoveredCrate])],
    extra_packages: &[&str],
    lua_feature: &str,
) {
    let mut cmd = Command::new("cargo");
    cmd.current_dir(workspace_root).arg("build").arg("--locked");
    if profile == "release" {
        cmd.arg("--release");
    }
    if offline {
        cmd.arg("--offline");
    }
    if let Some(triple) = target {
        cmd.arg("--target").arg(triple);
    }
    const MLUA_CONSUMER_CRATES: &[&str] = &["neoutl-lua-runtime", "neoutl-effect-lua"];
    for pkg in MLUA_CONSUMER_CRATES {
        cmd.arg("-p")
            .arg(pkg)
            .arg("--features")
            .arg(format!("{pkg}/{lua_feature}"));
    }

    let mut package_count = 0usize;
    for (label, crates) in groups {
        if crates.is_empty() {
            eprintln!("[xtask] {label}クレート0件");
            continue;
        }
        for c in *crates {
            cmd.arg("-p").arg(&c.package_name);
            package_count += 1;
        }
    }
    for pkg in extra_packages {
        cmd.arg("-p").arg(pkg);
        package_count += 1;
    }

    if package_count == 0 {
        eprintln!("[xtask] ビルド対象パッケージ0件のためcargo呼び出しを省略");
        return;
    }

    apply_toolchain_env(&mut cmd, workspace_root);

    let status = cmd.status().expect("cargo build 起動失敗");
    if !status.success() {
        panic!("[xtask] 統合ビルド失敗: exit={status}");
    }
}

fn apply_toolchain_env(cmd: &mut Command, workspace_root: &Path) {
    let mut extra_paths = Vec::new();

    if slang::slangc_path(workspace_root).is_file() {
        cmd.env("SLANG_DIR", slang::install_dir(workspace_root));
        extra_paths.push(slang::bin_dir(workspace_root));
    }

    if dxc::dxcompiler_path(workspace_root).is_file() {
        extra_paths.push(dxc::bin_dir(workspace_root));
    }

    if extra_paths.is_empty() {
        return;
    }

    let existing_path = env::var_os("PATH").unwrap_or_default();
    let mut paths = extra_paths;
    paths.extend(env::split_paths(&existing_path));
    let Ok(joined_path) = env::join_paths(paths) else {
        eprintln!("[xtask] PATH合成失敗");
        return;
    };
    cmd.env("PATH", joined_path);
}

fn prepend_path(cmd: &mut Command, dir: PathBuf) {
    let current = cmd
        .get_envs()
        .find(|(key, _)| *key == "PATH")
        .and_then(|(_, value)| value.map(|v| v.to_os_string()))
        .or_else(|| env::var_os("PATH"))
        .unwrap_or_default();
    let mut paths = vec![dir];
    paths.extend(env::split_paths(&current));
    let Ok(joined_path) = env::join_paths(paths) else {
        eprintln!("[xtask] PATH合成失敗");
        return;
    };
    cmd.env("PATH", joined_path);
}

const PLUGIN_HOST_VERSION: &str = "0.0.7";

fn plugin_host_install_root(workspace_root: &Path) -> PathBuf {
    workspace_root
        .join("target")
        .join("maolan-plugin-host-install")
}

fn stage_plugin_host(workspace_root: &Path, profile: &str, target: Option<&str>, offline: bool) {
    let install_root = plugin_host_install_root(workspace_root);
    let bin_name = exe_filename("maolan-plugin-host");
    let installed_bin = install_root.join("bin").join(&bin_name);

    if !installed_bin.is_file() {
        let mut cmd = Command::new("cargo");
        cmd.arg("install")
            .arg("maolan-plugin-host")
            .arg("--version")
            .arg(PLUGIN_HOST_VERSION)
            .arg("--locked")
            .arg("--root")
            .arg(&install_root);
        if let Some(triple) = target {
            cmd.arg("--target").arg(triple);
        }
        if offline {
            cmd.arg("--offline");
        }
        apply_toolchain_env(&mut cmd, workspace_root);
        prepend_path(&mut cmd, install_root.join("bin"));
        let status = cmd
            .status()
            .expect("maolan-plugin-hostインストール起動失敗");
        if !status.success() {
            panic!("[xtask] maolan-plugin-hostインストール失敗: exit={status}");
        }
    }

    let dest_dir = target_dir(workspace_root, profile, target);
    fs::create_dir_all(&dest_dir).expect("配置先ディレクトリ作成失敗");
    let dest = dest_dir.join(&bin_name);
    fs::copy(&installed_bin, &dest).unwrap_or_else(|err| {
        panic!(
            "[xtask] maolan-plugin-host配置失敗: {err} (src={})",
            installed_bin.display()
        )
    });
    eprintln!("[xtask] 配置: {bin_name}");
}

fn stage_crates(
    workspace_root: &Path,
    profile: &str,
    target: Option<&str>,
    dest_subdir: &str,
    crates: &[DiscoveredCrate],
) {
    let out_dir = target_dir(workspace_root, profile, target);
    let dest_dir = out_dir.join(dest_subdir);
    fs::create_dir_all(&dest_dir).expect("配置先ディレクトリ作成失敗");

    for c in crates {
        let filename = dylib_filename(&c.lib_name);
        let src = out_dir.join(&filename);
        let dst = dest_dir.join(&filename);
        match fs::copy(&src, &dst) {
            Ok(_) => eprintln!("[xtask] 配置: {dest_subdir}/{filename}"),
            Err(err) => eprintln!("[xtask] 配置失敗 {filename}: {err} (src={})", src.display()),
        }
        let catalog_src = c.source_dir.join("i18n");
        if catalog_src.is_dir() {
            let catalog_dst = dest_dir.join("i18n").join(&c.lib_name);
            if let Err(err) = copy_i18n(&catalog_src, &catalog_dst) {
                eprintln!("[xtask] 翻訳配置失敗 {filename}: {err}");
            }
        }
    }
}

fn copy_i18n(src: &Path, dst: &Path) -> std::io::Result<()> {
    fs::create_dir_all(dst)?;
    for entry in fs::read_dir(src)? {
        let entry = entry?;
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) == Some("yml") {
            fs::copy(&path, dst.join(entry.file_name()))?;
        }
    }
    Ok(())
}

fn stage_scripts(workspace_root: &Path, profile: &str, target: Option<&str>) {
    let src_dir = workspace_root.join("scripts");
    if !src_dir.is_dir() {
        return;
    }
    let dst_dir = target_dir(workspace_root, profile, target).join("scripts");
    copy_dir_recursive(&src_dir, &dst_dir).expect("Luaスクリプト配置失敗");
    eprintln!("[xtask] 配置: scripts/（Lua）");
}

fn copy_dir_recursive(src: &Path, dst: &Path) -> std::io::Result<()> {
    fs::create_dir_all(dst)?;
    for entry in fs::read_dir(src)? {
        let entry = entry?;
        let path = entry.path();
        let target = dst.join(entry.file_name());
        if path.is_dir() {
            copy_dir_recursive(&path, &target)?;
        } else if path.extension().and_then(|e| e.to_str()) == Some("lua") {
            fs::copy(path, target)?;
        }
    }
    Ok(())
}

fn workspace_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("workspace root解決失敗")
        .to_path_buf()
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let mut release = false;
    let mut offline = false;
    let mut task = "run".to_string();
    let mut target: Option<String> = None;
    let mut lua_feature = "luajit".to_string();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--release" => release = true,
            "--offline" => offline = true,
            "build" | "run" | "lint" => task = args[i].clone(),
            "--target" => {
                i += 1;
                target = args.get(i).cloned();
            }
            "--lua-feature" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    lua_feature = v.clone();
                }
            }
            _ => {}
        }
        i += 1;
    }
    let profile = if release { "release" } else { "debug" };
    let target = target.as_deref();

    let root = workspace_root();

    if task == "lint" {
        std::process::exit(if lint::run(&root) { 0 } else { 1 });
    }

    generate_japanese_i18n(&root);

    slang::ensure_installed(&root, offline);
    dxc::ensure_installed(&root, offline);
    let objects = discover_crates(&root, "crates/object/plugins");
    let effects = discover_crates(&root, "crates/effect/plugins");
    let decoders = discover_crates(&root, "crates/media/decoders");
    build_all(
        &root,
        profile,
        target,
        offline,
        &[
            ("objects", objects.as_slice()),
            ("effects", effects.as_slice()),
            ("decoders", decoders.as_slice()),
        ],
        &["NeoUtl"],
        &lua_feature,
    );

    stage_plugin_host(&root, profile, target, offline);
    stage_crates(&root, profile, target, "objects", &objects);
    stage_crates(&root, profile, target, "effects", &effects);
    stage_crates(&root, profile, target, "decoders", &decoders);
    fs::create_dir_all(target_dir(&root, profile, target).join("easings"))
        .expect("easings配置先ディレクトリ作成失敗");
    stage_scripts(&root, profile, target);

    if task != "run" {
        return;
    }

    let bin_path = target_dir(&root, profile, target).join(exe_filename("NeoUtl"));
    let status = Command::new(&bin_path)
        .current_dir(&root)
        .status()
        .unwrap_or_else(|e| panic!("[xtask] バイナリ起動失敗 ({}): {e}", bin_path.display()));
    if !status.success() {
        std::process::exit(status.code().unwrap_or(1));
    }
}

fn generate_japanese_i18n(root: &Path) {
    let mut messages = std::collections::BTreeSet::new();
    let mut files = Vec::new();
    collect_source_files(&root.join("src"), &mut files);
    collect_source_files(&root.join("crates"), &mut files);
    collect_source_files(&root.join("scripts"), &mut files);
    for path in files {
        let Ok(source) = fs::read_to_string(&path) else {
            continue;
        };
        for literal in string_literals(&source) {
            if literal.chars().any(|c| ('ぁ'..='龯').contains(&c)) {
                messages.insert(literal);
            }
        }
    }
    let mut output = String::from("# Generated by `cargo run -p xtask -- i18n`.\n");
    for message in messages {
        let escaped = escape_yaml_double_quoted(&message);
        output.push_str(&format!("\"{escaped}\": \"{escaped}\"\n"));
    }
    let dir = root.join("i18n");
    fs::create_dir_all(&dir).expect("i18nディレクトリ作成失敗");
    let catalog = dir.join("ja.yml");
    let unchanged = fs::read_to_string(&catalog)
        .map(|current| current == output)
        .unwrap_or(false);
    if !unchanged {
        fs::write(&catalog, output).expect("日本語翻訳ファイル作成失敗");
        eprintln!("[xtask] i18n/ja.ymlを生成しました");
    } else {
        eprintln!("[xtask] i18n/ja.ymlに変更なし");
    }
}

fn collect_source_files(dir: &Path, files: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect_source_files(&path, files);
        } else if matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("rs" | "lua")
        ) {
            files.push(path);
        }
    }
}

fn escape_yaml_double_quoted(message: &str) -> String {
    let mut escaped = String::with_capacity(message.len());
    for c in message.chars() {
        match c {
            '\\' => escaped.push_str("\\\\"),
            '"' => escaped.push_str("\\\""),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            c if (c as u32) < 0x20 => escaped.push_str(&format!("\\u{:04x}", c as u32)),
            c => escaped.push(c),
        }
    }
    escaped
}

fn string_literals(source: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut chars = source.char_indices().peekable();
    while let Some((_, c)) = chars.next() {
        if c == '/' {
            if let Some(&(_, '/')) = chars.peek() {
                chars.next();
                for (_, nc) in chars.by_ref() {
                    if nc == '\n' {
                        break;
                    }
                }
                continue;
            } else if let Some(&(_, '*')) = chars.peek() {
                chars.next();
                let mut depth = 1;
                while let Some((_, nc)) = chars.next() {
                    if nc == '/' && chars.peek().map(|&(_, c)| c) == Some('*') {
                        chars.next();
                        depth += 1;
                    } else if nc == '*' && chars.peek().map(|&(_, c)| c) == Some('/') {
                        chars.next();
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                }
                continue;
            }
        }
        if c == '\'' {
            let mut is_escaped = false;
            for (_, ch) in chars.by_ref() {
                if is_escaped {
                    is_escaped = false;
                } else if ch == '\\' {
                    is_escaped = true;
                } else if ch == '\'' {
                    break;
                }
            }
            continue;
        }
        if c != '"' {
            continue;
        }
        let mut value = String::new();
        loop {
            let Some((_, c)) = chars.next() else {
                break;
            };
            if c == '"' {
                result.push(value);
                break;
            }
            if c != '\\' {
                value.push(c);
                continue;
            }
            let Some((_, escape)) = chars.next() else {
                break;
            };
            match escape {
                'n' => value.push('\n'),
                't' => value.push('\t'),
                'r' => value.push('\r'),
                '0' => value.push('\0'),
                '\\' => value.push('\\'),
                '"' => value.push('"'),
                '\'' => value.push('\''),
                '\n' => {
                    while let Some(&(_, w)) = chars.peek() {
                        if w == ' ' || w == '\t' || w == '\n' || w == '\r' {
                            chars.next();
                        } else {
                            break;
                        }
                    }
                }
                'x' => {
                    let hex: String = (0..2)
                        .filter_map(|_| chars.next().map(|(_, h)| h))
                        .collect();
                    if let Ok(byte) = u8::from_str_radix(&hex, 16) {
                        value.push(byte as char);
                    }
                }
                'u' => {
                    if chars.peek().map(|&(_, c)| c) == Some('{') {
                        chars.next();
                        let mut hex = String::new();
                        for (_, h) in chars.by_ref() {
                            if h == '}' {
                                break;
                            }
                            hex.push(h);
                        }
                        if let Some(ch) =
                            u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32)
                        {
                            value.push(ch);
                        }
                    }
                }
                other => value.push(other),
            }
        }
    }
    result
}

use serde::Deserialize;
use std::env;
use std::fs;
use std::io::{Cursor, Read};
use std::path::{Path, PathBuf};

const RELEASES_API_URL: &str = "https://api.github.com/repos/shader-slang/slang/releases/latest";
const VERSION_MARKER_FILENAME: &str = ".slang-version";

fn slangc_filename() -> &'static str {
    if cfg!(target_os = "windows") {
        "slangc.exe"
    } else {
        "slangc"
    }
}

fn find_system_slangc() -> Option<PathBuf> {
    let path_var = env::var_os("PATH")?;
    let filename = slangc_filename();
    env::split_paths(&path_var)
        .map(|dir| dir.join(filename))
        .find(|candidate| candidate.is_file())
}

#[derive(Deserialize)]
struct ReleaseAsset {
    name: String,
    browser_download_url: String,
}

#[derive(Deserialize)]
struct ReleaseInfo {
    tag_name: String,
    assets: Vec<ReleaseAsset>,
}

pub fn install_dir(workspace_root: &Path) -> PathBuf {
    workspace_root.join("slang")
}

pub fn bin_dir(workspace_root: &Path) -> PathBuf {
    install_dir(workspace_root).join("bin")
}

fn version_marker_path(slang_dir: &Path) -> PathBuf {
    slang_dir.join(VERSION_MARKER_FILENAME)
}

fn read_installed_tag(slang_dir: &Path) -> Option<String> {
    let text = fs::read_to_string(version_marker_path(slang_dir)).ok()?;
    let tag = text.trim();
    (!tag.is_empty()).then(|| tag.to_string())
}

fn write_installed_tag(slang_dir: &Path, tag_name: &str) {
    if let Err(err) = fs::write(version_marker_path(slang_dir), tag_name) {
        eprintln!("[xtask][slang] バージョン記録失敗: {err}");
    }
}

fn platform_tag() -> &'static str {
    let os = if cfg!(target_os = "windows") {
        "windows"
    } else if cfg!(target_os = "macos") {
        "macos"
    } else {
        "linux"
    };
    let arch = if cfg!(target_arch = "aarch64") {
        "aarch64"
    } else {
        "x86_64"
    };
    match (os, arch) {
        ("windows", "x86_64") => "windows-x86_64",
        ("windows", "aarch64") => "windows-aarch64",
        ("macos", "x86_64") => "macos-x86_64",
        ("macos", "aarch64") => "macos-aarch64",
        ("linux", "x86_64") => "linux-x86_64",
        ("linux", "aarch64") => "linux-aarch64",
        _ => unreachable!("未対応OS/CPUアーキテクチャ組合せ"),
    }
}

fn github_token() -> Option<String> {
    std::env::var("GITHUB_TOKEN")
        .or_else(|_| std::env::var("GH_TOKEN"))
        .ok()
        .filter(|t| !t.is_empty())
}

fn fetch_latest_release() -> Result<ReleaseInfo, String> {
    let mut req = ureq::get(RELEASES_API_URL)
        .header("User-Agent", "NeoUtl-xtask")
        .header("Accept", "application/vnd.github+json");
    if let Some(token) = github_token() {
        req = req.header("Authorization", &format!("Bearer {token}"));
    }
    req.call()
        .map_err(|err| format!("GitHub Releases API取得失敗: {err}"))?
        .body_mut()
        .read_json::<ReleaseInfo>()
        .map_err(|err| format!("GitHub Releases APIレスポンス解析失敗: {err}"))
}

fn select_asset<'a>(assets: &'a [ReleaseAsset], platform_tag: &str) -> Option<&'a ReleaseAsset> {
    let suffix = format!("-{platform_tag}.zip");
    assets.iter().find(|asset| asset.name.ends_with(&suffix))
}

fn download_asset_bytes(url: &str) -> Result<Vec<u8>, String> {
    let mut req = ureq::get(url).header("User-Agent", "NeoUtl-xtask");
    if let Some(token) = github_token() {
        req = req.header("Authorization", &format!("Bearer {token}"));
    }
    let mut response = req
        .call()
        .map_err(|err| format!("Slangアセットダウンロード失敗: {err}"))?;
    let mut bytes = Vec::new();
    response
        .body_mut()
        .as_reader()
        .read_to_end(&mut bytes)
        .map_err(|err| format!("Slangアセット読込失敗: {err}"))?;
    Ok(bytes)
}

fn extract_zip(bytes: &[u8], slang_dir: &Path) -> Result<(), String> {
    if slang_dir.exists() {
        fs::remove_dir_all(slang_dir).map_err(|err| format!("既存slang削除失敗: {err}"))?;
    }
    fs::create_dir_all(slang_dir).map_err(|err| format!("slangディレクトリ作成失敗: {err}"))?;

    let mut archive =
        zip::ZipArchive::new(Cursor::new(bytes)).map_err(|err| format!("zip解析失敗: {err}"))?;

    for index in 0..archive.len() {
        let mut entry = archive
            .by_index(index)
            .map_err(|err| format!("zipエントリ読込失敗: {err}"))?;
        let Some(relative_path) = entry.enclosed_name() else {
            eprintln!("[xtask][slang] 不正なzipエントリを無視: index={index}");
            continue;
        };
        let dest_path = slang_dir.join(&relative_path);

        if entry.is_dir() {
            fs::create_dir_all(&dest_path).map_err(|err| format!("展開先作成失敗: {err}"))?;
            continue;
        }

        if let Some(parent) = dest_path.parent() {
            fs::create_dir_all(parent).map_err(|err| format!("展開先作成失敗: {err}"))?;
        }
        let mut out_file =
            fs::File::create(&dest_path).map_err(|err| format!("展開ファイル作成失敗: {err}"))?;
        std::io::copy(&mut entry, &mut out_file).map_err(|err| format!("展開失敗: {err}"))?;

        #[cfg(unix)]
        if let Some(mode) = entry.unix_mode() {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&dest_path, fs::Permissions::from_mode(mode));
        }
    }
    Ok(())
}

pub fn ensure_installed(workspace_root: &Path, offline: bool) {
    let slang_dir = install_dir(workspace_root);
    let installed_tag = read_installed_tag(&slang_dir);
    let local_installed = installed_tag.is_some() && slang_dir.is_dir();

    if offline {
        if local_installed {
            let tag = installed_tag.as_deref().unwrap_or("");
            eprintln!("[xtask][slang] --offline指定のため更新確認をスキップ: 導入済み {tag}");
            return;
        }
        if let Some(system_slangc) = find_system_slangc() {
            eprintln!(
                "[xtask][slang] --offline指定のため更新確認をスキップ: システム導入済みslangcを利用 ({})",
                system_slangc.display()
            );
            return;
        }
        panic!(
            "[xtask][slang] --offline指定だがSlang未導入（{}が存在せず、PATH上にもslangcが見つかりません）",
            slang_dir.display()
        );
    }

    let platform = platform_tag();

    let release = match fetch_latest_release() {
        Ok(release) => release,
        Err(err) => {
            if local_installed {
                eprintln!(
                    "[xtask][slang] 更新確認をスキップ（{err}）。導入済みのSlangを継続利用します"
                );
                return;
            }
            if let Some(system_slangc) = find_system_slangc() {
                eprintln!(
                    "[xtask][slang] 更新確認失敗（{err}）。システム導入済みslangcを利用します ({})",
                    system_slangc.display()
                );
                return;
            }
            panic!(
                "[xtask][slang] Slang未導入（project_root/slang・システムPATH双方とも見つからず）かつ取得失敗のためビルド続行不可: {err}"
            );
        }
    };

    if installed_tag.as_deref() == Some(release.tag_name.as_str()) && slang_dir.is_dir() {
        eprintln!("[xtask][slang] 最新版導入済み: {}", release.tag_name);
        return;
    }

    let Some(asset) = select_asset(&release.assets, platform) else {
        panic!(
            "[xtask][slang] リリース{}に対応アセットなし（platform={platform}）",
            release.tag_name
        );
    };

    eprintln!(
        "[xtask][slang] 導入開始: {} ({})",
        release.tag_name, asset.browser_download_url
    );
    let bytes = download_asset_bytes(&asset.browser_download_url)
        .unwrap_or_else(|err| panic!("[xtask][slang] ダウンロード失敗: {err}"));
    extract_zip(&bytes, &slang_dir).unwrap_or_else(|err| panic!("[xtask][slang] 展開失敗: {err}"));
    write_installed_tag(&slang_dir, &release.tag_name);
    eprintln!("[xtask][slang] 導入完了: {}", slang_dir.display());
}

pub fn slangc_path(workspace_root: &Path) -> PathBuf {
    bin_dir(workspace_root).join(slangc_filename())
}
